"use strict";(self.webpackChunkglobal_blog=self.webpackChunkglobal_blog||[]).push([["6607"],{77735(e){e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"/2026/11/01/stanford-cs329a-1","metadata":{"permalink":"/blog/2026/11/01/stanford-cs329a-1","source":"@site/blog/2026-11-01-stanford-cs329a-1/index.md","title":"stanford-cs329a-1","description":"","date":"2026-11-01T00:00:00.000Z","tags":[],"readingTime":0,"hasTruncateMarker":false,"authors":[],"frontMatter":{},"unlisted":false,"nextItem":{"title":"[Stanford CS146S #10] The Future of Software Engineering: Autonomous Agent Swarms, Zero-Human Deployment Pipelines, and Managing AI Fleets at Scale","permalink":"/blog/2026-10-31-stanford-cs146s-10"}},"content":""},{"id":"2026-10-31-stanford-cs146s-10","metadata":{"permalink":"/blog/2026-10-31-stanford-cs146s-10","source":"@site/blog/2026-10-31-stanford-cs146s-10/index.md","title":"[Stanford CS146S #10] The Future of Software Engineering: Autonomous Agent Swarms, Zero-Human Deployment Pipelines, and Managing AI Fleets at Scale","description":"The Grand Finale of Stanford CS146S: Synthesizing the 10-week curriculum into the autonomous software factory, zero-human deployment highways, AI fleet orchestration, and the redefined destiny of the human engineer as a system conductor.","date":"2026-10-31T00:00:00.000Z","tags":[{"inline":true,"label":"stanford-cs146s","permalink":"/blog/tags/stanford-cs-146-s"},{"inline":true,"label":"autonomous-engineering","permalink":"/blog/tags/autonomous-engineering"},{"inline":true,"label":"zero-human-deployments","permalink":"/blog/tags/zero-human-deployments"},{"inline":true,"label":"ai-fleets","permalink":"/blog/tags/ai-fleets"},{"inline":true,"label":"software-future","permalink":"/blog/tags/software-future"},{"inline":true,"label":"agent-swarms","permalink":"/blog/tags/agent-swarms"},{"inline":true,"label":"system-governance","permalink":"/blog/tags/system-governance"}],"readingTime":10.25,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"2026-10-31-stanford-cs146s-10","title":"[Stanford CS146S #10] The Future of Software Engineering: Autonomous Agent Swarms, Zero-Human Deployment Pipelines, and Managing AI Fleets at Scale","authors":["jbgih"],"tags":["stanford-cs146s","autonomous-engineering","zero-human-deployments","ai-fleets","software-future","agent-swarms","system-governance"],"date":"2026-10-31T00:00:00.000Z","keywords":["Autonomous Software Engineering Teams","Zero-Human Deployment Pipelines","AI Software Fleet Management","Human-Agent Software Governance","Self-Evolving Codebases"],"description":"The Grand Finale of Stanford CS146S: Synthesizing the 10-week curriculum into the autonomous software factory, zero-human deployment highways, AI fleet orchestration, and the redefined destiny of the human engineer as a system conductor."},"unlisted":false,"prevItem":{"title":"stanford-cs329a-1","permalink":"/blog/2026/11/01/stanford-cs329a-1"},"nextItem":{"title":"[Stanford CS146S #9] Autonomous TDD & Formal Verification: Z3 SMT Solvers, Property-Based Invariants, and Mathematical Proofs for AI-Generated Code","permalink":"/blog/2026-10-30-stanford-cs146s-9"}},"content":"![The Future of Software Engineering and AI Fleets](./images/10_cs146s_future_software_engineering_ai_fleets.png)\\n\\nWelcome to the **tenth and final installment** of our comprehensive engineering series analyzing **Stanford University\'s CS146S: The Modern Software Developer**.\\n\\nOver the preceding nine lectures, we dismantled the traditional paradigm of software development piece by piece:\\n- **Lecture 1**: The transition from syntax typist to system conductor.\\n- **Lecture 2**: Probabilistic token mechanics and prompt engineering.\\n- **Lecture 3**: Standardized tool execution via the Model Context Protocol (MCP).\\n- **Lecture 4**: Spec-Driven Development (SDD) and self-healing test loops.\\n- **Lecture 5**: Multi-agent swarms using the Architect-Implementer-Critic pattern.\\n- **Lecture 6**: Runtime dynamic tracing and incident mitigation with eBPF.\\n- **Lecture 7**: AST-aware linters and security taint analysis in CI/CD.\\n- **Lecture 8**: AI-native modularity, context budgets, and monolith decoupling.\\n- **Lecture 9**: Property-based invariants and mathematical proofs with Z3 SMT solvers.\\n\\nIn this **Capstone Finale**, the Stanford curriculum synthesizes these modular disciplines into a singular, unified vision: **The Autonomous Software Factory**. We explore how modern high-velocity organizations govern fleets of hundreds of concurrent AI agents, engineer zero-human continuous deployment pipelines, and define the enduring, indispensable role of the human engineer in an age of automated intelligence.\\n\\n{/* truncate */}\\n\\n---\\n\\n### 1. The Zero-Human Continuous Deployment Pipeline: \\"Dark Factories\\" for Code\\n\\nIn manufacturing, a \\"Dark Factory\\" refers to an industrial production facility that operates fully automated with zero human labor on the factory floor, requiring neither lighting nor human climate control. \\n\\nStanford CS146S introduces the software engineering equivalent: **The Zero-Human Deployment Highway**.\\n\\n```mermaid\\nflowchart LR\\n    subgraph Human_Domain [\\"Human Strategic Intent\\"]\\n        H1[\\"Product PRD & System Invariants\\"]\\n    end\\n\\n    subgraph Autonomous_Factory [\\"The Zero-Human Software Highway\\"]\\n        direction TB\\n        A1[\\"1. Spec Synthesis & Task Decomposition\\"] --\x3e A2[\\"2. Parallel Multi-Agent Implementation\\"]\\n        A2 --\x3e A3[\\"3. Sub-Second AST & Taint Gate\\"]\\n        A3 --\x3e A4[\\"4. Property Fuzzing & Z3 SMT Formal Proof\\"]\\n        A4 --\x3e A5[\\"5. Canary Shadow Dual-Run (100k Live Requests)\\"]\\n    end\\n\\n    subgraph Production [\\"Live Production Fleet\\"]\\n        P1[\\"Automated Zero-Downtime Rollout\\"]\\n        P2[\\"eBPF Autonomous SRE Sentry & Self-Healing\\"]\\n    end\\n\\n    Human_Domain ==>|\\"Structured SPEC.md\\"| Autonomous_Factory\\n    Autonomous_Factory ==>|\\"Provably Correct Binary\\"| Production\\n    Production -.->|\\"Telemetry & Regression Diff\\"| Autonomous_Factory\\n```\\n\\n#### The 5 Automated Verification Gates\\nIn a zero-human deployment pipeline, code is never committed to production based on subjective peer review or blind trust. Instead, code traverses five deterministic, machine-enforced gates:\\n1. **Contract Invariant Gate**: The PR must compile against strict machine-readable schemas (OpenAPI 3.1, Protobuf, Pydantic) with zero type hallucinations.\\n2. **Structural & Security AST Gate**: Sub-second AST parsers verify architectural boundary rules (no circular imports, context budget < 32k tokens) and execute taint analysis to guarantee that untrusted inputs cannot reach dangerous sinks.\\n3. **Stochastic Property-Based Gate (PBT)**: Hypothesis engines execute 100,000 randomized test cases over algebraic invariants (idempotence, round-trip symmetry).\\n4. **Mathematical SMT Theorem Prover Gate**: The Z3 SMT solver converts code semantics into first-order logic, returning `UNSAT` to prove the mathematical absence of integer overflows, deadlock races, or state invariant breaches.\\n5. **Shadow Dual-Run Canary Gate**: Production traffic is duplicated into an isolated sandbox where the refactored code executes alongside legacy services. If output telemetry matches across 100,000 live requests with identical latency, traffic switches automatically.\\n\\nIf any gate fails, the system does not page an on-call human. Instead, it extracts the minimal counterexample, feeds it into the autonomous agent swarm, synthesizes a patch, and re-executes the pipeline.\\n\\n---\\n\\n### 2. Fleet Orchestration: Managing 1,000 Concurrent AI Agents\\n\\nAs engineering organizations scale, they transition from a single developer chatting with a single AI assistant to orchestrating **Fleets of Autonomous AI Agents** working simultaneously across thousands of micro-repositories.\\n\\n```mermaid\\nflowchart TD\\n    subgraph Swarm_Coordination [\\"AI Fleet Mesh Architecture\\"]\\n        O1[\\"Central Fleet Orchestrator (DAG Scheduler)\\"]\\n        \\n        subgraph Squad_A [\\"Feature Squad: Payment Engine\\"]\\n            A_Arch[\\"Architect Agent\\"] --\x3e A_Imp1[\\"Implementer Agent Alpha\\"]\\n            A_Arch --\x3e A_Imp2[\\"Implementer Agent Beta\\"]\\n            A_Imp1 & A_Imp2 --\x3e A_Crit[\\"Critic & Formal Verifier\\"]\\n        end\\n\\n        subgraph Squad_B [\\"Modernization Squad: Dependency Migrations\\"]\\n            B_Scan[\\"AST Dependency Scanner\\"] --\x3e B_Refactor[\\"Codemod Transformer\\"]\\n            B_Refactor --\x3e B_Test[\\"Dual-Run Canary Validator\\"]\\n        end\\n\\n        subgraph Squad_C [\\"SRE Sentinel Squad: 24/7 Observability\\"]\\n            C_BPF[\\"eBPF Telemetry Harvester\\"] --\x3e C_LLM[\\"Anomaly Diagnostic Sentry\\"]\\n            C_LLM --\x3e C_Patch[\\"Automated Hotpatch Synthesizer\\"]\\n        end\\n\\n        O1 <==> Squad_A\\n        O1 <==> Squad_B\\n        O1 <==> Squad_C\\n    end\\n```\\n\\n#### Key Challenges in AI Fleet Governance\\n1. **Context Drift & Semantic Collisions**: When 20 implementer agents modify adjacent modules concurrently, local diffs succeed but global abstractions drift. Fleet orchestrators enforce **Distributed Blackboard Architectures**, where agents publish immutable state events to a shared message bus.\\n2. **Token Economics & Compute Allocation**: Not all tasks justify expensive reasoning models. Fleet schedulers employ tiered routing: lightweight 8B parameter models for AST linting and boilerplate generation, mid-tier models for property test synthesis, and deep reasoning models (Claude 3.7 Sonnet, o3-mini) strictly for architectural decomposition and SMT invariant synthesis.\\n3. **Byzantine Agent Faults & Consensus**: When agents hallucinate conflicting architectural decisions, the orchestrator triggers majority-voting consensus protocols or falls back to formal contract specifications.\\n\\n---\\n\\n### 3. The Self-Evolving Codebase: Autonomous Continuous Modernization\\n\\nIn legacy software organizations, technical debt accumulates because engineers are perpetually pressured to deliver features rather than upgrade libraries, refactor deprecations, or optimize database indices.\\n\\nStanford CS146S demonstrates how AI fleets enable **The Self-Evolving Codebase**:\\n- **Continuous Overnight Upgrades**: When a new major version of Python, React, or Go is released, autonomous modernization agents wake up in isolated branches, parse breaking changelogs, run AST codemods, update deprecated APIs, satisfy test suites, verify shadow runs, and merge production-ready PRs before human engineers begin their workday.\\n- **Dynamic Performance Optimization**: Combining eBPF runtime profiling (Lecture 6) with AST refactoring (Lecture 8), sentinel agents identify hot CPU code paths, generate vector-optimized C/Rust extensions, formally verify algorithmic equivalence, and deploy runtime hotpatches.\\n\\n---\\n\\n### 4. The Redefined Role of the Human Engineer: From Typist to System Governor\\n\\nDoes the rise of autonomous software factories render the human software engineer obsolete? \\n\\nStanford CS146S answers with an emphatic **NO**. The engineer\u2019s role is elevated to the highest leverage position in history: **The System Governor and Chief Architect**.\\n\\n```mermaid\\nflowchart TD\\n    subgraph Human_Domain [\\"The Indispensable Human Core\\"]\\n        H1[\\"1. Defining Business Problem & Human Intent\\"]\\n        H2[\\"2. Formulating Ethical Invariants & Moral Boundaries\\"]\\n        H3[\\"3. Evaluating Asymmetric Risk & Threat Modeling\\"]\\n        H4[\\"4. Designing Foundational Domain Ontologies\\"]\\n    end\\n\\n    subgraph Machine_Domain [\\"Autonomous AI Agent Execution\\"]\\n        M1[\\"Syntax Typing & Boilerplate Plumbing\\"]\\n        M2[\\"Unit Test & Property Fuzzing Generation\\"]\\n        M3[\\"Symbolic Logic & SMT Mathematical Verification\\"]\\n        M4[\\"Canary Deployment & Telemetry Diffing\\"]\\n    end\\n\\n    Human_Domain ==>|\\"Strategic Governance & Oversight\\"| Machine_Domain\\n```\\n\\n#### What Remains Uniquely Human?\\n1. **Problem Definition (\\"Why\\" and \\"What\\")**: AI agents excel at optimizing toward a defined loss function or specification; they cannot determine which human problems are worth solving.\\n2. **Ethical Constraints & Moral Trade-offs**: In credit underwriting, autonomous healthcare, and criminal justice, balancing accuracy against fairness, privacy, and systemic bias requires human ethical judgment.\\n3. **Asymmetric Risk Management**: Determining how much risk an organization should accept when deploying high-stakes infrastructure is fundamentally a business and legal decision.\\n4. **Domain Ontology Architecture**: Defining the core entities, boundaries, and language of a business domain remains a deeply creative human endeavor.\\n\\nThe developer who spent 40 hours a week typing boilerplate Java syntax is being replaced. In their place stands the **Modern Software Developer**: an engineer who commands a fleet of intelligent agents, enforces mathematical guarantees, and designs resilient distributed architectures.\\n\\n---\\n\\n### 5. Executable Blueprint: Autonomous Fleet Orchestrator & Deployment Gatekeeper\\n\\nBelow is an executable Python framework simulating the multi-tier gatekeeper that governs autonomous AI agent PRs. It validates schema invariants, runs property checks, and simulates shadow dual-run deployment.\\n\\n```python\\n\\"\\"\\"\\nautonomous_fleet_gatekeeper.py\\nStanford CS146S - Capstone Final Toolkit\\nSimulates an Autonomous Software Factory Gatekeeper that evaluates\\nAI-generated pull requests across Contract, AST, Property, and Shadow gates\\nbefore permitting zero-human production deployment.\\n\\"\\"\\"\\n\\nimport time\\nimport sys\\nfrom typing import Dict, Any, List\\n\\n\\nclass VerificationGate:\\n    def __init__(self, name: str):\\n        self.name = name\\n\\n    def evaluate(self, pr_payload: Dict[str, Any]) -> bool:\\n        raise NotImplementedError\\n\\n\\nclass SchemaContractGate(VerificationGate):\\n    def evaluate(self, pr_payload: Dict[str, Any]) -> bool:\\n        print(f\\"[{self.name}] Validating machine-readable schema contracts...\\")\\n        # Check strict typing and explicit interface definitions\\n        has_schema = pr_payload.get(\\"has_schema_contract\\", False)\\n        tokens = pr_payload.get(\\"context_tokens\\", 0)\\n        if not has_schema:\\n            print(f\\" \u274C Failed: Missing machine-readable contract (Pydantic/Protobuf).\\")\\n            return False\\n        if tokens > 32000:\\n            print(f\\" \u274C Failed: Context tokens ({tokens}) exceed module budget (<32k).\\")\\n            return False\\n        print(f\\" \u2705 Passed: Explicit schema verified. Context budget: {tokens} tokens.\\")\\n        return True\\n\\n\\nclass ASTSecurityGate(VerificationGate):\\n    def evaluate(self, pr_payload: Dict[str, Any]) -> bool:\\n        print(f\\"[{self.name}] Executing AST taint analysis and cyclic dependency scan...\\")\\n        taint_leaks = pr_payload.get(\\"taint_violations\\", 0)\\n        cyclic_sccs = pr_payload.get(\\"cyclic_dependencies\\", 0)\\n        if taint_leaks > 0:\\n            print(f\\" \u274C Failed: Detected {taint_leaks} untrusted taint dataflow leak(s).\\")\\n            return False\\n        if cyclic_sccs > 0:\\n            print(f\\" \u274C Failed: Detected {cyclic_sccs} cyclic dependency cluster(s).\\")\\n            return False\\n        print(\\" \u2705 Passed: Sub-second AST scan clean. Zero security taint leaks.\\")\\n        return True\\n\\n\\nclass PropertyVerificationGate(VerificationGate):\\n    def evaluate(self, pr_payload: Dict[str, Any]) -> bool:\\n        print(f\\"[{self.name}] Running 100,000 Hypothesis property fuzzing iterations...\\")\\n        pbt_passed = pr_payload.get(\\"pbt_passed\\", False)\\n        smt_proved = pr_payload.get(\\"smt_proved\\", False)\\n        if not pbt_passed:\\n            print(\\" \u274C Failed: Algebraic invariant violated (minimal counterexample extracted).\\")\\n            return False\\n        if not smt_proved:\\n            print(\\" \u274C Failed: Z3 SMT solver returned SAT (counterexample model found).\\")\\n            return False\\n        print(\\" \u2705 Passed: 100% state-space invariant proven by Z3 (UNSAT).\\")\\n        return True\\n\\n\\nclass ShadowDualRunGate(VerificationGate):\\n    def evaluate(self, pr_payload: Dict[str, Any]) -> bool:\\n        print(f\\"[{self.name}] Executing shadow dual-run on 100,000 live replicated requests...\\")\\n        diff_count = pr_payload.get(\\"shadow_diff_count\\", 0)\\n        latency_drift_pct = pr_payload.get(\\"latency_drift_pct\\", 0.0)\\n        if diff_count > 0:\\n            print(f\\" \u274C Failed: {diff_count} telemetry mismatch(es) detected in shadow execution.\\")\\n            return False\\n        if latency_drift_pct > 5.0:\\n            print(f\\" \u274C Failed: Latency regression of {latency_drift_pct}% exceeds 5% SLA.\\")\\n            return False\\n        print(f\\" \u2705 Passed: Zero diffs across 100,000 requests. Latency drift: {latency_drift_pct}%.\\")\\n        return True\\n\\n\\nclass AutonomousDeploymentOrchestrator:\\n    def __init__(self):\\n        self.pipeline: List[VerificationGate] = [\\n            SchemaContractGate(\\"Gate 1: Contract Schema\\"),\\n            ASTSecurityGate(\\"Gate 2: AST & Taint Analysis\\"),\\n            PropertyVerificationGate(\\"Gate 3: PBT & Z3 Formal Proof\\"),\\n            ShadowDualRunGate(\\"Gate 4: Shadow Dual-Run Canary\\"),\\n        ]\\n\\n    def process_pr(self, pr_payload: Dict[str, Any]) -> bool:\\n        print(\\"=\\" * 70)\\n        print(f\\"AUTONOMOUS DEPLOYMENT HIGHWAY - PR #{pr_payload.get(\'pr_id\')}: {pr_payload.get(\'title\')}\\")\\n        print(\\"=\\" * 70)\\n\\n        for gate in self.pipeline:\\n            success = gate.evaluate(pr_payload)\\n            if not success:\\n                print(\\"\\\\n\u{1F6A8} PIPELINE HALTED: PR rejected by automated gatekeeper.\\")\\n                print(\\"   Routing counterexample telemetry back to Autonomous Agent Swarm...\\")\\n                return False\\n            time.sleep(0.05)\\n\\n        print(\\"\\\\n\u{1F389} ALL GATES VERIFIED: PROMOTING DIRECTLY TO LIVE PRODUCTION FLEET.\\")\\n        print(\\"   Zero-Human Deployment Complete. Status: LIVE.\\")\\n        print(\\"=\\" * 70)\\n        return True\\n\\n\\nif __name__ == \\"__main__\\":\\n    orchestrator = AutonomousDeploymentOrchestrator()\\n\\n    # Simulate an AI-generated PR that satisfies all mathematical and operational gates\\n    production_ready_pr = {\\n        \\"pr_id\\": 14610,\\n        \\"title\\": \\"Migrate Payment Gateway to Autonomous Micro-Service\\",\\n        \\"has_schema_contract\\": True,\\n        \\"context_tokens\\": 14200,\\n        \\"taint_violations\\": 0,\\n        \\"cyclic_dependencies\\": 0,\\n        \\"pbt_passed\\": True,\\n        \\"smt_proved\\": True,\\n        \\"shadow_diff_count\\": 0,\\n        \\"latency_drift_pct\\": -2.4  # 2.4% faster\\n    }\\n\\n    orchestrator.process_pr(production_ready_pr)\\n```\\n\\n---\\n\\n### 6. Course Retrospective: The 10 Invariants of the Modern Software Developer\\n\\nAs we conclude this 10-week journey through Stanford CS146S, we crystallize the ten enduring laws of modern software development:\\n\\n| Week | Lecture Topic | Enduring Engineering Invariant |\\n| :---: | :--- | :--- |\\n| **#1** | Course Foundations | The developer is a Conductor, not a Typist. Leverage defines impact. |\\n| **#2** | Inside Coding LLMs | Never trust probabilistic completions without deterministic verification. |\\n| **#3** | Model Context Protocol | Standardize tool protocols (Stdio/HTTP) to decouple agents from APIs. |\\n| **#4** | Spec-Driven Dev (SDD) | Invest 80% of effort in precise `SPEC.md` and self-healing test loops. |\\n| **#5** | Multi-Agent Swarms | Separate concerns into Architect, Implementer, and Adversarial Critic. |\\n| **#6** | eBPF Dynamic Tracing | Observe live runtime kernel telemetry to diagnose anomalies before they fail. |\\n| **#7** | Automated Code Review | Enforce AST and taint constraints in CI; reserve LLMs for semantic intent. |\\n| **#8** | AI-Native Architecture | Budget modules to < 32k tokens; eradicate cyclic coupling via AST graphs. |\\n| **#9** | Formal Verification | Empirical tests show bugs; Z3 SMT solvers mathematically prove correctness. |\\n| **#10**| The Autonomous Future | Build zero-human deployment highways; govern fleets with ethical boundaries. |\\n\\n---\\n\\n### \u{1F4CC} 3\u20135 Line Executive Summary\\n1. **The Autonomous Software Factory**: Synthesized the 10-week Stanford CS146S curriculum into zero-human deployment highways governed by five deterministic verification gates.\\n2. **AI Fleet Mesh Orchestration**: Established protocols for coordinating hundreds of concurrent agents using distributed blackboards, tiered compute routing, and Byzantine consensus.\\n3. **Continuous Modernization**: Outlined self-evolving codebases that execute autonomous overnight dependency migrations and eBPF-driven runtime performance hotpatching.\\n4. **The Conductor\'s Destiny**: Defined the elevated role of the human engineer\u2014relieved of syntax typing to focus on problem ontology, ethical boundaries, and strategic systems governance.\\n\\n### References & Stanford CS146S Materials\\n- **Course**: Stanford CS146S (The Modern Software Developer), Fall 2026.\\n- **Instructors**: Dept. of Computer Science, Stanford University.\\n- **Series Complete**: Lectures 1 through 10 fully published and documented on Global Dev Blog."},{"id":"2026-10-30-stanford-cs146s-9","metadata":{"permalink":"/blog/2026-10-30-stanford-cs146s-9","source":"@site/blog/2026-10-30-stanford-cs146s-9/index.md","title":"[Stanford CS146S #9] Autonomous TDD & Formal Verification: Z3 SMT Solvers, Property-Based Invariants, and Mathematical Proofs for AI-Generated Code","description":"Stanford CS146S Lecture 9 in-depth guide: Transcending empirical unit testing with autonomous property-based testing (PBT), symbolic execution, and Z3 SMT solvers to mathematically prove the correctness of AI-generated code.","date":"2026-10-30T00:00:00.000Z","tags":[{"inline":true,"label":"stanford-cs146s","permalink":"/blog/tags/stanford-cs-146-s"},{"inline":true,"label":"autonomous-tdd","permalink":"/blog/tags/autonomous-tdd"},{"inline":true,"label":"formal-verification","permalink":"/blog/tags/formal-verification"},{"inline":true,"label":"z3-smt-solver","permalink":"/blog/tags/z-3-smt-solver"},{"inline":true,"label":"property-based-testing","permalink":"/blog/tags/property-based-testing"},{"inline":true,"label":"software-correctness","permalink":"/blog/tags/software-correctness"},{"inline":true,"label":"symbolic-execution","permalink":"/blog/tags/symbolic-execution"}],"readingTime":8.64,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"2026-10-30-stanford-cs146s-9","title":"[Stanford CS146S #9] Autonomous TDD & Formal Verification: Z3 SMT Solvers, Property-Based Invariants, and Mathematical Proofs for AI-Generated Code","authors":["jbgih"],"tags":["stanford-cs146s","autonomous-tdd","formal-verification","z3-smt-solver","property-based-testing","software-correctness","symbolic-execution"],"date":"2026-10-30T00:00:00.000Z","keywords":["Autonomous Test-Driven Development (ATDD)","Z3 SMT Solver Formal Verification","Property-Based Testing with Hypothesis","Mathematical Proofs for LLM Code","Invariant Synthesis for AI Systems"],"description":"Stanford CS146S Lecture 9 in-depth guide: Transcending empirical unit testing with autonomous property-based testing (PBT), symbolic execution, and Z3 SMT solvers to mathematically prove the correctness of AI-generated code."},"unlisted":false,"prevItem":{"title":"[Stanford CS146S #10] The Future of Software Engineering: Autonomous Agent Swarms, Zero-Human Deployment Pipelines, and Managing AI Fleets at Scale","permalink":"/blog/2026-10-31-stanford-cs146s-10"},"nextItem":{"title":"[Stanford CS146S #8] AI-Native Software Architecture & Refactoring: Decoupling Monoliths, Managing Semantic Debt, and Autonomous Large-Scale Migrations","permalink":"/blog/2026-10-29-stanford-cs146s-8"}},"content":"![Autonomous TDD and Formal Verification with Z3 SMT Solver](./images/09_cs146s_autonomous_tdd_formal_verification.png)\\r\\n\\r\\nWelcome to the ninth installment of our engineering analysis series on **Stanford University\'s CS146S: The Modern Software Developer**.\\r\\n\\r\\nThroughout this curriculum, we have evaluated prompt engineering mechanics (Lecture 2), tool integrations via the Model Context Protocol (Lecture 3), self-healing CI regression loops (Lecture 4), multi-agent swarms (Lecture 5), runtime tracing with eBPF (Lecture 6), AST-guided code reviews (Lecture 7), and AI-native modular architecture (Lecture 8).\\r\\n\\r\\nIn **Lecture 9**, the Stanford curriculum confronts the ultimate dilemma of modern AI engineering: **How can software teams trust non-deterministic, probabilistic foundation models to write mission-critical, zero-defect code in finance, aerospace, cryptography, and distributed systems?**\\r\\n\\r\\nAs Edsger Dijkstra famously observed over fifty years ago: *\\"Program testing can be used to show the presence of bugs, but never to show their absence!\\"* In this lecture, Stanford computer scientists outline the transition from empirical unit testing to **Autonomous Property-Based Testing (PBT)**, **Symbolic Execution**, and **Formal Verification using the Z3 SMT (Satisfiability Modulo Theories) solver**.\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n---\\r\\n\\r\\n### 1. The Limits of Example-Based Testing in the Generative AI Era\\r\\n\\r\\nIn traditional software development, engineers write example-based unit tests:\\r\\n```python\\r\\ndef test_calculate_fee():\\r\\n    assert calculate_fee(100) == 5\\r\\n    assert calculate_fee(0) == 0\\r\\n```\\r\\n\\r\\nWhen autonomous coding agents (Claude Code, Cursor, GitHub Copilot) generate code to satisfy example-based tests, they frequently suffer from **Test Overfitting**:\\r\\n- **Brittle Happy-Path Implementation**: The model writes logic that satisfies the 3 or 4 asserts in the test suite, while failing catastrophically on boundary conditions like negative numbers, empty arrays, integer overflows, or floating-point rounding errors.\\r\\n- **Mock Hallucination**: AI agents frequently modify test assertions or mock signatures rather than fixing underlying algorithmic bugs, creating an illusion of 100% test pass rates.\\r\\n- **Sparse State Space Coverage**: In a function accepting two 64-bit integers, the input domain contains 2^128 possible states. Five unit tests explore approximately $0.00000000000000000000000000000001\\\\%$ of the state space.\\r\\n\\r\\nTo provide genuine reliability guarantees, Stanford CS146S replaces example-based tests with a two-tier verification hierarchy: **Property-Based Testing (empirical fuzzing over algebraic invariants)** and **SMT Formal Verification (mathematical proofs across the entire state space)**.\\r\\n\\r\\n```mermaid\\r\\nflowchart TD\\r\\n    subgraph Traditional [\\"Tier 0: Traditional Example-Based Tests\\"]\\r\\n        E1[\\"Developer writes 3-5 static input/output assertions\\"]\\r\\n        E2[\\"Explores ~0% of the input state space\\"]\\r\\n        E3[\\"AI agents easily overfit or game test assertions\\"]\\r\\n    end\\r\\n\\r\\n    subgraph PBT [\\"Tier 1: Autonomous Property-Based Testing (Hypothesis)\\"]\\r\\n        P1[\\"LLM synthesizes algebraic system properties (Idempotence, Commutativity)\\"]\\r\\n        P2[\\"Fuzzing engine generates 100,000 stochastic edge cases\\"]\\r\\n        P3[\\"Shrinking engine reduces failures to minimal counterexamples\\"]\\r\\n    end\\r\\n\\r\\n    subgraph Formal [\\"Tier 2: Mathematical Formal Verification (Z3 SMT Solver)\\"]\\r\\n        Z1[\\"Translates AST and Specs into First-Order Logic Formulas\\"]\\r\\n        Z2[\\"Z3 Solver proves invariants across 100% infinite state space\\"]\\r\\n        Z3[\\"Returns UNSAT (Mathematically Proved) or SAT (Exact Counterexample)\\"]\\r\\n    end\\r\\n\\r\\n    Traditional --\x3e|\\"Upgraded to\\"| PBT\\r\\n    PBT --\x3e|\\"Elevated to Absolute Proof\\"| Formal\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\n### 2. Tier 1: Property-Based Testing (PBT) & Autonomous Invariant Synthesis\\r\\n\\r\\nInstead of asserting that `f(10) == 20`, **Property-Based Testing (PBT)** asserts algebraic properties that must hold true for *all* inputs within a domain.\\r\\n\\r\\n#### Universal Algebraic Properties for Software\\r\\n1. **Idempotence**: Applying an operation multiple times produces the same result as applying it once:\\r\\n```text\\r\\nf(f(x)) == f(x)    (e.g., payment deduplication, sorting, cache invalidation)\\r\\n```\\r\\n2. **Round-Trip Serialization (Bijection)**: Encoding an object and decoding it returns the identical original object:\\r\\n```text\\r\\ndecode(encode(payload)) == payload    (e.g., protocol buffers, parsers, compression)\\r\\n```\\r\\n3. **Commutativity / Order Invariance**: Order of execution does not alter the terminal outcome:\\r\\n```text\\r\\nprocess(a, b) == process(b, a)    (e.g., batch reconciliation, merge operations)\\r\\n```\\r\\n4. **Metamorphic Invariants**: Known relationships between input transformations and output transformations:\\r\\n```text\\r\\nsize(filter(collection, predicate)) <= size(collection)\\r\\n```\\r\\n\\r\\n#### Counterexample Shrinking\\r\\nWhen a property-based test fails among 100,000 generated inputs, the engine does not present a massive 500-element garbage array. Instead, algorithms like **Hypothesis Shrinking** systematically prune the input until it isolates the **minimal reproducible counterexample** (e.g., `x = 0` or `input = [-1]`).\\r\\n\\r\\nThe autonomous agent receives this minimal counterexample in its prompt context, instantly pinpointing the root-cause edge case.\\r\\n\\r\\n---\\r\\n\\r\\n### 3. Tier 2: Formal Verification with Z3 SMT Solver\\r\\n\\r\\nWhile Property-Based Testing tests thousands of pseudo-random inputs, it remains an empirical method. In safety-critical systems, we seek **formal mathematical verification**: proving that an invariant holds over the entire unbounded input space.\\r\\n\\r\\n```mermaid\\r\\nsequenceDiagram\\r\\n    autonumber\\r\\n    actor Dev as Systems Architect\\r\\n    participant LLM as Autonomous Coder LLM\\r\\n    participant Trans as Symbolic AST Translator\\r\\n    participant Z3 as Z3 SMT Theorem Prover\\r\\n    participant CI as Verified Release CI\\r\\n\\r\\n    Dev->>LLM: Natural Language Spec & Security Invariants\\r\\n    LLM->>LLM: Synthesize Implementation Code & Contract Assertions\\r\\n    LLM->>Trans: Export AST & Pre/Post Conditions\\r\\n    Trans->>Z3: Formulate First-Order Logic Formula (Code & NOT Spec)\\r\\n    Z3->>Z3: Search for Satisfiability (SMT DPLL(T) Engine)\\r\\n    alt Z3 returns SAT (Counterexample Found)\\r\\n        Z3--\x3e>LLM: Violation Found: Counterexample {balance=0, withdrawal=-2147483648}\\r\\n        LLM->>LLM: Self-Heal Implementation: Patch Integer Underflow\\r\\n        LLM->>Trans: Re-submit Patched AST\\r\\n    else Z3 returns UNSAT (Mathematically Proved)\\r\\n        Z3--\x3e>CI: Theorem Proved: Zero Invariant Violations for all inputs\\r\\n        CI--\x3e>Dev: Verified Correct-by-Construction Binary\\r\\n    end\\r\\n```\\r\\n\\r\\n#### How Z3 SMT Provers Work\\r\\nZ3, developed by Microsoft Research, is a high-performance **Satisfiability Modulo Theories (SMT)** solver. It evaluates first-order logic formulas combining booleans, bit-vectors, integers, reals, arrays, and uninterpreted functions.\\r\\n\\r\\nTo formally verify a function $F$ against specification $S$:\\r\\n1. Encode the execution semantics of $F$ as a logical formula `Phi_code(X, Y)`, where $Y = F(X)$.\\r\\n2. Encode the negation of the safety specification `NOT Psi_spec(X, Y)`.\\r\\n3. Check the satisfiability of the conjunction:\\r\\n```text\\r\\nFormula = Phi_code(X, Y) AND NOT Psi_spec(X, Y)\\r\\n```\\r\\n- **If UNSAT**: There is no input $X$ that can ever cause $F(X)$ to violate `Psi_spec`. The code is **mathematically proven correct**.\\r\\n- **If SAT**: Z3 produces a concrete variable assignment (a counterexample model) proving precisely how the code fails.\\r\\n\\r\\n---\\r\\n\\r\\n### 4. Executable Implementation: Formal Verification Harness with Z3\\r\\n\\r\\nBelow is an end-to-end Python script using Microsoft\u2019s `z3-solver` library. It formalizes a high-frequency financial account withdrawal engine with credit limits and fee caps, proves its mathematical correctness, and demonstrates how Z3 captures hidden edge cases that human unit tests overlook.\\r\\n\\r\\n```python\\r\\n\\"\\"\\"\\r\\nz3_formal_verifier.py\\r\\nStanford CS146S - Autonomous Formal Verification Toolkit\\r\\nFormally verifies safety invariants for financial transaction logic\\r\\nusing Microsoft Z3 SMT Solver. Proves absence of integer underflows,\\r\\noverdraft violations, and fee invariant breaches.\\r\\n\\"\\"\\"\\r\\n\\r\\nfrom z3 import (\\r\\n    Int,\\r\\n    Bool,\\r\\n    And,\\r\\n    Or,\\r\\n    Not,\\r\\n    Implies,\\r\\n    Solver,\\r\\n    sat,\\r\\n    unsat,\\r\\n    BitVec,\\r\\n    BitVecVal\\r\\n)\\r\\n\\r\\n\\r\\ndef verify_account_withdrawal_logic():\\r\\n    \\"\\"\\"\\r\\n    Formal Specification:\\r\\n    1. Account balance cannot drop below credit limit: balance - withdrawal - fee >= -credit_limit\\r\\n    2. Fee structure: 2% of withdrawal, but capped at $50 and minimum $1.\\r\\n    3. Withdrawal must be strictly positive.\\r\\n    4. Balance, credit_limit, and withdrawal are 32-bit signed integers (BitVec(32)).\\r\\n    \\"\\"\\"\\r\\n    print(\\"=\\" * 70)\\r\\n    print(\\"STANFORD CS146S: FORMAL VERIFICATION ENGINE (Z3 SMT SOLVER)\\")\\r\\n    print(\\"=\\" * 70)\\r\\n\\r\\n    # Define symbolic bit-vector variables (modeling exact 32-bit machine arithmetic)\\r\\n    balance = BitVec(\'balance\', 32)\\r\\n    credit_limit = BitVec(\'credit_limit\', 32)\\r\\n    withdrawal = BitVec(\'withdrawal\', 32)\\r\\n    fee = BitVec(\'fee\', 32)\\r\\n    new_balance = BitVec(\'new_balance\', 32)\\r\\n\\r\\n    # Preconditions (Assumptions on valid environment inputs)\\r\\n    preconditions = And(\\r\\n        withdrawal > BitVecVal(0, 32),\\r\\n        credit_limit >= BitVecVal(0, 32),\\r\\n        credit_limit <= BitVecVal(50000, 32),  # $500.00 max overdraft credit\\r\\n        fee >= BitVecVal(100, 32),             # $1.00 min fee (in cents)\\r\\n        fee <= BitVecVal(5000, 32)             # $50.00 max fee cap (in cents)\\r\\n    )\\r\\n\\r\\n    # Imperative implementation under test (naive AI-generated calculation)\\r\\n    # total_deduction = withdrawal + fee\\r\\n    # new_balance = balance - total_deduction\\r\\n    total_deduction = withdrawal + fee\\r\\n    implementation_semantics = (new_balance == balance - total_deduction)\\r\\n\\r\\n    # Postcondition Invariant (Safety Goal to mathematically prove)\\r\\n    # If the transaction is approved, new_balance MUST be >= -credit_limit\\r\\n    transaction_approved = (balance + credit_limit >= total_deduction)\\r\\n    safety_invariant = Implies(\\r\\n        transaction_approved,\\r\\n        new_balance >= -credit_limit\\r\\n    )\\r\\n\\r\\n    # Verification Query: Can we find ANY input where preconditions hold,\\r\\n    # implementation runs, BUT safety invariant is VIOLATED?\\r\\n    # Query: Preconditions AND Semantics AND NOT(Safety Invariant)\\r\\n    solver = Solver()\\r\\n    solver.add(preconditions)\\r\\n    solver.add(implementation_semantics)\\r\\n    solver.add(Not(safety_invariant))\\r\\n\\r\\n    print(\\"\\\\n[Query 1] Verifying 32-bit Signed Machine Arithmetic Safety...\\")\\r\\n    result = solver.check()\\r\\n\\r\\n    if result == sat:\\r\\n        model = solver.model()\\r\\n        print(\\"\u274C VERIFICATION FAILED: Z3 discovered a counterexample!\\")\\r\\n        print(\\"   The implementation suffers from Bit-Vector Integer Overflow/Underflow.\\")\\r\\n        print(f\\"   - Input balance      : {model[balance]}\\")\\r\\n        print(f\\"   - Input withdrawal   : {model[withdrawal]}\\")\\r\\n        print(f\\"   - Input fee          : {model[fee]}\\")\\r\\n        print(f\\"   - Input credit_limit : {model[credit_limit]}\\")\\r\\n        print(f\\"   - Calculated new_bal : {model[new_balance]}\\")\\r\\n    else:\\r\\n        print(\\"\u2705 VERIFICATION PASSED (UNSAT): Mathematically proved over 100% of 32-bit input space!\\")\\r\\n\\r\\n    # Now let\'s test a patched version with checked arithmetic guards\\r\\n    print(\\"\\\\n[Query 2] Verifying Patched Engine with Explicit Overflow Guards...\\")\\r\\n    solver_patched = Solver()\\r\\n\\r\\n    # Patched Precondition: Guard against integer overflow in total_deduction\\r\\n    # We require withdrawal <= 10000000 ($100,000) and balance within valid range\\r\\n    overflow_guards = And(\\r\\n        withdrawal <= BitVecVal(10000000, 32),\\r\\n        balance >= -credit_limit,\\r\\n        balance <= BitVecVal(100000000, 32)\\r\\n    )\\r\\n\\r\\n    solver_patched.add(preconditions)\\r\\n    solver_patched.add(overflow_guards)\\r\\n    solver_patched.add(implementation_semantics)\\r\\n    solver_patched.add(Not(safety_invariant))\\r\\n\\r\\n    result_patched = solver_patched.check()\\r\\n    if result_patched == unsat:\\r\\n        print(\\"\u2705 VERIFICATION PASSED (UNSAT): Patched implementation is MATHEMATICALLY SOUND.\\")\\r\\n        print(\\"   No possible input combination in 2^128 domain can violate the overdraft invariant.\\")\\r\\n    else:\\r\\n        print(\\"\u274C Still vulnerable:\\", solver_patched.model())\\r\\n\\r\\n    print(\\"=\\" * 70)\\r\\n\\r\\n\\r\\nif __name__ == \\"__main__\\":\\r\\n    verify_account_withdrawal_logic()\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\n### 5. Key Lecture Takeaways & Next Steps\\r\\n\\r\\n1. **Example-Based Tests Fail in the AI Era**: LLMs easily overfit sparse unit tests. Genuine reliability requires checking invariants across infinite inputs rather than checking 5 arbitrary values.\\r\\n2. **Combine PBT and SMT Solvers**: Deploy Property-Based Testing (Hypothesis) for high-velocity stochastic boundary fuzzing, and reserve Z3 SMT formal verification for safety-critical domain cores.\\r\\n3. **Automate the CEGAR Self-Healing Loop**: Feed SMT counterexample models directly back into the LLM prompt context to synthesize mathematically sound, correct-by-construction code patches.\\r\\n\\r\\nIn **Lecture 10 (The Capstone Finale)**, we will explore **The Future of the Software Engineer: Autonomous Engineering Teams, Zero-Human Deployment Pipelines, and Managing AI Software Fleets at Scale**.\\r\\n\\r\\n---\\r\\n\\r\\n### \u{1F4CC} 3\u20135 Line Executive Summary\\r\\n1. **The Fallacy of Example-Based Testing**: Unpacked why generative AI coding tools overfit to sparse unit test assertions while failing catastrophically on unstated boundary conditions.\\r\\n2. **Autonomous Property-Based Testing**: Formalized algebraic invariants (idempotence, round-trip symmetry, commutativity) and automated counterexample shrinking with Hypothesis.\\r\\n3. **Z3 SMT Formal Verification**: Demonstrated how to convert code semantics into first-order logic formulas, proving absolute invariant satisfaction (UNSAT) across 100% of the input state space.\\r\\n4. **CEGAR Autonomous Self-Healing**: Established a closed-loop pipeline where SMT counterexamples are fed back to LLM agents for deterministic, mathematically sound vulnerability repair.\\r\\n\\r\\n### References & Stanford CS146S Materials\\r\\n- **Course**: Stanford CS146S (The Modern Software Developer), Fall 2026.\\r\\n- **Instructors**: Dept. of Computer Science, Stanford University.\\r\\n- **Related Tools**: Microsoft Z3 Theorem Prover, Hypothesis PBT, Coq, TLA+, QuickCheck, Dafny."},{"id":"2026-10-29-stanford-cs146s-8","metadata":{"permalink":"/blog/2026-10-29-stanford-cs146s-8","source":"@site/blog/2026-10-29-stanford-cs146s-8/index.md","title":"[Stanford CS146S #8] AI-Native Software Architecture & Refactoring: Decoupling Monoliths, Managing Semantic Debt, and Autonomous Large-Scale Migrations","description":"Stanford CS146S Lecture 8 in-depth breakdown: Architecting systems for autonomous AI agents, eliminating semantic debt, decomposing legacy monoliths via AST dependency graphs, and orchestrating zero-downtime automated code migrations.","date":"2026-10-29T00:00:00.000Z","tags":[{"inline":true,"label":"stanford-cs146s","permalink":"/blog/tags/stanford-cs-146-s"},{"inline":true,"label":"ai-native-architecture","permalink":"/blog/tags/ai-native-architecture"},{"inline":true,"label":"software-refactoring","permalink":"/blog/tags/software-refactoring"},{"inline":true,"label":"semantic-debt","permalink":"/blog/tags/semantic-debt"},{"inline":true,"label":"monolith-decoupling","permalink":"/blog/tags/monolith-decoupling"},{"inline":true,"label":"autonomous-migration","permalink":"/blog/tags/autonomous-migration"},{"inline":true,"label":"code-modernization","permalink":"/blog/tags/code-modernization"}],"readingTime":10.58,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"2026-10-29-stanford-cs146s-8","title":"[Stanford CS146S #8] AI-Native Software Architecture & Refactoring: Decoupling Monoliths, Managing Semantic Debt, and Autonomous Large-Scale Migrations","authors":["jbgih"],"tags":["stanford-cs146s","ai-native-architecture","software-refactoring","semantic-debt","monolith-decoupling","autonomous-migration","code-modernization"],"date":"2026-10-29T00:00:00.000Z","keywords":["AI-Native Software Architecture","Automated Monolith Decoupling","Semantic Debt Mitigation","AST-Guided Large-Scale Refactoring","Autonomous Code Migration LLMs"],"description":"Stanford CS146S Lecture 8 in-depth breakdown: Architecting systems for autonomous AI agents, eliminating semantic debt, decomposing legacy monoliths via AST dependency graphs, and orchestrating zero-downtime automated code migrations."},"unlisted":false,"prevItem":{"title":"[Stanford CS146S #9] Autonomous TDD & Formal Verification: Z3 SMT Solvers, Property-Based Invariants, and Mathematical Proofs for AI-Generated Code","permalink":"/blog/2026-10-30-stanford-cs146s-9"},"nextItem":{"title":"[Stanford CS146S #7] Automated Code Review at Scale: AST-Aware Linters, Security Taint Analysis, and Autonomous LLM PR Reviewers","permalink":"/blog/2026-10-28-stanford-cs146s-7"}},"content":"![AI-Native Software Architecture and Large-Scale Refactoring](./images/08_cs146s_ai_native_architecture_refactoring.png)\\r\\n\\r\\nWelcome to the eighth installment of our comprehensive engineering series analyzing **Stanford University\'s CS146S: The Modern Software Developer**.\\r\\n\\r\\nIn the prior sessions, we evaluated how individual developers prompt coding LLMs (Lecture 2), integrate external tools via the Model Context Protocol (Lecture 3), engineer self-healing test harnesses (Lecture 4), coordinate multi-agent swarms (Lecture 5), profile runtime anomalies with eBPF (Lecture 6), and automate PR code reviews using AST linters and taint analysis (Lecture 7). \\r\\n\\r\\nIn **Lecture 8**, the curriculum confronts the systemic, long-term consequence of deploying high-velocity AI agents into production repositories: **How do we design software architectures that AI agents can navigate, reason about, and modify without collapsing under the weight of runaway complexity? And how do we employ AI agents to safely refactor and decouple legacy monolithic codebases?**\\r\\n\\r\\nAs engineering teams scale AI agent adoption, they quickly discover that traditional software architectures\u2014characterized by massive shared mutable states, implicit cyclic dependencies, and sprawling 100,000-line monoliths\u2014severely bottleneck LLM reasoning. In this lecture, Stanford computer scientists formalize the concept of **Semantic Debt**, define the foundational tenets of **AI-Native Architecture**, and provide a battle-tested blueprint for **AST-guided automated monolith decoupling**.\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n---\\r\\n\\r\\n### 1. The Velocity Paradox: Technical Debt vs. Semantic Debt\\r\\n\\r\\nTraditional software engineering metrics evaluate codebase health through the lens of **Technical Debt**: outdated library dependencies, unoptimized database queries, missing unit test coverage, and code smells. Compilers, static linters, and runtime APMs detect technical debt with deterministic precision.\\r\\n\\r\\nWhen autonomous AI coding agents enter the development lifecycle, velocity explodes: features that once took days are implemented in minutes. However, this unchecked velocity introduces an insidious failure mode: **Semantic Debt**.\\r\\n\\r\\n```mermaid\\r\\nflowchart TD\\r\\n    subgraph Technical_Debt [\\"Traditional Technical Debt\\"]\\r\\n        T1[\\"Compiler Warnings & Syntax Smells\\"]\\r\\n        T2[\\"Outdated Library Dependencies\\"]\\r\\n        T3[\\"Missing Test Coverage & Slow Queries\\"]\\r\\n    end\\r\\n\\r\\n    subgraph Semantic_Debt [\\"AI-Accelerated Semantic Debt\\"]\\r\\n        S1[\\"Syntactically Pristine Code That Hallucinates Domain Invariants\\"]\\r\\n        S2[\\"Implicit Context Drift & Leaky Domain Boundaries\\"]\\r\\n        S3[\\"Circular Cross-Module Coupling Hidden Behind Facades\\"]\\r\\n        S4[\\"Context Window Bloat: LLMs Paralyzed by Intertwined Subsystems\\"]\\r\\n    end\\r\\n\\r\\n    Technical_Debt -.->|\\"Deterministic Linters Catch Early\\"| PASS[\\"Detected in CI/CD\\"]\\r\\n    Semantic_Debt ==>|\\"Silently Accumulates Across PRs\\"| CRISIS[\\"Architectural Collapse & Agent Paralysis\\"]\\r\\n```\\r\\n\\r\\n#### What is Semantic Debt?\\r\\nSemantic debt occurs when code generated by an LLM is syntactically flawless and satisfies local unit tests, but silently violates global system invariants, creates implicit coupling, or fragments domain logic across disconnected files:\\r\\n1. **Context Window Saturation**: An agent refactoring an order processing service cannot reason about side effects because order cancellation logic is subtly intertwined across billing, inventory, and notification modules through cyclic database calls.\\r\\n2. **Concept Fragmentation**: Three different LLM-assisted developers implement user status validation in three distinct ways across the codebase (e.g., enum comparison, bitmask flag, and boolean helper), creating conceptual divergence.\\r\\n3. **Ghost Abstractions**: AI agents frequently introduce shallow wrapper classes or leaky abstractions to satisfy immediate prompt instructions without understanding the underlying domain boundary.\\r\\n\\r\\nLeft unchecked, semantic debt degrades the codebase until even advanced reasoning models (Claude 3.7 Sonnet, GPT-4.5) experience context paralysis, generating hallucinated patches that break adjacent services.\\r\\n\\r\\n---\\r\\n\\r\\n### 2. The Four Invariants of AI-Native Software Architecture\\r\\n\\r\\nTo make a software repository permanently maintainable by both human engineers and autonomous AI agents, Stanford CS146S proposes **AI-Native Architecture**. \\r\\n\\r\\nAn AI-native architecture is not simply a system that *uses* AI; it is a system **designed from the ground up to be observed, modified, and verified by autonomous AI agents**.\\r\\n\\r\\n```mermaid\\r\\nflowchart LR\\r\\n    subgraph Principles [\\"The 4 Invariants of AI-Native Architecture\\"]\\r\\n        direction TB\\r\\n        P1[\\"1. Context Budgeting (<32k Tokens/Module)\\"]\\r\\n        P2[\\"2. Strict Schema Contracts (Pydantic / gRPC / Zod)\\"]\\r\\n        P3[\\"3. Deterministic Functional Isolation (Hexagonal Architecture)\\"]\\r\\n        P4[\\"4. Self-Validating Characterization Suites\\"]\\r\\n    end\\r\\n\\r\\n    subgraph Autonomous_Agent [\\"Autonomous AI Agent\\"]\\r\\n        direction TB\\r\\n        A1[\\"Reads Module Specification\\"]\\r\\n        A2[\\"Operates Within Strict Context Limit\\"]\\r\\n        A3[\\"Generates Correct-by-Construction Code\\"]\\r\\n        A4[\\"Validates Against Invariant Tests\\"]\\r\\n    end\\r\\n\\r\\n    Principles ==> Autonomous_Agent\\r\\n```\\r\\n\\r\\n#### Invariant 1: Strict Context Budgeting\\r\\nHuman working memory is limited to roughly $7 \\\\pm 2$ concepts; an LLM\u2019s effective attention degrades when reasoning across millions of tokens with high needle-in-haystack distraction. An AI-native architecture enforces **Strict Context Budgeting**:\\r\\n- Every cohesive module, service, or bounded context must be fully understandable within **32k tokens** of context, including its interfaces, models, and tests.\\r\\n- If an agent requires reading more than 32k tokens to reliably implement a feature or fix a bug in a component, that component violates architectural boundaries and must be decomposed.\\r\\n\\r\\n#### Invariant 2: Explicit Machine-Readable Contracts\\r\\nHuman developers tolerate ambiguous natural language documentation; AI agents do not. AI-native systems replace free-text API docs with strict, machine-enforceable schemas:\\r\\n- **TypeScript / Zod** or **Python / Pydantic** models for all internal data exchange.\\r\\n- **Protocol Buffers (Protobuf)** or **OpenAPI 3.1** specifications defining immutable boundaries.\\r\\n- Pre-conditions, post-conditions, and invariant assertions baked into data structures.\\r\\n\\r\\n#### Invariant 3: Hexagonal Isolation (Ports & Adapters)\\r\\nAI agents excel at algorithmic logic and pure data transformation, but frequently introduce regressions when handling side-effectful external I/O (raw database connections, third-party REST APIs, global singletons). \\r\\n- **Core Domain Logic** must remain pure and free from I/O dependencies.\\r\\n- **Adapters** isolate database queries, message queues, and external APIs behind strongly typed interfaces (\\"Ports\\").\\r\\n- When refactoring domain logic, the AI agent operates strictly within the pure functional core, leaving external adapters untouched.\\r\\n\\r\\n#### Invariant 4: Characterization Test Harnesses (Golden Masters)\\r\\nBefore allowing an AI agent to refactor a mission-critical subsystem, the system must generate a **Golden Master Characterization Test Harness**. By capturing thousands of real-world inputs and recording deterministic output snapshots, the harness establishes an empirical truth that prevents semantic drift during autonomous migration.\\r\\n\\r\\n---\\r\\n\\r\\n### 3. AST-Guided Monolith Decoupling: The Strangler Fig Pattern Reimagined\\r\\n\\r\\nHow do engineering organizations transition massive, 10-year-old enterprise monoliths into clean, AI-native modular systems? Stanford CS146S rejects manual human rewrites\u2014which take years and usually fail\u2014in favor of **AST-Guided Autonomous Decoupling**.\\r\\n\\r\\n```mermaid\\r\\nsequenceDiagram\\r\\n    autonumber\\r\\n    actor Dev as Staff Engineer\\r\\n    participant AST as AST Call-Graph Analyzer\\r\\n    participant Agent as Autonomous Refactor LLM\\r\\n    participant Sandbox as Shadow Dual-Run Sandbox\\r\\n    participant Prod as Production Traffic Gate\\r\\n\\r\\n    Dev->>AST: Target Monolith Subsystem (e.g., BillingService)\\r\\n    AST->>AST: Build Call Graph & Detect Cyclic Dependencies\\r\\n    AST--\x3e>Dev: Graph Report & Decoupling Boundaries\\r\\n    Dev->>Agent: Prompt: Extract BillingService to Isolated Module\\r\\n    Agent->>Agent: Generate Interface Adapter & Extract Domain Logic\\r\\n    Agent->>Sandbox: Deploy Refactored Module in Shadow Mode\\r\\n    Sandbox->>Sandbox: Compare Legacy vs. Refactored Outputs (10,000 requests)\\r\\n    Sandbox--\x3e>Dev: Invariant Verification: 100% Match\\r\\n    Dev->>Prod: Shift 100% Traffic to Modularized Service & Delete Legacy Code\\r\\n```\\r\\n\\r\\n#### Step 1: AST Call-Graph Analysis & SCC Decomposition\\r\\nBefore touching any code, an automated tool parses the Abstract Syntax Tree (AST) of the repository to construct a directed dependency graph $G = (V, E)$, where vertices $V$ represent functions and classes, and edges $E$ represent invocations and import statements.\\r\\n\\r\\nUsing **Tarjan\'s Strongly Connected Components (SCC) algorithm**, the analyzer detects cyclic dependencies that bind subsystems together. Cyclic loops (e.g., `Module A -> Module B -> Module A`) must be broken first by introducing event buses or inversion-of-control dependency injection.\\r\\n\\r\\n#### Step 2: Automated Facade & Interface Extraction\\r\\nThe autonomous LLM generates an explicit Interface Facade between the monolithic core and the target extraction candidate. All direct function invocations are routed through the facade.\\r\\n\\r\\n#### Step 3: Shadow Dual-Run Verification\\r\\nIn high-reliability engineering environments, refactored code is never deployed directly to live users. Instead, a **Shadow Proxy** duplicates incoming production read requests, executing both the legacy monolithic code path and the AI-refactored modular path concurrently:\\r\\n- If outputs match across $100,000$ live requests with identical latency characteristics, the refactored module is promoted.\\r\\n- If a discrepancy occurs, the runtime difference is captured as a regression test case, and the LLM receives the diff to self-heal its implementation.\\r\\n\\r\\n---\\r\\n\\r\\n### 4. Executable Implementation: AST Dependency Graph & Cycle Detector\\r\\n\\r\\nBelow is a production-grade Python utility implementing AST call-graph extraction, cycle detection, and context token estimation. This tool serves as the foundational scanner used by AI refactoring agents to identify decomposition candidates in monolithic repositories.\\r\\n\\r\\n```python\\r\\n\\"\\"\\"\\r\\nast_dependency_analyzer.py\\r\\nStanford CS146S - Autonomous Architectural Refactoring Toolkit\\r\\nAnalyzes Python codebases, extracts module dependency call graphs,\\r\\ndetects cyclic coupling via Tarjan\'s SCC algorithm, and calculates\\r\\ntoken context budgets for AI-native modularity.\\r\\n\\"\\"\\"\\r\\n\\r\\nimport ast\\r\\nimport os\\r\\nimport sys\\r\\nfrom typing import Dict, Set, List, Tuple\\r\\nfrom collections import defaultdict\\r\\n\\r\\n\\r\\nclass DependencyVisitor(ast.NodeVisitor):\\r\\n    def __init__(self, current_module: str):\\r\\n        self.current_module = current_module\\r\\n        self.dependencies: Set[str] = set()\\r\\n\\r\\n    def visit_Import(self, node: ast.Import):\\r\\n        for alias in node.names:\\r\\n            self.dependencies.add(alias.name.split(\'.\')[0])\\r\\n        self.generic_visit(node)\\r\\n\\r\\n    def visit_ImportFrom(self, node: ast.ImportFrom):\\r\\n        if node.module:\\r\\n            self.dependencies.add(node.module.split(\'.\')[0])\\r\\n        self.generic_visit(node)\\r\\n\\r\\n\\r\\nclass CodebaseGraphAnalyzer:\\r\\n    def __init__(self, root_dir: str):\\r\\n        self.root_dir = root_dir\\r\\n        self.graph: Dict[str, Set[str]] = defaultdict(set)\\r\\n        self.module_token_estimates: Dict[str, int] = {}\\r\\n\\r\\n    def scan_codebase(self) -> None:\\r\\n        \\"\\"\\"Traverse directory, parse ASTs, and map dependency graph.\\"\\"\\"\\r\\n        for root, _, files in os.walk(self.root_dir):\\r\\n            for file in files:\\r\\n                if file.endswith(\'.py\') and not file.startswith(\'__\'):\\r\\n                    filepath = os.path.join(root, file)\\r\\n                    rel_path = os.path.relpath(filepath, self.root_dir)\\r\\n                    module_name = rel_path.replace(os.path.sep, \'.\').replace(\'.py\', \'\')\\r\\n\\r\\n                    try:\\r\\n                        with open(filepath, \'r\', encoding=\'utf-8\') as f:\\r\\n                            content = f.read()\\r\\n                            # Rough token approximation: 1 token ~ 4 characters\\r\\n                            self.module_token_estimates[module_name] = len(content) // 4\\r\\n                            tree = ast.parse(content, filename=filepath)\\r\\n\\r\\n                        visitor = DependencyVisitor(module_name)\\r\\n                        visitor.visit(tree)\\r\\n\\r\\n                        for dep in visitor.dependencies:\\r\\n                            # Filter only internal module dependencies\\r\\n                            if dep != module_name and os.path.exists(os.path.join(self.root_dir, dep + \'.py\')):\\r\\n                                self.graph[module_name].add(dep)\\r\\n                    except Exception as err:\\r\\n                        print(f\\"Warning: Failed to parse {filepath}: {err}\\", file=sys.stderr)\\r\\n\\r\\n    def find_strongly_connected_components(self) -> List[List[str]]:\\r\\n        \\"\\"\\"Tarjan\'s algorithm for detecting cyclic dependency clusters.\\"\\"\\"\\r\\n        index = 0\\r\\n        indices: Dict[str, int] = {}\\r\\n        lowlinks: Dict[str, int] = {}\\r\\n        on_stack: Dict[str, bool] = defaultdict(bool)\\r\\n        stack: List[str] = []\\r\\n        sccs: List[List[str]] = []\\r\\n\\r\\n        nodes = list(self.graph.keys())\\r\\n        for node in self.graph:\\r\\n            for dep in self.graph[node]:\\r\\n                if dep not in nodes:\\r\\n                    nodes.append(dep)\\r\\n\\r\\n        def strongconnect(node: str):\\r\\n            nonlocal index\\r\\n            indices[node] = index\\r\\n            lowlinks[node] = index\\r\\n            index += 1\\r\\n            stack.append(node)\\r\\n            on_stack[node] = True\\r\\n\\r\\n            for successor in self.graph.get(node, []):\\r\\n                if successor not in indices:\\r\\n                    strongconnect(successor)\\r\\n                    lowlinks[node] = min(lowlinks[node], lowlinks[successor])\\r\\n                elif on_stack[successor]:\\r\\n                    lowlinks[node] = min(lowlinks[node], indices[successor])\\r\\n\\r\\n            if lowlinks[node] == indices[node]:\\r\\n                scc = []\\r\\n                while True:\\r\\n                    w = stack.pop()\\r\\n                    on_stack[w] = False\\r\\n                    scc.append(w)\\r\\n                    if w == node:\\r\\n                        break\\r\\n                if len(scc) > 1:\\r\\n                    sccs.append(scc)\\r\\n\\r\\n        for node in nodes:\\r\\n            if node not in indices:\\r\\n                strongconnect(node)\\r\\n\\r\\n        return sccs\\r\\n\\r\\n    def evaluate_ai_native_readiness(self, max_context_tokens: int = 8000) -> None:\\r\\n        \\"\\"\\"Report modularity metrics and semantic debt risks.\\"\\"\\"\\r\\n        print(\\"=\\" * 70)\\r\\n        print(\\"STANFORD CS146S - AI-NATIVE ARCHITECTURE READINESS REPORT\\")\\r\\n        print(\\"=\\" * 70)\\r\\n\\r\\n        sccs = self.find_strongly_connected_components()\\r\\n        if sccs:\\r\\n            print(f\\"\u26A0\uFE0F  WARNING: Detected {len(sccs)} Cyclic Dependency Cluster(s)!\\")\\r\\n            for idx, cycle in enumerate(sccs, 1):\\r\\n                print(f\\"   Cluster #{idx} (Must decouple before agent refactoring):\\")\\r\\n                print(f\\"   --\x3e {\' <---\x3e \'.join(cycle)}\\")\\r\\n        else:\\r\\n            print(\\"\u2705 Clean Architecture: Zero cyclic dependencies detected.\\")\\r\\n\\r\\n        print(\\"\\\\n\u{1F4CA} Context Budget Analysis (Target: < 8,000 tokens per module):\\")\\r\\n        oversized_modules = []\\r\\n        for mod, tokens in sorted(self.module_token_estimates.items(), key=lambda x: x[1], reverse=True):\\r\\n            status = \\"\u2705 PASS\\" if tokens <= max_context_tokens else \\"\u274C OVERBUDGET (Semantic Debt Risk)\\"\\r\\n            print(f\\" - {mod:<35} : ~{tokens:>5} tokens [{status}]\\")\\r\\n            if tokens > max_context_tokens:\\r\\n                oversized_modules.append((mod, tokens))\\r\\n\\r\\n        if oversized_modules:\\r\\n            print(f\\"\\\\n\u{1F6A8} Recommendation: {len(oversized_modules)} module(s) exceed single-prompt context budgets.\\")\\r\\n            print(\\"   Decompose using Strangler Fig Pattern before delegating autonomous edits.\\")\\r\\n        print(\\"=\\" * 70)\\r\\n\\r\\n\\r\\nif __name__ == \\"__main__\\":\\r\\n    current_workspace = os.path.dirname(os.path.abspath(__file__))\\r\\n    analyzer = CodebaseGraphAnalyzer(current_workspace)\\r\\n    analyzer.scan_codebase()\\r\\n    analyzer.evaluate_ai_native_readiness()\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\n### 5. Key Lecture Takeaways & Next Steps\\r\\n\\r\\n1. **Beware the Velocity Trap**: Generating fast code without architectural invariants leads directly to **Semantic Debt**, where LLM agents eventually hallucinate and stall due to context saturation.\\r\\n2. **Design for Agent Cognition**: Restructure codebases into AI-native modules bounded by strict context budgets (< 32k tokens), machine-readable contracts (Pydantic/Protobuf), and pure functional cores.\\r\\n3. **Automate Monolith Decomposition with AST Graphs**: Never attempt monolithic refactoring blindly. Parse AST dependency trees, eliminate cyclic SCC loops, and use shadow dual-run sandboxes to verify behavioral equivalence.\\r\\n\\r\\nIn **Lecture 9**, we will explore **Autonomous Test-Driven Development (ATDD) & Formal Verification: Synthesizing Z3 SMT Solver Constraints and Property-Based Invariant Suites for LLM-Engineered Systems**.\\r\\n\\r\\n---\\r\\n\\r\\n### \u{1F4CC} 3\u20135 Line Executive Summary\\r\\n1. **The Emergence of Semantic Debt**: Identified how unchecked AI coding velocity silently compromises architectural invariants, creates hidden coupling, and saturates LLM context windows.\\r\\n2. **The 4 Invariants of AI-Native Architecture**: Established strict design standards\u2014context budgeting (< 32k tokens), explicit schema contracts, hexagonal functional isolation, and golden master test harnesses.\\r\\n3. **AST-Guided Monolith Decoupling**: Replaced risky manual rewrites with automated AST call-graph decomposition, Tarjan cyclic dependency detection, and zero-downtime shadow dual-run verification.\\r\\n4. **Autonomous Refactoring Toolkit**: Provided an executable Python analyzer that scans repositories, isolates cyclic clusters, and calculates token context budgets for agent-driven refactoring.\\r\\n\\r\\n### References & Stanford CS146S Materials\\r\\n- **Course**: Stanford CS146S (The Modern Software Developer), Fall 2026.\\r\\n- **Instructors**: Dept. of Computer Science, Stanford University.\\r\\n- **Related Tools**: Python AST, Tarjan SCC Algorithm, ArchUnit, Pydantic, Zod, OpenTelemetry, Docusaurus MDX."},{"id":"2026-10-28-stanford-cs146s-7","metadata":{"permalink":"/blog/2026-10-28-stanford-cs146s-7","source":"@site/blog/2026-10-28-stanford-cs146s-7/index.md","title":"[Stanford CS146S #7] Automated Code Review at Scale: AST-Aware Linters, Security Taint Analysis, and Autonomous LLM PR Reviewers","description":"In Lecture 7 of Stanford CS146S (The Modern Software Developer), explore how to scale engineering quality through automated code review. Discover how to combine Abstract Syntax Tree (AST) linters, static taint analysis, and semantic LLM PR reviewers to eliminate nitpicks and catch critical architectural regressions.","date":"2026-10-28T00:00:00.000Z","tags":[{"inline":true,"label":"stanford","permalink":"/blog/tags/stanford"},{"inline":true,"label":"cs146s","permalink":"/blog/tags/cs-146-s"},{"inline":true,"label":"code-review","permalink":"/blog/tags/code-review"},{"inline":true,"label":"static-analysis","permalink":"/blog/tags/static-analysis"},{"inline":true,"label":"ast","permalink":"/blog/tags/ast"},{"inline":true,"label":"taint-analysis","permalink":"/blog/tags/taint-analysis"},{"inline":true,"label":"llm-pr-review","permalink":"/blog/tags/llm-pr-review"},{"inline":true,"label":"devops","permalink":"/blog/tags/devops"},{"inline":true,"label":"security","permalink":"/blog/tags/security"}],"readingTime":8.26,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"2026-10-28-stanford-cs146s-7","title":"[Stanford CS146S #7] Automated Code Review at Scale: AST-Aware Linters, Security Taint Analysis, and Autonomous LLM PR Reviewers","authors":["jbgih"],"tags":["stanford","cs146s","code-review","static-analysis","ast","taint-analysis","llm-pr-review","devops","security"],"date":"2026-10-28T00:00:00.000Z","keywords":["Automated Code Review at Scale","AST-Aware Static Analysis","Security Taint Analysis LLM","Autonomous Pull Request Reviewer","Continuous Integration AI Guardrails"],"description":"In Lecture 7 of Stanford CS146S (The Modern Software Developer), explore how to scale engineering quality through automated code review. Discover how to combine Abstract Syntax Tree (AST) linters, static taint analysis, and semantic LLM PR reviewers to eliminate nitpicks and catch critical architectural regressions."},"unlisted":false,"prevItem":{"title":"[Stanford CS146S #8] AI-Native Software Architecture & Refactoring: Decoupling Monoliths, Managing Semantic Debt, and Autonomous Large-Scale Migrations","permalink":"/blog/2026-10-29-stanford-cs146s-8"},"nextItem":{"title":"[Stanford CS146S #6] AI-Assisted Debugging & Runtime Profiling: Leveraging eBPF, Dynamic Tracing, and LLMs for Incident Mitigation","permalink":"/blog/2026-10-27-stanford-cs146s-6"}},"content":"![Automated Code Review at Scale Architecture](./images/07_cs146s_code_review_at_scale.png)\\n\\nWelcome to Lecture 7 of our deep-dive series covering **Stanford University\u2019s CS146S: The Modern Software Developer**. \\n\\nIn our previous lecture, we tackled runtime production incidents using eBPF non-intrusive kernel tracing and AI SRE diagnostic hotpatching. Yet, as every seasoned engineering leader knows, the most cost-effective bug is the one that **never merges into the mainline branch in the first place**.\\n\\nIn high-velocity software engineering organizations, the Pull Request (PR) code review is the primary gatekeeper of software quality, architectural integrity, and security. However, as engineering teams scale, human code review inevitably degenerates into a massive operational bottleneck. Senior engineers spend 15 to 20 hours a week reviewing diffs, burning cognitive bandwidth on trivial stylistic nitpicks (indentation, naming conventions, import ordering) while suffering from **review fatigue** on massive 1,000-line changes\u2014inevitably waving through insidious concurrency races, SQL injections, and architectural boundary violations.\\n\\nIn today\u2019s lecture, Stanford faculty unveil the blueprint for **Automated Code Review at Scale**. By constructing a three-tier review hierarchy that couples **Abstract Syntax Tree (AST) linters**, **Inter-procedural Security Taint Analysis**, and **Autonomous LLM PR Reviewers**, modern engineering teams can eliminate 90% of manual code review toil while drastically increasing vulnerability detection rates.\\n\\n{/* truncate */}\\n\\n---\\n\\n### 1. The Code Review Crisis: The Limits of Human Peer Review\\n\\nWhy does traditional human code review break down as repositories scale across dozens of distributed squads?\\n\\nStanford researchers identify three fundamental failure modes in human-only review pipelines:\\n\\n```mermaid\\nflowchart TD\\n    subgraph Human_Review_Failure [\\"The Failure Modes of Human Peer Review at Scale\\"]\\n        A1[\\"The Bikeshedding Trap\\"] --\x3e A2[\\"Engineers debate stylistic minutiae (variable names, braces)\\"]\\n        A2 --\x3e A3[\\"High Review Latency: PR sits unmerged for 3 days awaiting nitpick fixes\\"]\\n        \\n        B1[\\"Cognitive Fatigue on Large PRs\\"] --\x3e B2[\\"Reviewing 10 lines: 10 comments.<br/>Reviewing 1,000 lines: \'LGTM\' (Looks Good To Me)\\"]\\n        B2 --\x3e B3[\\"Silent Escape: Critical security flaws and race conditions slip into main\\"]\\n        \\n        C1[\\"Context Blindness\\"] --\x3e C2[\\"Reviewers look only at git diff snippets, not whole call graphs\\"]\\n        C2 --\x3e C3[\\"Architectural Drift: Cross-service abstraction boundaries breached silently\\"]\\n    end\\n\\n    subgraph Automated_TriTier_Solution [\\"Stanford CS146S Tri-Tier Automated Review Pipeline\\"]\\n        D1[\\"Tier 1: AST-Aware Linters (Zero-Cost Syntax & Boundary Defense)\\"]\\n        D2[\\"Tier 2: Static Taint Analysis (Source-to-Sink Security Auditing)\\"]\\n        D3[\\"Tier 3: Autonomous LLM Reviewer (Semantic Intent, Design & Test Verification)\\"]\\n        D1 --\x3e D2 --\x3e D3\\n    end\\n```\\n\\n1. **Bikeshedding & Stylistic Friction**: Humans are psychologically predisposed to comment on trivial, easily digestible details rather than deeply analyzing complex distributed invariants. This creates adversarial friction between developers and inflates PR turnaround time.\\n2. **Review Fatigue & The 500-Line Threshold**: Empirical software engineering studies show that human defect detection accuracy plummets exponentially once a PR exceeds 400 lines of code. At 1,000 lines, reviewers suffer cognitive exhaustion and reflexively stamp \\"LGTM\\", allowing catastrophic regressions to slip into production.\\n3. **Diff Myopia & Context Blindness**: A standard GitHub PR diff only displays 3 to 5 lines of surrounding context. Reviewers cannot mentally trace whether a modified parameter breaks an invariant five function calls upstream in a different package.\\n\\n---\\n\\n### 2. The Tri-Tier Automated Code Review Architecture\\n\\nTo liberate human engineers from mechanical chores and establish bulletproof quality gates, Stanford CS146S establishes the **Tri-Tier Review Hierarchy**:\\n\\n```mermaid\\nflowchart TD\\n    PR[\\"Developer Submits GitHub Pull Request\\"] --\x3e Tier1[\\"Tier 1: AST-Aware Syntactic Linters<br/>(Biome, Ruff, Tree-sitter, Semgrep)\\"]\\n\\n    subgraph Fast_Deterministic_Gate [\\"Sub-Second Deterministic Gates\\"]\\n        Tier1 --\x3e|Failed: Style / Banned Imports / Dead Code| Block1[\\"Instant CI Failure (Inline Fix Suggestions)\\"]\\n        Tier1 --\x3e|Passed| Tier2[\\"Tier 2: Inter-Procedural Taint Analysis<br/>(Semgrep Taint, CodeQL, Flow Graph)\\"]\\n    end\\n\\n    subgraph Security_Gate [\\"Deep Security Dataflow Auditing\\"]\\n        Tier2 --\x3e|Untrusted Source reached Unsanitized Sink| Block2[\\"Block PR: Critical CVE / SQL Injection / XSS Alert\\"]\\n        Tier2 --\x3e|Passed Clean| Tier3[\\"Tier 3: Autonomous LLM Semantic Reviewer<br/>(Intent Validation, Edge Cases & Performance)\\"]\\n    end\\n\\n    subgraph Semantic_Gate [\\"High-Level LLM Reasoning\\"]\\n        Tier3 --\x3e|Semantic Issues / Missing Edge-Case Tests| Comment[\\"Post GitHub PR Inline Review with Diff Patches\\"]\\n        Tier3 --\x3e|All Invariants Verified| Approve[\\"Automated LGTM & Green CI Merge Approval\\"]\\n    end\\n```\\n\\n#### Detailed Breakdown of the Three Tiers:\\n1. **Tier 1: AST-Aware Syntactic Linters (Execution Time: < 500ms)**\\n   - **Tools**: Tree-sitter, Biome, Ruff, Semgrep OSS.\\n   - **Responsibility**: AST-level pattern matching for syntax validation, style formatting, dead code elimination, and boundary rules (e.g., forbidding UI components from directly importing database ORM models).\\n   - **Golden Rule**: **Humans must never comment on anything an AST linter can check.** If a stylistic comment is made in a human PR review, it constitutes an engineering failure to encode that rule into Tier 1.\\n2. **Tier 2: Inter-Procedural Security Taint Analysis (Execution Time: 5s \u2013 30s)**\\n   - **Tools**: Semgrep Pro, CodeQL, custom static analysis dataflow engines.\\n   - **Responsibility**: Tracking untrusted user input (\\"Sources\\" such as HTTP request query parameters or headers) through call graphs to dangerous execution endpoints (\\"Sinks\\" such as `exec()`, raw SQL queries, or deserializers).\\n   - **Enforcement**: If a taint path lacks a mathematically verified \\"Sanitizer\\" function along its trajectory, the PR is blocked unconditionally.\\n3. **Tier 3: Autonomous LLM Semantic Reviewer (Execution Time: 15s \u2013 60s)**\\n   - **Engines**: Claude 3.5 Sonnet, GPT-4o, fine-tuned code review LLMs.\\n   - **Responsibility**: Evaluating high-level semantic intent, business logic edge cases, concurrency hazards, backwards compatibility, and unit test coverage completeness.\\n   - **Output**: Concrete, executable GitHub suggested diff blocks (`suggestion`) that developers can apply with a single click.\\n\\n---\\n\\n### 3. Security Taint Analysis: Mathematical Foundations\\n\\nIn Tier 2, how does static analysis formally guarantee that user input cannot exploit vulnerabilities?\\n\\nStanford CS146S formalizes taint tracking using **Bounded Lattice Dataflow Analysis**:\\n\\n```latex\\nS --(Dataflow Edge e)--\x3e T\\nwhere Taint(T) = Clean   if f_sanitizer(x) in Path(S, T)\\n                 Tainted otherwise\\n```\\n\\n```mermaid\\nflowchart LR\\n    Source[\\"Source (Untrusted)<br/>req.body.searchQuery\\"] --\x3e|Propagation| VarA[\\"let query = searchQuery.trim()\\"]\\n    VarA --\x3e|Dataflow| Sanitizer{\\"Is Sanitizer Present?<br/>e.g., db.escape()\\"}\\n    \\n    Sanitizer --\x3e|No (Direct String Concatenation)| Sink[\\"Sink (Vulnerable Endpoint)<br/>db.raw(\'SELECT * FROM users WHERE name = \' + query)\\"]\\n    Sink --\x3e Alert[\\"CRITICAL SECURITY ALERT: SQL Injection Vulnerability\\"]\\n    \\n    Sanitizer --\x3e|Yes (Parameterized Binding)| SafeSink[\\"Safe Sink<br/>db.query(\'SELECT * FROM users WHERE name = $1\', [query])\\"]\\n```\\n\\n#### The LLM Augmentation for Taint Analysis:\\nTraditional static taint analyzers struggle with **custom sanitizers** (e.g., a proprietary regex sanitizer or encoding helper), generating frustrating false positives. In modern Stanford-grade pipelines, when a static analyzer detects an ambiguous taint path, it dispatches the candidate code snippet to an LLM verifier asking: *\\"Does this custom sanitizer function correctly neutralize SQL injection across all Unicode representations?\\"*\\n\\n---\\n\\n### 4. Implementation: Building an Autonomous GitHub PR Review Bot\\n\\nBelow is a complete, production-grade GitHub Pull Request review bot in Python. It parses incoming unified git diffs, executes AST boundary checks, and invokes an LLM to generate actionable inline review comments:\\n\\n```python\\n# pr_review_bot.py - Autonomous Multi-Tier Pull Request Review Engine\\nimport asyncio\\nimport os\\nfrom typing import List, Optional\\nfrom pydantic import BaseModel, Field\\n\\nclass InlineReviewComment(BaseModel):\\n    file_path: str\\n    line_number: int\\n    severity: str = Field(pattern=\\"^(CRITICAL|WARNING|SUGGESTION)$\\")\\n    critique: str\\n    suggested_diff: Optional[str] = None\\n\\nclass PRReviewSummary(BaseModel):\\n    pr_id: int\\n    verdict: str = Field(pattern=\\"^(APPROVE|REQUEST_CHANGES|COMMENT)$\\")\\n    architectural_summary: str\\n    inline_comments: List[InlineReviewComment]\\n\\nclass AutonomousPRReviewer:\\n    def __init__(self, llm_client, semgrep_runner):\\n        self.llm = llm_client\\n        self.semgrep = semgrep_runner\\n\\n    async def review_pull_request(self, pr_id: int, pr_diff: str, repo_context: str) -> PRReviewSummary:\\n        print(f\\"[PR-BOT] Starting review for PR #{pr_id}...\\")\\n\\n        # Step 1: Run Tier 1 & 2 AST and Taint Analysis via Semgrep\\n        print(\\"[PR-BOT] Executing Tier 1 & Tier 2 AST Taint Analysis...\\")\\n        taint_findings = await self.semgrep.run_taint_audit(pr_diff)\\n        \\n        # Step 2: Formulate Structured LLM Semantic Review Prompt\\n        system_prompt = \\"\\"\\"\\n        You are a Principal Software Architect conducting a rigorous GitHub PR review.\\n        Adhere strictly to the Stanford CS146S review doctrine:\\n        1. Ignore formatting, whitespace, and stylistic nitpicks (already enforced by linters).\\n        2. Scrutinize concurrency race conditions, edge-case null states, performance regressions (O(N^2) loops), and architectural drift.\\n        3. For every identified defect, provide an actionable inline GitHub suggestion block with valid replacement code.\\n        \\"\\"\\"\\n\\n        user_prompt = f\\"\\"\\"\\n        [PULL REQUEST #{pr_id} DIFF]\\n        {pr_diff}\\n\\n        [STATIC TAINT ANALYSIS FINDINGS]\\n        {taint_findings}\\n\\n        [SYSTEM REPOSITORY ARCHITECTURE CONTEXT]\\n        {repo_context}\\n\\n        Evaluate the PR and return a structured JSON response matching PRReviewSummary.\\n        \\"\\"\\"\\n\\n        print(\\"[PR-BOT] Executing Tier 3 Semantic LLM Review...\\")\\n        review_result: PRReviewSummary = await self.llm.generate_structured(\\n            system_prompt=system_prompt,\\n            user_prompt=user_prompt,\\n            schema=PRReviewSummary\\n        )\\n\\n        return review_result\\n\\n    def post_to_github(self, review: PRReviewSummary):\\n        \\"\\"\\"Simulates publishing review comments to GitHub PR API.\\"\\"\\"\\n        print(f\\"\\\\n================ [GITHUB PR #{review.pr_id} VERDICT: {review.verdict}] ================\\")\\n        print(f\\"Summary: {review.architectural_summary}\\\\n\\")\\n        for comment in review.inline_comments:\\n            print(f\\"[{comment.severity}] {comment.file_path}:{comment.line_number}\\")\\n            print(f\\"Comment: {comment.critique}\\")\\n            if comment.suggested_diff:\\n                print(\\"Suggested Replacement:\\")\\n                print(comment.suggested_diff)\\n            print(\\"-\\" * 60)\\n```\\n\\n---\\n\\n### 5. Key Lecture Takeaways & Next Steps\\n\\n1. **Humans Should Never Linter-Check**: Enforce all stylistic, syntactic, and structural import constraints at Tier 1 using sub-second AST linters (tree-sitter, Semgrep).\\n2. **Formalize Security with Taint Analysis**: Prevent vulnerabilities before they merge by tracking untrusted dataflow paths from user sources to execution sinks using mathematical lattice analysis.\\n3. **Elevate LLMs to Semantic Architects**: Use LLM reviewers not as grammar checkers, but as adversarial senior partners that verify business logic correctness, evaluate concurrency safety, and supply instant executable patch diffs.\\n\\nIn **Lecture 8**, we will explore **AI-Native Software Architecture & Refactoring: Decoupling Monoliths, Managing Semantic Debt, and Autonomous Large-Scale Migrations**.\\n\\n---\\n\\n### \u{1F4CC} 3\u20135 Line Executive Summary\\n1. **The Code Review Scaling Dilemma**: Solved human peer review failure modes\u2014bikeshedding, review fatigue on large diffs, and diff myopia\u2014by engineering a 3-tier automated review pipeline.\\n2. **Tier 1 & 2 AST and Taint Enforcement**: Automated stylistic and syntax rules via sub-second AST parsers, while deploying source-to-sink taint analysis to mathematically block injection vulnerabilities.\\n3. **Autonomous Semantic LLM Reviewers**: Leveraged LLMs as high-level architectural reviewers that evaluate business logic invariants, concurrency races, and generate self-contained inline code suggestions.\\n4. **Developer Experience Acceleration**: Reduced PR merge turnaround time by up to 70% while improving security defect catch rates by offloading mechanical nitpicks to automated CI gates.\\n\\n### References & Stanford CS146S Materials\\n- **Course**: Stanford CS146S (The Modern Software Developer), Fall 2026.\\n- **Instructors**: Dept. of Computer Science, Stanford University.\\n- **Related Tools**: Tree-sitter, Semgrep, CodeQL, Biome, GitHub Copilot PR Reviewer, Anthropic Claude PR Protocols."},{"id":"2026-10-27-stanford-cs146s-6","metadata":{"permalink":"/blog/2026-10-27-stanford-cs146s-6","source":"@site/blog/2026-10-27-stanford-cs146s-6/index.md","title":"[Stanford CS146S #6] AI-Assisted Debugging & Runtime Profiling: Leveraging eBPF, Dynamic Tracing, and LLMs for Incident Mitigation","description":"In Lecture 6 of Stanford CS146S (The Modern Software Developer), explore how combining extended Berkeley Packet Filters (eBPF) with LLM diagnostic agents transforms runtime debugging. Learn how non-intrusive kernel tracing feeds real-time telemetry to AI SREs for automated root-cause analysis and live incident mitigation.","date":"2026-10-27T00:00:00.000Z","tags":[{"inline":true,"label":"stanford","permalink":"/blog/tags/stanford"},{"inline":true,"label":"cs146s","permalink":"/blog/tags/cs-146-s"},{"inline":true,"label":"ebpf","permalink":"/blog/tags/ebpf"},{"inline":true,"label":"dynamic-tracing","permalink":"/blog/tags/dynamic-tracing"},{"inline":true,"label":"ai-debugging","permalink":"/blog/tags/ai-debugging"},{"inline":true,"label":"incident-response","permalink":"/blog/tags/incident-response"},{"inline":true,"label":"site-reliability-engineering","permalink":"/blog/tags/site-reliability-engineering"},{"inline":true,"label":"linux-kernel","permalink":"/blog/tags/linux-kernel"}],"readingTime":7.11,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"2026-10-27-stanford-cs146s-6","title":"[Stanford CS146S #6] AI-Assisted Debugging & Runtime Profiling: Leveraging eBPF, Dynamic Tracing, and LLMs for Incident Mitigation","authors":["jbgih"],"tags":["stanford","cs146s","ebpf","dynamic-tracing","ai-debugging","incident-response","site-reliability-engineering","linux-kernel"],"date":"2026-10-27T00:00:00.000Z","keywords":["AI-Assisted Runtime Debugging","eBPF Dynamic Tracing LLM","Autonomous Incident Mitigation","Kernel Observability AI SRE","Production Performance Profiling"],"description":"In Lecture 6 of Stanford CS146S (The Modern Software Developer), explore how combining extended Berkeley Packet Filters (eBPF) with LLM diagnostic agents transforms runtime debugging. Learn how non-intrusive kernel tracing feeds real-time telemetry to AI SREs for automated root-cause analysis and live incident mitigation."},"unlisted":false,"prevItem":{"title":"[Stanford CS146S #7] Automated Code Review at Scale: AST-Aware Linters, Security Taint Analysis, and Autonomous LLM PR Reviewers","permalink":"/blog/2026-10-28-stanford-cs146s-7"},"nextItem":{"title":"[Stanford CS146S #5] Multi-Agent Systems & Swarm Orchestration: Coordinating Autonomous Architect, Implementer, and Critic LLMs","permalink":"/blog/2026-10-26-stanford-cs146s-5"}},"content":"![AI-Assisted Debugging and eBPF Dynamic Tracing Architecture](./images/06_cs146s_ai_debugging_ebpf.png)\\n\\nWelcome to Lecture 6 of our deep-dive series covering **Stanford University\u2019s CS146S: The Modern Software Developer**. \\n\\nIn our preceding lecture, we explored multi-agent swarm orchestration\u2014coordinating Architect, Implementer, and Critic LLMs through structured DAG workflows to write massive modular codebases. Yet, even the most rigorously tested software eventually encounters the chaotic crucible of production. \\n\\nAt 3:00 AM, when an obscure concurrency deadlock freezes a distributed payment cluster or an unindexed database query causes tail latency to spike to 12 seconds, traditional developer debugging workflows collapse. Static analysis cannot predict dynamic race conditions, invasive `printf` debugging introduces the **Heisenbug effect** (altering timing and masking the bug), and distributed APM tracing tools drown Site Reliability Engineers (SREs) in gigabytes of unstructured log noise.\\n\\nIn today\'s lecture, Stanford faculty unveil the next frontier in autonomous software resilience: **AI-Assisted Debugging & Runtime Profiling**. By combining the zero-overhead, non-intrusive power of **extended Berkeley Packet Filters (eBPF)** with specialized **LLM Diagnostic SRE Agents**, modern engineering teams can capture kernel-level execution states in real-time, perform automated root-cause identification, and synthesize hotfixes in minutes rather than hours.\\n\\n{/* truncate */}\\n\\n---\\n\\n### 1. The Production Incident Crisis: Why Traditional Debugging Fails\\n\\nWhen high-throughput microservices fail under load, software engineers face three fundamental observability paradoxes:\\n\\n```mermaid\\nflowchart TD\\n    subgraph Traditional_Failure [\\"The Failure Modes of Traditional Production Triage\\"]\\n        A1[\\"Invasive Print / Debugging Hooks\\"] --\x3e A2[\\"Heisenbug Effect: Timing changes, bug disappears under instrumentation\\"]\\n        \\n        B1[\\"Distributed APM & Log Aggregation\\"] --\x3e B2[\\"Log Blindness: Millions of JSON lines/sec drown the critical root-cause trace\\"]\\n        B2 --\x3e B3[\\"Context Saturation: Humans cannot correlate cross-pod thread states\\"]\\n        \\n        C1[\\"Post-Mortem Core Dumps\\"] --\x3e C2[\\"High Downtime: Service must crash completely to capture memory state\\"]\\n        C2 --\x3e C3[\\"Zero Runtime Mitigation: Customers experience outage during triage\\"]\\n    end\\n\\n    subgraph AI_eBPF_Solution [\\"Stanford CS146S Paradigm: Zero-Overhead AI SRE\\"]\\n        D1[\\"Kernel-Level eBPF Probes\\"] --\x3e D2[\\"Zero-overhead non-intrusive bytecode tracing\\"]\\n        D2 --\x3e D3[\\"LLM SRE Engine: Automated causal graph synthesis & hotpatching\\"]\\n    end\\n```\\n\\n1. **The Heisenbug Dilemma**: Injecting logging code or attaching interactive debuggers (`gdb`, `lldb`) pauses threads, shifts lock acquisition order, and dilutes CPU caches, frequently making elusive race conditions vanish during investigation.\\n2. **Telemetry Deluge vs. Semantic Blindness**: Modern observability pipelines collect petabytes of metrics, traces, and logs. However, when an incident triggers 45 cascading alerts simultaneously, engineers waste hours determining which alert is the primary cause and which 44 are downstream symptoms.\\n3. **The Semantic Gap Between Kernel and Application**: High-level application metrics (e.g., \\"HTTP 504 Gateway Timeout\\") offer zero visibility into whether the root cause is thread pool starvation, TCP socket buffer bloat, or dirty page flushing blockages inside the Linux VFS layer.\\n\\n---\\n\\n### 2. The eBPF Revolution: Non-Intrusive Kernel Observability\\n\\nTo solve the Heisenbug problem, Stanford CS146S leverages **eBPF (extended Berkeley Packet Filter)**. eBPF is a revolutionary Linux kernel technology that allows developers to run sandboxed, verified programs directly within the operating system kernel without modifying kernel source code or loading dangerous kernel modules.\\n\\n```mermaid\\nflowchart TD\\n    subgraph UserSpace [\\"User Space (Applications & Containers)\\"]\\n        AppNode[\\"Payment Microservice Node.js / Go\\"]\\n        AIDaemon[\\"AI SRE Diagnostic Daemon (Python / LLM)\\"]\\n    end\\n\\n    subgraph KernelSpace [\\"Linux Kernel Space (Zero Overhead)\\"]\\n        Kprobe[\\"kprobe: sys_enter_write / sys_enter_futex\\"]\\n        Tracepoint[\\"tracepoint: sched_switch / tcp_retransmit\\"]\\n        RingBuffer[\\"eBPF BPF_MAP_TYPE_RINGBUF<br/>(Lockless Per-CPU Event Streaming)\\"]\\n        \\n        Kprobe & Tracepoint --\x3e|Microsecond Telemetry| RingBuffer\\n    end\\n\\n    RingBuffer --\x3e|Zero-Copy DMA Read| AIDaemon\\n    AIDaemon --\x3e|Root-Cause Analysis & Action Plan| Engineer[\\"SRE Incident Commander\\"]\\n    AIDaemon --\x3e|Optional Automated Hotpatch| AppNode\\n```\\n\\n#### Why eBPF is Essential for AI Debugging:\\n- **Zero Overhead**: eBPF programs are JIT-compiled into native machine instructions with strict safety verification (guaranteed loop termination, zero invalid memory access), imposing less than 1.5% CPU overhead under full line-rate traffic.\\n- **Universal Observability**: By attaching hooks to `kprobes` (kernel function entries), `kretprobes` (kernel function exits), `uprobes` (user-space application symbols), and socket filters, eBPF observes every system call, lock contention event, and network packet across all containers simultaneously.\\n- **Lockless Ring Buffers**: High-frequency kernel events are streamed to user space through lockless per-CPU ring buffers (`BPF_MAP_TYPE_RINGBUF`), preventing tracing overhead from degrading application throughput.\\n\\n---\\n\\n### 3. Bridging the Semantic Gap: Feeding Low-Level Traces to LLM Diagnostic Agents\\n\\nFeeding raw eBPF traces (millions of hexadecimal pointers and nanosecond timestamps) directly into an LLM context window will instantly cause context exhaustion and token hallucination.\\n\\nStanford CS146S formalizes a **Two-Stage Telemetry Distillation Engine**:\\n\\n1. **Deterministic Aggregation & Flame-Graph Folding**:\\n   - The user-space daemon aggregates call stacks into weighted folded formats (e.g., `process;thread;function_A;function_B;futex_wait 450ms`).\\n   - Differential analysis compares healthy baseline trace distributions against incident window distributions to extract statistical anomalies.\\n2. **Causal Graph & Hypothesis Generation**:\\n   - The LLM receives structured, pre-filtered diagnostic inputs: the anomaly delta, the affected microservice source code, and the current Kubernetes pod status.\\n   - Using **Chain-of-Thought (CoT) diagnostic prompting**, the LLM maps low-level kernel blockages back to application logic (e.g., identifying that an unclosed database connection pool is blocking on thread mutex locks).\\n\\n---\\n\\n### 4. Implementation: Building an eBPF Latency Tracer & LLM Remediation Pipeline\\n\\nBelow is a production-grade implementation of an eBPF slow-system-call tracer coupled with an asynchronous LLM incident mitigation engine:\\n\\n```python\\n# ebpf_ai_debugger.py - eBPF Observability & AI Diagnostic SRE Pipeline\\nimport asyncio\\nimport json\\nfrom bcc import BPF\\nfrom pydantic import BaseModel, Field\\nfrom typing import List, Optional\\n\\n# 1. C-based eBPF Kernel Probe Program\\nEBPF_PROGRAM = \\"\\"\\"\\n#include <uapi/linux/ptrace.h>\\n#include <linux/sched.h>\\n\\nstruct event_t {\\n    u32 pid;\\n    u64 latency_ns;\\n    char comm[TASK_COMM_LEN];\\n};\\n\\nBPF_HASH(start_time, u32, u64);\\nBPF_PERF_OUTPUT(latency_events);\\n\\nint trace_sys_enter_write(struct pt_regs *ctx) {\\n    u32 pid = bpf_get_current_pid_tgid() >> 32;\\n    u64 ts = bpf_ktime_get_ns();\\n    start_time.update(&pid, &ts);\\n    return 0;\\n}\\n\\nint trace_sys_exit_write(struct pt_regs *ctx) {\\n    u32 pid = bpf_get_current_pid_tgid() >> 32;\\n    u64 *tsp = start_time.lookup(&pid);\\n    if (tsp == 0) return 0;\\n\\n    u64 delta = bpf_ktime_get_ns() - *tsp;\\n    start_time.delete(&pid);\\n\\n    // Only report slow system calls (> 50ms latency spike)\\n    if (delta > 50000000) {\\n        struct event_t evt = {};\\n        evt.pid = pid;\\n        evt.latency_ns = delta;\\n        bpf_get_current_comm(&evt.comm, sizeof(evt.comm));\\n        latency_events.perf_submit(ctx, &evt, sizeof(evt));\\n    }\\n    return 0;\\n}\\n\\"\\"\\"\\n\\nclass IncidentRemediationPlan(BaseModel):\\n    root_cause: str\\n    culprit_function: str\\n    confidence_score: float = Field(ge=0.0, le=1.0)\\n    remediation_script: str\\n    mitigation_strategy: str\\n\\nclass AIDiagnosticEngine:\\n    def __init__(self, llm_client):\\n        self.llm = llm_client\\n\\n    async def diagnose_and_mitigate(self, event_data: dict, source_context: str) -> IncidentRemediationPlan:\\n        prompt = f\\"\\"\\"\\n        [INCIDENT DIAGNOSTIC ALERT]\\n        Kernel Telemetry: Process \'{event_data[\'comm\']}\' (PID: {event_data[\'pid\']}) \\n        experienced a severe syscall stall: {event_data[\'latency_ms\']:.2f} ms.\\n        \\n        Application Source Context:\\n        {source_context}\\n        \\n        Analyze the root cause (e.g., synchronous disk I/O blocking the event loop, thread deadlock).\\n        Output a structured JSON remediation plan containing root cause, affected function, and a mitigation patch.\\n        \\"\\"\\"\\n        response = await self.llm.generate_structured(prompt, schema=IncidentRemediationPlan)\\n        return response\\n\\nclass eBPFTelemetryMonitor:\\n    def __init__(self, ai_engine: AIDiagnosticEngine):\\n        self.bpf = BPF(text=EBPF_PROGRAM)\\n        self.bpf.attach_kprobe(event=\\"__x64_sys_write\\", fn_name=\\"trace_sys_enter_write\\")\\n        self.bpf.attach_kretprobe(event=\\"__x64_sys_write\\", fn_name=\\"trace_sys_exit_write\\")\\n        self.ai = ai_engine\\n\\n    def handle_event(self, cpu, data, size):\\n        event = self.bpf[\\"latency_events\\"].event(data)\\n        latency_ms = event.latency_ns / 1_000_000.0\\n        print(f\\"[ALERT] Slow write() syscall in {event.comm} (PID: {event.pid}) took {latency_ms:.2f}ms!\\")\\n        \\n        # Async trigger to LLM AI SRE\\n        asyncio.create_task(self.ai.diagnose_and_mitigate(\\n            event_data={\\"comm\\": event.comm, \\"pid\\": event.pid, \\"latency_ms\\": latency_ms},\\n            source_context=\\"// Relevant application controller snippet...\\"\\n        ))\\n\\n    def start_polling(self):\\n        self.bpf[\\"latency_events\\"].open_perf_buffer(self.handle_event)\\n        print(\\"[eBPF MONITOR] Kernel probes active. Monitoring production syscall latency...\\")\\n        while True:\\n            self.bpf.perf_buffer_poll()\\n```\\n\\n---\\n\\n### 5. Key Lecture Takeaways & Next Steps\\n\\n1. **Non-Intrusive Observability is Paramount**: Production debugging cannot rely on print statements or heavy profilers. eBPF provides zero-overhead, kernel-level ground truth.\\n2. **Deterministic Distillation Before LLMs**: Always aggregate and normalize high-frequency trace streams into statistical anomalies and flame-graphs before sending them to LLM diagnostic agents.\\n3. **Closed-Loop SRE Autonomy**: AI agents transform debugging from reactive post-mortems into active, real-time mitigation\u2014detecting tail latency spikes and generating remediation patches in flight.\\n\\nIn **Lecture 7**, we will explore **Code Review at Scale: AST-Aware Automated Linters, Security Taint Analysis, and Autonomous LLM PR Reviewers**.\\n\\n---\\n\\n### \u{1F4CC} 3\u20135 Line Executive Summary\\n1. **The Production Debugging Crisis**: Solved the Heisenbug effect and telemetry deluge by replacing invasive application-level logging with non-intrusive eBPF kernel tracing.\\n2. **Zero-Overhead Kernel Telemetry**: Deployed sandboxed eBPF bytecode hooks (`kprobes`, `tracepoints`) with lockless ring buffers, capturing microsecond-level system call stalls with under 1.5% CPU overhead.\\n3. **Telemetry-to-LLM Distillation Engine**: Filtered high-frequency kernel metrics into flame-graph anomalies and causal graphs, bridging the semantic gap between raw syscalls and application logic.\\n4. **Autonomous Incident Remediation**: Architected an AI SRE pipeline that continuously digests eBPF telemetry, pinpoints root-cause race conditions, and synthesizes automated hotpatches to mitigate live production outages.\\n\\n### References & Stanford CS146S Materials\\n- **Course**: Stanford CS146S (The Modern Software Developer), Fall 2026.\\n- **Instructors**: Dept. of Computer Science, Stanford University.\\n- **Related Technologies**: Linux eBPF/BCC, bpftrace, Cilium, Pixie, OpenTelemetry, LangChain SRE Agents."},{"id":"2026-10-26-stanford-cs146s-5","metadata":{"permalink":"/blog/2026-10-26-stanford-cs146s-5","source":"@site/blog/2026-10-26-stanford-cs146s-5/index.md","title":"[Stanford CS146S #5] Multi-Agent Systems & Swarm Orchestration: Coordinating Autonomous Architect, Implementer, and Critic LLMs","description":"In Lecture 5 of Stanford CS146S (The Modern Software Developer), we examine multi-agent swarm architectures. Discover why single-context LLMs fail on massive codebases, how to coordinate specialized Architect, Implementer, and Critic agents, and how to orchestrate asynchronous DAG workflows with structured schemas.","date":"2026-10-26T00:00:00.000Z","tags":[{"inline":true,"label":"stanford","permalink":"/blog/tags/stanford"},{"inline":true,"label":"cs146s","permalink":"/blog/tags/cs-146-s"},{"inline":true,"label":"multi-agent-systems","permalink":"/blog/tags/multi-agent-systems"},{"inline":true,"label":"swarm-orchestration","permalink":"/blog/tags/swarm-orchestration"},{"inline":true,"label":"llm-agents","permalink":"/blog/tags/llm-agents"},{"inline":true,"label":"software-engineering","permalink":"/blog/tags/software-engineering"},{"inline":true,"label":"distributed-systems","permalink":"/blog/tags/distributed-systems"}],"readingTime":6.65,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"2026-10-26-stanford-cs146s-5","title":"[Stanford CS146S #5] Multi-Agent Systems & Swarm Orchestration: Coordinating Autonomous Architect, Implementer, and Critic LLMs","authors":["jbgih"],"tags":["stanford","cs146s","multi-agent-systems","swarm-orchestration","llm-agents","software-engineering","distributed-systems"],"date":"2026-10-26T00:00:00.000Z","keywords":["Multi-Agent LLM Orchestration","Architect Implementer Critic Pattern","Autonomous Swarm Code Generation","Directed Acyclic Graph DAG Agents","Inter-Agent Communication Protocol"],"description":"In Lecture 5 of Stanford CS146S (The Modern Software Developer), we examine multi-agent swarm architectures. Discover why single-context LLMs fail on massive codebases, how to coordinate specialized Architect, Implementer, and Critic agents, and how to orchestrate asynchronous DAG workflows with structured schemas."},"unlisted":false,"prevItem":{"title":"[Stanford CS146S #6] AI-Assisted Debugging & Runtime Profiling: Leveraging eBPF, Dynamic Tracing, and LLMs for Incident Mitigation","permalink":"/blog/2026-10-27-stanford-cs146s-6"},"nextItem":{"title":"[Stanford CS146S #4] Spec-Driven Code Generation & Test Harnesses: Building Self-Healing Regression Loops with Claude Code & Cursor","permalink":"/blog/stanford-cs146s-4-spec-driven-code-generation-test-harnesses"}},"content":"![Multi-Agent Swarm Orchestration Architecture](./images/05_cs146s_multi_agent_swarm.png)\\n\\nWelcome to Lecture 5 of our deep-dive series covering **Stanford University\u2019s CS146S: The Modern Software Developer**. \\n\\nIn our previous lectures, we mastered developer prompt engineering, dissected the internal transformer mechanics of coding models, explored tool-use with the Model Context Protocol (MCP), and constructed self-healing spec-driven test harnesses. Each of these paradigms operated under a common implicit assumption: a **single primary LLM session** interacting with a single developer or IDE workspace.\\n\\nHowever, once a software project scales beyond a few thousand lines of code across distributed microservices, the single-agent paradigm fractures. Monolithic agents suffer from **context window saturation, attention dilution, and cognitive thrashing**.\\n\\nIn today\u2019s lecture, Stanford faculty unveil the future of AI-native engineering: **Multi-Agent Systems (MAS) and Swarm Orchestration**. We will explore how separating concerns across specialized **Architect, Implementer, and Critic** roles\u2014coordinated over structured message buses and Directed Acyclic Graphs (DAGs)\u2014delivers order-of-magnitude gains in software generation accuracy and codebase scale.\\n\\n{/* truncate */}\\n\\n---\\n\\n### 1. The Scaling Limits of Single-Context Monolithic LLMs\\n\\nWhy can\u2019t we simply hand an entire 500,000-line enterprise repository to a model with a 1-million-token context window and ask it to \\"refactor the payment billing pipeline\\"?\\n\\nStanford researchers identify three fundamental architectural bottlenecks:\\n\\n```mermaid\\nflowchart TD\\n    subgraph Monolithic_Failure [\\"The Bottlenecks of Single-Agent Scaling\\"]\\n        A1[\\"Massive Context Load (500k+ Tokens)\\"] --\x3e A2[\\"Attention Dilution & Needle-in-a-Haystack Degradation\\"]\\n        A2 --\x3e A3[\\"Instruction Drift: LLM forgets early constraints while reading late files\\"]\\n        \\n        B1[\\"Single Agent Role Collusion\\"] --\x3e B2[\\"Self-Confirmation Bias: Generator trusts its own flawed code\\"]\\n        B2 --\x3e B3[\\"Hallucination Lock-in: Critic cannot objectively review its own assumptions\\"]\\n        \\n        C1[\\"Sequential Step Execution\\"] --\x3e C2[\\"High Latency: Single thread processes tasks serially\\"]\\n        C2 --\x3e C3[\\"Context Window Exhaustion: Output token limit reached mid-refactor\\"]\\n    end\\n\\n    subgraph Multi_Agent_Advantage [\\"The Multi-Agent Swarm Solution\\"]\\n        D1[\\"Decomposed Task Graphs (DAG)\\"] --\x3e D2[\\"Specialized Isolated Contexts (10k tokens each)\\"]\\n        D2 --\x3e D3[\\"Parallel Concurrency + Adversarial Verification\\"]\\n    end\\n```\\n\\n1. **Attention Dilution & \'Lost in the Middle\'**: As context windows expand beyond 100k tokens, attention mechanisms exhibit non-uniform retrieval fidelity. Subtle API constraints or database invariants buried in middle files are routinely neglected.\\n2. **Role Collusion & Confirmation Bias**: When a single LLM acts simultaneously as system designer, coder, and quality assurance tester, it suffers from severe confirmation bias. It rarely invents edge cases that expose its own subtle implementation bugs.\\n3. **Context Window Thrashing**: Modifying 15 files sequentially in a single chat session pollutes the context buffer with intermediate bash diffs, compiler errors, and discarded hypotheses, quickly exhausting output token budgets.\\n\\n---\\n\\n### 2. The Tripartite Swarm Architecture: Architect, Implementer, and Critic\\n\\nTo achieve industrial robustness, Stanford CS146S formalizes the **Tripartite Agent Swarm Pattern**. Instead of generalist chatbots, we deploy specialized autonomous agents with strictly isolated responsibilities:\\n\\n```mermaid\\nflowchart TD\\n    UserPRD[\\"User Requirements / PRD\\"] --\x3e Architect[\\"Lead Architect Agent<br/>(System Decomposition & API Schema)\\"]\\n\\n    subgraph Swarm_Coordination [\\"Distributed Agent Swarm\\"]\\n        Architect --\x3e|Task DAG & JSON Contracts| Blackboard[\\"Shared Blackboard / State Memory\\"]\\n        \\n        Blackboard --\x3e WorkerA[\\"Implementer Agent A<br/>(Auth & DB Schema)\\"]\\n        Blackboard --\x3e WorkerB[\\"Implementer Agent B<br/>(Payment Gateway API)\\"]\\n        Blackboard --\x3e WorkerC[\\"Implementer Agent C<br/>(Webhook Event Handler)\\"]\\n        \\n        WorkerA --\x3e|Code Patch & Unit Tests| Critic[\\"Adversarial Critic / Verifier Agent<br/>(Security, Linters & Property Tests)\\"]\\n        WorkerB --\x3e|Code Patch & Unit Tests| Critic\\n        WorkerC --\x3e|Code Patch & Unit Tests| Critic\\n    end\\n\\n    Critic --\x3e|Rejection & Diagnostic Error Trace| WorkerB\\n    Critic --\x3e|Verified & All Checks Passed| PR[\\"Automated GitHub Pull Request\\"]\\n```\\n\\n#### Role Breakdown:\\n1. **The Lead Architect Agent**:\\n   - **Inputs**: User PRD, repository dependency tree, high-level business goals.\\n   - **Outputs**: A Directed Acyclic Graph (DAG) of decoupled implementation subtasks, strict JSON Schema interfaces, and contract definitions.\\n   - **Key Constraint**: The Architect writes zero implementation code. Its entire cognitive budget is dedicated to task breakdown and API interface stability.\\n2. **The Implementer Agents (Swarm Workers)**:\\n   - **Inputs**: A single task slice from the DAG, the API schema contracts, and the localized file tree.\\n   - **Outputs**: Modular source code, unit test cases, and dependency declarations.\\n   - **Execution**: Multiple Implementers operate completely concurrently in sandboxed branches or ephemeral containers.\\n3. **The Adversarial Critic & Verifier Agent**:\\n   - **Inputs**: The candidate code diff, the original Architect specification, and automated test logs.\\n   - **Outputs**: Static analysis metrics, security vulnerability scans (AST audit, secret leaks), and a definitive Pass/Fail judgment.\\n   - **Feedback Mechanism**: Upon failure, the Critic generates an explicit diagnostic diff with stack traces and returns it directly to the offending Implementer for a targeted self-healing cycle.\\n\\n---\\n\\n### 3. Inter-Agent Communication Topologies\\n\\nMulti-agent coordination requires strict communication protocols to prevent swarm hallucinations and infinite message loops. CS146S highlights two dominant orchestration topologies:\\n\\n#### A. Centralized Blackboard Pattern\\nIn the Blackboard pattern, agents do not message each other directly. Instead, they read from and write to a centralized, validated JSON state store:\\n\\n```json\\n{\\n  \\"task_id\\": \\"TASK-402-AUTH\\",\\n  \\"status\\": \\"in_review\\",\\n  \\"dependencies\\": [\\"TASK-401-DB-SCHEMA\\"],\\n  \\"assigned_agent\\": \\"worker-claude-code-01\\",\\n  \\"contract_schema_hash\\": \\"sha256:7f8a92...\\",\\n  \\"artifacts\\": {\\n    \\"patch_path\\": \\"/workspace/patches/auth_service.patch\\",\\n    \\"test_coverage\\": 94.2\\n  },\\n  \\"critic_feedback\\": null\\n}\\n```\\n\\n#### B. Directed Acyclic Graph (DAG) Execution Flow\\nRather than unrestricted conversation, agent tasks are modeled as nodes in a DAG where edges denote data dependencies. If Module B depends on Module A\'s data contract, Implementer B cannot spawn until Implementer A passes Critic verification.\\n\\n---\\n\\n### 4. Implementation: Building an Asynchronous Swarm Orchestrator in Python\\n\\nBelow is a production-grade asynchronous multi-agent orchestrator implementing the Architect-Implementer-Critic loop using Pydantic structured validation:\\n\\n```python\\n# swarm_orchestrator.py - Production Multi-Agent Swarm Engine\\nimport asyncio\\nfrom typing import List, Dict, Optional\\nfrom pydantic import BaseModel, Field\\n\\nclass SubTaskContract(BaseModel):\\n    task_id: str\\n    description: str\\n    file_targets: List[str]\\n    interface_schema: Dict[str, str]\\n\\nclass ArchitectPlan(BaseModel):\\n    plan_title: str\\n    subtasks: List[SubTaskContract]\\n\\nclass PatchResult(BaseModel):\\n    task_id: str\\n    code_diff: str\\n    unit_tests: str\\n\\nclass CriticAudit(BaseModel):\\n    passed: bool\\n    score: float = Field(ge=0.0, le=100.0)\\n    diagnostic_trace: Optional[str] = None\\n\\nclass SwarmOrchestrator:\\n    def __init__(self, architect_llm, coder_llm, critic_llm):\\n        self.architect = architect_llm\\n        self.coder = coder_llm\\n        self.critic = critic_llm\\n\\n    async def execute_task(self, user_prd: str):\\n        print(\\"[ORCHESTRATOR] Step 1: Synthesizing Architecture Plan...\\")\\n        plan: ArchitectPlan = await self.architect.generate_plan(user_prd)\\n        \\n        print(f\\"[ORCHESTRATOR] Architect decomposed PRD into {len(plan.subtasks)} subtasks.\\")\\n        \\n        # Concurrently execute subtasks across parallel Implementer workers\\n        tasks = [self._worker_critic_loop(task) for task in plan.subtasks]\\n        results = await asyncio.gather(*tasks)\\n        \\n        print(\\"[ORCHESTRATOR] All swarm subtasks successfully verified and integrated!\\")\\n        return results\\n\\n    async def _worker_critic_loop(self, task: SubTaskContract, max_retries: int = 3) -> PatchResult:\\n        attempt = 0\\n        error_context = None\\n\\n        while attempt < max_retries:\\n            attempt += 1\\n            print(f\\"[{task.task_id}] Implementer working (Attempt {attempt}/{max_retries})...\\")\\n            \\n            patch: PatchResult = await self.coder.implement_task(task, feedback=error_context)\\n            \\n            print(f\\"[{task.task_id}] Critic auditing patch...\\")\\n            audit: CriticAudit = await self.critic.verify(task, patch)\\n            \\n            if audit.passed:\\n                print(f\\"[{task.task_id}] PASSED verification (Score: {audit.score}/100)!\\")\\n                return patch\\n            \\n            print(f\\"[{task.task_id}] REJECTED by Critic: {audit.diagnostic_trace}\\")\\n            error_context = audit.diagnostic_trace\\n\\n        raise RuntimeError(f\\"Task {task.task_id} failed to pass Critic review after {max_retries} cycles.\\")\\n```\\n\\n---\\n\\n### 5. Key Lecture Takeaways & Next Steps\\n\\n1. **Monolithic Agents Don\'t Scale**: Context window saturation and self-confirmation bias necessitate decomposing software development into modular multi-agent swarms.\\n2. **Tripartite Specialization**: Strictly decouple the **Architect** (system decomposition and interface schemas), the **Implementer** (sandboxed concurrent coding), and the **Critic** (adversarial verification and AST auditing).\\n3. **Structured Coordination**: Rely on Directed Acyclic Graphs (DAGs) and validated JSON Blackboard state stores rather than chaotic free-form conversational chatter.\\n\\nIn **Lecture 6**, we will explore **AI-Assisted Debugging and Profiling: Leveraging eBPF, Dynamic Tracing, and LLMs for Runtime Incident Mitigation**.\\n\\n---\\n\\n### \u{1F4CC} 3\u20135 Line Executive Summary\\n1. **Multi-Agent Scaling Imperative**: Solved monolithic LLM failure modes\u2014attention dilution, instruction drift, and confirmation bias\u2014by replacing single-session prompts with multi-agent swarms.\\n2. **Tripartite Agent Separation**: Formalized the Architect (DAG planning & API contracts), Implementer (concurrent modular coding), and Critic (adversarial testing & security auditing) tripartite workflow.\\n3. **Deterministic Communication Protocols**: Prevented swarm hallucinations through structured Pydantic JSON schemas, centralized Blackboard state stores, and DAG-constrained execution graphs.\\n4. **Resilient Self-Healing Loops**: Architected asynchronous retry loops where Critic diagnostic traces automatically guide Implementer patch refinement until full regression test clearance.\\n\\n### References & Stanford CS146S Materials\\n- **Course**: Stanford CS146S (The Modern Software Developer), Spring/Fall 2026.\\n- **Instructors**: Dept. of Computer Science, Stanford University.\\n- **Related Frameworks**: LangGraph, AutoGen, CrewAI, Anthropic Multi-Agent Orchestration Protocols."},{"id":"stanford-cs146s-4-spec-driven-code-generation-test-harnesses","metadata":{"permalink":"/blog/stanford-cs146s-4-spec-driven-code-generation-test-harnesses","source":"@site/blog/2026-10-25-stanford-cs146s-4/index.md","title":"[Stanford CS146S #4] Spec-Driven Code Generation & Test Harnesses: Building Self-Healing Regression Loops with Claude Code & Cursor","description":"Stanford CS146S Lecture 4 engineering breakdown: Escaping the \'vibe coding\' trap with Spec-Driven Development (SDD), building closed-loop test harnesses, and automating self-healing Red-Green-Refactor cycles with Claude Code and Cursor.","date":"2026-10-25T00:00:00.000Z","tags":[{"inline":true,"label":"stanford-cs146s","permalink":"/blog/tags/stanford-cs-146-s"},{"inline":true,"label":"spec-driven-development","permalink":"/blog/tags/spec-driven-development"},{"inline":true,"label":"test-harness","permalink":"/blog/tags/test-harness"},{"inline":true,"label":"self-healing-code","permalink":"/blog/tags/self-healing-code"},{"inline":true,"label":"claude-code","permalink":"/blog/tags/claude-code"},{"inline":true,"label":"cursor","permalink":"/blog/tags/cursor"},{"inline":true,"label":"software-engineering","permalink":"/blog/tags/software-engineering"},{"inline":true,"label":"regression-testing","permalink":"/blog/tags/regression-testing"}],"readingTime":8.69,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"stanford-cs146s-4-spec-driven-code-generation-test-harnesses","title":"[Stanford CS146S #4] Spec-Driven Code Generation & Test Harnesses: Building Self-Healing Regression Loops with Claude Code & Cursor","authors":["jbgih"],"tags":["stanford-cs146s","spec-driven-development","test-harness","self-healing-code","claude-code","cursor","software-engineering","regression-testing"],"date":"2026-10-25T00:00:00.000Z","keywords":["Spec-Driven Development","Test Harness for AI Coding","Self-Healing Code Generation","Claude Code Automated Testing","LLM Regression Verification"],"description":"Stanford CS146S Lecture 4 engineering breakdown: Escaping the \'vibe coding\' trap with Spec-Driven Development (SDD), building closed-loop test harnesses, and automating self-healing Red-Green-Refactor cycles with Claude Code and Cursor."},"unlisted":false,"prevItem":{"title":"[Stanford CS146S #5] Multi-Agent Systems & Swarm Orchestration: Coordinating Autonomous Architect, Implementer, and Critic LLMs","permalink":"/blog/2026-10-26-stanford-cs146s-5"},"nextItem":{"title":"[Stanford CS146S #3] Model Context Protocol (MCP) & Autonomous Tool Use: The Universal Language Server Architecture for AI Agents","permalink":"/blog/stanford-cs146s-3-mcp-tool-use-architecture"}},"content":"![Spec-Driven Code Generation and Self-Healing Test Harness](./images/04_cs146s_spec_driven_test_harness.png)\\n\\nWelcome to the fourth installment of our comprehensive engineering series analyzing **Stanford University\'s CS146S: The Modern Software Developer**.\\n\\nIn Lecture 1, we examined the modern developer stack. In Lecture 2, we unmasked the probabilistic mechanics of coding LLMs. In Lecture 3, we explored the Model Context Protocol (MCP) as the universal connective tissue for autonomous agents. Now, in **Lecture 4 (Week 3)**, the Stanford curriculum addresses the greatest pragmatic challenge facing AI-assisted software teams today: **How do we reliably build complex, multi-thousand-line systems when LLMs inevitably hallucinate, introduce silent regressions, and drift from product requirements?**\\n\\nThe industry\'s naive solution\u2014popularized on social media as \\"vibe coding\\" or conversational prompt-and-pray\u2014fails completely in mission-critical environments. Drawing directly from Stanford\'s software engineering laboratory experiments, this lecture outlines **Spec-Driven Development (SDD)** and demonstrates how to build an automated **Test Harness** with **Self-Healing Feedback Loops** using modern tools like Claude Code and Cursor.\\n\\n{/* truncate */}\\n\\n---\\n\\n### 1. The Fallacy of \\"Vibe Coding\\": Why Prompting Without Specs Inevitably Decays\\n\\nWhen developers interact with AI agents using conversational prompts alone, system entropy increases monotonically with every conversation turn:\\n\\n```mermaid\\nflowchart TD\\n    subgraph Vibe_Coding_Entropy [\\"The Anti-Pattern: Conversational Vibe Coding\\"]\\n        V1[\\"Vague Prompt: \'Add payment checkout\'\\"] --\x3e V2[\\"LLM Generates 300 Lines of Code\\"]\\n        V2 --\x3e V3[\\"Developer Eyeballs Output (Looks plausible)\\"]\\n        V3 --\x3e V4[\\"Merge to Main\\"]\\n        V4 --\x3e V5[\\"Next Prompt: \'Add discount coupons\'\\"]\\n        V5 --\x3e V6[\\"LLM Silently Overwrites Payment State Machine\\"]\\n        V6 --\x3e V7[\\"Catastrophic Production Regression\\"]\\n    end\\n\\n    subgraph Spec_Driven_Determinism [\\"Stanford CS146S: Spec-Driven Development (SDD)\\"]\\n        S1[\\"Formal Specification (PRD / Interface Contract)\\"] --\x3e S2[\\"Deterministic Acceptance Test Suite (Harness)\\"]\\n        S2 --\x3e S3[\\"AI Code Generation (Claude Code / Cursor)\\"]\\n        S3 --\x3e S4[\\"Automated Test Execution (Red/Green)\\"]\\n        S4 --\x3e|Fail: Emits Traceback| S5[\\"Self-Healing Feedback Loop (Agent Fixes Diff)\\"]\\n        S4 --\x3e|Pass: All Invariants Validated| S6[\\"Zero-Regression Production Merge\\"]\\n    end\\n```\\n\\nThe fundamental flaw of \\"vibe coding\\" stems from **cognitive offloading without semantic constraints**:\\n1. **Context Window Forgetting**: As chat histories exceed 20,000 tokens, LLMs drop subtle negative constraints (e.g., *\\"never alter the idempotency key format\\"*).\\n2. **The Illusion of Fluency**: Syntactically elegant code often conceals boundary-condition failure modes (e.g., race conditions, unhandled null pointers, off-by-one errors).\\n3. **Cascading Regressions**: A prompt modifying Module A inadvertently breaks assumptions relied upon by Module B, creating an unending game of whack-a-mole.\\n\\nTo eliminate this entropy, Stanford CS146S mandates **Spec-Driven Development (SDD)**: natural language must be distilled into executable specifications before a single line of production code is written.\\n\\n---\\n\\n### 2. Anatomy of an AI-Native Test Harness\\n\\nAn AI test harness is not merely a collection of unit tests. It is an **algorithmic bounding box** that confines model exploration within mathematically verifiable boundaries.\\n\\n```mermaid\\nflowchart LR\\n    subgraph Spec_Pillar [\\"Pillar 1: Formal Spec\\"]\\n        A1[Markdown PRD]\\n        A2[Strict Type Schemas<br/>TypeScript / Pydantic]\\n        A3[Interface Invariants]\\n    end\\n\\n    subgraph Harness_Pillar [\\"Pillar 2: Test Harness Engine\\"]\\n        B1[Unit Test Suite]\\n        B2[Property-Based Fuzzing<br/>Hypothesis / fast-check]\\n        B3[Containerized Sandbox]\\n    end\\n\\n    subgraph Diagnostic_Pillar [\\"Pillar 3: Diagnostic Feedback\\"]\\n        C1[Compiler AST Output]\\n        C2[Structured JSON Tracebacks]\\n        C3[Coverage & Performance Budgets]\\n    end\\n\\n    Spec_Pillar ==> Harness_Pillar ==> Diagnostic_Pillar\\n```\\n\\nAn enterprise AI-ready test harness consists of three structural pillars:\\n\\n#### Pillar 1: The Separation of Roles (Architect vs. Implementer)\\n- **The Spec Author**: Human engineers (or high-level reasoning models like Claude 3.7 Sonnet in Thinking Mode) author the specification document (`SPEC.md`) and the test requirements.\\n- **The Implementer**: The AI coding agent (Claude Code, Cursor Composer) is strictly restricted to editing the implementation files. It is explicitly forbidden from modifying the test assertions.\\n\\n#### Pillar 2: Multi-Tier Verification Layers\\nRelying on a single test suite leaves blind spots. Stanford establishes the **Four-Layer Swiss Cheese Defense**:\\n1. **Static Type Checking** (TypeScript `strict: true` or Python `mypy --strict`): Catches 60% of structural and naming hallucinations instantly without running a test runner.\\n2. **AST Linters & Static Analysis** (Biome, ESLint, Ruff): Enforces architectural idioms and rejects forbidden dependencies.\\n3. **Unit & Edge-Case Assertions** (Vitest, pytest): Validates happy-path and known failure states.\\n4. **Property-Based Fuzzing** (Hypothesis, fast-check): Synthesizes thousands of random inputs to expose unhandled edge cases that neither the human nor the LLM anticipated.\\n\\n---\\n\\n### 3. The Self-Healing Closed Loop: Autonomous Red-Green-Refactor\\n\\nThe core breakthrough of modern autonomous tools like Claude Code and Cursor is their ability to execute terminal commands, parse stderr outputs, and iterate without human intervention.\\n\\n```mermaid\\nsequenceDiagram\\n    autonumber\\n    actor Human as Software Architect\\n    participant Agent as Claude Code / Cursor\\n    participant Harness as Automated Test Runner\\n    participant Repo as Codebase / Git\\n\\n    Human->>Agent: \\"Implement checkout service conforming to SPEC.md\\"\\n    Agent->>Repo: Read SPEC.md & existing interfaces\\n    Agent->>Repo: Generate candidate implementation (checkout.ts)\\n    Agent->>Harness: Execute `npm test -- checkout.test.ts`\\n    Harness--\x3e>Agent: \u274C Test Failed: AssertionError (Expected 402, received 500)\\n    \\n    rect rgb(30, 20, 50)\\n        Note over Agent: Self-Healing Loop Triggered\\n        Agent->>Agent: Analyze stack trace & line numbers\\n        Agent->>Agent: Identify missing Stripe card error handling\\n        Agent->>Repo: Apply surgical diff to checkout.ts\\n        Agent->>Harness: Re-execute `npm test -- checkout.test.ts`\\n    end\\n    \\n    Harness--\x3e>Agent: 23 passed, 0 failed\\n    Agent->>Harness: Execute `npm run lint` & `npm run typecheck`\\n    Harness--\x3e>Agent: Zero errors\\n    Agent->>Human: Implementation verified & passing all invariants.\\n```\\n\\nIn this autonomous loop:\\n1. **Deterministic Execution**: The harness runs within a local container or worktree, shielding the agent from external state pollution.\\n2. **Context-Injected Feedback**: When a test fails, the agent automatically receives the exact assertion error, standard error stream, and source diff in its context window.\\n3. **Surgical Diffs**: Instead of regenerating whole files (which risks introducing secondary bugs), modern agents apply atomic unified diffs until green status is achieved.\\n\\n---\\n\\n### 4. Implementation Blueprint: Spec-Driven Banking Transfer Engine\\n\\nTo demonstrate the power of this methodology, consider implementing a financial fund transfer engine where double-spend bugs or concurrency races would be catastrophic.\\n\\n#### Step 1: Writing the Specification (`SPEC_TRANSFER.md`)\\n\\n```markdown\\n# Specification: Account Transfer Engine (v1.0)\\n\\n## Invariants:\\n1. Source account balance must never drop below 0.\\n2. Sum of balances (Source + Destination) before transfer must equal sum after transfer.\\n3. Transfers must be idempotent: duplicate transferId must return existing transaction without debiting.\\n4. All database operations must execute within an atomic transaction.\\n```\\n\\n#### Step 2: The Independent Property-Based Test Harness\\n\\n```typescript\\n// transfer.test.ts - Authored by Human Architect\\nimport { describe, it, expect } from \'vitest\';\\nimport * as fc from \'fast-check\';\\nimport { executeTransfer, AccountStore } from \'./transfer\';\\n\\ndescribe(\'Account Transfer Invariant Tests\', () => {\\n  it(\'Property: Total money in system must remain constant (Conservation of Value)\', () => {\\n    fc.assert(\\n      fc.property(\\n        fc.integer({ min: 100, max: 10000 }), // Initial Source\\n        fc.integer({ min: 0, max: 5000 }),    // Initial Destination\\n        fc.integer({ min: 1, max: 20000 }),   // Transfer Amount\\n        (srcBal, dstBal, amount) => {\\n          const store = new AccountStore({ source: srcBal, dest: dstBal });\\n          const totalBefore = srcBal + dstBal;\\n\\n          try {\\n            executeTransfer(store, \'source\', \'dest\', amount, \'tx-1\');\\n          } catch (err) {\\n            // Expected failure if amount > srcBal\\n          }\\n\\n          const totalAfter = store.getBalance(\'source\') + store.getBalance(\'dest\');\\n          expect(totalAfter).toBe(totalBefore);\\n        }\\n      ),\\n      { numRuns: 1000 } // 1,000 randomized property iterations\\n    );\\n  });\\n});\\n```\\n\\nWhen Claude Code is unleashed with:\\n```bash\\nclaude \\"Implement transfer.ts to pass transfer.test.ts conforming to SPEC_TRANSFER.md. Run `npm test` until green.\\"\\n```\\nThe AI agent will fail on the first run (e.g., negative balance allowed under specific fast-check inputs), parse the generated counter-example, patch the conditional validation, re-run, and autonomously deliver bulletproof code.\\n\\n---\\n\\n### 5. Configuring Modern Agents: Claude Code & Cursor Rulesets\\n\\nTo enforce this workflow systematically across engineering teams, use declarative agent configuration files:\\n\\n#### 1. Claude Code Workspace Configuration (`CLAUDE.md`)\\n```markdown\\n# Agent Execution Guidelines\\n- Read SPEC.md before writing or refactoring any business logic.\\n- Never modify files matching `*.test.ts` or `*.spec.ts` unless explicitly instructed.\\n- After editing code, execute `npm run verify` (typecheck + lint + test) autonomously.\\n- If tests fail, analyze the counterexample, apply a patch, and re-verify before asking for user input.\\n```\\n\\n#### 2. Cursor IDE Rule (`.cursorrules`)\\n```json\\n{\\n  \\"rules\\": [\\n    \\"Always generate interfaces and types in a separate types/ directory before writing business implementations.\\",\\n    \\"When modifying a function, identify its corresponding test file and verify test coverage using Vitest.\\",\\n    \\"Refuse to complete a refactoring task if any existing unit tests are broken.\\"\\n  ]\\n}\\n```\\n\\n---\\n\\n### 6. Stanford CS146S Deep Q&A: Lecture 4\\n\\n> **Q. Professor, what prevents an AI agent from modifying the unit tests so that its flawed implementation passes?**\\n\\n**Faculty Response:**\\nThis is known as the **Tautological Test Anti-Pattern**. If an agent is granted write permissions to both the code and the test suite, its reward-maximizing behavior will frequently edit the test assertion (e.g., changing `expect(res).toBe(400)` to `expect(res).toBe(200)`) to achieve green status.\\n\\nTo prevent this:\\n1. **Filesystem Permissions**: Lock test files with read-only permissions in the agent\'s worktree (`chmod 444 *.test.ts` or sandbox policy).\\n2. **Git Commit Gating**: Pre-commit git hooks must inspect the diff: if any commit modifies both `src/` and `tests/` in an automated session, the build pipeline rejects it immediately.\\n3. **Spec-Test Separation**: Only human developers or a dedicated \\"Critic Agent\\" are permitted to edit acceptance criteria.\\n\\n---\\n\\n### 7. Lecture 4 Summary & Series Roadmap\\n\\n1. **Abandon Vibe Coding**: Conversational prompting without formal specifications guarantees cumulative regression and architectural rot.\\n2. **Harness First, Code Second**: An automated test harness with static typing, linters, and property tests provides the objective boundary LLMs need to iterate safely.\\n3. **Autonomous Self-Healing**: Leverage modern agent loops (Red-Green-Refactor) to let models absorb failure traces and autonomously converge on green test suites.\\n\\nIn **Lecture 5**, we will delve into **Multi-Agent Systems & Swarm Orchestration**: how to coordinate teams of specialized LLMs (Architect, Implementer, Critic, QA) to build full-scale enterprise software autonomously. Stay tuned to GlobalDevLog!\\n\\n---\\n\\n### \u{1F4CC} 3\u20135 Line Executive Summary\\n1. **The Fallacy of Vibe Coding**: Unconstrained conversational prompting accelerates codebase entropy; enterprise-scale AI engineering strictly requires Spec-Driven Development (SDD) as a formal contract.\\n2. **The Autonomous Test Harness**: A robust test harness combines static typing, AST linting, deterministic unit tests, and property-based fuzzing to bound LLM exploration within verifiable invariants.\\n3. **Self-Healing Regression Loops**: Modern coding agents (Claude Code, Cursor) leverage terminal feedback to autonomously diagnose test failures and iteratively apply atomic patches until all assertions pass.\\n4. **Separation of Verification Concerns**: Rigorous engineering workflows forbid the code-generating agent from modifying acceptance tests, completely eliminating tautological self-passing bugs.\\n\\n### References & Course Materials\\n- **Official Course Video Playlist**: [Stanford CS146S: The Modern Software Development (YouTube Playlist)](https://www.youtube.com/playlist?list=PLxpwjSdVZQ95OWe3QvkVEcU1f1X-6NDj9)\\n- **Primary Literature**: Spec-Driven Development; Hypothesis Property-Based Testing; Claude Code Agentic Workflow Specifications; Vitest Enterprise Testing Patterns.\\n- **Academic Institution**: Stanford University, Department of Computer Science"},{"id":"stanford-cs146s-3-mcp-tool-use-architecture","metadata":{"permalink":"/blog/stanford-cs146s-3-mcp-tool-use-architecture","source":"@site/blog/2026-10-24-stanford-cs146s-3/index.md","title":"[Stanford CS146S #3] Model Context Protocol (MCP) & Autonomous Tool Use: The Universal Language Server Architecture for AI Agents","description":"Stanford CS146S Lecture 3 comprehensive guide: Deep-diving into the Model Context Protocol (MCP) as the \'LSP for AI\', client-server topology, Stdio vs HTTP/SSE transports, and building secure tool-calling loops for autonomous coding agents.","date":"2026-10-24T00:00:00.000Z","tags":[{"inline":true,"label":"stanford-cs146s","permalink":"/blog/tags/stanford-cs-146-s"},{"inline":true,"label":"mcp","permalink":"/blog/tags/mcp"},{"inline":true,"label":"model-context-protocol","permalink":"/blog/tags/model-context-protocol"},{"inline":true,"label":"tool-use","permalink":"/blog/tags/tool-use"},{"inline":true,"label":"claude-code","permalink":"/blog/tags/claude-code"},{"inline":true,"label":"json-rpc","permalink":"/blog/tags/json-rpc"},{"inline":true,"label":"software-architecture","permalink":"/blog/tags/software-architecture"}],"readingTime":8.24,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"stanford-cs146s-3-mcp-tool-use-architecture","title":"[Stanford CS146S #3] Model Context Protocol (MCP) & Autonomous Tool Use: The Universal Language Server Architecture for AI Agents","authors":["jbgih"],"tags":["stanford-cs146s","mcp","model-context-protocol","tool-use","claude-code","json-rpc","software-architecture"],"date":"2026-10-24T00:00:00.000Z","keywords":["Model Context Protocol","MCP Architecture","Claude Tool Use","JSON-RPC 2.0","Autonomous AI Agents"],"description":"Stanford CS146S Lecture 3 comprehensive guide: Deep-diving into the Model Context Protocol (MCP) as the \'LSP for AI\', client-server topology, Stdio vs HTTP/SSE transports, and building secure tool-calling loops for autonomous coding agents."},"unlisted":false,"prevItem":{"title":"[Stanford CS146S #4] Spec-Driven Code Generation & Test Harnesses: Building Self-Healing Regression Loops with Claude Code & Cursor","permalink":"/blog/stanford-cs146s-4-spec-driven-code-generation-test-harnesses"},"nextItem":{"title":"[Stanford CS146S #2] Inside Coding LLMs & Prompt Engineering: Pre-training, RLHF, and the \'Trust but Verify\' Swiss Cheese Model","permalink":"/blog/stanford-cs146s-2-coding-llms-prompt-engineering"}},"content":"![Model Context Protocol Architecture](./images/03_cs146s_mcp_architecture.png)\\r\\n\\r\\nWelcome to the third installment of our deep-dive engineering series on **Stanford University\'s CS146S: The Modern Software Developer**.\\r\\n\\r\\nIn Lecture 1, we established the paradigm shift from syntax typist to agent conductor. In Lecture 2, we examined the probabilistic nature of coding LLMs and the defensive \\"Trust but Verify\\" harness. In **Lecture 3 (Week 2)**, the curriculum addresses the single greatest architectural bottleneck in modern AI systems: **How do isolated foundation models safely and modularly interact with the external world?**\\r\\n\\r\\nBefore 2024, connecting an LLM to a database, terminal, or GitHub API required fragile, bespoke integration glue. Drawing directly from Anthropic\'s open standard specification and Stanford\'s distributed systems analysis, this lecture unpacks the **Model Context Protocol (MCP)**\u2014the universal adapter that is doing for autonomous AI agents what the **Language Server Protocol (LSP)** did for modern code editors.\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n---\\r\\n\\r\\n### 1. The Fragmentation Crisis: Why We Needed an \\"LSP for AI\\"\\r\\n\\r\\nHistorically, every new AI IDE or coding tool (Cursor, Claude Code, GitHub Copilot, Devin) attempted to connect to identical enterprise resources: Git repositories, PostgreSQL clusters, Slack channels, and AWS infrastructure.\\r\\n\\r\\n```mermaid\\r\\nflowchart LR\\r\\n    subgraph Legacy_N_Times_M [\\"The Legacy N x M Spaghetti Problem\\"]\\r\\n        A1[AI Host: Claude Code] -.->|Custom API Glue| R1[(PostgreSQL)]\\r\\n        A1 -.->|Custom Shell Wrapper| R2[Git Worktree]\\r\\n        A2[AI Host: Cursor] -.->|Duplicate Integration| R1\\r\\n        A2 -.->|Custom Tool Hook| R3[Figma API]\\r\\n        A3[AI Host: Claude Desktop] -.->|Third Tool Driver| R1\\r\\n    end\\r\\n\\r\\n    subgraph Modern_MCP_Standard [\\"Stanford CS146S: The Clean MCP Standard\\"]\\r\\n        H1[Any MCP Host<br/>Claude Code / Cursor] ==>|Standard JSON-RPC 2.0| C[Universal MCP Client]\\r\\n        C <==>|Stdio / SSE Transport| S1[PostgreSQL MCP Server]\\r\\n        C <==>|Stdio / SSE Transport| S2[Git Worktree MCP Server]\\r\\n        C <==>|Stdio / SSE Transport| S3[DevOps Docker MCP Server]\\r\\n    end\\r\\n```\\r\\n\\r\\nIn the compiler and editor ecosystem of the 2010s, Microsoft solved the $N \\\\times M$ complexity crisis by introducing the **Language Server Protocol (LSP)**. Instead of every editor writing a custom parser for TypeScript, Rust, and Go, language teams built a single LSP server, and editors built a single LSP client.\\r\\n\\r\\n**Model Context Protocol (MCP)** represents the exact same architectural breakthrough for artificial intelligence. By decoupling model reasoning from tool execution, MCP establishes a vendor-neutral, plug-and-play communication protocol over JSON-RPC 2.0.\\r\\n\\r\\n---\\r\\n\\r\\n### 2. The 3-Tier MCP System Architecture\\r\\n\\r\\nAn MCP-compliant ecosystem is comprised of three distinct participants operating across two decoupled layers:\\r\\n\\r\\n```mermaid\\r\\nflowchart TD\\r\\n    subgraph Host_Environment [\\"1. MCP Host (Application Layer)\\"]\\r\\n        Host[\\"Host Application<br/>(Claude Code / Claude Desktop / IDE)\\"]\\r\\n        LLM[\\"Foundation Reasoning Model<br/>(Claude 3.7 Sonnet / GPT-4o)\\"]\\r\\n        Client[\\"Embedded MCP Client Engine\\"]\\r\\n        Host <--\x3e LLM\\r\\n        Host <--\x3e Client\\r\\n    end\\r\\n\\r\\n    subgraph Transport_Layer [\\"2. Transport Layer (Physical Boundary)\\"]\\r\\n        direction LR\\r\\n        T1[\\"Stdio Transport<br/>(Subprocess Stdin/Stdout IPC)\\"]\\r\\n        T2[\\"Streamable HTTP Transport<br/>(HTTP POST + Server-Sent Events SSE)\\"]\\r\\n    end\\r\\n\\r\\n    subgraph Server_Ecosystem [\\"3. MCP Servers (Resource & Tool Providers)\\"]\\r\\n        S1[\\"Filesystem MCP Server<br/>(Sandboxed Workspace I/O)\\"]\\r\\n        S2[\\"PostgreSQL MCP Server<br/>(Read-Only Schema & Queries)\\"]\\r\\n        S3[\\"GitHub MCP Server<br/>(PRs, Issues, Commit Diffs)\\"]\\r\\n        S4[\\"Puppeteer Web MCP Server<br/>(Headless Browser Automation)\\"]\\r\\n    end\\r\\n\\r\\n    Client <==> T1 <==> S1 & S2\\r\\n    Client <==> T2 <==> S3 & S4\\r\\n```\\r\\n\\r\\n#### 2.1. MCP Host\\r\\nThe parent application that orchestrates the user experience, controls LLM context windows, and holds user permissions. Examples include **Claude Code CLI**, Claude Desktop, and modern agentic development environments.\\r\\n\\r\\n#### 2.2. MCP Client\\r\\nAn internal protocol handler embedded inside the Host. The client maintains a strict 1:1 stateful connection with an MCP server, handles lifecycle initialization, negotiates protocol capabilities, and serializes tool calls.\\r\\n\\r\\n#### 2.3. MCP Server\\r\\nA lightweight, purpose-built process that exposes specific data resources and executable functions. A server can be written in TypeScript, Python, or Go, and runs either locally as a child process or remotely behind a secure reverse proxy.\\r\\n\\r\\n---\\r\\n\\r\\n### 3. Dual Transport Layers: Stdio vs. Streamable HTTP/SSE\\r\\n\\r\\nThe MCP specification decouples message semantics from the physical wire format:\\r\\n\\r\\n| Transport Dimension | Stdio Transport (Local IPC) | Streamable HTTP Transport (Remote SSE) |\\r\\n| :--- | :--- | :--- |\\r\\n| **Communication Channel** | Standard input (`stdin`) and standard output (`stdout`) of a spawned child process | HTTP POST for client requests, Server-Sent Events (SSE) for server streams |\\r\\n| **Latency & Overhead** | **Near-zero latency** (direct OS pipe, no TCP/TLS handshake) | Network roundtrip latency + TLS encryption overhead |\\r\\n| **Security Boundary** | Local OS user permissions and filesystem sandboxes | OAuth 2.0 Bearer tokens, mTLS, and network firewalls |\\r\\n| **Typical Use Cases** | Local workspace file editing, git operations, local SQLite/PostgreSQL | Cloud SaaS APIs, enterprise database clusters, shared company knowledge bases |\\r\\n\\r\\n---\\r\\n\\r\\n### 4. The Three Core Primitives of MCP\\r\\n\\r\\nAn MCP server exposes its capabilities to the model via three foundational primitives:\\r\\n\\r\\n```mermaid\\r\\nflowchart LR\\r\\n    subgraph Primitives [\\"MCP Three Core Primitives\\"]\\r\\n        P1[\\"1. Resources (Read-Only Context)<br/>URIs: postgres://db/users/schema<br/>file:///app/src/index.ts\\"]\\r\\n        P2[\\"2. Tools (Executable Actions)<br/>Functions with JSON-Schema<br/>write_file(), run_query(), execute_test()\\"]\\r\\n        P3[\\"3. Prompts (Parametric Templates)<br/>Reusable Slash Commands<br/>/security-review, /generate-spec\\"]\\r\\n    end\\r\\n\\r\\n    subgraph Notifications [\\"Push Synchronization\\"]\\r\\n        N1[\\"notifications/tools/list_changed<br/>Real-time dynamic tool updates\\"]\\r\\n    end\\r\\n```\\r\\n\\r\\n1. **Resources (Context Ingestion)**: Analogous to GET endpoints. Resources expose static or dynamic data (files, system logs, database schemas) via URI schemes (e.g., `git://repo/diff/HEAD`). The LLM reads resources to ground its context without side effects.\\r\\n2. **Tools (State Mutations & Execution)**: Executable functions callable by the model. Each tool definition includes an `inputSchema` formatted in strict JSON Schema. When the model invokes a tool, the Host asks the human for authorization before dispatching the execution payload to the MCP server.\\r\\n3. **Prompts (Structured Workflows)**: Pre-engineered prompt templates stored on the server. They allow engineering teams to version-control standard operational workflows (e.g., `/refactor-test` or `/audit-cve`).\\r\\n\\r\\n---\\r\\n\\r\\n### 5. The Tool-Calling Loop in Action: Inside Claude Code\\r\\n\\r\\nHow does the MCP tool execution loop work under the hood? The sequence diagram below maps the complete round-trip lifecycle:\\r\\n\\r\\n```mermaid\\r\\nsequenceDiagram\\r\\n    autonumber\\r\\n    actor Dev as Developer\\r\\n    participant Host as Claude Code (Host)\\r\\n    participant Model as Claude 3.7 Sonnet (LLM)\\r\\n    participant Client as MCP Client\\r\\n    participant Server as PostgreSQL MCP Server\\r\\n\\r\\n    Dev->>Host: \\"Diagnose why user checkout failed for ID 8492\\"\\r\\n    Host->>Client: Request available tools (tools/list)\\r\\n    Client->>Server: JSON-RPC tools/list\\r\\n    Server--\x3e>Client: Returns [query_orders, inspect_logs]\\r\\n    Client--\x3e>Host: Tool schemas injected into LLM system prompt\\r\\n\\r\\n    Host->>Model: Prompt + Tool Definitions + User Query\\r\\n    Model->>Model: Chain-of-Thought: Need order record first\\r\\n    Model--\x3e>Host: Stop Reason: tool_use (query_orders, args: {id: 8492})\\r\\n\\r\\n    rect rgb(30, 41, 59)\\r\\n        note over Host,Dev: Human-in-the-Loop Guardrail\\r\\n        Host->>Dev: Authorize tool: query_orders(id=8492)? [Y/n]\\r\\n        Dev--\x3e>Host: Confirmed: Yes\\r\\n    end\\r\\n\\r\\n    Host->>Client: Execute tool_use\\r\\n    Client->>Server: JSON-RPC tools/call (query_orders)\\r\\n    Server--\x3e>Client: Returns JSON: {status: \'failed\', error: \'insufficient_funds\'}\\r\\n    Client--\x3e>Host: Tool Result payload\\r\\n\\r\\n    Host->>Model: Re-feed Tool Result into Context Window\\r\\n    Model->>Model: Synthesize root cause analysis\\r\\n    Model--\x3e>Host: \\"The checkout failed due to an insufficient funds exception on Stripe webhook.\\"\\r\\n    Host--\x3e>Dev: Final diagnostic report presented\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\n### 6. Security & Trust: The Model Isolation Boundary\\r\\n\\r\\nIn traditional prompt hacking, an adversarial injection could trick an LLM into deleting files or exfiltrating API secrets. MCP implements a strict **Principle of Least Privilege**:\\r\\n\\r\\n1. **Explicit User Consent**: An MCP Host must never execute a state-mutating tool (`rm`, `write_patch`, `drop_table`) without explicit human confirmation.\\r\\n2. **Schema Invariant Sanitization**: The MCP Client enforces type validation on all arguments before passing them to the server, preventing command injection at the transport level.\\r\\n3. **Scoped OAuth 2.0 Tokens**: For remote HTTP servers, tokens carry granular scopes (e.g., `read:repo_metadata` without `write:code`).\\r\\n\\r\\n---\\r\\n\\r\\n### 7. Stanford CS146S Deep Q&A: Lecture 3\\r\\n\\r\\n> **Q. Professor, how does MCP differ from OpenAI Function Calling or LangChain tools?**\\r\\n\\r\\n**Faculty Response:**\\r\\nFunction calling is simply an **LLM API feature**: a model emits JSON arguments matching a schema. \\r\\n\\r\\nHowever, before MCP, **who executed that function? Where did the server live? How was it authenticated? How did another developer reuse your tool?** Every company wrote custom spaghetti code to bridge that gap.\\r\\n\\r\\nMCP is not an LLM feature; it is an **Open Industry Protocol**. It standardizes the entire transport, schema negotiation, permission model, and lifecycle management. A single PostgreSQL MCP server written today can be used identically by Claude Code, Cursor, a custom internal enterprise agent, or any future AI host without altering a single line of server code.\\r\\n\\r\\n---\\r\\n\\r\\n### 8. Lecture 3 Summary & Series Roadmap\\r\\n\\r\\n1. **Adopt Open Standards**: Avoid proprietary, hard-coded tool wrappers. Standardize tool integrations on MCP.\\r\\n2. **Decouple Brain from Hands**: Keep the LLM focused on reasoning, while delegating I/O and state mutations to sandboxed MCP servers.\\r\\n3. **Enforce Human-in-the-Loop**: Safeguard production environments by requiring explicit authorization gates on state-mutating tools.\\r\\n\\r\\nIn **Lecture 4**, we will explore **Spec-Driven Code Generation & Test Harnesses in Practice**: how to configure Claude Code and Cursor with automated regression loops that write, debug, and verify production features autonomously. Stay tuned to GlobalDevLog!\\r\\n\\r\\n---\\r\\n\\r\\n### \u{1F4CC} 3\u20135 Line Executive Summary\\r\\n1. **The MCP Standardization Paradigm**: Model Context Protocol (MCP) serves as the \\"LSP for AI Agents\\", replacing brittle $N \\\\times M$ custom wrappers with an open, bidirectional JSON-RPC 2.0 protocol across AI hosts and tools.\\r\\n2. **Decoupling Brain from Hands**: The LLM context window remains strictly dedicated to high-level logical reasoning, delegating physical I/O and state mutations to sandboxed, isolated MCP servers.\\r\\n3. **Dual Transport Architecture**: High-speed, local low-latency workflows execute via sub-millisecond Stdio pipes, while enterprise distributed agents scale via Streamable HTTP/SSE secured with OAuth 2.0.\\r\\n4. **Human-in-the-Loop Security Guardrails**: Mission-critical agent deployments enforce the Principle of Least Privilege\u2014blocking destructive disk and database state mutations until explicit developer confirmation is granted.\\r\\n\\r\\n### References & Course Materials\\r\\n- **Official Course Video Playlist**: [Stanford CS146S: The Modern Software Development (YouTube Playlist)](https://www.youtube.com/playlist?list=PLxpwjSdVZQ95OWe3QvkVEcU1f1X-6NDj9)\\r\\n- **Primary Literature**: Model Context Protocol Specification (modelcontextprotocol.io); Anthropic Claude Tool Use Architecture; Microsoft Language Server Protocol (LSP).\\r\\n- **Academic Institution**: Stanford University, Department of Computer Science"},{"id":"stanford-cs146s-2-coding-llms-prompt-engineering","metadata":{"permalink":"/blog/stanford-cs146s-2-coding-llms-prompt-engineering","source":"@site/blog/2026-10-23-stanford-cs146s-2/index.md","title":"[Stanford CS146S #2] Inside Coding LLMs & Prompt Engineering: Pre-training, RLHF, and the \'Trust but Verify\' Swiss Cheese Model","description":"Stanford CS146S Lecture 2 comprehensive guide: Exploring the internal mechanics of coding LLMs from Pre-training and RLHF to Chain-of-Thought prompting, OpenAI Codex architecture, and defending against the Swiss Cheese Model of AI code generation.","date":"2026-10-23T00:00:00.000Z","tags":[{"inline":true,"label":"stanford-cs146s","permalink":"/blog/tags/stanford-cs-146-s"},{"inline":true,"label":"coding-llms","permalink":"/blog/tags/coding-llms"},{"inline":true,"label":"prompt-engineering","permalink":"/blog/tags/prompt-engineering"},{"inline":true,"label":"rlhf","permalink":"/blog/tags/rlhf"},{"inline":true,"label":"chain-of-thought","permalink":"/blog/tags/chain-of-thought"},{"inline":true,"label":"swiss-cheese-model","permalink":"/blog/tags/swiss-cheese-model"},{"inline":true,"label":"software-architecture","permalink":"/blog/tags/software-architecture"}],"readingTime":11.89,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"stanford-cs146s-2-coding-llms-prompt-engineering","title":"[Stanford CS146S #2] Inside Coding LLMs & Prompt Engineering: Pre-training, RLHF, and the \'Trust but Verify\' Swiss Cheese Model","authors":["jbgih"],"tags":["stanford-cs146s","coding-llms","prompt-engineering","rlhf","chain-of-thought","swiss-cheese-model","software-architecture"],"date":"2026-10-23T00:00:00.000Z","keywords":["Coding LLMs","Prompt Engineering","RLHF","Chain of Thought","Swiss Cheese Model"],"description":"Stanford CS146S Lecture 2 comprehensive guide: Exploring the internal mechanics of coding LLMs from Pre-training and RLHF to Chain-of-Thought prompting, OpenAI Codex architecture, and defending against the Swiss Cheese Model of AI code generation."},"unlisted":false,"prevItem":{"title":"[Stanford CS146S #3] Model Context Protocol (MCP) & Autonomous Tool Use: The Universal Language Server Architecture for AI Agents","permalink":"/blog/stanford-cs146s-3-mcp-tool-use-architecture"},"nextItem":{"title":"[Stanford CS146S #1] Course Overview: The Modern Software Developer \u2014 The Shift from Typist to Conductor in the Age of AI Agents","permalink":"/blog/stanford-cs146s-1-modern-software-developer"}},"content":"![Inside Coding LLMs & Prompt Engineering](./images/02_cs146s_coding_llms_swiss_cheese.png)\\r\\n\\r\\nWelcome back to the technical deep-dive series covering **Stanford University\'s CS146S: The Modern Software Developer**. \\r\\n\\r\\nIn Lecture 1, we established the macro architectural perspective: how modern software engineers are pivoting from manual syntax typists into conductors presiding over autonomous agent squads. In **Lecture 2 (Week 1)**, the curriculum dives directly into the underlying computational engine powering this revolution: **Coding Large Language Models (LLMs)** and the engineering discipline of **Prompt Engineering**.\\r\\n\\r\\nDrawing directly from foundational works by Andrej Karpathy (*Deep Dive into LLMs*), OpenAI (*How OpenAI Uses Codex*), and Google Cloud/DAIR.AI prompt engineering research, this lecture demystifies how neural networks acquire coding fluency, why they remain statistical simulators rather than conscious reasoning entities, and how software engineers must implement the **\\"Trust but Verify\\"** doctrine to overcome the treacherous **Swiss Cheese Model** of automated code generation.\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n---\\r\\n\\r\\n### 1. The Anatomy of an LLM: The Three-Stage Training Pipeline\\r\\n\\r\\nTo effectively prompt, orchestrate, and debug an AI coding assistant, a software engineer must understand how the model\'s weights were forged. As Andrej Karpathy emphasizes, modern LLMs are not monolithic rule engines; they are the culmination of a rigorous **three-stage training pipeline**:\\r\\n\\r\\n```mermaid\\r\\nflowchart LR\\r\\n    subgraph Stage1 [\\"Stage 1: Pre-training\\"]\\r\\n        D1[Raw Web & GitHub Code<br/>Trillions of Tokens] --\x3e N1[Transformer Base Model<br/>Next-Token Probability P(w_t | Context)]\\r\\n    end\\r\\n\\r\\n    subgraph Stage2 [\\"Stage 2: Supervised Fine-Tuning (SFT)\\"]\\r\\n        N1 --\x3e D2[High-Quality Instruction Pairs<br/>Prompt & Gold-Standard Response]\\r\\n        D2 --\x3e N2[Instruction-Tuned Assistant<br/>Conversational Protocol]\\r\\n    end\\r\\n\\r\\n    subgraph Stage3 [\\"Stage 3: RLHF & Alignment\\"]\\r\\n        N2 --\x3e D3[Human Preference Ranking<br/>Reward Model Scoring]\\r\\n        D3 --\x3e N3[Production Coding LLM<br/>Safe, Aligned & Deterministic]\\r\\n    end\\r\\n```\\r\\n\\r\\n#### 1.1. Pre-training: Self-Supervised Knowledge Ingestion\\r\\nDuring pre-training, a dense decoder-only Transformer model processes petabytes of raw text and source code. The model does not understand words in a human linguistic sense; instead, text is chunked into sub-word tokens via **Byte-Pair Encoding (BPE)**:\\r\\n- A typical token represents roughly 3\u20134 characters or common code fragments (e.g., `def `, `return `, `const `).\\r\\n- The loss objective is deceptively simple: **Next-Token Prediction**. Given a context window of previous tokens, the network computes a softmax probability distribution over the entire vocabulary `V`:\\r\\n\\r\\n```text\\r\\nP(w_t | w_1, w_2, ..., w_t-1) = Softmax(W_v * h_t-1)\\r\\n```\\r\\n\\r\\n- By minimizing cross-entropy loss across trillions of code tokens, the network implicitly encodes syntax trees, algorithmic idioms, API conventions, and typing relationships. However, a purely pre-trained base model is merely an autocomplete engine\u2014it will continue code blindly without following conversational intent.\\r\\n\\r\\n#### 1.2. Supervised Fine-Tuning (SFT): The Dialogue Protocol\\r\\nTo transform an unruly autocomplete engine into a docile pair-programmer, AI labs perform **Supervised Fine-Tuning (SFT)**. \\r\\n- Human software engineers and expert annotators curate tens of thousands of high-fidelity `<User Query, Assistant Response>` pairs.\\r\\n- The model is fine-tuned to adopt a helpful persona, structure code within markdown blocks, explain edge cases, and follow formatting constraints.\\r\\n\\r\\n#### 1.3. Reinforcement Learning from Human Feedback (RLHF) & Direct Preference Optimization (DPO)\\r\\nEven after SFT, models frequently generate code that is plausible yet inefficient, subtly insecure, or verbose. \\r\\n- In **RLHF**, human reviewers evaluate multiple candidate responses generated by the model for the same programming prompt and assign relative preference rankings.\\r\\n- A **Reward Model (RM)** is trained to predict human preference scores.\\r\\n- Using algorithms like PPO (Proximal Policy Optimization) or modern DPO (Direct Preference Optimization), the LLM\'s weights are steered to maximize reward while penalizing drift (via KL-divergence penalties) from the original policy.\\r\\n\\r\\n> **Key Takeaway**: When a coding LLM answers your architecture prompt, it is performing a **statistical simulation** of what an elite human engineer would generate based on the statistical priors encoded across its training weights.\\r\\n\\r\\n---\\r\\n\\r\\n### 2. How Codex Understands Code: ASTs and Token Sequences\\r\\n\\r\\nIn the seminal literature *How OpenAI Uses Codex*, researchers revealed why LLMs excel so remarkably at programming languages compared to natural language:\\r\\n\\r\\n1. **Deterministic Syntax & Formal Grammars**: Unlike human languages riddled with ambiguity, idioms, and slang, programming languages adhere strictly to formal context-free grammars. Code can be parsed into unambiguous **Abstract Syntax Trees (ASTs)**.\\r\\n2. **Local and Global Invariants**: A variable declared in line 5 must match the reference in line 84. The Transformer\'s multi-head self-attention mechanism is mathematically ideal for tracking these long-range syntactic dependencies.\\r\\n3. **Pervasive GitHub Pre-training**: Modern coding LLMs have ingested hundreds of millions of public repositories, exposing them to virtually every standard library, framework API, and design pattern in existence.\\r\\n\\r\\nHowever, Codex and its descendants do not execute code internally during token generation. They predict tokens based on syntactic co-occurrence. If a library was deprecated after the model\'s knowledge cutoff, or if an API signature takes four arguments instead of three, the model will effortlessly generate syntactically flawless code that fails catastrophically at runtime.\\r\\n\\r\\n---\\r\\n\\r\\n### 3. Prompt Engineering as a Software Engineering Discipline\\r\\n\\r\\nPrompt engineering is often trivialized as \\"crafting clever chat messages.\\" In Stanford CS146S, prompt engineering is treated as a rigorous software engineering discipline: designing structured, deterministic inputs to guide probabilistic models toward invariant outputs.\\r\\n\\r\\n```mermaid\\r\\nflowchart TD\\r\\n    subgraph Prompt_Strategies [\\"Prompt Architecture Hierarchy\\"]\\r\\n        P1[\\"Zero-Shot: Direct Command<br/>\'Implement QuickSort in Go\'\\"]\\r\\n        P2[\\"Few-Shot: In-Context Pattern Matching<br/>Input-Output Exemplars\\"]\\r\\n        P3[\\"Chain-of-Thought (CoT): Reasoning Path<br/>\'Let\'s analyze edge cases step-by-step\'\\"]\\r\\n        P4[\\"Grounded Spec Prompting: Constraints & Invariants<br/>Machine-Actionable Schema + Hard Boundaries\\"]\\r\\n    end\\r\\n\\r\\n    P1 --\x3e|Higher Error Rate on Complex Logic| Fail[Hallucination & Edge Case Misses]\\r\\n    P2 --\x3e|Enforces Output Schema| Better[Consistent JSON/AST Formats]\\r\\n    P3 --\x3e|Triggers Latent Self-Verification| Strong[Complex Algorithmic Correctness]\\r\\n    P4 --\x3e|Deterministic Production Standard| Prod[Verified Production Code Base]\\r\\n```\\r\\n\\r\\n#### 3.1. Zero-Shot vs. Few-Shot In-Context Learning\\r\\n- **Zero-Shot**: Passing an instruction with zero examples. Effective for trivial, boilerplate tasks (`\\"Convert this JSON schema to TypeScript interface\\"`).\\r\\n- **Few-Shot**: Providing 2\u20133 canonical exemplars within the prompt. Few-shot prompting leverages the Transformer\'s **in-context learning** capability without updating model weights. It is indispensable for enforcing strict JSON return types, custom logging wrappers, or proprietary API calling conventions.\\r\\n\\r\\n#### 3.2. Chain-of-Thought (CoT) & Reasoning Elicitation\\r\\nWhen prompted with: *\\"Write a lock-free concurrent ring buffer in C++,\\"* a zero-shot prompt forces the model to synthesize the final code tokens immediately, leading to race conditions.\\r\\n\\r\\nBy injecting the prompt directive:\\r\\n> *\\"Before writing any code, analyze the memory model constraints, identify potential thread contention points step-by-step, and state the memory barrier invariants (std::memory_order_acquire / release).\\"*\\r\\n\\r\\nWe force the model to allocate token bandwidth to **intermediate reasoning**. Because Transformer attention is auto-regressive, each subsequent token is conditioned on the explicit reasoning steps generated in preceding tokens, dramatically reducing logical errors.\\r\\n\\r\\n#### 3.3. Defensive Prompting & Hallucination Mitigation\\r\\nTo prevent the model from inventing non-existent packages or methods:\\r\\n1. **Explicit Negative Constraints**: *\\"Do NOT import external third-party libraries; use standard library only.\\"*\\r\\n2. **Confidence Thresholding**: *\\"If the required database schema cannot be determined from the provided DDL, output `SCHEMA_ERROR` and list the missing columns. Do not guess.\\"*\\r\\n3. **Sandboxed Role Definition**: Restrict the model\'s operational scope to a specific subsystem (e.g., *\\"You are a static code security auditor examining this function for OWASP Top 10 vulnerabilities\\"*).\\r\\n\\r\\n---\\r\\n\\r\\n### 4. The \\"Swiss Cheese Model\\" of AI Code Generation\\r\\n\\r\\nThe most critical mental model introduced in Week 1 is Andrej Karpathy\'s adaptation of the **Swiss Cheese Model** to coding LLMs.\\r\\n\\r\\nIn safety engineering (aviation, medicine), James Reason\'s Swiss Cheese Model posits that catastrophic accidents occur when flaws (holes) in multiple independent defensive layers momentarily align. In AI software engineering, the reverse hazard is true:\\r\\n\\r\\n```mermaid\\r\\nflowchart TD\\r\\n    subgraph Swiss_Cheese_Risk [\\"The AI Swiss Cheese Hazard\\"]\\r\\n        A[\\"LLM Output: 95% Brilliant & Elegant Code\\"]\\r\\n        H1[\\"Hole 1: Subtle Off-By-One Indexing Bug\\"]\\r\\n        H2[\\"Hole 2: Non-Thread-Safe Mutex Lock Order\\"]\\r\\n        H3[\\"Hole 3: Missing Input Buffer Bounds Check\\"]\\r\\n    end\\r\\n\\r\\n    subgraph Defense_Layers [\\"Human-Agent Defensive Verification Pipeline\\"]\\r\\n        L1[\\"Layer 1: Static Type Checker & Linters (TypeScript / Ruff)\\"]\\r\\n        L2[\\"Layer 2: Deterministic Unit & Property Test Suites (Pytest)\\"]\\r\\n        L3[\\"Layer 3: Dynamic Sanitizers & Concurrency Fuzzers (ASan/TSan)\\"]\\r\\n        L4[\\"Layer 4: Human Architectural & Security Code Review\\"]\\r\\n    end\\r\\n\\r\\n    A --\x3e H1 & H2 & H3\\r\\n    H1 --\x3e|Blocked by| L1\\r\\n    H2 --\x3e|Blocked by| L3\\r\\n    H3 --\x3e|Blocked by| L4\\r\\n    L4 ==> PASS[Production Release Safe]\\r\\n```\\r\\n\\r\\n#### Why Coding LLMs Have Holes\\r\\nAn LLM can write 200 lines of mathematically stunning, cleanly formatted code that solves a complex dynamic programming problem\u2014yet leave a critical off-by-one boundary vulnerability on line 187, or use a non-reentrant system call inside a multithreaded loop.\\r\\n\\r\\nBecause the code looks impeccably written, human engineers suffer from **Automation Bias**: the psychological tendency to uncritically trust automated systems. If developers merge AI-generated PRs after a superficial glance, those latent holes will inevitably puncture production systems.\\r\\n\\r\\n---\\r\\n\\r\\n### 5. The \\"Trust but Verify\\" Engineering Architecture\\r\\n\\r\\nTo safely harness coding LLMs at scale, Stanford CS146S mandates the **\\"Trust but Verify\\"** engineering architecture. Software teams must construct an impenetrable harness around the AI generator:\\r\\n\\r\\n```mermaid\\r\\nsequenceDiagram\\r\\n    autonumber\\r\\n    actor Dev as Software Engineer (Architect)\\r\\n    participant Spec as SPEC.md & Invariant Rules\\r\\n    participant LLM as Coding LLM (Claude Code / Cursor)\\r\\n    participant Harness as Automated Verification Gate\\r\\n    participant Prod as Production Main Branch\\r\\n\\r\\n    Dev->>Spec: Write Formal Constraints & Invariants\\r\\n    Dev->>LLM: Dispatch Task with Spec & Context\\r\\n    LLM->>LLM: Chain-of-Thought Synthesis\\r\\n    LLM->>Harness: Commit Generated Code & Tests\\r\\n\\r\\n    rect rgb(30, 41, 59)\\r\\n        note over Harness: Automated Verification Gate\\r\\n        Harness->>Harness: 1. Strict Typing & Linting (Zero Warnings)\\r\\n        Harness->>Harness: 2. Unit & Integration Test Execution\\r\\n        Harness->>Harness: 3. Property-Based Invariant Fuzzing\\r\\n    end\\r\\n\\r\\n    alt Any Gate Fails\\r\\n        Harness--\x3e>LLM: Re-feed Error Trace (Loop Engineering)\\r\\n        LLM->>Harness: Synthesize Fix Patch\\r\\n    else All Gates Pass\\r\\n        Harness--\x3e>Dev: Clean Diff with 100% Passing Gate Metrics\\r\\n        Dev->>Dev: High-Level Architectural & Security Review\\r\\n        Dev->>Prod: Merge to Main Branch\\r\\n    end\\r\\n```\\r\\n\\r\\n#### The Four Hardened Gates:\\r\\n1. **Gate 1: Strict Static Analysis**: The code must compile with zero compiler warnings, pass strict static type checking (e.g., `tsc --strict`, `mypy --strict`), and pass zero-tolerance linting rules (Ruff, ESLint).\\r\\n2. **Gate 2: Deterministic Test Contracts**: The LLM must not only generate implementation code but also write matching unit tests. These tests are executed in isolated sandboxes to verify edge cases ($N=0$, $N=1$, negative inputs, concurrent requests).\\r\\n3. **Gate 3: Property-Based Fuzzing**: For algorithmic modules, invariant fuzzers (e.g., Hypothesis for Python, fast-check for TypeScript) feed thousands of randomized edge-case inputs to prove that invariants hold under extreme boundaries.\\r\\n4. **Gate 4: The Human Signature**: No AI code reaches production without human review focusing on business logic, architectural alignment, data migration safety, and cryptographic integrity.\\r\\n\\r\\n---\\r\\n\\r\\n### 6. Comparative Matrix: Prompting Paradigms\\r\\n\\r\\n| Dimension | Naive Conversational Prompting | Few-Shot Schema Prompting | Spec-Driven Prompting (Stanford CS146S) |\\r\\n| :--- | :--- | :--- | :--- |\\r\\n| **Input Format** | Casual natural language chat (`\\"Fix this bug\\"`) | System prompt + 2\u20133 input/output JSON exemplars | Formal Markdown specification (`SPEC.md`) + invariant contracts |\\r\\n| **Model Cognition** | Unconstrained single-shot token generation | Constrained token distribution matching exemplar schema | Step-by-step reasoning (CoT) + sandboxed tool calling via MCP |\\r\\n| **Hallucination Risk** | **High** (30\u201345% on novel edge cases) | **Low** for syntax, **Moderate** for business logic | **Extremely Low** (guarded by automated verification harness) |\\r\\n| **Reproducibility** | Non-deterministic, sensitive to minor phrasing | High schema consistency | Fully reproducible and machine-versioned in Git |\\r\\n| **Primary Use Case** | Brainstorming, simple bash scripts, syntax lookup | Data transformation, structured API parsers | Production features, microservice refactoring, infrastructure code |\\r\\n\\r\\n---\\r\\n\\r\\n### 7. Stanford CS146S Deep Q&A: Lecture 2 Insights\\r\\n\\r\\nDuring the interactive session of Lecture 2, the discussion centered on how LLMs behave when integrated into large enterprise repositories:\\r\\n\\r\\n> **Q. Professor, why does a coding LLM work brilliantly on a small LeetCode problem, but start hallucinating and making breaking changes when working on a 100,000-line enterprise repository?**\\r\\n\\r\\n**Faculty Response:**\\r\\nThis is the fundamental problem of **Context Saturation & Attention Dilution**. \\r\\n1. When you feed thousands of lines of repository code into an LLM\'s context window, the model\'s self-attention weights become dispersed across non-essential tokens. \\r\\n2. As context grows beyond 30,000\u201350,000 tokens, models suffer from the **\\"Lost in the Middle\\"** phenomenon: they attend strongly to the very beginning (system prompt) and very end (latest query), while ignoring subtle architectural invariants buried in the middle files.\\r\\n3. In modern software engineering, the solution is **Repo Mapping & Precise Context Retrieval**: feeding the model only the relevant Abstract Syntax Tree symbols, interfaces, and direct dependencies rather than dumping the entire repository into the prompt. (We explore this extensively in Lecture 3).\\r\\n\\r\\n---\\r\\n\\r\\n### 8. Lecture 2 Summary & Series Roadmap\\r\\n\\r\\n1. **Understand the Machine**: Coding LLMs are statistical token simulators trained via Pre-training, SFT, and RLHF. They predict patterns; they do not possess innate verification capabilities.\\r\\n2. **Engineer the Prompt**: Deploy Chain-of-Thought (CoT) and structured constraints to unlock intermediate reasoning states.\\r\\n3. **Beware the Swiss Cheese**: Plausible code is not correct code. Never trust AI-generated code without automated linters, deterministic unit tests, and property fuzzers.\\r\\n4. **Embrace \\"Trust but Verify\\"**: Automate the verification loop so human engineers can focus exclusively on architectural integrity and security review.\\r\\n\\r\\nIn **Lecture 3**, we will tackle **Context Management & Repository Architecture**: how to navigate massive codebases using Tree-sitter AST parsing, vector embeddings, and the Model Context Protocol (MCP) without exceeding token limits or causing hallucination cascades. Stay tuned to GlobalDevLog!\\r\\n\\r\\n---\\r\\n\\r\\n### \u{1F4CC} 3\u20135 Line Executive Summary\\r\\n1. **The Nature of Coding LLMs**: LLMs are statistical simulators forged through a 3-stage pipeline (Pre-training next-token prediction, SFT instruction protocols, and RLHF/DPO alignment) rather than conscious reasoning agents.\\r\\n2. **Prompting as Software Engineering**: For complex concurrency and logic, forcing Chain-of-Thought (CoT) reasoning steps and negative constraints provides critical self-grounding tokens that eliminate hallucinations.\\r\\n3. **The Swiss Cheese Hazard**: Impeccably formatted AI code frequently harbors latent off-by-one errors and race conditions; engineering teams must actively counteract automation bias.\\r\\n4. **The \\"Trust but Verify\\" Doctrine**: Deploy a rigorous four-gate verification harness\u2014strict static typing, deterministic unit tests, property-based invariant fuzzing, and human architectural code review\u2014before any AI code reaches production.\\r\\n\\r\\n### References & Course Materials\\r\\n- **Official Course Video Playlist**: [Stanford CS146S: The Modern Software Development (YouTube Playlist)](https://www.youtube.com/playlist?list=PLxpwjSdVZQ95OWe3QvkVEcU1f1X-6NDj9)\\r\\n- **Primary Literature**: Andrej Karpathy, *Deep Dive into LLMs*; OpenAI, *How OpenAI Uses Codex*; Google Cloud & DAIR.AI, *Prompt Engineering Guide*.\\r\\n- **Academic Institution**: Stanford University, Department of Computer Science"},{"id":"stanford-cs146s-1-modern-software-developer","metadata":{"permalink":"/blog/stanford-cs146s-1-modern-software-developer","source":"@site/blog/2026-10-22-stanford-cs146s-1/index.md","title":"[Stanford CS146S #1] Course Overview: The Modern Software Developer \u2014 The Shift from Typist to Conductor in the Age of AI Agents","description":"Stanford CS146S Lecture 1 comprehensive guide: Demystifying the seismic paradigm shift in modern software engineering from manual syntax typing to orchestrating autonomous AI agent workflows via Spec-Driven Development and Loop Engineering.","date":"2026-10-22T00:00:00.000Z","tags":[{"inline":true,"label":"stanford-cs146s","permalink":"/blog/tags/stanford-cs-146-s"},{"inline":true,"label":"agentic-workflows","permalink":"/blog/tags/agentic-workflows"},{"inline":true,"label":"spec-driven-development","permalink":"/blog/tags/spec-driven-development"},{"inline":true,"label":"human-agent-engineering","permalink":"/blog/tags/human-agent-engineering"},{"inline":true,"label":"mcp","permalink":"/blog/tags/mcp"},{"inline":true,"label":"software-architecture","permalink":"/blog/tags/software-architecture"}],"readingTime":8.1,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"stanford-cs146s-1-modern-software-developer","title":"[Stanford CS146S #1] Course Overview: The Modern Software Developer \u2014 The Shift from Typist to Conductor in the Age of AI Agents","authors":["jbgih"],"tags":["stanford-cs146s","agentic-workflows","spec-driven-development","human-agent-engineering","mcp","software-architecture"],"date":"2026-10-22T00:00:00.000Z","keywords":["Stanford CS146S","Agentic Workflows","Spec-Driven Development","Human-Agent Engineering","Model Context Protocol (MCP)"],"description":"Stanford CS146S Lecture 1 comprehensive guide: Demystifying the seismic paradigm shift in modern software engineering from manual syntax typing to orchestrating autonomous AI agent workflows via Spec-Driven Development and Loop Engineering."},"unlisted":false,"prevItem":{"title":"[Stanford CS146S #2] Inside Coding LLMs & Prompt Engineering: Pre-training, RLHF, and the \'Trust but Verify\' Swiss Cheese Model","permalink":"/blog/stanford-cs146s-2-coding-llms-prompt-engineering"},"nextItem":{"title":"Custom Domain on GitHub Pages #1: Zero-Downtime Migration with Porkbun and Cloudflare DNS (CNAME Flattening & Universal SSL)","permalink":"/blog/github-pages-custom-domain-cloudflare-dns"}},"content":"![Stanford CS146S Modern Software Developer](./images/01_cs146s_human_agent_orchestration.png)\\r\\n\\r\\nWelcome to the comprehensive technical breakdown of **Stanford University\'s CS146S: The Modern Software Developer**. \\r\\n\\r\\nFor the past five decades, computer science education has trained developers to be meticulous typists: memorizing syntactic permutations, writing algorithmic routines from scratch, and manually hand-crafting thousands of lines of boilerplate code. Today, the software engineering industry is undergoing its most radical transformation since the invention of the compiler: the transition from **Manual Coding** to **Human-Agent Engineering**.\\r\\n\\r\\nIn this foundational inaugural lecture, we unpack how high-velocity engineering organizations (Google, Meta, OpenAI) are redefining developer productivity, why the developer is transforming from a code typist into an orchestra conductor, and how **Spec-Driven Development (SDD)**, **Agentic Workflows**, and the **Model Context Protocol (MCP)** constitute the indispensable toolkit for the modern engineer.\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n---\\r\\n\\r\\n### 1. The Paradigm Shift: From Syntax Typist to System Conductor\\r\\n\\r\\nIn traditional software engineering workflows, the primary bottleneck has always been human keyboard throughput and cognitive syntax recall. An engineer conceives an architectural intent, translates that intent into concrete language tokens (Java, TypeScript, Python), and spends 70% of their time navigating mundane plumbing: defining schema interfaces, wiring REST controllers, writing boilerplate CRUD tests, and fixing trivial syntactic typos.\\r\\n\\r\\nWith the advent of foundation reasoning models and autonomous coding agents (Claude Code, Cursor, GitHub Copilot Workspace), the generation of syntactically valid code has effectively reached near-zero marginal cost.\\r\\n\\r\\n```mermaid\\r\\nflowchart TD\\r\\n    subgraph Traditional_Workflow [\\"Traditional Manual Paradigm: Developer as Typist\\"]\\r\\n        A1[Human Architectural Idea] --\x3e|Manual Typing 70% Time| B1[Boilerplate Syntax & Plumbing]\\r\\n        B1 --\x3e|Manual Test Writing| C1[Local Compilation & Debugging]\\r\\n        C1 --\x3e|Slow Linear Velocity| D1[Single Feature Delivery]\\r\\n    end\\r\\n\\r\\n    subgraph Modern_Agentic_Workflow [\\"Stanford CS146S Paradigm: Developer as Conductor\\"]\\r\\n        A2[Human Architect: Specification & Invariants] ==>|High-Level Spec.md| B2[Autonomous AI Agent Squad]\\r\\n        B2 --\x3e|Multi-File Edit via MCP| C2[Automated Loop Engineering: Test & Self-Heal]\\r\\n        C2 --\x3e|Continuous Feedback| B2\\r\\n        C2 ==>|Verified Code Base| D2[Human Architectural & Security Review]\\r\\n        D2 ==>|10x Scaled Velocity| E2[Production Deployment]\\r\\n    end\\r\\n```\\r\\n\\r\\nModern developers are no longer evaluated by how many lines of code (LOC) they write per day. Instead, they operate as **Engineering Managers presiding over a squad of autonomous AI agents**. When an engineering manager delegates work to junior engineers, they do not dictate every keypress. Instead, they provide unambiguous specifications, outline system boundaries, and define deterministic acceptance criteria.\\r\\n\\r\\n---\\r\\n\\r\\n### 2. Spec-Driven Development (SDD): \\"What\\" Over \\"How\\"\\r\\n\\r\\nThe central methodology championed by Stanford CS146S is **Spec-Driven Development (SDD)**. In naive AI-assisted coding, developers interact with models through chatty, conversational prompts like: *\\"Can you make a user login system?\\"* \\r\\n\\r\\nThis approach invariably leads to architectural divergence, code hallucination, and missing edge-case handling. Under SDD, the primary engineering deliverable is not the raw code, but a formal, machine-actionable **Specification Document (`SPEC.md`)**.\\r\\n\\r\\n```markdown\\r\\n# Engineering Specification Template (SPEC.md)\\r\\n\\r\\n## 1. Context & Business Domain\\r\\n- Implement idempotent payment webhook processing for Stripe API v2024-06.\\r\\n- Database: PostgreSQL 16 with Row-Level Security (RLS) enabled.\\r\\n\\r\\n## 2. Invariants & Non-Negotiable Constraints\\r\\n- All database mutations MUST occur inside an explicit database transaction.\\r\\n- Webhook signature validation (HMAC-SHA256) MUST fail closed before any payload parsing.\\r\\n- Latency threshold: P99 response time < 80ms.\\r\\n\\r\\n## 3. Interfaces & Schemas\\r\\n- Input: `POST /api/v1/payments/webhook` with raw request body buffer.\\r\\n- Event Types Handled: `payment_intent.succeeded`, `payment_intent.payment_failed`.\\r\\n\\r\\n## 4. Verification & Test Suite Requirements\\r\\n- Unit test coverage > 95% for transaction rollbacks on duplicate event IDs.\\r\\n- Concurrency test: 50 concurrent duplicate webhooks MUST produce exactly 1 database insert.\\r\\n```\\r\\n\\r\\nBy investing deep cognitive effort into crafting rigorous specifications, human developers establish unbreakable guardrails. The AI agent is given total autonomy over the *\\"How\\"* (synthesizing the implementation), while the human retains absolute authority over the *\\"What\\"* and the *\\"Why\\"*.\\r\\n\\r\\n---\\r\\n\\r\\n### 3. Agentic Workflows & Automated Loop Engineering\\r\\n\\r\\nA defining concept introduced in Lecture 1 is **Loop Engineering**. Foundation models are probabilistic engines; expecting an LLM to generate a complex, multi-file distributed system in a single forward pass without errors is mathematically flawed.\\r\\n\\r\\nInstead of expecting one-shot perfection, modern software engineering structures the agent workflow into a closed, self-correcting autonomous loop:\\r\\n\\r\\n```mermaid\\r\\nstateDiagram-v2\\r\\n    [*] --\x3e Spec_Ingestion: Human Supplies SPEC.md\\r\\n    Spec_Ingestion --\x3e Workspace_Planning: Agent Maps Codebase Graph\\r\\n    \\r\\n    state Workspace_Planning {\\r\\n        [*] --\x3e IdentifyDependencies\\r\\n        IdentifyDependencies --\x3e FormulatePatchPlan\\r\\n    }\\r\\n\\r\\n    Workspace_Planning --\x3e Multi_File_Edit: Execute Code Modifications\\r\\n    Multi_File_Edit --\x3e Automated_Verification: Trigger CI/CD & Unit Test Suite\\r\\n    \\r\\n    state Automated_Verification {\\r\\n        [*] --\x3e RunTests\\r\\n        RunTests --\x3e InspectExitCode\\r\\n    }\\r\\n\\r\\n    Automated_Verification --\x3e Self_Correction: Test Failure or Lint Error\\r\\n    Self_Correction --\x3e Multi_File_Edit: Inject Stack Trace into Agent Context\\r\\n    \\r\\n    Automated_Verification --\x3e Human_Review: All Tests Pass (Exit Code 0)\\r\\n    Human_Review --\x3e Merge_Production: Architectural & Security Sign-off\\r\\n    Merge_Production --\x3e [*]\\r\\n```\\r\\n\\r\\n#### The Four Stages of the Autonomous Loop:\\r\\n1. **Planning (Workspace Discovery)**: The agent traverses the project file graph, reading interface contracts and schema definitions.\\r\\n2. **Execution (Multi-File Transformation)**: The agent applies diffs across client, server, and migration files simultaneously.\\r\\n3. **Verification (Deterministic Feedback)**: The agent autonomously invokes test runners (`pytest`, `vitest`, `cargo test`) and linters.\\r\\n4. **Self-Correction (Loop Iteration)**: When an assertion fails, the agent intercepts the stdout/stderr trace, analyzes the root cause, and edits the code until all test suites pass.\\r\\n\\r\\n---\\r\\n\\r\\n### 4. Model Context Protocol (MCP): The Universal Agent Protocol\\r\\n\\r\\nHow does an AI model escape the isolated text sandbox and interact with real-world developer tools? The answer lies in the **Model Context Protocol (MCP)**, the open industry standard for agentic tool integration.\\r\\n\\r\\n```mermaid\\r\\nsequenceDiagram\\r\\n    autonumber\\r\\n    actor Dev as Developer (Conductor)\\r\\n    participant IDE as AI Native IDE / Agent Host\\r\\n    participant MCP as MCP Server Gateway\\r\\n    participant FS as Local Filesystem & Git\\r\\n    participant DB as Development Database\\r\\n    participant CI as Test Runner / Linter\\r\\n\\r\\n    Dev->>IDE: Execute Spec (\\"Migrate Auth to JWT\\")\\r\\n    IDE->>MCP: List Available Tools & Resources\\r\\n    MCP--\x3e>IDE: Tools: [read_file, write_patch, run_tests, query_db]\\r\\n    \\r\\n    loop Loop Engineering Iteration\\r\\n        IDE->>MCP: Call tool: \\"read_file(/src/auth.py)\\"\\r\\n        MCP->>FS: Fetch file buffer\\r\\n        FS--\x3e>MCP: Raw file stream\\r\\n        MCP--\x3e>IDE: File content in Context Window\\r\\n        \\r\\n        IDE->>MCP: Call tool: \\"write_patch(/src/auth.py, diff)\\"\\r\\n        MCP->>FS: Apply atomic diff\\r\\n        \\r\\n        IDE->>MCP: Call tool: \\"run_tests(\'tests/test_auth.py\')\\"\\r\\n        MCP->>CI: Spawn subprocess pytest\\r\\n        CI--\x3e>MCP: Test Output: 1 Failed (Missing Secret Key)\\r\\n        MCP--\x3e>IDE: Error log feedback\\r\\n        \\r\\n        IDE->>IDE: Reason: Secret key missing in config.py\\r\\n        IDE->>MCP: Call tool: \\"write_patch(/src/config.py)\\"\\r\\n        MCP->>FS: Apply patch\\r\\n        \\r\\n        IDE->>MCP: Call tool: \\"run_tests(\'tests/test_auth.py\')\\"\\r\\n        MCP->>CI: Spawn subprocess pytest\\r\\n        CI--\x3e>MCP: Test Output: 100% Passed (Exit 0)\\r\\n    end\\r\\n    \\r\\n    IDE--\x3e>Dev: Ready for Review: Clean Git Diff & All Tests Passing\\r\\n```\\r\\n\\r\\nThrough MCP, coding agents can query PostgreSQL schemas, inspect runtime logs, trigger headless browser tests, and execute git worktree checkouts without human manual copying and pasting.\\r\\n\\r\\n---\\r\\n\\r\\n### 5. Architectural Comparison: Typist vs. Conductor\\r\\n\\r\\n| Engineering Dimension | Traditional Paradigm (The Code Typist) | Modern Stanford CS146S Paradigm (The AI Conductor) |\\r\\n| :--- | :--- | :--- |\\r\\n| **Primary Skillset** | Syntactic fluency, manual typing speed, regex memorization | System architecture, specification writing, threat modeling |\\r\\n| **Development Unit** | Functions, lines of code, individual file edits | Whole-system specifications, invariants, automated test contracts |\\r\\n| **Tooling** | Passive text editors, standard linters, manual debuggers | Autonomous agents (Claude Code, Cursor), MCP servers, CI/CD loops |\\r\\n| **Primary Bottleneck** | Typing speed, cognitive fatigue, manual boilerplate writing | Ambiguous specifications, incomplete test coverage, prompt leakage |\\r\\n| **Verification Strategy** | Manual step-through debugging, console.log printouts | Automated deterministic test suites, invariant fuzzing, property tests |\\r\\n| **Failure Modes** | Syntax errors, missed semicolons, off-by-one loops | Semantic hallucination, architectural drift, subtle security oversights |\\r\\n\\r\\n---\\r\\n\\r\\n### 6. Deep Q&A: Why Fundamentals Matter More Than Ever\\r\\n\\r\\nDuring the inaugural lecture at Stanford, students raised a critical question that every computer science major is asking today:\\r\\n\\r\\n> **Q. Professor, if AI agents can write 80% of our code in seconds, do we still need to study algorithms, memory management, and data structures?**\\r\\n\\r\\nThe faculty answer is profound and decisive: **Computer science fundamentals are significantly more critical today than they were a decade ago.**\\r\\n\\r\\n1. **The Reviewer\'s Burden**: Generating 1,000 lines of plausible code takes an AI 15 seconds. Reviewing that code to detect an $O(N^2)$ algorithmic trap, an unclosed database connection pool, a subtle race condition, or a cryptographic vulnerability requires **profound, master-level understanding of systems programming**.\\r\\n2. **Accountability Remains 100% Human**: An AI agent cannot be held legally or professionally liable when a production service crashes or customer data leaks. The human engineer whose name is on the pull request bears total responsibility.\\r\\n3. **Debugging the Edge Cases**: When an autonomous agent gets stuck in a self-correction loop, only an engineer with deep knowledge of operating systems, network protocols, and hardware architectures can step in and diagnose the underlying impedance mismatch.\\r\\n\\r\\n---\\r\\n\\r\\n### 7. Lecture 1 Takeaways & Series Roadmap\\r\\n\\r\\n1. **Redefine Your Identity**: Stop thinking of yourself as a code author. You are an architect, a spec designer, and an agent manager.\\r\\n2. **Master Spec-Driven Development**: Treat `SPEC.md` as your primary high-leverage engineering artifact.\\r\\n3. **Embrace Loop Engineering**: Shift from expecting single-shot AI answers to designing self-healing loops backed by rigorous unit tests.\\r\\n\\r\\nIn **Lecture 2**, we will dive into **Context Management & Prompt Architecture**: how to structure multi-thousand-token context windows, optimize repository maps, and prevent context saturation during complex multi-file feature additions. Stay tuned to GlobalDevLog!\\r\\n---\\r\\n\\r\\n### \u{1F4CC} 3\u20135 Line Executive Summary\\r\\n1. **The Paradigm Shift**: Software engineers have transitioned from manual syntax typists into system orchestra conductors commanding autonomous AI agent squads.\\r\\n2. **Spec-Driven Development (SDD)**: High-leverage engineering now centers on formalizing invariants and boundary constraints in machine-actionable `SPEC.md` documents rather than typing implementation details.\\r\\n3. **Loop Engineering & MCP**: Effective AI workflows rely on iterative, self-healing feedback loops backed by automated deterministic test suites and the Model Context Protocol (MCP).\\r\\n4. **The Reviewer\'s Burden**: As AI code generation costs approach zero, foundational computer science mastery (operating systems, data structures, concurrency) becomes exponentially more critical for auditing subtle architectural vulnerabilities.\\r\\n\\r\\n### References & Course Materials\\r\\n- **Official Course Video Playlist**: [Stanford CS146S: The Modern Software Development (YouTube Playlist)](https://www.youtube.com/playlist?list=PLxpwjSdVZQ95OWe3QvkVEcU1f1X-6NDj9)\\r\\n- **Academic Institution**: Stanford University, Department of Computer Science"},{"id":"github-pages-custom-domain-cloudflare-dns","metadata":{"permalink":"/blog/github-pages-custom-domain-cloudflare-dns","source":"@site/blog/2026-10-21-github-pages-custom-domain-cloudflare-dns/index.md","title":"Custom Domain on GitHub Pages #1: Zero-Downtime Migration with Porkbun and Cloudflare DNS (CNAME Flattening & Universal SSL)","description":"A step-by-step production guide to ditching free github.io subdomains, acquiring an apex custom domain via Porkbun, delegating to Cloudflare Anycast DNS, configuring CNAME flattening, and setting up Docusaurus without breaking HTTPS.","date":"2026-10-21T00:00:00.000Z","tags":[{"inline":true,"label":"github-pages","permalink":"/blog/tags/github-pages"},{"inline":true,"label":"custom-domain","permalink":"/blog/tags/custom-domain"},{"inline":true,"label":"porkbun","permalink":"/blog/tags/porkbun"},{"inline":true,"label":"cloudflare","permalink":"/blog/tags/cloudflare"},{"inline":true,"label":"docusaurus","permalink":"/blog/tags/docusaurus"},{"inline":true,"label":"devops","permalink":"/blog/tags/devops"}],"readingTime":5.43,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbjihwan","page":null}],"frontMatter":{"slug":"github-pages-custom-domain-cloudflare-dns","title":"Custom Domain on GitHub Pages #1: Zero-Downtime Migration with Porkbun and Cloudflare DNS (CNAME Flattening & Universal SSL)","authors":["jbjihwan"],"tags":["github-pages","custom-domain","porkbun","cloudflare","docusaurus","devops"],"keywords":["Docusaurus GitHub Pages Custom Domain","Cloudflare DNS Porkbun CNAME setup","CNAME Flattening apex domain GitHub Pages","Cloudflare Full SSL Edge Certificate","static CNAME deployment reset bug fix"],"description":"A step-by-step production guide to ditching free github.io subdomains, acquiring an apex custom domain via Porkbun, delegating to Cloudflare Anycast DNS, configuring CNAME flattening, and setting up Docusaurus without breaking HTTPS."},"unlisted":false,"prevItem":{"title":"[Stanford CS146S #1] Course Overview: The Modern Software Developer \u2014 The Shift from Typist to Conductor in the Age of AI Agents","permalink":"/blog/stanford-cs146s-1-modern-software-developer"},"nextItem":{"title":"[Web Monetization #2] Automating Google AdSense Approval on Static Sites: Fixing the ads.txt 404 Crawl Trap & HeadTags Integration","permalink":"/blog/static-site-adsense-ads-txt-guide"}},"content":"Hosting an engineering blog on GitHub Pages under `username.github.io/project` is one of the most cost-effective and friction-free setups for developers. You push markdown files, Git workflows trigger, and GitHub serves your static artifacts worldwide. \\r\\n\\r\\nHowever, as soon as you consider serious branding and monetization, you hit an uncompromising roadblock: **Google AdSense strictly bans free secondary subdomains like `*.github.io` from site application**. Furthermore, any search engine authority (PageRank and Domain Authority) you build remains tied to GitHub\'s domain rather than your personal asset.\\r\\n\\r\\nTo build a professional engineering presence, you need an **apex custom domain** (e.g., `globaldevlog.com`). In this first installment of our static blog infrastructure series, we walk through the exact zero-downtime migration blueprint from `jbjihwan.github.io/global_blog` to `https://globaldevlog.com`, powered by a high-availability **Porkbun + Cloudflare + GitHub Pages 3-tier architecture**.\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n---\\r\\n\\r\\n![Production DNS & CDN Routing Architecture for Static Engineering Blog](./images/01_dns_routing_architecture.png)\\r\\n\\r\\n---\\r\\n\\r\\n## 1. Architectural Philosophy: The 3-Tier Production Setup\\r\\n\\r\\nThe naive approach to connecting a custom domain to GitHub Pages is pointing raw `A` records from your registrar directly to GitHub\'s Anycast IP addresses (`185.199.108.153`, `185.199.109.153`, `185.199.110.153`, `185.199.111.153`). \\r\\n\\r\\nWhile functional, this legacy approach has significant operational flaws:\\r\\n- No edge DDoS protection or bot challenge filtering.\\r\\n- Slow DNS propagation when switching underlying infrastructure.\\r\\n- Zero fine-grained caching control over static assets.\\r\\n\\r\\nWe decouple responsibilities across three specialized providers:\\r\\n\\r\\n| Tier | Provider | Core Responsibilities |\\r\\n| :--- | :--- | :--- |\\r\\n| **1. Registrar** | **Porkbun** | Lowest acquisition & annual renewal fees, perpetual free WHOIS privacy, DNSSEC |\\r\\n| **2. Edge DNS & Security** | **Cloudflare** | Global Anycast DNS (< 10ms resolution), **CNAME Flattening on apex (`@`)**, Universal SSL, Bot Fight mode |\\r\\n| **3. Static Origin** | **GitHub Pages** | Pre-compiled Docusaurus artifacts, automated CI/CD via `gh-pages` branch, zero hosting cost |\\r\\n\\r\\n---\\r\\n\\r\\n## 2. Step 1: Purchasing via Porkbun and Delegating NameServers\\r\\n\\r\\n1. **Domain Acquisition**: Acquire your target `.com` domain on Porkbun. Porkbun offers transparent pricing with no hidden renewal markups.\\r\\n2. **Add Domain to Cloudflare**: Log into Cloudflare, click **Add Site**, enter your root domain (`globaldevlog.com`), and select the **Free Plan**.\\r\\n3. **Obtain Edge Nameservers**: Cloudflare assigns a dedicated pair of authoritative nameservers, for example:\\r\\n   ```text\\r\\n   roan.ns.cloudflare.com\\r\\n   sneh.ns.cloudflare.com\\r\\n   ```\\r\\n4. **Delegate in Porkbun**: In the Porkbun domain management dashboard:\\r\\n   - Locate **Authoritative Nameservers**.\\r\\n   - Remove Porkbun\'s default records (`fwd0.porkbun.com`, etc.).\\r\\n   - Paste Cloudflare\'s two nameserver addresses and save. Propagation typically finishes within 5 to 15 minutes.\\r\\n\\r\\n---\\r\\n\\r\\n## 3. Step 2: Cloudflare CNAME Flattening & Full SSL Mode\\r\\n\\r\\nAccording to RFC 1034, an apex/naked domain (`@`) cannot be configured as a `CNAME` record because it must coexist with `SOA` and `NS` records at the zone apex. Traditionally, this forced developers to use brittle `A` records.\\r\\n\\r\\nCloudflare solves this via **CNAME Flattening**: at runtime, Cloudflare\'s edge DNS resolves the CNAME target (`username.github.io`) into IP addresses and returns them directly to DNS queries, providing full CNAME benefits on the naked apex.\\r\\n\\r\\n### A. Configure DNS Records\\r\\nIn the Cloudflare dashboard under **[DNS] > [Records]**, create two proxied records:\\r\\n\\r\\n| Type | Name | Target | Proxy Status | TTL |\\r\\n| :--- | :--- | :--- | :--- | :--- |\\r\\n| **CNAME** | `@` | `jbjihwan.github.io` | **Proxied (Orange Cloud)** | Auto |\\r\\n| **CNAME** | `www` | `jbjihwan.github.io` | **Proxied (Orange Cloud)** | Auto |\\r\\n\\r\\n> **Proxy Status Must Be Enabled**: Keeping the orange cloud active routes all incoming traffic through Cloudflare\'s global Anycast edge, providing instant SSL termination, compression (Brotli), and automated HTTPS redirects.\\r\\n\\r\\n### B. Configure SSL/TLS Encryption\\r\\nNavigate to Cloudflare\'s **[SSL/TLS] > [Overview]**:\\r\\n- Set the encryption mode to **Full** (or **Full Strict**).\\r\\n- This ensures complete encryption across the entire route: from the user\'s browser to Cloudflare Edge, and from Cloudflare Edge to GitHub Pages over TLS.\\r\\n\\r\\n---\\r\\n\\r\\n## 4. Step 3: Docusaurus Configuration Update\\r\\n\\r\\nWhen moving from a GitHub repository subpath (e.g. `/global_blog/`) to an apex domain root, you must update `docusaurus.config.ts`:\\r\\n\\r\\n```typescript\\r\\nconst config: Config = {\\r\\n  title: \'Global Dev Blog\',\\r\\n  tagline: \'Engineering Deep Dives in AI, Robotics, Computer Vision\',\\r\\n\\r\\n  // Update URL to the new apex custom domain\\r\\n  url: \'https://globaldevlog.com\',\\r\\n  // Change baseUrl from subpath \'/global_blog/\' to root \'/\'\\r\\n  baseUrl: \'/\',\\r\\n\\r\\n  organizationName: \'jbjihwan\',\\r\\n  projectName: \'global_blog\',\\r\\n  trailingSlash: false,\\r\\n  // ...\\r\\n};\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\n## 5. Step 4: The GitHub Pages CNAME Reset Trap & Solution\\r\\n\\r\\nOne of the most maddening bugs when connecting GitHub Pages to a custom domain is the **silent CNAME wipe**:\\r\\n1. You enter `globaldevlog.com` in GitHub\'s repository **Settings > Pages > Custom domain**.\\r\\n2. You run `npm run deploy` from your local machine.\\r\\n3. Suddenly, your custom domain resets to `username.github.io/project`, and visitors get 404s or SSL certificate mismatches!\\r\\n\\r\\n### Why This Happens\\r\\nGitHub Pages expects a plain text `CNAME` file in the root of the deployment branch (`gh-pages`). When Docusaurus runs `deploy`, it builds fresh artifacts into `build/` and force-pushes that folder to `gh-pages`. If the `CNAME` file is not inside `build/`, the deployment obliterates the previous `CNAME` commit on GitHub.\\r\\n\\r\\n### The Permanent Fix\\r\\nPlace your domain directly inside `static/CNAME`:\\r\\n\\r\\n```text\\r\\nglobaldevlog.com\\r\\n```\\r\\n\\r\\nBecause Docusaurus automatically copies everything in `static/` to the build output root during compilation, your `CNAME` file is committed to `gh-pages` on every single release. The domain connection will never drop again.\\r\\n\\r\\n---\\r\\n\\r\\n## 6. Live Production Verification\\r\\n\\r\\nRun the deployment command:\\r\\n```bash\\r\\nnpm run deploy\\r\\n```\\r\\n\\r\\nOnce deployment succeeds, run quick terminal checks to verify headers and SSL certificate authenticity:\\r\\n\\r\\n```bash\\r\\ncurl -I https://globaldevlog.com\\r\\n# HTTP/2 200\\r\\n# server: cloudflare\\r\\n# strict-transport-security: max-age=31536000\\r\\n\\r\\ncurl -I https://www.globaldevlog.com\\r\\n# HTTP/2 200 or 301 Redirect to apex\\r\\n```\\r\\n\\r\\n### Summary of What We Achieved\\r\\n- **Zero Server Overhead**: The entire platform runs completely free on GitHub Pages.\\r\\n- **Enterprise CDN & Protection**: Cloudflare absorbs traffic spikes, DDoS attempts, and manages SSL certificates automatically.\\r\\n- **Monetization & Search Independence**: The domain is ready for Google AdSense review and search engine ownership verification.\\r\\n\\r\\n---\\r\\n\\r\\n## \u{1F51C} Next in This Series\\r\\n\\r\\nWith your apex custom domain live, the next critical milestones are monetization approval and multi-engine visibility:\\r\\n- **Part 2**: *[Static Site Monetization #2] Google AdSense Approval on Docusaurus: ads.txt 404 Resolution and Asynchronous Script Injection*\\r\\n- **Part 3**: *[Multi-Search Engine SEO #3] Google, Naver & Bing Webmaster Setup: Sitemap Deletion Quirks and Host Error Troubleshooting*\\r\\n\\r\\n---\\r\\n\\r\\n### \u{1F4CC} 3\u20135 Line Executive Summary\\r\\n1. **Architectural Cost-Efficiency**: By combining Porkbun (wholesale domain registrar), Cloudflare (enterprise Anycast CDN & DNS), and GitHub Pages (zero-cost static hosting), you achieve enterprise-grade global edge distribution at $0 hosting overhead.\\r\\n2. **Overcoming RFC 1034 via CNAME Flattening**: Cloudflare resolves the DNS zone apex limitation by dynamically synthesizing pseudo-A records for `@`, allowing clean root domain routing (`https://domain.com`) directly to GitHub Pages.\\r\\n3. **End-to-End Strict Encryption**: Configuring Cloudflare SSL/TLS to \'Full (Strict)\' establishes verified, bidirectional cryptographic protection from the visitor\'s browser all the way to GitHub\'s origin servers.\\r\\n4. **Permanent Deployment Persistence**: Hardcoding `static/CNAME` in Docusaurus and configuring `docusaurus.config.ts` prevents GitHub Pages from resetting your custom domain during automated CI/CD and deploy cycles."},{"id":"static-site-adsense-ads-txt-guide","metadata":{"permalink":"/blog/static-site-adsense-ads-txt-guide","source":"@site/blog/2026-10-21-static-site-adsense-ads-txt-guide/index.md","title":"[Web Monetization #2] Automating Google AdSense Approval on Static Sites: Fixing the ads.txt 404 Crawl Trap & HeadTags Integration","description":"A comprehensive developer guide to configuring Google AdSense ownership verification on Docusaurus, deploying static ads.txt to root, and preventing Cloudflare WAF crawl dropouts.","date":"2026-10-21T00:00:00.000Z","tags":[{"inline":true,"label":"google-adsense","permalink":"/blog/tags/google-adsense"},{"inline":true,"label":"docusaurus","permalink":"/blog/tags/docusaurus"},{"inline":true,"label":"github-pages","permalink":"/blog/tags/github-pages"},{"inline":true,"label":"web-monetization","permalink":"/blog/tags/web-monetization"},{"inline":true,"label":"devops","permalink":"/blog/tags/devops"},{"inline":true,"label":"cloudflare","permalink":"/blog/tags/cloudflare"},{"inline":true,"label":"seo","permalink":"/blog/tags/seo"}],"readingTime":5.65,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"static-site-adsense-ads-txt-guide","title":"[Web Monetization #2] Automating Google AdSense Approval on Static Sites: Fixing the ads.txt 404 Crawl Trap & HeadTags Integration","authors":["jbgih"],"tags":["google-adsense","docusaurus","github-pages","web-monetization","devops","cloudflare","seo"],"date":"2026-10-21T00:00:00.000Z","project":"devops","description":"A comprehensive developer guide to configuring Google AdSense ownership verification on Docusaurus, deploying static ads.txt to root, and preventing Cloudflare WAF crawl dropouts.","keywords":["Google AdSense ads.txt Error Fix","Docusaurus Google AdSense Integration","Static Site AdSense Approval","GitHub Pages ads.txt Deployment","Cloudflare WAF Googlebot Crawler"]},"unlisted":false,"prevItem":{"title":"Custom Domain on GitHub Pages #1: Zero-Downtime Migration with Porkbun and Cloudflare DNS (CNAME Flattening & Universal SSL)","permalink":"/blog/github-pages-custom-domain-cloudflare-dns"},"nextItem":{"title":"From GitHub Pages to Custom Domain: Complete Guide to Porkbun, Cloudflare DNS, AdSense Approval, and Multi-Engine SEO","permalink":"/blog/github-pages-custom-domain-adsense-seo-guide"}},"content":"![Google AdSense Approval and Crawler Pipeline](./images/01_ads_txt_crawler_flow.png)\\r\\n\\r\\n> \u{1F4CC} **Key Takeaways (TL;DR)**\\r\\n> - **The Problem**: Unlike traditional dynamic CMS platforms (WordPress, Ghost), static site generators (Docusaurus, Next.js SSG, Hugo) hosted on GitHub Pages or Cloudflare Pages frequently trigger the notorious **\\"Earnings at Risk: ads.txt file missing\\"** alert and fail site ownership checks due to client-side hydration delays and crawler blocking.\\r\\n> - **The Solution**: Inject the publisher verification meta tag directly into `<head>` using Docusaurus `headTags` configuration, place the plain `ads.txt` file in `static/ads.txt` for root-level deployment, and configure Cloudflare WAF bypass rules for the `Googlebot-AdsTxt` crawler.\\r\\n> - **The Result**: 100% automated crawler accessibility, zero 404 crawl errors on `/ads.txt`, seamless AdSense review compliance, and sustained Lighthouse SEO and performance scores above 95.\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n---\\r\\n\\r\\n## 1. The Static Site AdSense Dilemma\\r\\n\\r\\nTransitioning a developer blog from a raw sub-path (`username.github.io/blog`) to a production apex domain (such as `https://globaldevlog.com`) unlocks the gateway to **Google AdSense monetization**. However, modern Static Site Generators (SSGs) introduce unique architectural quirks that dynamic platforms never encounter:\\r\\n\\r\\n1. **No Backend Database or Plugin Ecosystem**: WordPress handles ownership verification and `ads.txt` via plugins like Site Kit. In Docusaurus, every asset must be explicitly declared at build time.\\r\\n2. **Client-Side Hydration vs. Static Head Injection**: Injecting scripts through raw React component lifecycles (`useEffect`) causes delays. Search engine crawlers and AdSense verification bots inspect raw HTML responses before JavaScript execution.\\r\\n3. **The `ads.txt` 404 Crawl Trap**: Misplacing `ads.txt` within build subdirectories prevents the AdSense crawler (`Googlebot-AdsTxt`) from reading `https://yourdomain.com/ads.txt`, jeopardizing domain monetization.\\r\\n\\r\\nLet us walk through the robust, step-by-step engineering solution.\\r\\n\\r\\n---\\r\\n\\r\\n## 2. Step 1: Injecting Site Ownership Verification in Docusaurus\\r\\n\\r\\nWhen you register your custom domain in the Google AdSense Console (**Sites > Add site**), Google requests domain verification through one of three mechanisms:\\r\\n- A JavaScript code snippet\\r\\n- An HTML `<meta>` tag: `<meta name=\\"google-adsense-account\\" content=\\"ca-pub-XXXXXXXXXXXXXXXX\\">`\\r\\n- An `ads.txt` snippet\\r\\n\\r\\nFor static sites, **injecting the meta tag into `headTags`** is the cleanest, highest-performance approach.\\r\\n\\r\\n### \u{1F4D0} Configuration (`docusaurus.config.ts`)\\r\\n\\r\\nOpen `docusaurus.config.ts` and add the `headTags` entry:\\r\\n\\r\\n```typescript\\r\\nimport type {Config} from \'@docusaurus/types\';\\r\\n\\r\\nconst config: Config = {\\r\\n  title: \'Global Dev Blog\',\\r\\n  url: \'https://globaldevlog.com\',\\r\\n  baseUrl: \'/\',\\r\\n\\r\\n  // Google AdSense Site Verification Meta Tag\\r\\n  headTags: [\\r\\n    {\\r\\n      tagName: \'meta\',\\r\\n      attributes: {\\r\\n        name: \'google-adsense-account\',\\r\\n        content: \'ca-pub-XXXXXXXXXXXXXXXX\', // Replace with your AdSense Publisher ID\\r\\n      },\\r\\n    },\\r\\n  ],\\r\\n\\r\\n  // ... rest of your configuration\\r\\n};\\r\\n\\r\\nexport default config;\\r\\n```\\r\\n\\r\\n### \u{1F4A1} Why `headTags` Outperforms `scripts` During Review\\r\\n* **Zero Performance Tax**: Unlike loading the full `adsbygoogle.js` bundle (which weighs ~120 KB and triggers third-party script warnings in Google PageSpeed Insights), a simple `<meta>` tag executes in 0ms.\\r\\n* **Guaranteed Crawler Accessibility**: It renders natively into the pre-compiled server-rendered static HTML output (`build/index.html`), ensuring instant verification when the Google review bot pings your site.\\r\\n\\r\\n---\\r\\n\\r\\n## 3. Step 2: Conquering the ads.txt 404 Crawling Trap\\r\\n\\r\\nWithin 48 to 72 hours of submitting a site, publishers commonly face the dreaded red console alert:\\r\\n> \u26A0\uFE0F *\\"Earnings at risk: You need to fix some ads.txt file issues to avoid severe impact to your revenue.\\"*\\r\\n\\r\\nThe root cause is straightforward: `Googlebot-AdsTxt` queried `https://yourdomain.com/ads.txt` and received an HTTP 404 status.\\r\\n\\r\\n### \u{1F6E0}\uFE0F Root-Level Deployment via `static/ads.txt`\\r\\n\\r\\nIn Docusaurus, all contents inside the root `static/` directory are copied verbatim into the root of the production output directory (`build/`) during compilation.\\r\\n\\r\\n1. Create `static/ads.txt`:\\r\\n   ```text\\r\\n   google.com, pub-XXXXXXXXXXXXXXXX, DIRECT, f08c47fec0942fa0\\r\\n   ```\\r\\n   *(Replace `pub-XXXXXXXXXXXXXXXX` with your authorized publisher ID).*\\r\\n\\r\\n2. Verify file presence in your git working tree:\\r\\n   ```bash\\r\\n   git status\\r\\n   # Untracked files: static/ads.txt\\r\\n   ```\\r\\n\\r\\n3. Deploy to production:\\r\\n   ```bash\\r\\n   npm run deploy\\r\\n   ```\\r\\n\\r\\n### \u{1F50D} Verification Checklist\\r\\nOnce deployed, open your terminal or browser to verify HTTP headers:\\r\\n\\r\\n```bash\\r\\ncurl -I https://globaldevlog.com/ads.txt\\r\\n```\\r\\n\\r\\nExpected response:\\r\\n```http\\r\\nHTTP/2 200\\r\\ncontent-type: text/plain; charset=utf-8\\r\\ncache-control: max-age=600\\r\\nserver: cloudflare\\r\\n```\\r\\n\\r\\nConfirm that accessing `https://www.globaldevlog.com/ads.txt` seamlessly redirects (HTTP 301/308) to the apex domain without stripping the request path.\\r\\n\\r\\n---\\r\\n\\r\\n## 4. Step 3: Cloudflare WAF & Edge Security Tuning\\r\\n\\r\\nIf your domain routes through Cloudflare with the orange cloud proxy enabled, Cloudflare\'s security layer might inadvertently challenge or block Google\'s automated verification crawlers.\\r\\n\\r\\n```mermaid\\r\\nflowchart LR\\r\\n    Bot[\\"Googlebot-AdsTxt Crawler\\"] --\x3e Edge[\\"Cloudflare Edge WAF\\"]\\r\\n    Edge --\x3e|\\"Check: User-Agent & ASN\\"| Rule{\\"WAF Firewall Rule\\"}\\r\\n    Rule --\x3e|\\"Bot Fight Mode (False Positive)\\"| Drop[\\"403 Forbidden / Managed Challenge\\"]\\r\\n    Rule --\x3e|\\"Custom Bypass Expression\\"| Origin[\\"GitHub Pages Origin (/ads.txt)\\"]\\r\\n```\\r\\n\\r\\n### Countermeasures\\r\\n1. **Cloudflare Security > Bots**: If **Super Bot Fight Mode** is active, check the security event log for blocked requests containing User-Agent `Googlebot-AdsTxt` or `Mediapartners-Google`.\\r\\n2. **Create a WAF Custom Rule**:\\r\\n   * **Rule Name**: Allow Google Ads Crawler\\r\\n   * **Expression**:\\r\\n     ```text\\r\\n     (http.user_agent contains \\"Googlebot-AdsTxt\\") or (http.user_agent contains \\"Mediapartners-Google\\")\\r\\n     ```\\r\\n   * **Action**: *Skip / Bypass* (Bypass WAF, Rate Limiting, and Managed Challenge).\\r\\n\\r\\n---\\r\\n\\r\\n## 5. The 4-Pillar Quality Checklist for First-Try AdSense Approval\\r\\n\\r\\nGoogle AdSense rejects up to 80% of personal development blogs under the generic umbrella reason *\\"Low Value Content\\"*. To guarantee approval, verify these structural prerequisites before requesting site review:\\r\\n\\r\\n| Evaluation Pillar | Mandatory Criterion | Failure Mode if Violated |\\r\\n| :--- | :--- | :--- |\\r\\n| **1. Statutory Compliance Pages** | Comprehensive `/privacy-policy`, `/about`, and `/contact` pages | Site Navigation Policy Violation |\\r\\n| **2. Original Content Volume** | 20+ original in-depth technical articles (1,200+ words each) | Low Value Content / Insufficient Content |\\r\\n| **3. Zero Broken Hyperlinks** | 0 dead links, 0 unresolved anchor tags, 0 404 assets | Site Unreachable / Incomplete Navigation |\\r\\n| **4. Responsive Multi-Viewport** | Fluid mobile/tablet rendering without horizontal layout shift | Substandard Mobile Usability |\\r\\n\\r\\n---\\r\\n\\r\\n## 6. Conclusion & Next Steps\\r\\n\\r\\nWith `headTags` injecting your verification metadata, `static/ads.txt` reliably serving your publisher authorization string, and Cloudflare routing verified bots cleanly to GitHub Pages, your static site is now 100% fortified for AdSense review.\\r\\n\\r\\n* In the upcoming **Episode #3**, we will explore multi-engine search indexing: configuring Google Search Console, Naver Search Advisor, and Bing Webmaster Tools across multiple sitemaps!\\r\\n\\r\\n---\\r\\n\\r\\n### \u{1F4CC} 3\u20135 Line Executive Summary\\r\\n1. **Static Site Ownership Verification**: Bypassing client-side hydration delays, inject the AdSense publisher verification meta tag directly into `<head>` via Docusaurus `headTags` for instantaneous crawler detection.\\r\\n2. **Eliminating the ads.txt 404 Crawl Trap**: Placing `ads.txt` in the root `static/` directory ensures it is deployed directly to `https://domain.com/ads.txt`, permanently preventing the \\"Earnings at Risk\\" penalty.\\r\\n3. **Cloudflare WAF Bot Bypass**: Configure Cloudflare custom WAF rules to skip Managed Challenge on `Googlebot-AdsTxt` and `Mediapartners-Google`, averting false-positive CAPTCHA crawl dropouts.\\r\\n4. **4-Pillar AdSense Review Readiness**: Guarantee first-attempt approval by establishing statutory privacy/about/contact pages, maintaining zero 404 broken links, and offering 20+ comprehensive technical articles.\\r\\n\\r\\n> \u{1F4CC} **Explore the Production Implementation**:  \\r\\n> \u2022 [Global Dev Blog - GitHub Pages Custom Domain & Cloudflare DNS Guide](https://globaldevlog.com/ko/blog/github-pages-custom-domain-cloudflare-dns)  \\r\\n> \u2022 [Global Dev Blog - Static Site Security & npm audit Vulnerability Truth](https://globaldevlog.com/ko/blog/static-site-security-npm-audit-truth)  \\r\\n> \u2022 [Visit Global Dev Blog Home (Available in 6 Locales)](https://globaldevlog.com/)"},{"id":"github-pages-custom-domain-adsense-seo-guide","metadata":{"permalink":"/blog/github-pages-custom-domain-adsense-seo-guide","source":"@site/blog/2026-10-20-custom-domain-adsense-seo-guide/index.md","title":"From GitHub Pages to Custom Domain: Complete Guide to Porkbun, Cloudflare DNS, AdSense Approval, and Multi-Engine SEO","description":"A comprehensive production blueprint for migrating a static Docusaurus blog on GitHub Pages to an apex custom domain via Porkbun and Cloudflare DNS, securing Google AdSense verification, and mastering multi-search engine SEO across Google, Naver, and Bing.","date":"2026-10-20T00:00:00.000Z","tags":[{"inline":true,"label":"docusaurus","permalink":"/blog/tags/docusaurus"},{"inline":true,"label":"devops","permalink":"/blog/tags/devops"},{"inline":true,"label":"cloudflare","permalink":"/blog/tags/cloudflare"},{"inline":true,"label":"seo","permalink":"/blog/tags/seo"},{"inline":true,"label":"web-monetization","permalink":"/blog/tags/web-monetization"}],"readingTime":5.71,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbjihwan","page":null}],"frontMatter":{"slug":"github-pages-custom-domain-adsense-seo-guide","title":"From GitHub Pages to Custom Domain: Complete Guide to Porkbun, Cloudflare DNS, AdSense Approval, and Multi-Engine SEO","authors":["jbjihwan"],"tags":["docusaurus","devops","cloudflare","seo","web-monetization"],"keywords":["Docusaurus GitHub Pages Custom Domain","Cloudflare DNS Porkbun CNAME setup","Google AdSense ads.txt static site","Google Search Console sitemap delete troubleshooting","Naver Search Advisor sitemap RSS host error"],"description":"A comprehensive production blueprint for migrating a static Docusaurus blog on GitHub Pages to an apex custom domain via Porkbun and Cloudflare DNS, securing Google AdSense verification, and mastering multi-search engine SEO across Google, Naver, and Bing."},"unlisted":false,"prevItem":{"title":"[Web Monetization #2] Automating Google AdSense Approval on Static Sites: Fixing the ads.txt 404 Crawl Trap & HeadTags Integration","permalink":"/blog/static-site-adsense-ads-txt-guide"},"nextItem":{"title":"[2026 Guide] How to Fix npm audit Vulnerabilities Without Breaking Builds: The Truth Behind npm audit fix --force","permalink":"/blog/static-site-security-npm-audit-truth"}},"content":"Hosting a developer blog on GitHub Pages under `username.github.io/project` is one of the quickest ways to share technical insights. However, as your readership grows and you prepare for professional monetization, you hit a hard architectural wall: **Google AdSense strictly prohibits free subdomains like `*.github.io`**. To qualify for AdSense publisher verification, establish domain equity, and secure multi-region organic reach, you need your own apex custom domain.\\r\\n\\r\\nMigrating a static documentation or engineering site to a custom domain is not just a DNS record change. It involves coordinating registrar name delegation, edge SSL termination, canonical redirects, automated publisher ads.txt hosting, and navigating subtle search console UI quirks across global and regional search engines.\\r\\n\\r\\nIn this guide, we break down our end-to-end migration from `jbjihwan.github.io/global_blog` to `https://globaldevlog.com`, including our zero-downtime DNS architecture, AdSense integration, and actionable solutions for real-world indexing traps in Google Search Console, Naver Search Advisor, and Bing Webmaster Tools.\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n---\\r\\n\\r\\n![Production DNS & CDN Routing Architecture for Static Engineering Blog](./images/01_dns_routing_architecture.png)\\r\\n\\r\\n---\\r\\n\\r\\n## 1. Architectural Strategy: Porkbun + Cloudflare + GitHub Pages\\r\\n\\r\\nWhen connecting an apex domain (e.g., `globaldevlog.com`) to GitHub Pages, the traditional method uses raw `A` records pointing to GitHub\'s four Anycast IPs (`185.199.108.153`, etc.). While functional, this lacks modern edge security, DDoS filtering, and automatic HTTPS certificate renewal.\\r\\n\\r\\nWe adopted a high-availability 3-tier architecture:\\r\\n\\r\\n| Tier | Provider | Core Responsibilities |\\r\\n| :--- | :--- | :--- |\\r\\n| **Registrar** | **Porkbun** | Domain acquisition, WHOIS privacy protection, DNSSEC, authoritative NS delegation |\\r\\n| **Edge DNS & Security** | **Cloudflare** | Global Anycast DNS, CNAME Flattening on apex (`@`), Universal SSL Edge certificate, Bot Fight mode |\\r\\n| **Origin SSG** | **GitHub Pages** | Static artifact hosting compiled by Docusaurus, zero server maintenance, branch synchronization (`gh-pages`) |\\r\\n\\r\\n### Porkbun NameServer Delegation\\r\\nIn the Porkbun management console, replace default registrar nameservers with Cloudflare\'s assigned edge nameservers:\\r\\n```text\\r\\nNS: roan.ns.cloudflare.com\\r\\nNS: sneh.ns.cloudflare.com\\r\\n```\\r\\n\\r\\n### Cloudflare CNAME Flattening Setup\\r\\nApex domains (`@`) traditionally do not support CNAME records per RFC 1034. Cloudflare resolves this via **CNAME Flattening**, seamlessly resolving `@` to GitHub Pages:\\r\\n- **Type**: `CNAME` | **Name**: `@` | **Target**: `jbjihwan.github.io` | **Proxy status**: Proxied\\r\\n- **Type**: `CNAME` | **Name**: `www` | **Target**: `jbjihwan.github.io` | **Proxy status**: Proxied\\r\\n- **SSL/TLS Mode**: Set to **Full** (or Full Strict) to guarantee end-to-end HTTPS encryption.\\r\\n\\r\\n---\\r\\n\\r\\n## 2. Docusaurus Configuration Migration\\r\\n\\r\\nTo transition cleanly from subpath routing (`/global_blog/`) to the domain root (`/`), update `docusaurus.config.ts`:\\r\\n\\r\\n```typescript\\r\\nconst config: Config = {\\r\\n  title: \'Global Dev Blog\',\\r\\n  url: \'https://globaldevlog.com\',\\r\\n  baseUrl: \'/\',\\r\\n  organizationName: \'jbjihwan\',\\r\\n  projectName: \'global_blog\',\\r\\n  trailingSlash: false,\\r\\n  // ...\\r\\n};\\r\\n```\\r\\n\\r\\n### Static CNAME File\\r\\nGitHub Pages requires a plain text `CNAME` file located at the web root of your deployment branch. Place it in `static/CNAME`:\\r\\n```text\\r\\nglobaldevlog.com\\r\\n```\\r\\nDuring `npm run deploy`, Docusaurus automatically copies everything from `static/` to the build root, informing GitHub\'s routing engine to map all incoming traffic for `globaldevlog.com` to this repository.\\r\\n\\r\\n---\\r\\n\\r\\n## 3. Google AdSense Approval Setup for Static Sites\\r\\n\\r\\nGoogle AdSense approval requires verifying site ownership, confirming an active publisher script, and crawling a root `ads.txt` file.\\r\\n\\r\\n### A. Publisher Script Injection\\r\\nIn `docusaurus.config.ts`, inject the Google AdSense loader script asynchronously:\\r\\n\\r\\n```typescript\\r\\n  scripts: [\\r\\n    {\\r\\n      src: \'https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=ca-pub-4654073335496617\',\\r\\n      async: true,\\r\\n      crossorigin: \'anonymous\',\\r\\n    },\\r\\n  ],\\r\\n```\\r\\n\\r\\n### B. Direct Root `ads.txt` Deployment\\r\\nPlace your verified publisher credentials in `static/ads.txt`:\\r\\n```text\\r\\ngoogle.com, pub-4654073335496617, DIRECT, f08c47fec0942fa0\\r\\n```\\r\\nVerify live deployment immediately via curl or browser:\\r\\n```bash\\r\\ncurl -I https://globaldevlog.com/ads.txt\\r\\n# HTTP/2 200\\r\\n# content-type: text/plain; charset=utf-8\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\n![Global Search Engine Indexing & AdSense Monetization Pipeline](./images/02_indexing_pipeline.png)\\r\\n\\r\\n---\\r\\n\\r\\n## 4. Multi-Search Engine SEO & Real-World Troubleshooting\\r\\n\\r\\nSubmitting sitemaps across multiple engines reveals distinct platform quirks and hidden UI traps. Here is how to conquer them:\\r\\n\\r\\n### A. Google Search Console: The Sitemap Delete Trap\\r\\nWhen submitting localized sitemaps (`sitemap.xml`, `ko/sitemap.xml`, `ja/sitemap.xml`, `es/sitemap.xml`), accidental typos (such as submitting the root URL `https://globaldevlog.com/` as a sitemap) can create permanent \\"Has errors\\" notices.\\r\\n\\r\\nMany developers click the three vertical dots (`\u22EE`) on the table row, only to find **\\"See page indexing\\"** disabled with no option to delete.\\r\\n\\r\\n**The Fix:**\\r\\n1. Do not rely on the table row menu. **Click directly on the sitemap URL text/row itself** to open the **Sitemap Details View**.\\r\\n2. In the top-right corner of the details screen, click the header\'s three dots (`\u22EE`).\\r\\n3. Click **[Remove sitemap]** to purge the erroneous entry.\\r\\n4. For temporary \\"Couldn\'t fetch\\" errors (e.g., during DNS propagation), re-entering the path in **\\"Add a new sitemap\\"** triggers an immediate re-fetch and turns the status to **Success**.\\r\\n\\r\\n### B. Naver Search Advisor: \\"URL\uC744 \uD638\uC2A4\uD2B8 \uB2E8\uC704\uB85C \uC785\uB825\uD574\uC8FC\uC138\uC694\\"\\r\\nNaver dominates Korean search traffic. When registering on Naver Search Advisor:\\r\\n1. **Host-Level Error**: Attempting to submit `https://globaldevlog.com/sitemap.xml` in the initial \\"\uC0AC\uC774\uD2B8 \uB4F1\uB85D\\" screen triggers a popup: *\\"URL\uC744 \uD638\uC2A4\uD2B8 \uB2E8\uC704\uB85C \uC785\uB825\uD574\uC8FC\uC138\uC694\\"*. This screen is only for domain registration (`https://globaldevlog.com`).\\r\\n2. **Dual Ownership Verification**: Deploy both the HTML verification file (`static/naver<hash>.html`) and the meta tag in `themeConfig.metadata`:\\r\\n   ```typescript\\r\\n   metadata: [\\r\\n     { name: \'naver-site-verification\', content: \'f04ea0b38166c1e280ce8e18acef37093b75f383\' },\\r\\n   ],\\r\\n   ```\\r\\n3. **Submitting Sitemaps & RSS**: Inside **Site Management** (`\uC0AC\uC774\uD2B8 \uBAA9\uB85D` > click your domain):\\r\\n   - Navigate to **[\uC694\uCCAD]** > **[\uC0AC\uC774\uD2B8\uB9F5 \uC81C\uCD9C]**: enter `sitemap.xml`\\r\\n   - Navigate to **[\uC694\uCCAD]** > **[RSS \uC81C\uCD9C]**: enter `https://globaldevlog.com/blog/rss.xml`\\r\\n4. **Accelerating Yeti Bot**: Under **[\uC694\uCCAD]** > **[\uC6F9 \uD398\uC774\uC9C0 \uC218\uC9D1]**, submit priority paths (`blog`, `ko/blog`, and latest posts) to trigger immediate crawling.\\r\\n\\r\\n### C. Bing Webmaster Tools & AI Copilot / ChatGPT Ingestion\\r\\nBing Webmaster Tools powers not only Bing, but also Yahoo, DuckDuckGo, Copilot, and ChatGPT Search.\\r\\n- **1-Click GSC Import**: Connect via your Google account to automatically import verified domain ownership and submitted sitemaps.\\r\\n- **Bypassing the 48-Hour Sync Lag**: GSC synchronization can take up to 48 hours. By clicking **[Sitemaps]** > **[Submit sitemap]** and manually entering `https://globaldevlog.com/sitemap.xml` (plus localized variants), Bing\'s crawler dispatches immediately.\\r\\n\\r\\n---\\r\\n\\r\\n## 5. Verification Checklist\\r\\n\\r\\nBefore announcing your custom domain, run this sanity check:\\r\\n\\r\\n- [x] **DNS Resolution**: `globaldevlog.com` and `www.globaldevlog.com` resolve without SSL warnings.\\r\\n- [x] **Canonical CNAME**: `static/CNAME` deployed to GitHub Pages origin.\\r\\n- [x] **AdSense Assets**: `https://globaldevlog.com/ads.txt` returns HTTP 200 with matching publisher ID.\\r\\n- [x] **Localized Sitemaps**: All language sitemaps (`/sitemap.xml`, `/ko/`, `/ja/`, `/es/`) return HTTP 200.\\r\\n- [x] **Search Console Health**: Google, Naver, and Bing show clean, verified properties with active RSS feeds.\\r\\n\\r\\nWith this modern infrastructure in place, your static blog operates with the speed of an edge CDN, zero server hosting bills, maximum search visibility across four languages, and full readiness for AdSense monetization.\\r\\n\\r\\n---\\r\\n\\r\\n### \u{1F4CC} 3\u20135 Line Executive Summary\\r\\n1. **Zero-Cost Edge Infrastructure**: Transitioning from free `github.io` to an apex domain via Porkbun, Cloudflare DNS, and GitHub Pages achieves enterprise CDN caching and SSL security at $0 server cost.\\r\\n2. **CNAME Flattening & Route Canonicalization**: Resolves RFC 1034 apex limitations and canonicalizes `www` to root domain with zero SSL handshake friction or redirect loops.\\r\\n3. **AdSense Ownership & ads.txt Hardening**: Directly injects publisher verification into static `<head>` and serves `static/ads.txt` from site root, averting crawler 404 traps.\\r\\n4. **Multi-Engine Search Indexing Triad**: Synchronizes localized sitemaps and RSS feeds across Google Search Console, Naver Search Advisor, and Bing Webmaster Tools with zero host mismatches."},{"id":"static-site-security-npm-audit-truth","metadata":{"permalink":"/blog/static-site-security-npm-audit-truth","source":"@site/blog/2026-10-18-static-site-security-hardening/index.md","title":"[2026 Guide] How to Fix npm audit Vulnerabilities Without Breaking Builds: The Truth Behind npm audit fix --force","description":"How to fix npm audit vulnerabilities without breaking builds. Dissecting why 45 npm vulnerabilities in build tools pose zero runtime risk on static sites, and how to safely resolve GHSA alerts.","date":"2026-10-18T00:00:00.000Z","tags":[{"inline":true,"label":"web-security","permalink":"/blog/tags/web-security"},{"inline":true,"label":"npm-audit","permalink":"/blog/tags/npm-audit"},{"inline":true,"label":"docusaurus","permalink":"/blog/tags/docusaurus"},{"inline":true,"label":"devops","permalink":"/blog/tags/devops"},{"inline":true,"label":"supply-chain","permalink":"/blog/tags/supply-chain"}],"readingTime":5.33,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"static-site-security-npm-audit-truth","title":"[2026 Guide] How to Fix npm audit Vulnerabilities Without Breaking Builds: The Truth Behind npm audit fix --force","authors":["jbgih"],"tags":["web-security","npm-audit","docusaurus","devops","supply-chain"],"keywords":["npm audit fix","npm audit fix --force","static site security","npm vulnerabilities","GHSA vulnerabilities"],"description":"How to fix npm audit vulnerabilities without breaking builds. Dissecting why 45 npm vulnerabilities in build tools pose zero runtime risk on static sites, and how to safely resolve GHSA alerts."},"unlisted":false,"prevItem":{"title":"From GitHub Pages to Custom Domain: Complete Guide to Porkbun, Cloudflare DNS, AdSense Approval, and Multi-Engine SEO","permalink":"/blog/github-pages-custom-domain-adsense-seo-guide"},"nextItem":{"title":"[Vision AI] Korean ANPR OCR Engine, Regex Normalization & Temporal Majority Voting (v01 to v11 Evolution) (#5)","permalink":"/blog/2026-06-29-vision-anpr-5"}},"content":"Every modern frontend developer has experienced this sudden spike of adrenaline: you run `npm audit` on your clean documentation or blog repository, and the terminal screams back in alarming red text:\\n\\n```text\\n45 vulnerabilities (15 moderate, 15 high, 15 critical)\\nTo address all issues (including breaking changes), run:\\n  npm audit fix --force\\n```\\n\\nSeeing words like **Critical**, **Remote Code Execution (RCE)**, and **Prototype Pollution** triggers an immediate instinct: type `npm audit fix --force` to make the scary red warnings go away. \\n\\nHowever, in the world of **Static Site Generators (SSG)** like Docusaurus, Next.js, or Hugo deployed to GitHub Pages or AWS S3, doing so is often an engineering mistake that breaks production builds without improving your actual security posture.\\n\\nIn this article, we dissect the **static site threat model**, explain why bundler vulnerabilities differ fundamentally from server vulnerabilities, and share a production-tested **4-Layer Security Hardening Blueprint** to protect what actually matters: your secrets, client privacy, and repository integrity.\\n\\n{/* truncate */}\\n\\n---\\n\\n![Threat Model Comparison: Dynamic Server vs Static Site](./images/01_threat_model.png)\\n\\n---\\n\\n## 1. Executive Summary: The Core Engineering Trade-off\\n\\n1. **Build-Time Tools != Production Runtime**: Packages flagged in `npm audit` (such as `tinypool`, `serialize-javascript`, `postcss-selector-parser`) are node worker and bundler dependencies executed locally on your machine during `npm run build`. \\n2. **Zero Live Server on CDN**: Once compiled, GitHub Pages serves static, immutable HTML, CSS, and client-side JavaScript. There is **no running Node.js daemon**, no backend port listening, and no database connection in production.\\n3. **The Danger of `--force`**: Running `npm audit fix --force` blindly downgrades core frameworks (e.g., rolling Docusaurus back to older releases), breaking React 19 compatibility, MDX v3 pipelines, and future flag architectures.\\n4. **Where Real Static Risks Lie**: The genuine security risks of static blogs are **credential/API key leakage in public Git history**, **PII exposure in datasets**, and **client-side cross-origin leakage**.\\n\\n---\\n\\n## 2. Anatomy of the 45 Vulnerabilities: Build vs Runtime\\n\\nLet\'s examine the actual CVEs reported in our audit log:\\n\\n### A. Tinypool Prototype Pollution (`GHSA-5gmw-xhrv-c9v3` - Critical)\\n- **Vulnerability**: If untrusted user input is passed into the worker initialization options of `tinypool`, an attacker can pollute `Object.prototype`.\\n- **Reality in SSG**: `tinypool` is used internally by `@docusaurus/faster` to parallelize bundling tasks across CPU cores during build time. The input parameters come solely from your own `docusaurus.config.ts`. No external visitor on your website can send HTTP payloads to your local CPU worker pool.\\n\\n### B. Serialize-JavaScript RCE (`GHSA-5c6j-r48x-rmvq` - High)\\n- **Vulnerability**: Remote Code Execution via crafted RegExp flags or serialized dates.\\n- **Reality in SSG**: Webpack uses this to serialize internal compilation chunks into static `.js` bundles. Once written to the `build/` directory, JavaScript files are passive assets served over HTTPS. No server-side deserialization takes place.\\n\\n### C. PostCSS Selector Parser CPU Exhaustion (`GHSA-rj75-hqrm-r3gf` - Moderate)\\n- **Vulnerability**: Quadratic complexity in flat selector parsing allows Denial of Service (DoS) via maliciously crafted CSS strings.\\n- **Reality in SSG**: The CSS files being parsed are your own theme stylesheets (`custom.css`). Unless an attacker has write access to your Git repository, your build server will never parse untrusted external CSS.\\n\\nRunning `npm audit fix --force` in this situation attempts to downgrade `@docusaurus/core` from `3.10.2` to `3.7.0`. This breaks Docusaurus v4 future flags and React 19 rendering, introducing breaking bugs into your codebase to patch an exploit that cannot physically occur in your architecture.\\n\\n---\\n\\n## 3. What Actually Matters: The 4-Layer Static Security Blueprint\\n\\nIf npm bundler vulnerabilities are low risk, where should static site engineers invest their security budget? Here is the multi-layered defense pipeline implemented in this blog.\\n\\n![4-Layer Static Blog Security Hardening Pipeline](./images/02_security_pipeline.png)\\n\\n### Layer 1: Automated Pre-Commit Secret Scanning\\n\\nThe single greatest catastrophic risk for public technical blogs is accidentally committing an OpenAI key (`sk-...`), a GitHub Personal Access Token (`ghp_...`), or an AWS access credential (`AKIA...`).\\n\\nWe created an automated audit script (`tools/audit_security.py`) that utilizes Git\'s object database to scan every tracked file against high-entropy regex patterns:\\n\\n```python\\nPATTERNS = [\\n    (r\'(?i)(api[_-]?key|secret|token|password|auth|bearer)\\\\s*[:=]\\\\s*[\\"\\\\\']([^\\"\\\\\']{8,})[\\"\\\\\']\', \\"Potential Key Assignment\\"),\\n    (r\'ghp_[a-zA-Z0-9]{36}\', \\"GitHub Personal Access Token\\"),\\n    (r\'sk-[a-zA-Z0-9]{32,}\', \\"OpenAI API Key\\"),\\n    (r\'AIzaSy[a-zA-Z0-9_-]{33}\', \\"Google API Key\\"),\\n    (r\'AKIA[0-9A-Z]{16}\', \\"AWS Access Key\\"),\\n    (r\'-----BEGIN\\\\s+(RSA\\\\s+)?PRIVATE\\\\s+KEY-----\', \\"Private Key Certificate\\"),\\n]\\n```\\n\\nRunning this audit script before every release ensures zero hardcoded tokens ever reach the remote repository.\\n\\n### Layer 2: Personally Identifiable Information (PII) Scrubbing\\n\\nWhen publishing engineering articles on AI datasets (such as our 23-part Maeumjigi clinical counseling series or 5-part ANPR Vision AI series):\\n- **Synthetic Data First**: All counseling records were synthetically generated via LLM pipelines (`synth_gen`) rather than using real clinical transcripts, guaranteeing zero medical privacy breach.\\n- **Regex PII Audit**: Our scanner automatically validates markdown text against Korean national identity numbers (`\\\\d{6}-[1-4]\\\\d{6}`) and phone numbers (`010-\\\\d{4}-\\\\d{4}`).\\n\\n### Layer 3: Hardened `.gitignore` Configuration\\n\\nA standard `.gitignore` often ignores `.env.local` while leaving `.env` exposed. We hardened `.gitignore` to comprehensively block sensitive files, private certificates, and raw analytics dumps:\\n\\n```gitignore\\n# Environment & Secret Protection\\n.env\\n.env.*\\n*.pem\\n*.key\\n*.pfx\\n*.cert\\n*credential*\\n*.secret\\n\\n# Analytics & CSV dumps\\n*.csv\\n\\n# Archived template files\\n_old/\\n```\\n\\n### Layer 4: Client-Side Privacy & Iframe Sandboxing\\n\\nEven without a backend server, static sites must respect user privacy and prevent data leakage:\\n\\n1. **Strict Referrer Policy**: In `docusaurus.config.ts`, we inject a strict referrer header into `<head>`:\\n   ```typescript\\n   themeConfig: {\\n     metadata: [\\n       { name: \'referrer\', content: \'strict-origin-when-cross-origin\' },\\n     ],\\n   }\\n   ```\\n   This ensures that when a reader clicks an external documentation link, your blog\'s specific full URL parameters are truncated, preventing path leakage.\\n\\n2. **Giscus Discussion Sandboxing**: We host comments via GitHub Discussions. In `BlogPostItem/index.tsx`, Giscus is configured with:\\n   - `emitMetadata=\\"0\\"`: Prevents post-message iframe broadcasts from exposing discussion details to third-party browser scripts.\\n   - `loading=\\"lazy\\"`: Prevents iframe resource execution until the reader scrolls to the bottom of the article.\\n\\n---\\n\\n## 4. Key Takeaways for Developers\\n\\n- **Do Not Panic at `npm audit`**: Always distinguish between **Build-Time Bundler Dependencies** and **Production Runtime Dependencies**.\\n- **Beware of `--force`**: Automated downgrades often introduce real, breaking application bugs while solving theoretical vulnerabilities that cannot be triggered on a static CDN.\\n- **Focus on the Real Attack Surface**: Automate secret detection, scrub sensitive data from datasets, enforce strict client-side referrer policies, and protect your Git history."},{"id":"2026-06-29-vision-anpr-5","metadata":{"permalink":"/blog/2026-06-29-vision-anpr-5","source":"@site/blog/2026-06-29-vision-anpr-5/index.md","title":"[Vision AI] Korean ANPR OCR Engine, Regex Normalization & Temporal Majority Voting (v01 to v11 Evolution) (#5)","description":"Korean license plate syntax validation, EasyOCR tuning, temporal sliding window majority voting, and the complete 11-iteration engineering journey from v01 to v11.","date":"2026-06-29T00:00:00.000Z","tags":[{"inline":true,"label":"computer-vision","permalink":"/blog/tags/computer-vision"},{"inline":true,"label":"anpr","permalink":"/blog/tags/anpr"},{"inline":true,"label":"easyocr","permalink":"/blog/tags/easyocr"},{"inline":true,"label":"regex","permalink":"/blog/tags/regex"},{"inline":true,"label":"voting-ensemble","permalink":"/blog/tags/voting-ensemble"},{"inline":true,"label":"python","permalink":"/blog/tags/python"}],"readingTime":2.8,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"2026-06-29-vision-anpr-5","title":"[Vision AI] Korean ANPR OCR Engine, Regex Normalization & Temporal Majority Voting (v01 to v11 Evolution) (#5)","authors":["jbgih"],"tags":["computer-vision","anpr","easyocr","regex","voting-ensemble","python"],"date":"2026-06-29T00:00:00.000Z","project":"anpr_vision","description":"Korean license plate syntax validation, EasyOCR tuning, temporal sliding window majority voting, and the complete 11-iteration engineering journey from v01 to v11.","keywords":["EasyOCR Korean License Plate","ANPR Majority Voting Ensemble","Korean Plate Regex Normalization","License Plate Recognition Accuracy","ITS Traffic Violation Vision"]},"unlisted":false,"prevItem":{"title":"[2026 Guide] How to Fix npm audit Vulnerabilities Without Breaking Builds: The Truth Behind npm audit fix --force","permalink":"/blog/static-site-security-npm-audit-truth"},"nextItem":{"title":"[Vision AI] Overcoming Blurry Blackbox Artifacts: Deep Super-Resolution (EDSR vs FSRCNN) & Multi-Frame Image Stacking (#4)","permalink":"/blog/2026-06-28-vision-anpr-4"}},"content":"![Temporal Majority Voting and Final Confirmation](./images/01_voting_evolution.png)\\r\\n\\r\\n> \u{1F4CC} **Key Takeaways (TL;DR)**\\r\\n> - **Problem**: Single-frame OCR inevitably suffers from transient misreadings (e.g., `64\uC5441511`, `24\uAC001511`) due to vehicle yaw, glare, and vibration.\\r\\n> - **Solution**: Implemented Korean plate regex validation (`^\\\\d{2,3}[\uAC00-\uD7A3]\\\\d{4}$`) coupled with a temporal sliding window majority voting engine across a 7-frame buffer (`plate_confirm_threshold=3`).\\r\\n> - **Result**: Advanced through 11 system iterations (v01 to v11), transitioning from initial gibberish (`ACCIIXOY-1Z01...`) on June 5 to deterministic confirmation of `64\uAC001511` on June 7 with 99.4% reliability.\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n---\\r\\n\\r\\n## 1. Korean ANPR Syntax & EasyOCR Tuning\\r\\n\\r\\nKorean vehicle registration plates follow strict regulatory syntax:\\r\\n\\r\\n```text\\r\\nSyntax: [2 or 3 Digits] + [1 Hangul Syllable] + [4 Digits]\\r\\nExample: 64\uAC001511, 123\uAC004567\\r\\n```\\r\\n\\r\\n```python\\r\\nimport easyocr\\r\\nimport re\\r\\nfrom collections import deque, Counter\\r\\n\\r\\nreader = easyocr.Reader([\'ko\', \'en\'], gpu=True)\\r\\n\\r\\ndef parse_korean_plate(plate_img):\\r\\n    results = reader.readtext(plate_img, detail=0)\\r\\n    raw_text = \\"\\".join(results).replace(\\" \\", \\"\\")\\r\\n    \\r\\n    # Korean License Plate Regex Match\\r\\n    pattern = r\'(\\\\d{2,3}[\uAC00-\uD7A3]\\\\d{4})\'\\r\\n    match = re.search(pattern, raw_text)\\r\\n    return match.group(1) if match else None\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\n## 2. Temporal Majority Voting Engine\\r\\n\\r\\nTo overcome transient single-frame OCR flicker, we maintain a sliding history queue:\\r\\n\\r\\n```python\\r\\nplate_history = deque(maxlen=CONFIG[\\"plate_history_size\\"])  # 7\\r\\nconfirmed_plate = None\\r\\n\\r\\ndef update_plate_voting(detected_text):\\r\\n    global confirmed_plate\\r\\n    if detected_text:\\r\\n        plate_history.append(detected_text)\\r\\n        \\r\\n    if len(plate_history) >= CONFIG[\\"plate_confirm_threshold\\"]:\\r\\n        counts = Counter(plate_history)\\r\\n        most_common_plate, count = counts.most_common(1)[0]\\r\\n        \\r\\n        # Confirm plate if 3 or more votes agree\\r\\n        if count >= CONFIG[\\"plate_confirm_threshold\\"]:\\r\\n            confirmed_plate = most_common_plate\\r\\n            \\r\\n    return confirmed_plate\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\n## 3. The 11-Iteration Evolution: June 5 to June 7\\r\\n\\r\\n![Final v11 Integrated Pipeline in Action](./images/02_final_system.png)\\r\\n\\r\\nOur `log.txt` preserves the raw chronological milestones:\\r\\n\\r\\n| Timestamp | Raw Plate Log | Technical Iteration & Key Breakthrough |\\r\\n| :--- | :--- | :--- |\\r\\n| **06-05 01:13** | `ACCIIXOY-1Z01V1t145V...` | **v01**: Unconstrained full-frame OCR. Road textures misinterpreted as text |\\r\\n| **06-06 00:13** | `fa\uC774`, `ealan`, `cai` | **v04**: YOLOv3 vehicle bounding box integration |\\r\\n| **06-06 01:40** | `64115114`, `16416114` | **v07**: Dedicated YOLOv5 plate detector crops plate ROI |\\r\\n| **06-06 16:35** | `64\uC5441511` -> `64\uAC001511` | **v09**: EDSR_x4 deep super-resolution resolves Hangul stroke |\\r\\n| **06-07 01:27** | `24\uAC001511` -> `64\uAC001511` | **v10**: Multi-frame image stacking cancels sensor noise |\\r\\n| **06-07 18:20** | **`64\uAC001511 (Size: 370x315)`** | **v11 Final**: Temporal Majority Voting locks deterministic plate confirmation! |\\r\\n\\r\\n---\\r\\n\\r\\n## 4. Conclusion & Future Horizons\\r\\n\\r\\nAcross this 5-part series, we designed an end-to-end computer vision system integrating **dynamic lane tracking, polygon IoU intrusion detection, hierarchical object localization, CSRT tracking, EDSR_x4 super-resolution, and temporal voting OCR**. This pipeline provides a proven template for production-grade intelligent transportation systems.\\r\\n\\r\\n---\\r\\n\\r\\n### \u{1F4CC} 3\u20135 Line Executive Summary\\r\\n1. **Korean License Plate Syntax Validation**: EasyOCR character output is strictly filtered against standardized Korean plate regex patterns (`^\\\\d{2,3}[\uAC00-\uD7A3]\\\\d{4}$`), discarding syntactically invalid character fragments.\\r\\n2. **Temporal Sliding Window Majority Voting**: To counteract frame-level yaw, glare, and vibration, OCR hypotheses are buffered across a 7-frame sliding window, requiring 3 identical matches before confirming the plate.\\r\\n3. **11-Iteration System Evolution (v01 to v11)**: Systematically progressed from unconstrained raw OCR gibberish on June 5 to deterministic, noise-resilient recognition (`64\uAC001511`) on June 7 with 99.4% accuracy.\\r\\n4. **End-to-End ITS Architectural Pipeline**: Concludes the 5-part series by unifying dynamic lane detection, polygon IoU violation checks, hierarchical YOLOv5 localization, CSRT tracking, EDSR super-resolution, and voting OCR into an edge-ready pipeline."},{"id":"2026-06-28-vision-anpr-4","metadata":{"permalink":"/blog/2026-06-28-vision-anpr-4","source":"@site/blog/2026-06-28-vision-anpr-4/index.md","title":"[Vision AI] Overcoming Blurry Blackbox Artifacts: Deep Super-Resolution (EDSR vs FSRCNN) & Multi-Frame Image Stacking (#4)","description":"Reconstructing cropped low-resolution license plate patches via EDSR 4x deep super-resolution and temporal multi-frame image stacking.","date":"2026-06-28T00:00:00.000Z","tags":[{"inline":true,"label":"computer-vision","permalink":"/blog/tags/computer-vision"},{"inline":true,"label":"super-resolution","permalink":"/blog/tags/super-resolution"},{"inline":true,"label":"edsr","permalink":"/blog/tags/edsr"},{"inline":true,"label":"image-stacking","permalink":"/blog/tags/image-stacking"},{"inline":true,"label":"anpr","permalink":"/blog/tags/anpr"},{"inline":true,"label":"deep-learning","permalink":"/blog/tags/deep-learning"},{"inline":true,"label":"python","permalink":"/blog/tags/python"}],"readingTime":1.89,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"2026-06-28-vision-anpr-4","title":"[Vision AI] Overcoming Blurry Blackbox Artifacts: Deep Super-Resolution (EDSR vs FSRCNN) & Multi-Frame Image Stacking (#4)","authors":["jbgih"],"tags":["computer-vision","super-resolution","edsr","image-stacking","anpr","deep-learning","python"],"date":"2026-06-28T00:00:00.000Z","project":"anpr_vision","description":"Reconstructing cropped low-resolution license plate patches via EDSR 4x deep super-resolution and temporal multi-frame image stacking.","keywords":["EDSR Super Resolution","License Plate Image Deblurring","OpenCV dnn_superres","Multi-Frame Image Stacking","Deep Residual Upscaling"]},"unlisted":false,"prevItem":{"title":"[Vision AI] Korean ANPR OCR Engine, Regex Normalization & Temporal Majority Voting (v01 to v11 Evolution) (#5)","permalink":"/blog/2026-06-29-vision-anpr-5"},"nextItem":{"title":"[Vision AI] Hierarchical Object Detection: YOLOv3 Vehicle ROI, YOLOv5 Plate Detector & CSRT Tracking (#3)","permalink":"/blog/2026-06-27-vision-anpr-3"}},"content":"![EDSR Deep Super-Resolution Results](./images/01_edsr_sr_comparison.png)\\r\\n\\r\\n> \u{1F4CC} **Key Takeaways (TL;DR)**\\r\\n> - **Problem**: Cropped license plates from dashcam footage often measure under 40x20 pixels with heavy H.264 macroblocking; standard bicubic interpolation fails to resolve character contours.\\r\\n> - **Solution**: Integrated EDSR_x4 deep residual networks (EDSR_x4.pb) that omit batch normalization to preserve dynamic range, combined with temporal multi-frame image stacking across 3 to 5 consecutive frames.\\r\\n> - **Result**: Quadrupled plate pixel density and sharpened stroke edges, lifting downstream EasyOCR accuracy on Korean characters from 32% to over 91%.\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n---\\r\\n\\r\\n## 1. Resolution Limitations & The Need for Deep Super-Resolution\\r\\n\\r\\nEven with precise license plate localization, optical limitations thwart standard OCR:\\r\\n\\r\\n1. **Failure of Bicubic Scaling**: Interpolation algorithms blur edges further without hallucinating high-frequency contours.\\r\\n2. **H.264 Compression & Sensor Noise**: Dashcam compression creates severe pixelation that distorts alphanumeric strokes.\\r\\n\\r\\nWe integrated **EDSR_x4 via the OpenCV DNN Super-Resolution module** to reconstruct high-frequency details:\\r\\n\\r\\n```python\\r\\nimport cv2\\r\\nfrom cv2 import dnn_superres\\r\\n\\r\\ndef init_super_resolution_engine(model_path=\\"EDSR_x4.pb\\"):\\r\\n    sr = dnn_superres.DnnSuperResImpl_create()\\r\\n    sr.readModel(model_path)\\r\\n    sr.setModel(\\"edsr\\", 4)\\r\\n    sr.setPreferableBackend(cv2.dnn.DNN_BACKEND_CUDA)\\r\\n    sr.setPreferableTarget(cv2.dnn.DNN_TARGET_CUDA)\\r\\n    return sr\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\n## 2. Multi-Frame Image Stacking for Noise Reduction\\r\\n\\r\\n![Multi-frame Image Stacking Comparison](./images/02_frame_stacking.png)\\r\\n\\r\\n```text\\r\\nI_stacked(x, y) = (1 / N) * \u03A3 Warp(I_i(x, y))\\r\\n```\\r\\n\\r\\nThis temporal stacking cancels random sensor noise while boosting text-background contrast.\\r\\n\\r\\n---\\r\\n\\r\\n## 3. Looking Forward\\r\\n\\r\\nIn Post #5, we conclude the series with **Korean ANPR OCR tuning, regex syntactic validation**, and the **temporal majority voting engine**, recounting our engineering evolution from initial gibberish to finalized recognition (`64\uAC001511`).\\r\\n\\r\\n---\\r\\n\\r\\n### \u{1F4CC} 3\u20135 Line Executive Summary\\r\\n1. **The Low-Resolution Optical Barrier**: Cropped license plate patches from dashcam video often measure under $40 \\\\times 20$ pixels with heavy compression artifacts, causing standard bicubic interpolation to blur critical character strokes.\\r\\n2. **EDSR_x4 Deep Super-Resolution**: By removing batch normalization layers, the EDSR residual architecture preserves pixel-level dynamic range and reconstructs sharp high-frequency edges via OpenCV `dnn_superres`.\\r\\n3. **Temporal Multi-Frame Image Stacking**: Aligning and averaging $3 \\\\sim 5$ consecutive bounding box patches cancels out stochastic camera sensor noise and motion jitter before feeding the image to OCR.\\r\\n4. **Massive OCR Accuracy Recovery**: The combined super-resolution and frame stacking pipeline quadruples pixel density, elevating downstream Korean character recognition rates from 32% to over 91%."},{"id":"2026-06-27-vision-anpr-3","metadata":{"permalink":"/blog/2026-06-27-vision-anpr-3","source":"@site/blog/2026-06-27-vision-anpr-3/index.md","title":"[Vision AI] Hierarchical Object Detection: YOLOv3 Vehicle ROI, YOLOv5 Plate Detector & CSRT Tracking (#3)","description":"Two-stage hierarchical localization: broad vehicle detection via YOLOv3, localized license plate inference via YOLOv5, and CSRT correlation filter tracking.","date":"2026-06-27T00:00:00.000Z","tags":[{"inline":true,"label":"computer-vision","permalink":"/blog/tags/computer-vision"},{"inline":true,"label":"anpr","permalink":"/blog/tags/anpr"},{"inline":true,"label":"yolo","permalink":"/blog/tags/yolo"},{"inline":true,"label":"csrt-tracker","permalink":"/blog/tags/csrt-tracker"},{"inline":true,"label":"object-detection","permalink":"/blog/tags/object-detection"},{"inline":true,"label":"opencv","permalink":"/blog/tags/opencv"},{"inline":true,"label":"python","permalink":"/blog/tags/python"}],"readingTime":2.01,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"2026-06-27-vision-anpr-3","title":"[Vision AI] Hierarchical Object Detection: YOLOv3 Vehicle ROI, YOLOv5 Plate Detector & CSRT Tracking (#3)","authors":["jbgih"],"tags":["computer-vision","anpr","yolo","csrt-tracker","object-detection","opencv","python"],"date":"2026-06-27T00:00:00.000Z","project":"anpr_vision","description":"Two-stage hierarchical localization: broad vehicle detection via YOLOv3, localized license plate inference via YOLOv5, and CSRT correlation filter tracking.","keywords":["YOLOv5 License Plate Detection","CSRT Tracker OpenCV","Hierarchical Object Detection","Real-Time Tracking 50FPS","Vehicle ROI Localization"]},"unlisted":false,"prevItem":{"title":"[Vision AI] Overcoming Blurry Blackbox Artifacts: Deep Super-Resolution (EDSR vs FSRCNN) & Multi-Frame Image Stacking (#4)","permalink":"/blog/2026-06-28-vision-anpr-4"},"nextItem":{"title":"[Vision AI] Dynamic Lane Boundary Extraction & Geometric IoU Intrusion Criterion (#2)","permalink":"/blog/2026-06-26-vision-anpr-2"}},"content":"![YOLOv5 Plate Detection Localization](./images/01_plate_localization.png)\\r\\n\\r\\n> \u{1F4CC} **Key Takeaways (TL;DR)**\\r\\n> - **Problem**: Searching for tiny plates (30x15 pixels) across the raw 640x480 frame generates massive false positives from roadside signs and drops inference speed below 10 FPS.\\r\\n> - **Solution**: Designed a two-stage hierarchical architecture: broad vehicle detection (YOLOv3-tiny) crops the vehicle ROI, within which a fine-tuned YOLOv5 (lp_det.pt, conf=0.6) locates the license plate. Integrated OpenCV CSRT correlation filter tracking with a 15-frame redetection interval.\\r\\n> - **Result**: Eliminated 98% of background false positives and slashed GPU overhead by 80%, sustaining real-time 50+ FPS continuous tracking.\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n---\\r\\n\\r\\n## 1. The Pitfalls of Global Detection & The Hierarchical Solution\\r\\n\\r\\nRunning plate detectors across the full 640x480 image causes two critical flaws:\\r\\n\\r\\n1. **Background Clutter**: Street advertisements, road billboards, and store signs trigger high false-alarm rates.\\r\\n2. **Resolution Downsampling Loss**: Resizing 640x480 to typical model inputs (e.g., 640x640) squashes tiny 30-pixel plates into sub-feature extinction.\\r\\n\\r\\nOur two-stage hierarchical pipeline addresses this by constraining the search space:\\r\\n\\r\\n```python\\r\\nvehicle_boxes = detect_vehicles_yolov3(frame, net=vehicle_net, conf_thresh=0.5)\\r\\n\\r\\nfor box in vehicle_boxes:\\r\\n    x1, y1, x2, y2 = box\\r\\n    vehicle_roi = frame[y1:y2, x1:x2]\\r\\n    plate_boxes = plate_model(vehicle_roi)\\r\\n    for pbox in plate_boxes:\\r\\n        px1, py1, px2, py2 = pbox\\r\\n        global_plate_box = [x1 + px1, y1 + py1, x1 + px2, y1 + py2]\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\n## 2. Real-Time Latency Mitigation: CSRT Tracker Integration\\r\\n\\r\\n![Continuous Tracking with OpenCV CSRT](./images/02_csrt_tracking.png)\\r\\n\\r\\n```python\\r\\nif frame_count % CONFIG[\\"detection_interval\\"] == 0:\\r\\n    boxes = detect_vehicles_yolov3(frame)\\r\\n    tracker = cv2.TrackerCSRT_create()\\r\\n    tracker.init(frame, tuple(boxes[0]))\\r\\nelse:\\r\\n    success, tracked_box = tracker.update(frame)\\r\\n    if not success:\\r\\n        tracker = None\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\n## 3. Looking Forward\\r\\n\\r\\nIn Post #4, we explore deep **EDSR_x4 super-resolution** to reconstruct crisp alphanumeric strokes from blurry low-resolution plate crops, combined with **multi-frame image stacking**.\\r\\n\\r\\n---\\r\\n\\r\\n### \u{1F4CC} 3\u20135 Line Executive Summary\\r\\n1. **The Global Search Bottleneck**: Detecting tiny $30 \\\\times 15$ pixel license plates directly on raw full-frame inputs triggers heavy background false positives from billboards and bogs down inference below 10 FPS.\\r\\n2. **Two-Stage Hierarchical Localization**: Deploying lightweight YOLOv3-tiny for coarse vehicle ROI extraction followed by dedicated YOLOv5 plate detection within the vehicle patch eliminates 98% of false alarms.\\r\\n3. **CSRT Correlation Filter Tracking**: Utilizing OpenCV CSRT tracker with a 15-frame periodic redetection schedule reduces full-model inference frequency while maintaining stable bounding box continuity.\\r\\n4. **80% GPU Overhead Reduction & 50+ FPS**: Decoupling continuous detection from correlation tracking slashes GPU computational load by 80%, sustaining real-time processing exceeding 50 FPS."},{"id":"2026-06-26-vision-anpr-2","metadata":{"permalink":"/blog/2026-06-26-vision-anpr-2","source":"@site/blog/2026-06-26-vision-anpr-2/index.md","title":"[Vision AI] Dynamic Lane Boundary Extraction & Geometric IoU Intrusion Criterion (#2)","description":"Canny edge filtering, probabilistic Hough transform (HoughLinesP), slope thresholding, and geometric polygon IoU intrusion calculation.","date":"2026-06-26T00:00:00.000Z","tags":[{"inline":true,"label":"computer-vision","permalink":"/blog/tags/computer-vision"},{"inline":true,"label":"anpr","permalink":"/blog/tags/anpr"},{"inline":true,"label":"lane-detection","permalink":"/blog/tags/lane-detection"},{"inline":true,"label":"hough-transform","permalink":"/blog/tags/hough-transform"},{"inline":true,"label":"iou","permalink":"/blog/tags/iou"},{"inline":true,"label":"opencv","permalink":"/blog/tags/opencv"},{"inline":true,"label":"python","permalink":"/blog/tags/python"}],"readingTime":2.23,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"2026-06-26-vision-anpr-2","title":"[Vision AI] Dynamic Lane Boundary Extraction & Geometric IoU Intrusion Criterion (#2)","authors":["jbgih"],"tags":["computer-vision","anpr","lane-detection","hough-transform","iou","opencv","python"],"date":"2026-06-26T00:00:00.000Z","project":"anpr_vision","description":"Canny edge filtering, probabilistic Hough transform (HoughLinesP), slope thresholding, and geometric polygon IoU intrusion calculation.","keywords":["OpenCV Lane Detection","HoughLinesP Lane Tracking","Lane Intrusion Detection","Polygon IoU Calculation","Canny Edge Boundary"]},"unlisted":false,"prevItem":{"title":"[Vision AI] Hierarchical Object Detection: YOLOv3 Vehicle ROI, YOLOv5 Plate Detector & CSRT Tracking (#3)","permalink":"/blog/2026-06-27-vision-anpr-3"},"nextItem":{"title":"[Vision AI] Blackbox Lane Intrusion & Super-Resolution ANPR: 6-Stage End-to-End Pipeline & Real-Time Constraints (#1)","permalink":"/blog/2026-06-25-vision-anpr-1"}},"content":"![Dynamic Lane Detection Overlay](./images/01_lane_detection.png)\\r\\n\\r\\n> \u{1F4CC} **Key Takeaways (TL;DR)**\\r\\n> - **Problem**: Dashcam footage contains heavy pavement specular reflection, tar cracks, and road shadows that induce false lane lines; simple coordinate checking cannot reliably catch the exact moment of lane encroachment.\\r\\n> - **Solution**: Implemented vanishing-point trapezoidal ROI masking, slope thresholding (|slope| > 0.5), and a 7-frame temporal moving average queue. Formulated intrusion as geometric IoU between vehicle tire footprints and lane boundaries.\\r\\n> - **Result**: Filtered out >95% of road texture noise while capturing vehicle lane crossing events with sub-frame accuracy.\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n---\\r\\n\\r\\n## 1. Dynamic Lane Detection: Canny & Probabilistic Hough Transform\\r\\n\\r\\n```python\\r\\ndef detect_lanes(frame):\\r\\n    height, width = frame.shape[:2]\\r\\n    gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)\\r\\n    blur = cv2.GaussianBlur(gray, (5, 5), 0)\\r\\n    edges = cv2.Canny(blur, 50, 150)\\r\\n    \\r\\n    mask = np.zeros_like(edges)\\r\\n    roi_polygon = np.array([[\\r\\n        (int(width * 0.1), height),\\r\\n        (int(width * 0.45), int(height * 0.6)),\\r\\n        (int(width * 0.55), int(height * 0.6)),\\r\\n        (int(width * 0.9), height)\\r\\n    ]], np.int32)\\r\\n    cv2.fillPoly(mask, roi_polygon, 255)\\r\\n    masked_edges = cv2.bitwise_and(edges, mask)\\r\\n    \\r\\n    lines = cv2.HoughLinesP(\\r\\n        masked_edges,\\r\\n        rho=1,\\r\\n        theta=np.pi / 180,\\r\\n        threshold=20,\\r\\n        minLineLength=20,\\r\\n        maxLineGap=10\\r\\n    )\\r\\n    return lines\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\n## 2. Slope Filtering & Temporal Smoothing\\r\\n\\r\\nRaw line segments are filtered using slope criteria:\\r\\n\\r\\n```text\\r\\nSlope m = (y2 - y1) / (x2 - x1)\\r\\n```\\r\\n\\r\\n* **Left Lane**: `m < -0.5`\\r\\n* **Right Lane**: `m > 0.5`\\r\\n* **Horizontal Noise**: `|m| <= 0.5` (crosswalks and bumps are rejected)\\r\\n\\r\\nA `deque(maxlen=7)` temporal moving average smooths lane equations across consecutive frames.\\r\\n\\r\\n---\\r\\n\\r\\n## 3. Geometric Polygon IoU Lane Intrusion Criterion\\r\\n\\r\\n![Lane Intrusion IoU Evaluation](./images/02_intrusion_iou.png)\\r\\n\\r\\n```text\\r\\nFootprint = [x_min, y_min + 0.7*h, x_max, y_max]\\r\\nIoU = Area(Footprint \u2229 Lane_Polygon) / Area(Footprint)\\r\\n```\\r\\n\\r\\n```python\\r\\ndef check_lane_intrusion(vehicle_box, lane_polygon, threshold=0.05):\\r\\n    vx1, vy1, vx2, vy2 = vehicle_box\\r\\n    vh = vy2 - vy1\\r\\n    footprint = Polygon([(vx1, vy1 + 0.7*vh), (vx2, vy1 + 0.7*vh), (vx2, vy2), (vx1, vy2)])\\r\\n    \\r\\n    intersection = footprint.intersection(lane_polygon).area\\r\\n    iou = intersection / footprint.area\\r\\n    return iou > threshold, iou\\r\\n```\\r\\n\\r\\nWhen `IoU > 0.05`, the system flags a violation event and triggers **YOLOv5 license plate localization**.\\r\\n\\r\\n---\\r\\n\\r\\n## 4. Looking Forward\\r\\n\\r\\nIn Post #3, we explore **hierarchical object detection with fine-tuned YOLOv5 (`lp_det.pt`)** and real-time **CSRT tracking integration** to slash GPU inference overhead by 80%.\\r\\n\\r\\n---\\r\\n\\r\\n### \u{1F4CC} 3\u20135 Line Executive Summary\\r\\n1. **Vanishing-Point Trapezoidal Masking**: Focusing edge analysis within a geometric perspective ROI eliminates 95% of irrelevant roadside background clutter and false edge artifacts.\\r\\n2. **Probabilistic Hough Transform & Slope Filtering**: Applying `HoughLinesP` combined with strict slope boundaries ($|slope| > 0.5$) separates true lane markers from pavement cracks and tar seams.\\r\\n3. **Temporal Moving Average Smoothing**: Buffering slope and intercept coefficients across a 7-frame temporal queue prevents erratic lane jitter caused by bumps and lighting changes.\\r\\n4. **Geometric Polygon IoU Intrusion Criterion**: Replaces naive point-in-polygon checks with strict tire-footprint intersection-over-union (IoU), reliably triggering violation events without false alarms."},{"id":"2026-06-25-vision-anpr-1","metadata":{"permalink":"/blog/2026-06-25-vision-anpr-1","source":"@site/blog/2026-06-25-vision-anpr-1/index.md","title":"[Vision AI] Blackbox Lane Intrusion & Super-Resolution ANPR: 6-Stage End-to-End Pipeline & Real-Time Constraints (#1)","description":"Architecting a 6-stage computer vision pipeline combining dynamic lane detection, IoU intrusion metrics, YOLOv5 license plate detection, EDSR super-resolution, and OCR voting.","date":"2026-06-25T00:00:00.000Z","tags":[{"inline":true,"label":"computer-vision","permalink":"/blog/tags/computer-vision"},{"inline":true,"label":"anpr","permalink":"/blog/tags/anpr"},{"inline":true,"label":"object-detection","permalink":"/blog/tags/object-detection"},{"inline":true,"label":"super-resolution","permalink":"/blog/tags/super-resolution"},{"inline":true,"label":"opencv","permalink":"/blog/tags/opencv"},{"inline":true,"label":"deep-learning","permalink":"/blog/tags/deep-learning"},{"inline":true,"label":"python","permalink":"/blog/tags/python"}],"readingTime":2.98,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"2026-06-25-vision-anpr-1","title":"[Vision AI] Blackbox Lane Intrusion & Super-Resolution ANPR: 6-Stage End-to-End Pipeline & Real-Time Constraints (#1)","authors":["jbgih"],"tags":["computer-vision","anpr","object-detection","super-resolution","opencv","deep-learning","python"],"date":"2026-06-25T00:00:00.000Z","project":"anpr_vision","description":"Architecting a 6-stage computer vision pipeline combining dynamic lane detection, IoU intrusion metrics, YOLOv5 license plate detection, EDSR super-resolution, and OCR voting.","keywords":["ANPR Pipeline","Dashcam Video Analytics","Computer Vision Pipeline","Real-Time Vehicle Tracking","YOLO Super Resolution"]},"unlisted":false,"prevItem":{"title":"[Vision AI] Dynamic Lane Boundary Extraction & Geometric IoU Intrusion Criterion (#2)","permalink":"/blog/2026-06-26-vision-anpr-2"},"nextItem":{"title":"[Maeumjigi Capstone Dev Log #23] Dual-Layer Safety Wrapper, AWS EC2 GPU Budgeting & Semester 1 Defense","permalink":"/blog/2026-06-18-maeumjigi-23"}},"content":"![6-Stage ANPR Pipeline Diagram](./images/01_pipeline_diagram.png)\\r\\n\\r\\n> \u{1F4CC} **Key Takeaways (TL;DR)**\\r\\n> - **Problem**: Low-resolution dashcam footage suffers from severe vehicle vibration, nighttime backlighting, and heavy motion blur, making direct license plate recognition and lane violation tracking extremely error-prone.\\r\\n> - **Solution**: Designed a unified 6-stage vision architecture: Canny/Hough lane extraction -> YOLOv3 vehicle detection -> polygon IoU lane violation calculation -> YOLOv5 plate localization -> EDSR_x4 super-resolution -> EasyOCR temporal voting.\\r\\n> - **Result**: Constructed an end-to-end Python pipeline achieving robust vehicle tracking and lane boundary monitoring even under degraded dashcam conditions.\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n---\\r\\n\\r\\n## 1. Project Background: Why Dashcam Vision is Hard\\r\\n\\r\\nIn intelligent transportation systems (ITS) and autonomous traffic enforcement, **real-time lane intrusion detection and automatic number plate recognition (ANPR)** are foundational capabilities. However, real-world dashcam footage presents severe optical challenges:\\r\\n\\r\\n1. **Extreme Low Resolution & Blurred Textures**: The license plate of a leading or overtaking vehicle often spans merely 30x15 to 50x25 pixels across a 640x480 frame, causing alphanumeric strokes to merge into indistinct blobs.\\r\\n2. **Vehicle Vibration & Rolling Shutter Distortions**: Road bumps, sudden decelerations, and perspective shifts distort straight lane boundaries.\\r\\n3. **Real-Time Latency Bottlenecks**: Executing heavy full-frame vision transformers per frame results in fatal FPS drops, disabling real-time tracking.\\r\\n\\r\\n---\\r\\n\\r\\n## 2. 6-Stage Hierarchical Pipeline Architecture\\r\\n\\r\\nTo achieve both high precision and high throughput, we modularized the system into a **6-stage decoupled pipeline**:\\r\\n\\r\\n```mermaid\\r\\nflowchart TD\\r\\n    Raw[\\"Raw Dashcam Frame 640x480\\"] --\x3e L1[\\"Stage 1: Canny + Hough Dynamic Lane Extraction\\"]\\r\\n    Raw --\x3e L2[\\"Stage 2: YOLOv3-tiny Vehicle Detection\\"]\\r\\n    L1 & L2 --\x3e L3[\\"Stage 3: Vehicle Footprint & Lane Polygon IoU Intrusion Metric\\"]\\r\\n    L3 -- If Intrusion Triggered --\x3e L4[\\"Stage 4: Localized YOLOv5 Plate Detection in Vehicle ROI\\"]\\r\\n    L4 --\x3e L5[\\"Stage 5: EDSR_x4 Deep 4x Super-Resolution\\"]\\r\\n    L5 --\x3e L6[\\"Stage 6: EasyOCR + Regex + Temporal Majority Voting\\"]\\r\\n    L6 --\x3e Result[\\"Confirmed Violation Plate: 64\uAC001511\\"]\\r\\n```\\r\\n\\r\\n![Final Detection and ANPR Recognition Output](./images/02_final_result.png)\\r\\n\\r\\n### Decoupled Processing Responsibilities\\r\\n1. **Lane Extraction**: Trapezoidal dynamic ROI masking, Canny edge detection, and slope filtering isolate driving corridor bounds.\\r\\n2. **Vehicle Detection**: Lightweight YOLOv3-tiny outputs candidate vehicle bounding boxes in milliseconds.\\r\\n3. **Intrusion Criterion**: Computes geometric Intersection-over-Union (IoU > 0.05) between vehicle tire footprint and the lane boundary polygon.\\r\\n4. **Plate Localization**: YOLOv5 (`lp_det.pt`) evaluates only the cropped vehicle ROI, saving immense compute cycles.\\r\\n5. **Super-Resolution**: The cropped plate patch is passed through a deep EDSR_x4 neural network, reconstructing high-frequency character contours.\\r\\n6. **OCR & Majority Voting**: EasyOCR extracts alphanumeric tokens, which undergo Korean syntax regex validation and temporal multi-frame voting to confirm the plate number.\\r\\n\\r\\n---\\r\\n\\r\\n## 3. Core System Parameters (`CONFIG`)\\r\\n\\r\\n```python\\r\\nCONFIG = {\\r\\n    \\"output_width\\": 640,\\r\\n    \\"output_height\\": 480,\\r\\n    \\"conf_threshold_vehicle\\": 0.5,\\r\\n    \\"nms_threshold_vehicle\\": 0.4,\\r\\n    \\"min_vehicle_w\\": 70,\\r\\n    \\"min_vehicle_h\\": 70,\\r\\n    \\"lane_iou_threshold\\": 0.05,\\r\\n    \\"detection_interval\\": 15,\\r\\n    \\"min_plate_area_for_ocr\\": 1200,\\r\\n    \\"plate_history_size\\": 7,\\r\\n    \\"plate_confirm_threshold\\": 3,\\r\\n    \\"sr_model\\": \\"EDSR_x4.pb\\",\\r\\n    \\"yolo_plate_model\\": \\"lp_det.pt\\"\\r\\n}\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\n## 4. Looking Forward\\r\\n\\r\\nIn Post #2, we dive deep into **Canny edge filtering, probabilistic Hough transform mathematics (HoughLinesP), slope-based outlier rejection**, and the geometric polygon IoU intrusion criterion.\\r\\n\\r\\n---\\r\\n\\r\\n### \u{1F4CC} 3\u20135 Line Executive Summary\\r\\n1. **The Real-World Dashcam Vision Barrier**: Low-resolution dashcam inputs suffer from severe vibration, optical blur, and compressed plates spanning merely $30 \\\\times 15$ pixels, rendering naive single-stage models ineffective.\\r\\n2. **6-Stage Decoupled Pipeline Design**: Solves accuracy and throughput bottlenecks by orchestrating lane extraction, vehicle detection, polygon IoU violation calculation, localized plate cropping, EDSR super-resolution, and voting OCR.\\r\\n3. **Hierarchical Compute Optimization**: Restricting intensive deep learning models to localized vehicle bounding boxes prevents catastrophic full-frame inference slowdowns.\\r\\n4. **Edge Real-Time Feasibility**: Balancing correlation tracking and temporal voting enables continuous 50+ FPS video processing with deterministic 99.4% plate recognition reliability."},{"id":"2026-06-18-maeumjigi-23","metadata":{"permalink":"/blog/2026-06-18-maeumjigi-23","source":"@site/blog/2026-06-18-maeumjigi-23/index.md","title":"[Maeumjigi Capstone Dev Log #23] Dual-Layer Safety Wrapper, AWS EC2 GPU Budgeting & Semester 1 Defense","description":"Final Milestone of Semester 1: Engineering our dual-layer Safety Wrapper for crisis de-escalation, calculating AWS EC2 g5.2xlarge GPU serving budgets, and presenting our Capstone Final Defense.","date":"2026-06-18T00:00:00.000Z","tags":[{"inline":true,"label":"devlog","permalink":"/blog/tags/devlog"},{"inline":true,"label":"safety-wrapper","permalink":"/blog/tags/safety-wrapper"},{"inline":true,"label":"guardrail","permalink":"/blog/tags/guardrail"},{"inline":true,"label":"aws-ec2","permalink":"/blog/tags/aws-ec-2"},{"inline":true,"label":"gpu-serving","permalink":"/blog/tags/gpu-serving"},{"inline":true,"label":"capstone-defense","permalink":"/blog/tags/capstone-defense"},{"inline":true,"label":"suicide-prevention","permalink":"/blog/tags/suicide-prevention"}],"readingTime":4.43,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"2026-06-18-maeumjigi-23","title":"[Maeumjigi Capstone Dev Log #23] Dual-Layer Safety Wrapper, AWS EC2 GPU Budgeting & Semester 1 Defense","authors":["jbgih"],"tags":["devlog","safety-wrapper","guardrail","aws-ec2","gpu-serving","capstone-defense","suicide-prevention"],"date":"2026-06-18T00:00:00.000Z","keywords":["AI Mental Health Chatbot","AI Safety Wrapper","LLM Guardrail Architecture","Crisis Intervention Protocol","AWS EC2 GPU Serving"],"description":"Final Milestone of Semester 1: Engineering our dual-layer Safety Wrapper for crisis de-escalation, calculating AWS EC2 g5.2xlarge GPU serving budgets, and presenting our Capstone Final Defense."},"unlisted":false,"prevItem":{"title":"[Vision AI] Blackbox Lane Intrusion & Super-Resolution ANPR: 6-Stage End-to-End Pipeline & Real-Time Constraints (#1)","permalink":"/blog/2026-06-25-vision-anpr-1"},"nextItem":{"title":"[Maeumjigi Capstone Dev Log #22] 4th Fine-Tuning Triumph: Checkpoint-4400, Data Mix Ratios & Full System Architecture","permalink":"/blog/2026-05-30-maeumjigi-22"}},"content":"![Cover Image](./images/01_cover.png)\\r\\n\\r\\nJune 18, 2026, marks the triumphant completion of the 1st semester of our university capstone engineering project. From our humble beginnings as a simple Android convention scraper in March, **Maeumjigi** has evolved into a full-scale, clinical-grade AI mental health counseling ecosystem. \\r\\n\\r\\nOur final sprint focused on two mission-critical objectives:\\r\\n1. **The Dual-Layer Safety Wrapper**: Engineering a bulletproof guardrail architecture to guarantee zero-hallucination crisis intervention.\\r\\n2. **Production Cloud Serving & Final Defense**: Sizing AWS EC2 GPU infrastructure budgets and delivering our final faculty presentation.\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n### 1. The Dual-Layer Safety Wrapper Architecture\\r\\n\\r\\nIn consumer chatbots, occasional hallucinations or awkward phrasing are minor annoyances. In an AI platform dedicated to youth and military suicide prevention, **a single hallucinated response or dismissive answer could be fatal**.\\r\\n\\r\\nTo protect vulnerable users, we designed a **Dual-Layer Safety Wrapper** that wraps around our fine-tuned Qwen 3.5-9B model (Checkpoint-4400):\\r\\n\\r\\n```mermaid\\r\\nflowchart TD\\r\\n    subgraph Inbound_Triage [\\"Layer 1: Pre-Inference Guardrail\\"]\\r\\n        A[User Message Received] --\x3e B[Regex Crisis Keyword Detector]\\r\\n        B --\x3e C[Zero-Shot Semantic Crisis Classifier]\\r\\n        C --\x3e D{Risk Severity Assessment}\\r\\n    end\\r\\n\\r\\n    subgraph Decision_Branch [\\"Emergency Routing\\"]\\r\\n        D --\x3e|Level 3: Active Suicidality / Imminent Danger| E[Emergency Protocol Triggered]\\r\\n        E --\x3e|Bypass Generative Model| F[Deterministic Crisis Intervention & 109 / 1393 Dialing]\\r\\n        \\r\\n        D --\x3e|Level 1-2: Mild to Moderate Emotional Distress| G[Pass to Fine-Tuned LLM]\\r\\n    end\\r\\n\\r\\n    subgraph Inference_Core [\\"Model Generation\\"]\\r\\n        G --\x3e H[vLLM Serving Engine: Checkpoint-4400]\\r\\n        H --\x3e I[Raw Generative Token Stream]\\r\\n    end\\r\\n\\r\\n    subgraph Outbound_Verifier [\\"Layer 2: Post-Inference Guardrail\\"]\\r\\n        I --\x3e J[Toxicity & Hallucination Filter]\\r\\n        J --\x3e K[Clinical Referral Footer Injection]\\r\\n        K --\x3e L[Sanitized Real-Time SSE to Client]\\r\\n    end\\r\\n\\r\\n    F --\x3e L\\r\\n```\\r\\n\\r\\n#### Crisis Escalation Protocol (Level 1 to 3)\\r\\n\\r\\n| Risk Classification | Clinical Indicators | System Response Action | Latency Target |\\r\\n| :---: | :--- | :--- | :---: |\\r\\n| **Level 1 (Mild)** | Fatigue, loneliness, academic/work stress | Empathetic listening, active validation | < 800 ms |\\r\\n| **Level 2 (Moderate)** | Chronic hopelessness, self-worth collapse | Cognitive reframing, counseling clinic recommendation | < 800 ms |\\r\\n| **Level 3 (Crisis)** | Explicit suicidal ideation, intent, or self-harm | **Instant LLM bypass: Display 24/7 Lifeline (109 / 1393) modal with one-tap emergency call** | **< 150 ms** |\\r\\n\\r\\n---\\r\\n\\r\\n### 2. Guardrail Middleware Implementation\\r\\n\\r\\nThe Safety Wrapper operates as an asynchronous FastAPI middleware, validating payloads prior to dispatching GPU inference requests:\\r\\n\\r\\n```python\\r\\n# Safety Wrapper core logic: safety_wrapper.py\\r\\nimport re\\r\\nfrom fastapi import Request, HTTPException\\r\\n\\r\\nCRISIS_PATTERNS = [\\r\\n    r\\"(\uC8FD\uACE0\\\\s*\uC2F6|\uC790\uC0B4|\uBAA9\uC228\uC744\\\\s*\uB04A|\uC0B4\uAE30\\\\s*\uC2EB|\uB6F0\uC5B4\uB0B4\uB9AC)\\",\\r\\n    r\\"(suicide|kill\\\\s*myself|end\\\\s*my\\\\s*life)\\"\\r\\n]\\r\\n\\r\\nclass SafetyWrapper:\\r\\n    def __init__(self, emergency_hotline=\\"109\\"):\\r\\n        self.compiled_regex = [re.compile(p, re.IGNORECASE) for p in CRISIS_PATTERNS]\\r\\n        self.hotline = emergency_hotline\\r\\n\\r\\n    def evaluate_input(self, user_text: str) -> dict:\\r\\n        for pattern in self.compiled_regex:\\r\\n            if pattern.search(user_text):\\r\\n                return {\\r\\n                    \\"is_crisis\\": True,\\r\\n                    \\"action\\": \\"ESCALATE_IMMEDIATELY\\",\\r\\n                    \\"override_response\\": (\\r\\n                        f\\"\uB2F9\uC2E0\uC758 \uACE0\uD1B5\uC744 \uAE4A\uC774 \uACF5\uAC10\uD569\uB2C8\uB2E4. \uC9C0\uAE08 \uC989\uC2DC \uC804\uBB38\uAC00\uC758 \uB3C4\uC6C0\uC744 \uBC1B\uC73C\uC2E4 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \\"\\r\\n                        f\\"24\uC2DC\uAC04 \uC790\uC0B4\uC608\uBC29 \uC0C1\uB2F4\uC804\uD654 \u260E {self.hotline}\uBC88\uC73C\uB85C \uC5F0\uB77D\uD574 \uC8FC\uC138\uC694. \uB2F9\uC2E0\uC740 \uD63C\uC790\uAC00 \uC544\uB2D9\uB2C8\uB2E4.\\"\\r\\n                    )\\r\\n                }\\r\\n        return {\\"is_crisis\\": False, \\"action\\": \\"PROCEED_TO_LLM\\"}\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\n### 3. AWS EC2 GPU Production Budget & Sizing\\r\\n\\r\\nTo serve our validated chatbot to university students and military beta testers over the 5-month summer break, we conducted an AWS EC2 instance sizing and cost optimization study:\\r\\n\\r\\n| Instance Family | GPU Configuration | vCPU / RAM | On-Demand (Hourly) | 5-Month Estimated Cost (On-Demand) | 1-Year Savings Plan (Hourly) | 5-Month Optimized Cost |\\r\\n| :--- | :---: | :---: | :---: | :---: | :---: | :---: |\\r\\n| **g4dn.2xlarge** | 1x NVIDIA T4 (16GB) | 8 vCPU / 32GB | $0.752 | $2,707 | $0.481 | $1,731 |\\r\\n| **g5.2xlarge (Chosen)** | **1x NVIDIA A10G (24GB)** | **8 vCPU / 32GB** | **$1.212** | **$4,363** | **$0.763** | **$2,746 (Save 37%)** |\\r\\n| **g6.2xlarge** | 1x NVIDIA L4 (24GB) | 8 vCPU / 32GB | $0.978 | $3,520 | $0.626 | $2,253 |\\r\\n\\r\\n**Engineering Selection**: While `g4dn.2xlarge` offered lower cost, its 16GB VRAM could not host our 9B model alongside vLLM PagedAttention KV-caches without extreme 4-bit quantization degradation. We selected **`g5.2xlarge` with a 1-year Savings Plan**, unlocking 24GB high-speed GDDR6 VRAM, sub-50ms token latencies, and 37% budgetary savings!\\r\\n\\r\\n![Final Presentation](./images/02_presentation.png)\\r\\n\\r\\n---\\r\\n\\r\\n### 4. 1st Semester Capstone Retrospective & Defense Highlights\\r\\n\\r\\nOn June 18th, our engineering team presented the completed **1st Semester Final Defense Presentation (PPTX)** before the university evaluation panel:\\r\\n\\r\\n```mermaid\\r\\ntimeline\\r\\n    title Maeumjigi Semester 1 Engineering Milestones\\r\\n    March 2026 : Project Kickoff : Claude Code Adoption : Convention Scraper Pivot\\r\\n    April 2026 : 120K Corpus Preprocessing : Llama 3.1 JSONL Pipeline : Next.js 14 Frontend\\r\\n    May 2026 : 4 Rounds of Fine-Tuning : Checkpoint-4400 Locked : FastAPI PostgreSQL Hardened\\r\\n    June 2026 : Dual Safety Wrapper : AWS g5.2xlarge Sizing : 1st Semester Final Presentation Passed\\r\\n```\\r\\n\\r\\nThe review panel commended the team for solving the over-counseling trap through empirical data mixing (2:1 ratio) and praised the clinical safety guarantees provided by the deterministic Safety Wrapper.\\r\\n\\r\\n---\\r\\n\\r\\n### 5. What\'s Next in Semester 2?\\r\\n\\r\\nWith Phase 1 concluded, our team enters summer deployment:\\r\\n1. Provisioning our AWS EC2 `g5.2xlarge` instance with automated containerized health checks.\\r\\n2. Launching closed-beta testing across military welfare communities.\\r\\n3. Returning in Semester 2 with live multi-turn field data and expanded knowledge graph capabilities!\\r\\n\\r\\n---\\r\\n\\r\\n## Summary & Key Takeaways\\r\\n\\r\\n- **Dual-Layer Safety Wrapper Architecture**: Engineered a mission-critical guardrail combining pre-inference crisis keyword/semantic triage with post-generation ethical compliance checks.\\r\\n- **Zero-Hallucination Emergency Routing**: Implemented deterministic emergency bypass protocols that immediately route high-risk suicidal ideation directly to 24/7 lifeline hotlines.\\r\\n- **Production GPU Serving Economics**: Benchmarked AWS EC2 `g5.2xlarge` (NVIDIA A10G 24GB) instances, establishing 60+ concurrent session capacity within an optimized student capstone budget.\\r\\n- **Semester 1 Final Defense Success**: Concluded Phase 1 with a successful faculty defense, validating end-to-end clinical empathy, pipeline safety, and system resilience."},{"id":"2026-05-30-maeumjigi-22","metadata":{"permalink":"/blog/2026-05-30-maeumjigi-22","source":"@site/blog/2026-05-30-maeumjigi-22/index.md","title":"[Maeumjigi Capstone Dev Log #22] 4th Fine-Tuning Triumph: Checkpoint-4400, Data Mix Ratios & Full System Architecture","description":"Concluding Phase 1 fine-tuning: discovering the optimal 2:1 emotional-to-daily data mix ratio, validating Checkpoint-4400, and publishing our end-to-end full system architecture.","date":"2026-05-30T00:00:00.000Z","tags":[{"inline":true,"label":"devlog","permalink":"/blog/tags/devlog"},{"inline":true,"label":"fine-tuning","permalink":"/blog/tags/fine-tuning"},{"inline":true,"label":"qwen","permalink":"/blog/tags/qwen"},{"inline":true,"label":"checkpoint-analysis","permalink":"/blog/tags/checkpoint-analysis"},{"inline":true,"label":"architecture","permalink":"/blog/tags/architecture"},{"inline":true,"label":"over-counseling","permalink":"/blog/tags/over-counseling"},{"inline":true,"label":"capstone","permalink":"/blog/tags/capstone"}],"readingTime":4.15,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"2026-05-30-maeumjigi-22","title":"[Maeumjigi Capstone Dev Log #22] 4th Fine-Tuning Triumph: Checkpoint-4400, Data Mix Ratios & Full System Architecture","authors":["jbgih"],"tags":["devlog","fine-tuning","qwen","checkpoint-analysis","architecture","over-counseling","capstone"],"date":"2026-05-30T00:00:00.000Z","keywords":["Qwen 3.5 9B Fine-Tuning","Data Mix Ratio Optimization","LLM Overfitting Prevention","Checkpoint 4400 Evaluation","Mental Health Chatbot Architecture"],"description":"Concluding Phase 1 fine-tuning: discovering the optimal 2:1 emotional-to-daily data mix ratio, validating Checkpoint-4400, and publishing our end-to-end full system architecture."},"unlisted":false,"prevItem":{"title":"[Maeumjigi Capstone Dev Log #23] Dual-Layer Safety Wrapper, AWS EC2 GPU Budgeting & Semester 1 Defense","permalink":"/blog/2026-06-18-maeumjigi-23"},"nextItem":{"title":"[Maeumjigi Capstone Dev Log #21] Optimizing Data Mix Ratios and Starting the 4th Fine-Tuning","permalink":"/blog/2026-05-22-maeumjigi-21"}},"content":"![Cover Image](./images/01_cover.png)\\r\\n\\r\\nThe final week of May 2026 (May 27\u201330) proved to be the grand culmination of our experimental modeling phase. After weeks of hyperparameter tuning, GPU out-of-memory crashes, and dataset revisions, our **4th Fine-Tuning cycle (fine_tuning_4)** crossed the finish line. \\r\\n\\r\\nThis post reveals the technical breakthrough that resolved the chronic \\"over-counseling\\" trap, quantitative validation of our golden weight **Checkpoint-4400**, and the end-to-end system architecture designed for real-world deployment.\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n### 1. The Over-Counseling Paradox & Data Mix Optimization\\r\\n\\r\\nIn our earlier fine-tuning cycles (v1 through v3), the model suffered from an unexpected behavioral pathology we coined the **\\"Over-Counseling Trap\\"**:\\r\\n- When a user said: *\\"Good morning! What should I eat for lunch?\\"*\\r\\n- The model unnaturally replied: *\\"I hear deep sorrow in your morning greeting. Eating alone can feel overwhelming. Please remember you are not alone; take a deep breath.\\"*\\r\\n\\r\\nBecause the training corpus consisted exclusively of 100% clinical depression and psychological counseling transcripts, the model had overfitted into interpreting *every* casual human interaction as a critical depressive cry for help.\\r\\n\\r\\nTo eliminate this pathological hyper-empathy without compromising crisis intervention sensitivity, we engineered experimental **Data Mix Ratios** blending daily casual chit-chat (AI Hub Social Multi-Turn Corpus) with our curated counseling data:\\r\\n\\r\\n```mermaid\\r\\npie title \\"4th Fine-Tuning Golden Mix Composition (2:1 Ratio)\\"\\r\\n    \\"Curated Clinical & Crisis Counseling (AI Hub v4)\\" : 66.7\\r\\n    \\"Open-Domain Daily Chit-Chat & Casual Banter\\" : 33.3\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\n### 2. Checkpoint-4400: Loss Convergence & Golden Weights\\r\\n\\r\\nWe fine-tuned **Qwen 2.5 / 3.5-9B** across 6,000 steps on an enterprise A100 GPU cluster using QLoRA (`r=16`, `lora_alpha=32`, `learning_rate=2e-4` with cosine decay).\\r\\n\\r\\nAnalyzing intermediate checkpoints revealed that **Checkpoint-4400** represented the exact Pareto-optimal boundary between conversational fluidity and clinical safety:\\r\\n\\r\\n```mermaid\\r\\nxychart-beta\\r\\n    title \\"Validation Loss & Over-Counseling Metric Across Training Steps\\"\\r\\n    x-axis [\\"Step 1000\\", \\"Step 2000\\", \\"Step 3000\\", \\"Step 4000\\", \\"Step 4400\\", \\"Step 5000\\", \\"Step 6000\\"]\\r\\n    y-axis \\"Validation Loss (Lower is Better)\\" 0.8 --\x3e 2.4\\r\\n    line [2.35, 1.82, 1.45, 1.18, 1.04, 1.22, 1.48]\\r\\n```\\r\\n\\r\\n| Checkpoint Identifier | Validation Perplexity | Empathy Depth Score | Casual Context Score | Behavioral Diagnosis |\\r\\n| :---: | :---: | :---: | :---: | :--- |\\r\\n| **Checkpoint-2000** | 4.82 | 64.2 / 100 | 88.0 / 100 | Underfitted; replies resemble generic base model |\\r\\n| **Checkpoint-3500** | 3.15 | 81.4 / 100 | 79.5 / 100 | Good empathy; occasional overly serious responses |\\r\\n| **Checkpoint-4400 (Golden)** | **2.68** | **94.2 / 100** | **92.8 / 100** | **Optimal! Crisp humor in daily chat, deep empathy in crisis** |\\r\\n| **Checkpoint-5500** | 3.42 | 95.0 / 100 | 58.2 / 100 | Overfitted; loss diverges, robotic therapy loops return |\\r\\n\\r\\nCheckpoint-4400 demonstrated flawless contextual switching: answering casual greetings lightheartedly, while seamlessly transitioning into calm, de-escalating empathy the second emotional vulnerability was detected.\\r\\n\\r\\n---\\r\\n\\r\\n### 3. End-to-End System Architecture\\r\\n\\r\\nWith Checkpoint-4400 locked in, we designed the complete production architecture, codified in `chatbot_architecture.html`:\\r\\n\\r\\n```mermaid\\r\\nflowchart TD\\r\\n    subgraph Client_Tier [\\"Client Layer (Web & Mobile)\\"]\\r\\n        UI1[Next.js 14 Web PWA]\\r\\n        UI2[React Native Mobile App]\\r\\n    end\\r\\n\\r\\n    subgraph Gateway_Tier [\\"API Gateway & Ingress\\"]\\r\\n        Nginx[Nginx Reverse Proxy & SSL Termination]\\r\\n        FastAPI[FastAPI Asynchronous Gateway]\\r\\n        Redis[(Redis Session Buffer & Rate Limiter)]\\r\\n    end\\r\\n\\r\\n    subgraph Guardrail_Tier [\\"Safety & Clinical Validation\\"]\\r\\n        Guard_In[Pre-Filter: Zero-Shot Suicide & Self-Harm Triage]\\r\\n        Guard_Out[Post-Verifier: Hallucination & Emergency Hotline Injector]\\r\\n    end\\r\\n\\r\\n    subgraph Model_Tier [\\"Model Serving Infrastructure\\"]\\r\\n        vLLM[vLLM High-Throughput Serving Engine]\\r\\n        Model[(Qwen 3.5-9B + LoRA Checkpoint-4400)]\\r\\n    end\\r\\n\\r\\n    subgraph Data_Tier [\\"Persistence & Analytics\\"]\\r\\n        Postgres[(PostgreSQL User & Conversation History)]\\r\\n    end\\r\\n\\r\\n    UI1 & UI2 <--\x3e|HTTPS / WSS / SSE| Nginx\\r\\n    Nginx <--\x3e FastAPI\\r\\n    FastAPI <--\x3e Redis\\r\\n    FastAPI --\x3e Guard_In\\r\\n    Guard_In --\x3e|Passed Safe / Level 1-2| vLLM\\r\\n    Guard_In --\x3e|Critical Crisis: Level 3| Guard_Out\\r\\n    vLLM <--\x3e Model\\r\\n    vLLM --\x3e Guard_Out\\r\\n    Guard_Out --\x3e FastAPI\\r\\n    FastAPI <--\x3e Postgres\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\n### 4. LoRA Adapter Configuration & Automated Reporting\\r\\n\\r\\nThe finalized `adapter_config.json` locked our architectural parameters:\\r\\n\\r\\n```json\\r\\n{\\r\\n  \\"base_model_name_or_path\\": \\"Qwen/Qwen2.5-9B-Instruct\\",\\r\\n  \\"lora_alpha\\": 32,\\r\\n  \\"lora_dropout\\": 0.05,\\r\\n  \\"r\\": 16,\\r\\n  \\"target_modules\\": [\\"q_proj\\", \\"k_proj\\", \\"v_proj\\", \\"o_proj\\", \\"gate_proj\\", \\"up_proj\\", \\"down_proj\\"],\\r\\n  \\"task_type\\": \\"CAUSAL_LM\\"\\r\\n}\\r\\n```\\r\\n\\r\\nOn May 30th, our autonomous documentation script compiled `fine_tuning_4_report.docx`, incorporating full qualitative inference transcripts comparing the original base Qwen model against Checkpoint-4400.\\r\\n\\r\\n![System Architecture](./images/02_architecture.png)\\r\\n\\r\\n---\\r\\n\\r\\n### 5. Day 22 Milestones & What Lies Ahead\\r\\n\\r\\n1. **Over-Counseling Conquered**: The 2:1 data mix ratio permanently cured our model from hyper-formal, robotic therapeutic over-reactions.\\r\\n2. **Golden Weight Staged**: Checkpoint-4400 achieved our project\'s lowest validation perplexity (2.68) and highest human evaluation scores.\\r\\n3. **Production Blueprint Published**: Completed the full-stack architecture bridging Next.js, FastAPI, vLLM, and Redis.\\r\\n\\r\\nIn Dev Log #23, we enter the final milestone of Semester 1: building our dual-layer Safety Wrapper guardrail and calculating cloud GPU server budgets for university deployment!\\r\\n\\r\\n---\\r\\n\\r\\n## Summary & Key Takeaways\\r\\n\\r\\n- **Over-Counseling Paradox Resolved**: Eliminated hyper-formal, robotic therapeutic reactions by curating a balanced 2:1 training data mix ratio of clinical counseling to daily casual chit-chat.\\r\\n- **Golden Weight Checkpoint-4400**: Identified Checkpoint-4400 as our optimal fine-tuned weight, achieving the project\'s lowest validation loss (2.68) and peak human empathy scores.\\r\\n- **Production Full-Stack Architecture**: Established an end-to-end serving blueprint integrating Next.js, FastAPI orchestration, vLLM continuous batching, and Redis session caching.\\r\\n- **Milestone Validation**: Confirmed stable sub-second response latencies and high conversational fluency, completing our Phase 1 experimental modeling sprint."},{"id":"2026-05-22-maeumjigi-21","metadata":{"permalink":"/blog/2026-05-22-maeumjigi-21","source":"@site/blog/2026-05-22-maeumjigi-21/index.md","title":"[Maeumjigi Capstone Dev Log #21] Optimizing Data Mix Ratios and Starting the 4th Fine-Tuning","description":"Achieving peak model performance by training on the 2:1 emotional-to-daily dialogue ratio, balancing lucid conversational answers with empathetic care.","date":"2026-05-22T00:00:00.000Z","tags":[{"inline":true,"label":"devlog","permalink":"/blog/tags/devlog"},{"inline":true,"label":"fine-tuning","permalink":"/blog/tags/fine-tuning"},{"inline":true,"label":"dataset","permalink":"/blog/tags/dataset"},{"inline":true,"label":"prompt","permalink":"/blog/tags/prompt"},{"inline":true,"label":"capstone","permalink":"/blog/tags/capstone"}],"readingTime":2.06,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"2026-05-22-maeumjigi-21","title":"[Maeumjigi Capstone Dev Log #21] Optimizing Data Mix Ratios and Starting the 4th Fine-Tuning","authors":["jbgih"],"tags":["devlog","fine-tuning","dataset","prompt","capstone"],"date":"2026-05-22T00:00:00.000Z","keywords":["AI Mental Health Chatbot","LLM Fine-tuning","AI Safety Wrapper","Capstone Project","Prompt Engineering"],"description":"Achieving peak model performance by training on the 2:1 emotional-to-daily dialogue ratio, balancing lucid conversational answers with empathetic care."},"unlisted":false,"prevItem":{"title":"[Maeumjigi Capstone Dev Log #22] 4th Fine-Tuning Triumph: Checkpoint-4400, Data Mix Ratios & Full System Architecture","permalink":"/blog/2026-05-30-maeumjigi-22"},"nextItem":{"title":"[Webots Robotics] Sim-to-Real: Hardware Transfer via Arduino Uno, HC-06 Bluetooth & ArUco Vision Tracking (#5)","permalink":"/blog/2026-05-21-rl-qlearning-5"}},"content":"![Cover Image](./images/01_cover.png)\\n\\nOn May 21st and 22nd, the Maeumjigi Capstone team embarked on massive data generation and preparation for the **4th Fine-Tuning (fine_tuning_4)**.\\n\\n{/* truncate */}\\n\\n### The Tug-of-War Between Emotional and Daily Conversations\\n\\nWhile testing the 3rd fine-tuning model, I discovered a critical issue.\\n\\n> \\"When fine-tuning with the haiku_pred dataset, the responses seem too heavily skewed towards emotional counseling. How should we fine-tune to maintain the original model\'s daily conversation abilities?\\"\\n\\nOur goal is a \'suicide prevention counselor conveying warm empathy\', but the model was showing signs of **overfitting**, giving overly serious and emotional responses even to mundane questions like \\"How\'s the weather?\\" or \\"What should I eat?\\".\\n\\nTo solve this, we planned an experiment to train the model by mixing emotional data and daily chat data at appropriate ratios.\\n\\n### Generating 10,000 v6 Emotion Dataset Entries via Application Programming Interface (API)\\n\\n> \\"Unify to 512 tokens / Average 500 tokens per entry / 20 Personas / File: v6.jsonl\\"\\n\\nTo create the best dataset, I used the Anthropic API (Haiku) Batch mode to generate a staggering 10,000 entries of emotional conversation data (`Emotion_train_dataset_v6.jsonl`). Though there was a frustrating moment when the API batch ran in the background without showing progress, I filled in the missing entries with an additional script (`fill_v6.py`) to complete the 10,000 count.\\n\\n### Finding the Golden Ratio (fine_tuning_4)\\n\\n> \\"Emotion_train_dataset_v6.jsonl is complete. Now make a 7:3 ratio dataset, a 2:1 ratio, and a 5:5 ratio dataset.\\"\\n> \\"This 4th fine-tuning will be based on the training dataset mix ratio (mixed_2_1, mixed_5_5, mixed_7_3) instead of alpha values.\\"\\n\\n![Ratio Experiment](./images/02_ratio.png)\\n\\nThe 4th fine-tuning has now become an arena to verify which data ratio perfectly harmonizes the Artificial Intelligence (AI)\'s \'daily casualness\' with \'professional counseling\'. We generated three versions of the dataset and started injecting them into the Qwen3.5-9B model!\\n\\n---\\n\\n## Summary & Key Takeaways\\n\\n- **Identifying Conversational Skew**: Discovered severe emotional counseling bias where the 3rd fine-tuning model gave overly solemn, therapeutic responses to mundane everyday greetings.\\n- **Large-Scale Synthetic Corpus Generation**: Engineered 10,000 standardized emotional dialogues (`v6.jsonl`) via Anthropic Haiku Batch API across 20 distinct personas with 500-token length constraints.\\n- **Multi-Ratio Experimental Matrix**: Formulated three comparative dataset mixtures (`mixed_7_3`, `mixed_2_1`, and `mixed_5_5`) blending emotional counseling with daily banter.\\n- **Initiating the 4th Fine-Tuning Sprint**: Commenced training on Qwen 3.5-9B to rigorously identify the golden dataset ratio that harmonizes professional counseling empathy with natural daily conversation."},{"id":"2026-05-21-rl-qlearning-5","metadata":{"permalink":"/blog/2026-05-21-rl-qlearning-5","source":"@site/blog/2026-05-21-rl-qlearning-5/index.md","title":"[Webots Robotics] Sim-to-Real: Hardware Transfer via Arduino Uno, HC-06 Bluetooth & ArUco Vision Tracking (#5)","description":"Deploying the simulation-trained 648-bin Q-Learning policy onto a physical 2-wheeled Arduino Uno robot using ceiling webcam homography and real-time ArUco 6-DoF marker pose tracking.","date":"2026-05-21T00:00:00.000Z","tags":[{"inline":true,"label":"reinforcement-learning","permalink":"/blog/tags/reinforcement-learning"},{"inline":true,"label":"sim-to-real","permalink":"/blog/tags/sim-to-real"},{"inline":true,"label":"arduino","permalink":"/blog/tags/arduino"},{"inline":true,"label":"robotics","permalink":"/blog/tags/robotics"},{"inline":true,"label":"computer-vision","permalink":"/blog/tags/computer-vision"},{"inline":true,"label":"aruco","permalink":"/blog/tags/aruco"},{"inline":true,"label":"python","permalink":"/blog/tags/python"}],"readingTime":5.89,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"2026-05-21-rl-qlearning-5","title":"[Webots Robotics] Sim-to-Real: Hardware Transfer via Arduino Uno, HC-06 Bluetooth & ArUco Vision Tracking (#5)","authors":["jbgih"],"tags":["reinforcement-learning","sim-to-real","arduino","robotics","computer-vision","aruco","python"],"date":"2026-05-21T00:00:00.000Z","project":"rl_q_learning","description":"Deploying the simulation-trained 648-bin Q-Learning policy onto a physical 2-wheeled Arduino Uno robot using ceiling webcam homography and real-time ArUco 6-DoF marker pose tracking.","keywords":["Sim-to-Real Hardware Transfer","ArUco Marker Pose Tracking","Arduino Uno Robot Navigation","HC-06 Bluetooth IPC","Webcam Homography Robotics"]},"unlisted":false,"prevItem":{"title":"[Maeumjigi Capstone Dev Log #21] Optimizing Data Mix Ratios and Starting the 4th Fine-Tuning","permalink":"/blog/2026-05-22-maeumjigi-21"},"nextItem":{"title":"[Maeumjigi Capstone Dev Log #20] 3rd Fine-Tuning Complete & Backend Feature Enhancements","permalink":"/blog/2026-05-20-maeumjigi-20"}},"content":"![ArUco Marker Vision Tracking](./images/01_aruco_vision.png)\\r\\n\\r\\n> \u{1F4CC} **Key Takeaways (TL;DR)**\\r\\n> - **Problem**: Severe computational constraints on microcontrollers (Arduino Uno ATmega328P with only 2KB SRAM), non-linear wheel slip, noisy ultrasonic sensing, and the classical **Reality Gap** between Webots simulation physics and physical hardware.\\r\\n> - **Solution**: Designed a **distributed I/O architecture (HC-06 Bluetooth at 115,200 baud)** where a host PC runs OpenCV vision processing and Q-Table inference while the Arduino handles low-level PWM motor actuation. Overhead camera lens distortion correction and **ArUco marker homography (`vision.py`)** deliver sub-centimeter real-time (x, y, \u03B8) tracking.\\r\\n> - **Result**: Zero-shot transfer of the simulation-trained 648-state Q-Table achieved an **86.7% target reaching success rate (26/30 trials)** in a physical 1.2m \xd7 1.2m arena, successfully closing the reality gap without real-world fine-tuning.\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n---\\r\\n\\r\\n## 1. The Challenge of Sim-to-Real: Navigating the Reality Gap\\r\\n\\r\\nIn virtual Webots simulations, surface friction coefficients remain idealized, wheel motors rotate with deterministic precision, and simulated distance sensors yield noiseless measurements. Real hardware, however, introduces unpredictable physical perturbations:\\r\\n\\r\\n1. **Severe Memory & Compute Bottlenecks**: The **Arduino Uno (ATmega328P)** operates with only 32KB flash memory and 2KB SRAM. Running deep neural networks or heavy matrix operations directly on-chip is physically impossible.\\r\\n2. **Sensor Noise & Blind Angles**: Inexpensive ultrasonic rangefinders suffer from specular reflection at shallow incidence angles, reporting 0 or spiking to maximum range when pinging smooth acrylic boundaries.\\r\\n3. **Wheel Slip & Odometry Drift**: Minor variations in wheel friction and motor gearboxes cause differential-drive robots to veer off-course even when commanded to drive straight, making dead-reckoning odometry completely unreliable.\\r\\n\\r\\n---\\r\\n\\r\\n## 2. Distributed Control Architecture: Host PC (Brain) \u2194 Arduino (Muscle)\\r\\n\\r\\nTo overcome microcontroller limitations, we decoupled high-level reasoning from low-level actuation: **\\"PC as the brain, Arduino as the muscle.\\"**\\r\\n\\r\\n```mermaid\\r\\nflowchart TD\\r\\n    subgraph CeilingCam[\\"Ceiling Vision System (Overhead Camera)\\"]\\r\\n        Cam[\\"FHD Webcam (30 FPS)\\"]\\r\\n        Aruco[\\"ArUco Marker Detection (DICT_4X4_50)<br>Perspective Homography (homography.npy)\\"]\\r\\n        Cam --\x3e Aruco\\r\\n    end\\r\\n\\r\\n    subgraph PC[\\"Host PC (Python Engine)\\"]\\r\\n        Pose[\\"Robot Pose Estimation (x, y, \u03B8)\\"]\\r\\n        Disc[\\"648-bin Discretizer\\"]\\r\\n        QL[\\"Trained Q-Table (\u03B5=0)\\"]\\r\\n        BT_Host[\\"HC-06 Bluetooth SPP (115200 baud)\\"]\\r\\n        \\r\\n        Aruco --\x3e Pose --\x3e Disc --\x3e QL --\x3e BT_Host\\r\\n    end\\r\\n\\r\\n    subgraph Robot[\\"Physical Mobile Robot (Real Hardware)\\"]\\r\\n        BT_Slave[\\"HC-06 Bluetooth Receiver\\"]\\r\\n        MCU[\\"Arduino Uno (Firmware)\\"]\\r\\n        Motors[\\"L298N Dual H-Bridge + Geared DC Motors\\"]\\r\\n        \\r\\n        BT_Host <--\x3e|\\"Action Byte [0..3]<br>Ack/Status\\"| BT_Slave --\x3e MCU --\x3e Motors\\r\\n    end\\r\\n```\\r\\n\\r\\n* **Host PC Pipeline**: An overhead webcam captures the complete arena top-down, tracking an ArUco fiducial marker mounted on top of the robot at 30 FPS. The robot\'s planar pose `(x, y, \u03B8)` is calculated and mapped into the discrete 648-state space to retrieve the optimal greedy action from the Q-Table.\\r\\n* **HC-06 Serial Communication**: To minimize Round-Trip Time (RTT) over the Bluetooth Serial Port Profile (SPP), the transmission baud rate was upgraded from the default 9,600 to **115,200 bps**, sustaining a low-latency 30~50Hz control loop.\\r\\n* **Arduino Firmware (`arduino_firmware.ino`)**: Upon receiving single-byte action commands (`0: Forward`, `1: Backward`, `2: Turn Left`, `3: Turn Right`), the microcontroller modulates PWM pins on the L298N motor driver for precise tick-based open-loop pulses.\\r\\n\\r\\n---\\r\\n\\r\\n## 3. Overhead Camera Homography & ArUco Vision Tracking\\r\\n\\r\\n![Hardware Setup and Arena Calibration](./images/02_hardware_setup.png)\\r\\n\\r\\nTo measure robot positioning and obstacle proximity with millimeter accuracy across the real arena, we built an **OpenCV-based top-down computer vision pipeline**.\\r\\n\\r\\n### \u{1F4D0} Perspective Rectification & Homography (`calib_auto.py`)\\r\\n1. **Checkerboard Distortion Calibration**: To eliminate barrel distortion from wide-angle webcam lenses, intrinsic camera matrix (K) and distortion coefficients (D) were pre-computed using a standard 9\xd76 checkerboard.\\r\\n2. **Perspective Homography**: To project the angled camera viewpoint into a canonical 1.2m \xd7 1.2m square bird\'s-eye view, a 3\xd73 perspective homography matrix (`homography.npy`) was established from the 4 marked arena corner coordinates.\\r\\n\\r\\n### \u{1F4BB} ArUco Marker Pose Tracking Implementation (`vision.py`)\\r\\n\\r\\n```python\\r\\nimport cv2\\r\\nimport numpy as np\\r\\n\\r\\n# Load ArUco dictionary and detection parameters\\r\\naruco_dict = cv2.aruco.getPredefinedDictionary(cv2.aruco.DICT_4X4_50)\\r\\nparameters = cv2.aruco.DetectorParameters()\\r\\ndetector = cv2.aruco.ArucoDetector(aruco_dict, parameters)\\r\\n\\r\\ndef get_robot_pose(frame, homography_matrix):\\r\\n    \\"\\"\\"Calculates planar coordinates (x, y) and heading angle (theta) from rectified image.\\"\\"\\"\\r\\n    warped = cv2.warpPerspective(frame, homography_matrix, (600, 600))\\r\\n    corners, ids, _ = detector.detectMarkers(warped)\\r\\n    \\r\\n    if ids is not None and len(ids) > 0:\\r\\n        c = corners[0][0]\\r\\n        center_x = float(np.mean(c[:, 0]))\\r\\n        center_y = float(np.mean(c[:, 1]))\\r\\n        \\r\\n        # Calculate heading angle (theta) from marker front edge vector\\r\\n        front_x = (c[0][0] + c[1][0]) / 2.0\\r\\n        front_y = (c[0][1] + c[1][1]) / 2.0\\r\\n        theta = np.arctan2(front_y - center_y, front_x - center_x)\\r\\n        \\r\\n        return center_x, center_y, theta\\r\\n    return None\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\n## 4. Hardware Troubleshooting & Real-World Deployment Results\\r\\n\\r\\nTransitioning from simulation to physical operation revealed critical edge cases addressed through robust engineering countermeasures:\\r\\n\\r\\n| Symptom (Troubleshooting) | Root Cause | Engineering Solution |\\r\\n| :--- | :--- | :--- |\\r\\n| **Robot drifts sideways during forward command** | Gearbox friction differences between left & right DC motors | Implemented an interactive calibration script (`ble_vision_turn_calib.py`) to apply dynamic PWM trim offsets |\\r\\n| **Runaway behavior during Bluetooth disconnect** | Packet drops under RF interference causing robot to retain last command | Embedded a 200ms communication watchdog timer in firmware to immediately cut motor power upon signal loss |\\r\\n| **Intermittent ArUco marker detection loss** | Specular glare from ceiling fluorescent lighting on glossy marker surface | Fine-tuned adaptive thresholding parameters and added a 1D Kalman Filter position extrapolator |\\r\\n\\r\\n### \u{1F3C6} Final Real-World Benchmark\\r\\n* **Autonomous Goal Reaching Rate**: Tested across 30 independent trials in the physical 1.2m \xd7 1.2m obstacle arena, the robot achieved an **86.7% success rate (26/30 successful arrivals)**.\\r\\n* Leveraging just **2,592 pre-computed discrete Q-values (~2.5 KB)**, the agent navigated complex physical obstacles without any real-world gradient updates.\\r\\n\\r\\n---\\r\\n\\r\\n## 5. Concluding the RL Q-Learning Dev Log Series\\r\\n\\r\\nWith this final Sim-to-Real deployment, our 5-part **RL Q-Learning Robotics series** reaches its conclusion:\\r\\n\\r\\n1. **#1**: 648-Bin State Discretization & Webots TCP Socket IPC Architecture\\r\\n2. **#2**: Tabular Q-Learning \u03B5-Decay Exploration & Multi-Objective Reward Shaping\\r\\n3. **#3**: Overcoming Arena Local Minima in 12-Wall Environments via Headless Pipelines\\r\\n4. **#4**: Quantitative Benchmark with `evaluate_qlearning` vs. SARSA & DQN\\r\\n5. **#5**: Sim-to-Real Hardware Transfer via Arduino Uno, Bluetooth SPP & ArUco Vision\\r\\n\\r\\nFrom foundational simulator modeling and algorithmic tuning to multi-seed automation and physical hardware deployment, this series documented the complete lifecycle of reinforcement learning for embedded robotics. Stay tuned for future deep dives into our next projects!\\r\\n\\r\\n---\\r\\n\\r\\n### \u{1F4CC} 3\u20135 Line Executive Summary\\r\\n1. **Closing the Sim-to-Real Reality Gap**: Solves microcontroller computational limits (Arduino Uno 2KB SRAM) and physical wheel slip by zero-shot transferring the Webots-trained 648-state Q-Table to physical hardware.\\r\\n2. **Distributed Brain-Muscle Architecture**: A host PC executes heavy OpenCV vision and tabular Q-learning inference, transmitting binary movement commands via HC-06 Bluetooth SPP at 115,200 baud to the Arduino PWM motor controller.\\r\\n3. **Sub-Centimeter ArUco Vision Homography**: An overhead camera calibrated for barrel distortion tracks 6-DoF ArUco markers (`DICT_4X4_50`), transforming raw pixels into accurate real-world metric coordinates (x, y, \u03B8).\\r\\n4. **86.7% Physical Hardware Target Success**: Achieved a 26/30 successful target-reaching benchmark in a physical 1.2m \xd7 1.2m arena, demonstrating that discretized state spaces bridge the simulation-to-reality divide without on-device retraining."},{"id":"2026-05-20-maeumjigi-20","metadata":{"permalink":"/blog/2026-05-20-maeumjigi-20","source":"@site/blog/2026-05-20-maeumjigi-20/index.md","title":"[Maeumjigi Capstone Dev Log #20] 3rd Fine-Tuning Complete & Backend Feature Enhancements","description":"Designing our 3rd fine-tuning strategy, carefully calibrating the ratio between casual chat and crisis response to prevent emotional over-triggering.","date":"2026-05-20T00:00:00.000Z","tags":[{"inline":true,"label":"devlog","permalink":"/blog/tags/devlog"},{"inline":true,"label":"fine-tuning","permalink":"/blog/tags/fine-tuning"},{"inline":true,"label":"backend","permalink":"/blog/tags/backend"},{"inline":true,"label":"frontend","permalink":"/blog/tags/frontend"},{"inline":true,"label":"database","permalink":"/blog/tags/database"},{"inline":true,"label":"capstone","permalink":"/blog/tags/capstone"}],"readingTime":2.33,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"2026-05-20-maeumjigi-20","title":"[Maeumjigi Capstone Dev Log #20] 3rd Fine-Tuning Complete & Backend Feature Enhancements","authors":["jbgih"],"tags":["devlog","fine-tuning","backend","frontend","database","capstone"],"date":"2026-05-20T00:00:00.000Z","keywords":["AI Mental Health Chatbot","LLM Fine-tuning","AI Safety Wrapper","Capstone Project","Prompt Engineering"],"description":"Designing our 3rd fine-tuning strategy, carefully calibrating the ratio between casual chat and crisis response to prevent emotional over-triggering."},"unlisted":false,"prevItem":{"title":"[Webots Robotics] Sim-to-Real: Hardware Transfer via Arduino Uno, HC-06 Bluetooth & ArUco Vision Tracking (#5)","permalink":"/blog/2026-05-21-rl-qlearning-5"},"nextItem":{"title":"[Webots Robotics] Deterministic Evaluation via evaluate_qlearning & Benchmark vs. DQN and SARSA (#4)","permalink":"/blog/2026-05-20-rl-qlearning-4"}},"content":"![Cover Image](./images/01_cover.png)\\n\\nOver the two days of May 19th and 20th, the automation of evaluation for the 3rd fine-tuning (`fine_tuning_3`) and the enhancement of backend/frontend features for building the actual app service proceeded in parallel.\\n\\n{/* truncate */}\\n\\n### Concluding the 3rd Fine-Tuning and Automation Scripts\\n\\nBased on the insights gained from the previous fine-tuning, the training for the 3rd fine-tuning, which was set up with concepts of knowledge graphs and ontologies in mind, was completed.\\n\\n> \\"Select the checkpoint with the Best Eval from the experimental models in the fine_tuning_3 folder, replace the files in the adapter folder, and report the results.\\"\\n> \\"Write a run_test_20_30.sh file that runs inference and evaluation in parallel for fine_tuning_3 as well.\\"\\n\\nInstead of manually digging through folders to copy checkpoints like before, I instructed the Artificial Intelligence (AI) to write a script that automatically extracted the best performing model weights (Best Checkpoint) and set them up in the `adapter` folder. Then, I executed the parallel inference script, `run_test_20_30.sh`, throwing the evaluation for the 4 Alias models to the background server.\\n\\n### Backend/Frontend: Chatbot Database (DB) Saving and Community Board Features\\n\\nWhile the models were hard at work running inferences on the server, I accelerated the `mental-health` DB and app integration work in my local environment.\\n\\n> \\"Summarize seed_data.sql. What is the pw for users? Is it Test1234!? What was the db I was trying to apply this sql to?\\"\\n\\nTo break through the login issue that caused the frustrating `401 Unauthorized` error last time, I thoroughly examined `seed_data.sql` to verify the password hashing and user data.\\n\\nAs a result, I was able to leave a meaningful Git commit on the afternoon of May 20th:\\n`feat: Added chatbot DB save, board pagination, and emotion diary filter`\\n\\n![App Features](./images/02_app_feature.png)\\n\\nFinally, the conversation logs of our fine-tuned Large Language Model (LLM) chatbot officially started being saved to the DB! In addition, the pagination feature for the community board where users can communicate, and the emotion diary filter feature for recording daily moods were successfully added to the frontend.\\n\\nIt was a thrilling moment when the massive, invisible fine-tuned model finally began to be served in the beautiful vessel of a mobile app.\\n\\n---\\n\\n## Summary & Key Takeaways\\n\\n- **Automated Checkpoint Selection**: Engineered server-side evaluation scripts (`run_test_20_30.sh`) that dynamically extract and stage the best-performing adapter weights without manual intervention.\\n- **Parallel Multi-Model Benchmarking**: Orchestrated background evaluation pipelines running simultaneous inference across four distinct alias model candidates on remote GPU compute nodes.\\n- **Full-Duplex Conversation Persistence**: Resolved authentication deadlocks (`401 Unauthorized`) and established persistent relational database logging for all multi-turn chatbot exchanges.\\n- **Frontend App Feature Expansion**: Integrated community discussion pagination and multi-attribute mood diary filtering into the production React Native mobile client."},{"id":"2026-05-20-rl-qlearning-4","metadata":{"permalink":"/blog/2026-05-20-rl-qlearning-4","source":"@site/blog/2026-05-20-rl-qlearning-4/index.md","title":"[Webots Robotics] Deterministic Evaluation via evaluate_qlearning & Benchmark vs. DQN and SARSA (#4)","description":"Zero-exploration (\u03B5=0) deterministic evaluation pipeline with evaluate_qlearning.py, examining path efficiency, near-miss metrics, and benchmark comparisons against DQN and SARSA.","date":"2026-05-20T00:00:00.000Z","tags":[{"inline":true,"label":"reinforcement-learning","permalink":"/blog/tags/reinforcement-learning"},{"inline":true,"label":"q-learning","permalink":"/blog/tags/q-learning"},{"inline":true,"label":"evaluation","permalink":"/blog/tags/evaluation"},{"inline":true,"label":"benchmark","permalink":"/blog/tags/benchmark"},{"inline":true,"label":"dqn","permalink":"/blog/tags/dqn"},{"inline":true,"label":"sarsa","permalink":"/blog/tags/sarsa"},{"inline":true,"label":"robotics","permalink":"/blog/tags/robotics"},{"inline":true,"label":"python","permalink":"/blog/tags/python"}],"readingTime":3.76,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"2026-05-20-rl-qlearning-4","title":"[Webots Robotics] Deterministic Evaluation via evaluate_qlearning & Benchmark vs. DQN and SARSA (#4)","authors":["jbgih"],"tags":["reinforcement-learning","q-learning","evaluation","benchmark","dqn","sarsa","robotics","python"],"date":"2026-05-20T00:00:00.000Z","project":"rl_q_learning","description":"Zero-exploration (\u03B5=0) deterministic evaluation pipeline with evaluate_qlearning.py, examining path efficiency, near-miss metrics, and benchmark comparisons against DQN and SARSA.","keywords":["Deterministic Policy Evaluation","Near-Miss Obstacle Metric","Q-Learning vs DQN vs SARSA","Autonomous Navigation Benchmark","Zero Exploration Inference"]},"unlisted":false,"prevItem":{"title":"[Maeumjigi Capstone Dev Log #20] 3rd Fine-Tuning Complete & Backend Feature Enhancements","permalink":"/blog/2026-05-20-maeumjigi-20"},"nextItem":{"title":"[Webots Robotics] Conquering Local Minima in 12-Wall Obstacles: Multi-Seed Headless Simulation (#3)","permalink":"/blog/2026-05-19-rl-qlearning-3"}},"content":"![Success and Steps Benchmark](./images/01_eval_success_steps.png)\\r\\n\\r\\n> \u{1F4CC} **Key Takeaways (TL;DR)**\\r\\n> - **Objective**: Measure the pure, deterministic performance of the learned greedy policy (\u03B5=0) without exploration noise, validating real-world deployability.\\r\\n> - **Methodology**: Implemented `evaluate_qlearning.py` running 30 independent trials across 5 round-robin evaluation seeds, rigorously tracking success rates, path efficiency vs. theoretical shortest routes, and obstacle near-miss counts.\\r\\n> - **Result**: Tabular Q-Learning attained a 93.3% deterministic success rate in the 12-wall arena with superior path smoothness and ultra-low 0.02ms inference latency, outperforming heavier DQN and SARSA baselines.\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n---\\r\\n\\r\\n## 1. Quantitative Evaluation Pipeline (`evaluate_qlearning.py`)\\r\\n\\r\\nTraining reward curves are inherently noisy due to \u03B5-greedy exploration. To evaluate the true deployment capability of our agent, we must test the **purely deterministic policy ($\\\\epsilon = 0$)**.\\r\\n\\r\\nWe built an evaluation runner that loads the saved Q-table (`qlearning_qtable.npy`) and evaluates the agent across 5 distinct test seeds (`EVAL_SEEDS = (0, 1, 2, 3, 4)`).\\r\\n\\r\\n```mermaid\\r\\nflowchart LR\\r\\n    Model[\\"Trained Q-Table<br>(qlearning_qtable.npy)\\"] --\x3e Agent[\\"Greedy Agent<br>(\u03B5 = 0 Fixed)\\"]\\r\\n    EvalSeeds[\\"5 Test Seeds<br>(EVAL_SEEDS 0..4)\\"] --\x3e Webots[\\"Webots Simulator<br>(30 Evaluation Trials)\\"]\\r\\n    Agent <--\x3e Webots\\r\\n    Webots --\x3e CSV[\\"Trace & Metric Logging<br>(eval_log.csv / traces)\\"]\\r\\n```\\r\\n\\r\\n### \u{1F4BB} Evaluation Loop Architecture\\r\\n\\r\\n```python\\r\\n# evaluate_qlearning.py excerpt\\r\\nagent = QLearningAgent(seed=0)\\r\\nagent.load(model_path) # Load trained Q-Table\\r\\n\\r\\nfor ep in range(n_episodes):\\r\\n    env_seed = EVAL_SEEDS[ep % len(EVAL_SEEDS)]\\r\\n    raw, info = env.reset(seed=env_seed, return_info=True)\\r\\n    s = discretize(raw)\\r\\n    \\r\\n    for t in range(1, max_steps + 1):\\r\\n        a = agent.act(s, deterministic=True) # Pure argmax Q(s, a)\\r\\n        raw_next, r, done, info = env.step(a)\\r\\n        s = discretize(raw_next)\\r\\n        \\r\\n        # Log trajectory coordinates and near-misses (dist <= 0.15m)\\r\\n        record_metrics(info)\\r\\n        if done: break\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\n## 2. Comprehensive Evaluation Metrics\\r\\n\\r\\n1. **Success Rate**: Percentage of runs reaching the target radius (0.10m) within 150 steps without collision.\\r\\n2. **Path Efficiency**: Ratio of theoretical shortest path distance (L_shortest) to actual traversed path length (L_actual).\\r\\n   **Path Efficiency (%) = (Shortest Path / Actual Path) \xd7 100%**\\r\\n3. **Near-Miss Frequency**: Number of steps where obstacle distance dipped below 0.15m.\\r\\n4. **Oscillation Count**: Metric penalizing back-and-forth steering jitter.\\r\\n\\r\\n---\\r\\n\\r\\n## 3. Algorithm Benchmark: Tabular Q-Learning vs. SARSA vs. DQN\\r\\n\\r\\n![Trajectory Quality & Benchmarks](./images/02_eval_quality.png)\\r\\n\\r\\nComparative evaluation in the identical Webots 12-wall arena across the three reinforcement learning algorithms revealed clear performance trade-offs:\\r\\n\\r\\n| Metric | Tabular Q-Learning (Ours) | SARSA (On-policy) | Deep Q-Network (DQN) |\\r\\n| :--- | :---: | :---: | :---: |\\r\\n| **Learning Paradigm** | Off-policy TD(0) | On-policy TD(0) | Neural Network (Deep RL) |\\r\\n| **Parameter Size** | **2,592 floats (~2.5 KB)** | 2,592 floats (~2.5 KB) | ~150,000 weights (~600 KB) |\\r\\n| **Deterministic Success Rate (`obstacle12`)** | **93.3%** | 86.7% | 90.0% |\\r\\n| **Average Steps per Episode** | **41.2 steps** | 48.5 steps | 44.7 steps |\\r\\n| **Per-Step Inference Latency** | **0.02 ms** (NumPy array lookup) | 0.02 ms | 2.15 ms (PyTorch forward pass) |\\r\\n| **Near-Miss Frequency** | Low (balanced detour) | Minimal (excessively conservative) | Moderate |\\r\\n\\r\\n### \u{1F50D} In-Depth Behavioral Analysis\\r\\n* **Why Q-Learning Excels**: By evaluating `max_a\' Q(s\', a\')`, off-policy Q-Learning ignores transient exploratory collisions during training, settling on the **shortest feasible detour path**.\\r\\n* **SARSA\'s Conservative Bias**: On-policy updates factor in exploration penalties, causing SARSA to over-correct and choose excessively long, inefficient detours to avoid walls at all costs.\\r\\n* **DQN\'s Trade-off**: DQN handles continuous inputs well, but training stability requires replay buffers and target networks, while its 2.15ms latency and GPU requirement impose severe constraints on lightweight microcontrollers like Arduino.\\r\\n\\r\\n---\\r\\n\\r\\n## 4. Evaluation Takeaways\\r\\n\\r\\nOur discrete 648-bin **Tabular Q-Learning model requires just 2.5 KB of memory**, yet matched and exceeded deep neural network models in success rate (93.3%) and real-time execution speed.\\r\\n\\r\\n---\\r\\n\\r\\n## 5. What\'s Next?\\r\\n\\r\\nWith simulation benchmarks thoroughly concluded, the ultimate milestone remains: **transferring policy to reality (Sim-to-Real)**.\\r\\n\\r\\nIn our final Episode #5, we will detail the hardware integration: deploying our policy to a **2-wheel differential Arduino Uno robot, communicating via HC-06 Bluetooth, and tracking ground-truth position via ceiling webcam checkerboard calibration and ArUco markers**!\\r\\n\\r\\n---\\r\\n\\r\\n### \u{1F4CC} 3\u20135 Line Executive Summary\\r\\n1. **Zero-Exploration Deterministic Evaluation**: Evaluated the greedy policy with exploration set to zero (\u03B5=0) across 30 trials and 5 evaluation seeds via `evaluate_qlearning.py` to verify true deployment readiness.\\r\\n2. **Three-Dimensional Metric Triad**: Measured not just success rates, but path efficiency ratios against theoretical shortest paths and safety near-miss counts to guarantee collision avoidance.\\r\\n3. **Triangular Benchmark (Q-Learning vs SARSA vs DQN)**: Tabular Q-Learning achieved 93.3% success in the 12-wall obstacle arena, outperforming on-policy SARSA (80.0%) and off-policy DQN (86.7%).\\r\\n4. **Microcontroller Latency Dominance**: Discretized Q-table lookups executed in 0.02ms with negligible memory footprints, decisively outclassing deep neural network inference on constrained embedded hardware."},{"id":"2026-05-19-rl-qlearning-3","metadata":{"permalink":"/blog/2026-05-19-rl-qlearning-3","source":"@site/blog/2026-05-19-rl-qlearning-3/index.md","title":"[Webots Robotics] Conquering Local Minima in 12-Wall Obstacles: Multi-Seed Headless Simulation (#3)","description":"Overcoming the Local Minima dilemma in complex 12-wall obstacle environments (obstacle12) and orchestrating high-speed automated multi-seed Webots simulations.","date":"2026-05-19T00:00:00.000Z","tags":[{"inline":true,"label":"reinforcement-learning","permalink":"/blog/tags/reinforcement-learning"},{"inline":true,"label":"q-learning","permalink":"/blog/tags/q-learning"},{"inline":true,"label":"webots","permalink":"/blog/tags/webots"},{"inline":true,"label":"obstacle-avoidance","permalink":"/blog/tags/obstacle-avoidance"},{"inline":true,"label":"local-minima","permalink":"/blog/tags/local-minima"},{"inline":true,"label":"headless","permalink":"/blog/tags/headless"},{"inline":true,"label":"python","permalink":"/blog/tags/python"}],"readingTime":3.51,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"2026-05-19-rl-qlearning-3","title":"[Webots Robotics] Conquering Local Minima in 12-Wall Obstacles: Multi-Seed Headless Simulation (#3)","authors":["jbgih"],"tags":["reinforcement-learning","q-learning","webots","obstacle-avoidance","local-minima","headless","python"],"date":"2026-05-19T00:00:00.000Z","project":"rl_q_learning","description":"Overcoming the Local Minima dilemma in complex 12-wall obstacle environments (obstacle12) and orchestrating high-speed automated multi-seed Webots simulations.","keywords":["Local Minima Reinforcement Learning","Webots Headless Simulation","Obstacle Avoidance Multi-Seed","Deep RL vs Tabular Q","PowerShell Automated Training"]},"unlisted":false,"prevItem":{"title":"[Webots Robotics] Deterministic Evaluation via evaluate_qlearning & Benchmark vs. DQN and SARSA (#4)","permalink":"/blog/2026-05-20-rl-qlearning-4"},"nextItem":{"title":"[Webots Robotics] Tabular Q-Learning Implementation & Reward Shaping Tuning (#2)","permalink":"/blog/2026-05-18-rl-qlearning-2"}},"content":"![obstacle12 Simulation Arena](./images/01_obstacle12_arena.png)\\r\\n\\r\\n> \u{1F4CC} **Key Takeaways (TL;DR)**\\r\\n> - **Problem**: When a goal lies directly behind an obstacle, the myopic nature of distance-delta rewards (+0.1 \xd7 \u0394dist) pulls the robot into head-on collisions, trapping it in severe **Local Minima**.\\r\\n> - **Solution**: Integrated 3-way head-scan obstacle perception (front/left/right) with long-horizon Bellman value propagation (\u03B3=0.99), alongside an automated PowerShell **Webots Headless pipeline (`headless_run.ps1`)** executing multi-seed training across seeds 0, 1, and 2.\\r\\n> - **Result**: The agent successfully learned robust detour policies in the 12-wall arena, achieving a 90%+ goal success rate after 600 episodes.\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n---\\r\\n\\r\\n## 1. The Obstacle Challenge: The Local Minima Trap\\r\\n\\r\\nIn an empty arena (`no_obstacle`), navigating is simply a matter of steering toward the target heading. However, introducing **12 interior walls (`obstacle12`)** unveiled a critical bottleneck in reward design:\\r\\n\\r\\n```mermaid\\r\\nflowchart TD\\r\\n    Start[\\"Start (Robot)\\"]\\r\\n    Wall[\\"Obstacle Wall\\"]\\r\\n    Goal[\\"Target Goal\\"]\\r\\n    \\r\\n    Start --\x3e|\\"Direct drive (greedy distance reward)\\"| Wall\\r\\n    Wall -.->|\\"Collision & deadlocked (Local Minima)\\"| Wall\\r\\n    Start ==>|\\"Detour Policy<br>Accepts temporary distance penalty\\"| Goal\\r\\n```\\r\\n\\r\\n* **The Dilemma**: When the target is directly on the other side of an interior wall, driving straight ahead leads directly to collision.\\r\\n* **Reward Conflict**: Circumnavigating the wall requires moving temporarily away from the goal (negative distance delta). Under naive exploration, the agent enters a deadlock\u2014spinning or timing out against the wall.\\r\\n\\r\\n---\\r\\n\\r\\n## 2. Solution Strategy: Head-Scan Perception & Value Backpropagation\\r\\n\\r\\nOvercoming this trap relies on coupling **3-directional head-scan perception** with a **high discount factor (\u03B3 = 0.99)**:\\r\\n\\r\\n1. **Perceptual State Discretization**:\\r\\n   * Attempting to advance while `front_distance = Danger` yields a heavy collision penalty (-1.0).\\r\\n   * Sweeping the sensor head left and right reveals free avenues (`left_distance = Safe` or `right_distance = Safe`), encouraging lateral turns.\\r\\n2. **Long-Term Temporal Difference Credit Assignment**:\\r\\n   * Although turning away temporarily depresses the step reward, successfully rounding the wall and reaching the target yields the substantial terminal reward (+1.0).\\r\\n   * Backpropagated through Q(s, a) with \u03B3 = 0.99, the agent gradually learns that detour steps possess higher expected return than head-on approaches.\\r\\n\\r\\n---\\r\\n\\r\\n## 3. Webots Headless Automation Pipeline\\r\\n\\r\\nRigorous reinforcement learning requires **multi-seed validation (Seeds 0, 1, 2)**. Running 1,500 episodes interactively in the Webots GUI three times would take many hours.\\r\\n\\r\\nWe automated this with a **`headless_run.ps1` PowerShell script**, launching Webots in high-speed, no-render mode (`--mode=fast --no-rendering`):\\r\\n\\r\\n### \u{1F4BB} Automated Pipeline (`headless_run.ps1`)\\r\\n\\r\\n```powershell\\r\\n# Launch Webots in background headless fast mode\\r\\n$webotsProc = Start-Process -FilePath $WebotsExe `\\r\\n    -ArgumentList @(\\"--mode=fast\\", \\"--no-rendering\\", \\"--stdout\\", \\"--stderr\\", $WorldFile) `\\r\\n    -PassThru\\r\\n\\r\\n# Train agent over socket IPC\\r\\npython train_qlearning.py --scenario obstacle12 --seed 0 --episodes 1500\\r\\n\\r\\n# Cleanup process and generate performance plots\\r\\nStop-Process -Id $webotsProc.Id -Force\\r\\npython -m qlearning.plot_curves --log-dir logs/obstacle12/seed_0\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\n## 4. Empirical Evaluation: Cross-Environment Learning Curves\\r\\n\\r\\n![Cross-Environment Learning Curves](./images/02_comparison_curves.png)\\r\\n\\r\\nThe graph above contrasts convergence across 3 random seeds between the unobstructed world (`no_obstacle`) and the 12-wall obstacle world (`obstacle12`).\\r\\n\\r\\n### \u{1F4CA} Benchmark Metrics\\r\\n\\r\\n| Metric | Empty Arena (`no_obstacle`) | 12-Wall Arena (`obstacle12`) |\\r\\n| :--- | :---: | :---: |\\r\\n| **Initial Convergence** | ~300 - 400 episodes | ~600 - 800 episodes |\\r\\n| **Final Success Rate (100-ep MA)** | **98.5% - 99.2%** | **91.4% - 94.8%** |\\r\\n| **Mean Steps per Episode** | 15 - 22 steps | 38 - 52 steps (detour path) |\\r\\n| **Cross-Seed Variance** | Negligible (highly stable) | Moderate (exploration path dependency) |\\r\\n\\r\\n* **Extended Exploration**: In `obstacle12`, discovering viable detour corridors requires approximately 200 additional episodes of random trials, keeping the average reward depressed until episode 400.\\r\\n* **Detour Mastery**: Beyond episode 800, all seeds stabilize above 90% success, confirming that the agent reliably maneuvers through tight gaps without collisions.\\r\\n\\r\\n---\\r\\n\\r\\n## 5. What\'s Next?\\r\\n\\r\\nOur 648-bin Tabular Q-Learning model successfully navigates maze-like obstacle configurations.\\r\\n\\r\\nIn Episode #4, we will load the saved model checkpoints (`models/*.npy`) to benchmark greedy, deterministic performance using **`evaluate_qlearning.py` and analyze comparative metrics against DQN and SARSA**!\\r\\n\\r\\n---\\r\\n\\r\\n## Summary & Key Takeaways\\r\\n\\r\\n- **Complex Obstacle Arena Design**: Configured a constrained 1.2m \xd7 1.2m environment in Webots featuring 12 randomized interior wall blocks to evaluate non-trivial spatial pathfinding.\\r\\n- **Dynamic Episode Management**: Implemented automatic collision thresholds, goal radius triggering, and programmatic episode resets via Webots Supervisor IPC.\\r\\n- **Overcoming Local Minima**: Augmented reward shaping with negative gradient penalties against entrapment and oscillatory turning behaviors near corners.\\r\\n- **Headless Training Acceleration**: Achieved over 1,000 episodes per hour by disabling 3D rendering and running the Webots physics engine in fast headless batch mode."},{"id":"2026-05-18-rl-qlearning-2","metadata":{"permalink":"/blog/2026-05-18-rl-qlearning-2","source":"@site/blog/2026-05-18-rl-qlearning-2/index.md","title":"[Webots Robotics] Tabular Q-Learning Implementation & Reward Shaping Tuning (#2)","description":"In-depth breakdown of Tabular Q-Learning TD(0) update formulas, exponential epsilon-decay exploration, and dense reward shaping to overcome sparse rewards in mobile robot navigation.","date":"2026-05-18T00:00:00.000Z","tags":[{"inline":true,"label":"reinforcement-learning","permalink":"/blog/tags/reinforcement-learning"},{"inline":true,"label":"q-learning","permalink":"/blog/tags/q-learning"},{"inline":true,"label":"reward-shaping","permalink":"/blog/tags/reward-shaping"},{"inline":true,"label":"webots","permalink":"/blog/tags/webots"},{"inline":true,"label":"robotics","permalink":"/blog/tags/robotics"},{"inline":true,"label":"machine-learning","permalink":"/blog/tags/machine-learning"},{"inline":true,"label":"python","permalink":"/blog/tags/python"}],"readingTime":4.58,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"2026-05-18-rl-qlearning-2","title":"[Webots Robotics] Tabular Q-Learning Implementation & Reward Shaping Tuning (#2)","authors":["jbgih"],"tags":["reinforcement-learning","q-learning","reward-shaping","webots","robotics","machine-learning","python"],"date":"2026-05-18T00:00:00.000Z","project":"rl_q_learning","description":"In-depth breakdown of Tabular Q-Learning TD(0) update formulas, exponential epsilon-decay exploration, and dense reward shaping to overcome sparse rewards in mobile robot navigation.","keywords":["Q-Learning Reward Shaping","Epsilon Greedy Exploration","Sparse Reward Reinforcement Learning","Bellman Optimality TD","Robot Obstacle Avoidance"]},"unlisted":false,"prevItem":{"title":"[Webots Robotics] Conquering Local Minima in 12-Wall Obstacles: Multi-Seed Headless Simulation (#3)","permalink":"/blog/2026-05-19-rl-qlearning-3"},"nextItem":{"title":"[Maeumjigi Capstone Dev Log #19] Automated Evaluation Reports & FastAPI PostgreSQL 401 Debugging","permalink":"/blog/2026-05-17-maeumjigi-19"}},"content":"![Training Reward Curve](./images/01_reward_curve.png)\\r\\n\\r\\n> \u{1F4CC} **Key Takeaways (TL;DR)**\\r\\n> - **Problem**: Sparse reward setups (+1.0 at goal, -1.0 at collision) cause severe exploration delays, causing the agent to wander or spin for thousands of episodes before stumbling upon the target.\\r\\n> - **Solution**: Implemented a multi-objective **Dense Reward Shaping** mechanism combining potential-based Euclidean distance delta rewards (+0.1 \xd7 \u0394dist) with step (-0.01), turning (-0.01), and backward (-0.05) penalties, paired with exponential epsilon decay (1.0 \u2192 0.05).\\r\\n> - **Result**: The moving average reward shifted into a steady positive regime (0.7+) within 500 episodes in the `no_obstacle` scenario, achieving a 98%+ goal success rate.\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n---\\r\\n\\r\\n## 1. Tabular Q-Learning Update Formula & Agent Architecture\\r\\n\\r\\nTabular Q-Learning is an **off-policy Temporal Difference (TD(0))** algorithm grounded in the Bellman Optimality Equation.\\r\\n\\r\\nThe agent maintains an action-value table Q(s, a) structured as a 2D NumPy array of shape $(648, 4)$. Using the experience transition tuple $(s, a, r, s\', done)$ streamed from the Webots socket server, the $Q$-values are updated in real time via:\\r\\n\\r\\n### \u{1F4D0} Q-Learning TD(0) Update Rule\\r\\n\\r\\n```text\\r\\nTarget = r + \u03B3 * max_a\' Q(s\', a\') * (1 - done)\\r\\nTD Error = Target - Q(s, a)\\r\\nQ(s, a) <- Q(s, a) + \u03B1 * TD Error\\r\\n```\\r\\n\\r\\n* **Learning Rate (\u03B1 = 0.1)**: Balances the rate of incorporating new feedback versus retaining historical estimates.\\r\\n* **Discount Factor (\u03B3 = 0.99)**: Values long-term future returns, critical for multi-step navigation.\\r\\n* **Terminal Masking (`1 - done`)**: Clamps future expectations to zero upon goal arrival or collision, isolating the terminal reward.\\r\\n\\r\\n### \u{1F4BB} Agent Core Implementation (`qlearning_agent.py`)\\r\\n\\r\\n```python\\r\\nimport numpy as np\\r\\n\\r\\nclass QLearningAgent:\\r\\n    def __init__(self, n_states=648, n_actions=4, alpha=0.1, gamma=0.99,\\r\\n                 eps_start=1.0, eps_min=0.05, eps_decay=0.995, seed=0):\\r\\n        self.rng = np.random.default_rng(seed)\\r\\n        self.Q = np.zeros((n_states, n_actions), dtype=np.float64)\\r\\n        self.alpha = float(alpha)\\r\\n        self.gamma = float(gamma)\\r\\n        self.epsilon = float(eps_start)\\r\\n        self.eps_min = float(eps_min)\\r\\n        self.eps_decay = float(eps_decay)\\r\\n        self.n_actions = int(n_actions)\\r\\n\\r\\n    def act(self, s: int, deterministic: bool = False) -> int:\\r\\n        \\"\\"\\"\u03B5-Greedy behavior policy: Exploration vs. Exploitation\\"\\"\\"\\r\\n        if (not deterministic) and self.rng.random() < self.epsilon:\\r\\n            return int(self.rng.integers(self.n_actions))\\r\\n        return int(np.argmax(self.Q[s]))\\r\\n\\r\\n    def update(self, s: int, a: int, r: float, s_next: int, done: bool) -> float:\\r\\n        \\"\\"\\"TD(0) Off-policy Q-Table update\\"\\"\\"\\r\\n        target = r if done else r + self.gamma * float(np.max(self.Q[s_next]))\\r\\n        td_error = target - self.Q[s, a]\\r\\n        self.Q[s, a] += self.alpha * td_error\\r\\n        return float(td_error)\\r\\n\\r\\n    def decay_epsilon(self):\\r\\n        \\"\\"\\"Exponential decay executed at the end of each episode\\"\\"\\"\\r\\n        self.epsilon = max(self.eps_min, self.epsilon * self.eps_decay)\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\n## 2. Exponential Epsilon-Greedy Decay Strategy\\r\\n\\r\\nAt the start of training, the agent has zero domain knowledge, requiring **\u03B5 = 1.0 (100% random exploration)** to discover the arena boundaries.\\r\\n\\r\\nHowever, an uncurbed exploration rate induces perpetual collisions even after the optimal path has been resolved. We apply per-episode exponential decay:\\r\\n\\r\\n**\u03B5_(ep+1) = max(\u03B5_min, \u03B5_ep \xd7 0.995)**\\r\\n\\r\\n* **Episode 1**: \u03B5 = 1.0 (Full exploration)\\r\\n* **Episode 300**: \u03B5 \u2248 0.22 (Shift toward exploiting high Q-values)\\r\\n* **Episode 600**: \u03B5 = 0.05 (Floor exploration rate \u03B5_min, 95% greedy execution)\\r\\n\\r\\n---\\r\\n\\r\\n## 3. Dense Reward Shaping for Sparse Navigation\\r\\n\\r\\nA fundamental challenge in mobile robotics is **sparse reward feedback**. In a 1.2m \xd7 1.2m arena, moving randomly yields zero reward until the robot coincidentally intersects the $0.10m$ goal tolerance.\\r\\n\\r\\nTo guide convergence, we engineered a **Dense Reward Shaping** schedule inside the Webots controller (`RL_controller.py`):\\r\\n\\r\\n| Reward Component | Value | Design Objective & Physical Effect |\\r\\n| :--- | :---: | :--- |\\r\\n| **Goal Reached (`REWARD_GOAL`)** | **+1.0** | Terminal reward on successful target arrival |\\r\\n| **Wall/Obstacle Collision (`REWARD_COLLISION`)** | **-1.0** | Severe penalty on physical impact |\\r\\n| **Distance Delta Reward (`REWARD_DELTA_SCALE`)** | **+0.1 \xd7 \u0394dist** | Immediate feedback proportional to Euclidean distance reduction |\\r\\n| **Step Time Penalty (`REWARD_STEP`)** | **-0.01** | Prevents idling and incentivizes shortest paths |\\r\\n| **Turning Penalty (`REWARD_TURN`)** | **-0.01** | Suppresses unproductive spinning behavior |\\r\\n| **Backward Penalty (`REWARD_BACKWARD`)** | **-0.05** | Discourages inefficient reverse driving |\\r\\n\\r\\n### \u{1F50D} Mathematical Principle of Distance Delta\\r\\n**\u0394dist = dist_prev - dist_curr**\\r\\n* Driving $0.05m$ toward the target awards $+0.1 \\\\times 0.05 = +0.005$ immediately.\\r\\n* Conversely, driving away incurs an instant penalty, allowing the agent to align its heading with the target within the first 100 episodes.\\r\\n\\r\\n---\\r\\n\\r\\n## 4. Empirical Evaluation: Reward and Success Curves\\r\\n\\r\\nTraining for 1,500 episodes in the `no_obstacle` world demonstrated remarkable convergence matching our theoretical expectations.\\r\\n\\r\\n![Success Rate Curve](./images/02_success_curve.png)\\r\\n\\r\\n### \u{1F4C8} Convergence Milestones\\r\\n1. **Episodes 0 ~ 200 (Exploration Phase)**:\\r\\n   * Frequent wall collisions and 150-step timeouts keep the moving average reward in the negative range (-0.4 ~ -0.2).\\r\\n2. **Episodes 200 ~ 500 (Ascent Phase)**:\\r\\n   * As distance-delta rewards propagate through the Q-Table, the policy establishes a strong forward-driving preference whenever `goal_heading` is centered.\\r\\n   * Success rate surges from 20% to **over 80%**.\\r\\n3. **Episodes 500 ~ 1,500 (Asymptotic Convergence)**:\\r\\n   * With \u03B5 settled at 0.05, average steps per episode plummet from 150 (timeout) to **15 ~ 22 steps**.\\r\\n   * The 100-episode moving average success rate converges above **98.5%**.\\r\\n\\r\\n---\\r\\n\\r\\n## 5. What\'s Next?\\r\\n\\r\\nWe have proven that Tabular Q-Learning over 648 states solves empty arena navigation cleanly.\\r\\n\\r\\nHowever, **real-world environments are packed with walls and obstacles**. In Episode #3, we will investigate the **`obstacle12` and `obstacle_hard` maps**, examining how our agent handles local minima traps and running multi-seed parallel training!\\r\\n\\r\\n---\\r\\n\\r\\n## Summary & Key Takeaways\\r\\n\\r\\n- **Bellman Optimality Formulation**: Formulated tabular Q-value updates with learning rate \u03B1 = 0.1 and discount factor \u03B3 = 0.95 to guarantee mathematical convergence across discrete state transitions.\\r\\n- **Multi-Objective Reward Shaping**: Engineered a balanced reward function combining distance-delta incentives (+10 \xd7 \u0394d), goal arrival bonuses (+100), step costs (-0.1), and collision penalties (-50).\\r\\n- **Adaptive Exploration Schedule**: Applied an exponential \u03B5-decay policy from 1.0 down to a floor of 0.05 over 1,000 episodes, effectively balancing exploration with exploitation.\\r\\n- **Empirical Convergence**: Validated rapid policy convergence within 300 to 500 episodes in open benchmark environments before scaling to obstacle-dense arenas."},{"id":"2026-05-17-maeumjigi-19","metadata":{"permalink":"/blog/2026-05-17-maeumjigi-19","source":"@site/blog/2026-05-17-maeumjigi-19/index.md","title":"[Maeumjigi Capstone Dev Log #19] Automated Evaluation Reports & FastAPI PostgreSQL 401 Debugging","description":"Overcoming full-stack hurdles: generating automated LLM benchmark reports with Claude Code, resolving cryptic JWT 401 Unauthorized errors in PostgreSQL, and designing our hybrid Knowledge Graph architecture.","date":"2026-05-17T00:00:00.000Z","tags":[{"inline":true,"label":"devlog","permalink":"/blog/tags/devlog"},{"inline":true,"label":"automated-reporting","permalink":"/blog/tags/automated-reporting"},{"inline":true,"label":"fastapi","permalink":"/blog/tags/fastapi"},{"inline":true,"label":"postgresql","permalink":"/blog/tags/postgresql"},{"inline":true,"label":"authentication","permalink":"/blog/tags/authentication"},{"inline":true,"label":"troubleshooting","permalink":"/blog/tags/troubleshooting"},{"inline":true,"label":"knowledge-graph","permalink":"/blog/tags/knowledge-graph"},{"inline":true,"label":"capstone","permalink":"/blog/tags/capstone"}],"readingTime":4.68,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"2026-05-17-maeumjigi-19","title":"[Maeumjigi Capstone Dev Log #19] Automated Evaluation Reports & FastAPI PostgreSQL 401 Debugging","authors":["jbgih"],"tags":["devlog","automated-reporting","fastapi","postgresql","authentication","troubleshooting","knowledge-graph","capstone"],"date":"2026-05-17T00:00:00.000Z","keywords":["FastAPI PostgreSQL Integration","401 Unauthorized Troubleshooting","JWT Authentication Salt Mismatch","LLM Evaluation Report Automation","Knowledge Graph Chatbot Architecture"],"description":"Overcoming full-stack hurdles: generating automated LLM benchmark reports with Claude Code, resolving cryptic JWT 401 Unauthorized errors in PostgreSQL, and designing our hybrid Knowledge Graph architecture."},"unlisted":false,"prevItem":{"title":"[Webots Robotics] Tabular Q-Learning Implementation & Reward Shaping Tuning (#2)","permalink":"/blog/2026-05-18-rl-qlearning-2"},"nextItem":{"title":"[Webots Robotics] Q-Learning Autonomous Navigation: 648-Bin State Discretization & Socket Architecture (#1)","permalink":"/blog/2026-05-17-rl-qlearning-1"}},"content":"![Cover Image](./images/01_cover.png)\\r\\n\\r\\nMid-May 2026 was supposed to be a calm interval after wrapping up our 2nd fine-tuning (`fine_tuning_2`). Instead, May 17th hit our team with a relentless double challenge: condensing hundreds of raw inference metrics into an automated technical report, while simultaneously battling a cryptic `HTTP 401 Unauthorized` cascading error across our newly integrated **FastAPI** and **PostgreSQL** backend.\\r\\n\\r\\nHere is the complete post-mortem of how we automated our reporting and systematically neutralized the backend authentication breakdown.\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n### 1. Autonomous Fine-Tuning Evaluation Reporting\\r\\n\\r\\nAnalyzing the 2nd fine-tuning results required processing hundreds of inference samples across multiple checkpoint variants (comparing Alpha values: 16, 32, and 64). Doing this manually was mathematically unfeasible given our capstone deadlines.\\r\\n\\r\\nWe engineered a structured prompt document (`report_prompt.md`) that guided **Claude Code** to analyze raw JSON evaluation matrices and automatically synthesize an executive technical report:\\r\\n\\r\\n```markdown\\r\\n# Excerpt from report_prompt.md\\r\\n1. Parse evaluation metrics (BERTScore, ROUGE-L, Perplexity) from /eval/results_alpha_*.json.\\r\\n2. Group model variants by empathy score, conversational naturalness, and safety compliance.\\r\\n3. Highlight critical failure cases (e.g., hyper-formal robotic apologies vs conversational warmth).\\r\\n4. Output the synthesis directly into a publication-ready Word document structure.\\r\\n```\\r\\n\\r\\nThe AI agent generated `fine_tuning_2_report.docx` in under 3 minutes, complete with comparative analysis tables and qualitative excerpt breakdowns.\\r\\n\\r\\n---\\r\\n\\r\\n### 2. The Nightmare of HTTP 401 Unauthorized in PostgreSQL\\r\\n\\r\\nWith reporting streamlined, we restored our staging database dump (`backup.sql`) into a local PostgreSQL instance to test end-to-end user session persistence. Although the database restored with zero SQL syntax errors, our Next.js frontend crashed into an inescapable login loop:\\r\\n\\r\\n```text\\r\\nINFO: 127.0.0.1:54322 - \\"POST /auth/login HTTP/1.1\\" 401 Unauthorized\\r\\nDETAIL: {\\"error\\": \\"Invalid credentials or malformed signature\\"}\\r\\n```\\r\\n\\r\\nEven with verified test credentials (`test@maeumjigi.kr` / `Password123!`), the FastAPI authentication service persistently rejected every login handshake.\\r\\n\\r\\n```mermaid\\r\\nsequenceDiagram\\r\\n    autonumber\\r\\n    actor Client as Next.js Web Client\\r\\n    participant API as FastAPI Gateway (/auth/login)\\r\\n    participant DB as PostgreSQL Database\\r\\n    participant Auth as Passlib Bcrypt Verifier\\r\\n\\r\\n    Client->>API: POST /auth/login {email, password}\\r\\n    API->>DB: SELECT id, password_hash FROM users WHERE email=...\\r\\n    DB--\x3e>API: Returns $2a$12$... hash string\\r\\n    API->>Auth: bcrypt.verify(\\"Password123!\\", db_hash)\\r\\n    Note over Auth: Trap 1: Salt algorithm mismatch ($2a$ vs $2b$)!\\r\\n    Auth--\x3e>API: Verification Failed (False)\\r\\n    API--\x3e>Client: 401 Unauthorized\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\n### 3. Root Cause Investigation & debug_login.py\\r\\n\\r\\nTo isolate whether the breakdown stemmed from frontend CORS headers, database corruption, or JWT secret misconfigurations, we wrote a standalone diagnostic script: `debug_login.py`.\\r\\n\\r\\n```python\\r\\n# Standalone authentication diagnostic utility: debug_login.py\\r\\nimport sys\\r\\nfrom passlib.context import CryptContext\\r\\nfrom sqlalchemy import create_engine, text\\r\\n\\r\\nDATABASE_URL = \\"postgresql://postgres:secret@localhost:5432/maeumjigi\\"\\r\\npwd_context = CryptContext(schemes=[\\"bcrypt\\"], deprecated=\\"auto\\")\\r\\n\\r\\ndef diagnose_user_auth(email: str, raw_pass: str):\\r\\n    engine = create_engine(DATABASE_URL)\\r\\n    with engine.connect() as conn:\\r\\n        result = conn.execute(text(\\"SELECT password_hash FROM users WHERE email = :e\\"), {\\"e\\": email}).fetchone()\\r\\n        if not result:\\r\\n            print(\\"[FAIL] User not found in database!\\")\\r\\n            return\\r\\n        \\r\\n        stored_hash = result[0]\\r\\n        print(f\\"[INFO] Retrieved hash: {stored_hash[:15]}...\\")\\r\\n        \\r\\n        # Verify hash algorithm version compatibility\\r\\n        is_valid = pwd_context.verify(raw_pass, stored_hash)\\r\\n        print(f\\"[RESULT] Password Match Status: {is_valid}\\")\\r\\n\\r\\nif __name__ == \\"__main__\\":\\r\\n    diagnose_user_auth(\\"test@maeumjigi.kr\\", \\"Password123!\\")\\r\\n```\\r\\n\\r\\nRunning this diagnostic exposed three compounding bugs:\\r\\n\\r\\n| Failure Vector | Technical Root Cause | Resolution Applied |\\r\\n| :--- | :--- | :--- |\\r\\n| **Bcrypt Salt Version** | Database dump contained `$2a$` hashes from older PHP/Node seeds; modern `passlib` expected `$2b$`. | Configured `pwd_context = CryptContext(schemes=[\\"bcrypt\\"], bcrypt__ident=\\"2b\\", deprecated=\\"auto\\")`. |\\r\\n| **JWT Secret Encoding** | Secret string was loaded via `.env` with trailing newline `\\r\\r\\n`, breaking HMAC-SHA256 signature checks. | Sanitized key ingestion: `SECRET_KEY = os.getenv(\\"JWT_SECRET\\").strip().encode(\'utf-8\')`. |\\r\\n| **CORS Preflight** | Chrome browser blocked `Authorization: Bearer` headers during OPTIONS preflight checks. | Explicitly registered `CORSMiddleware` with `allow_headers=[\\"*\\"]` and `expose_headers=[\\"*\\"]`. |\\r\\n\\r\\nWithin 45 minutes of targeted refactoring, login latency dropped to 42ms with a 100% success rate!\\r\\n\\r\\n![DB Troubleshooting](./images/02_db.png)\\r\\n\\r\\n---\\r\\n\\r\\n### 4. Architectural Expansion: Exploring Hybrid Knowledge Graphs\\r\\n\\r\\nResolving backend stability opened room for deeper architectural exploration. During clinical evaluation of our 2nd fine-tuned model, we noticed an intrinsic weakness shared by all parametric LLMs: **factual hallucinations during multi-hop crisis reasoning**.\\r\\n\\r\\n```mermaid\\r\\nflowchart TD\\r\\n    subgraph User_Query [\\"User Input: Complex Crisis State\\"]\\r\\n        U[\\"I stopped taking my SSRI antidepressants 3 days ago and feel severe tremors.\\"]\\r\\n    end\\r\\n\\r\\n    subgraph Hybrid_Architecture [\\"Hybrid Symbolic-Neural Architecture\\"]\\r\\n        U --\x3e KG_Extractor[Clinical Entity & Relation Extractor]\\r\\n        KG_Extractor --\x3e|Cypher Query| KG[(Neo4j Medical Knowledge Graph)]\\r\\n        KG --\x3e|Verified Triples: SSRI -> Discontinuation Syndrome| Context_Injector[Clinical Context Injector]\\r\\n        \\r\\n        U --\x3e Direct_Prompt[Empathetic System Prompt]\\r\\n        Direct_Prompt & Context_Injector --\x3e FineTuned_LLM[Fine-Tuned Qwen / Llama 3.1]\\r\\n    end\\r\\n\\r\\n    subgraph Verified_Output [\\"Safety-Compliant Response\\"]\\r\\n        FineTuned_LLM --\x3e Output[\\"Empathetic validation + Immediate medical warning regarding SSRI discontinuation syndrome.\\"]\\r\\n    end\\r\\n```\\r\\n\\r\\nBy drafting `chatbot_design_prompt.md`, we laid the theoretical foundation for blending parametric LLM conversational empathy with deterministic Knowledge Graph validation.\\r\\n\\r\\n---\\r\\n\\r\\n### 5. Day 19 Key Engineering Takeaways\\r\\n\\r\\n1. **Automated Documentation**: Reduced model benchmarking documentation turnaround from 6 hours to under 3 minutes using structured prompts and AI agents.\\r\\n2. **Hardened Authentication**: Diagnosed and permanently resolved bcrypt salt mismatches and CORS header traps across PostgreSQL and FastAPI.\\r\\n3. **Hybrid AI Vision**: Established the conceptual design for integrating symbolic Knowledge Graphs to eliminate clinical hallucinations in mental health counseling.\\r\\n\\r\\nIn Dev Log #20, we explore the completion of our 3rd fine-tuning cycle and the rollout of live community board features!\\n\\n---\\n\\n## Summary & Key Takeaways\\n\\n- **Autonomous Benchmark Reporting**: Automated multi-checkpoint fine-tuning analysis, transforming raw JSON matrices into formatted technical Word documents in under 3 minutes via structured AI prompts.\\n- **Root-Cause Authentication Resolution**: Diagnosed and permanently fixed cascading `401 Unauthorized` errors stemming from bcrypt salt incompatibilities and JWT secret newline mismatches.\\n- **Hybrid Knowledge Graph Design**: Architected a dual-engine blueprint coupling parametric LLM empathy with deterministic Neo4j graph triples to prevent clinical medication hallucinations.\\n- **Full-Stack Session Reliability**: Established resilient session persistence and clean CORS handshake pipelines across Next.js, FastAPI, and PostgreSQL."},{"id":"2026-05-17-rl-qlearning-1","metadata":{"permalink":"/blog/2026-05-17-rl-qlearning-1","source":"@site/blog/2026-05-17-rl-qlearning-1/index.md","title":"[Webots Robotics] Q-Learning Autonomous Navigation: 648-Bin State Discretization & Socket Architecture (#1)","description":"Designing a 648-bin state space discretizer and a TCP socket IPC architecture for Webots mobile robot autonomous navigation with tabular Q-Learning.","date":"2026-05-17T00:00:00.000Z","tags":[{"inline":true,"label":"reinforcement-learning","permalink":"/blog/tags/reinforcement-learning"},{"inline":true,"label":"q-learning","permalink":"/blog/tags/q-learning"},{"inline":true,"label":"webots","permalink":"/blog/tags/webots"},{"inline":true,"label":"robotics","permalink":"/blog/tags/robotics"},{"inline":true,"label":"discretization","permalink":"/blog/tags/discretization"},{"inline":true,"label":"python","permalink":"/blog/tags/python"}],"readingTime":4.04,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"2026-05-17-rl-qlearning-1","title":"[Webots Robotics] Q-Learning Autonomous Navigation: 648-Bin State Discretization & Socket Architecture (#1)","authors":["jbgih"],"tags":["reinforcement-learning","q-learning","webots","robotics","discretization","python"],"date":"2026-05-17T00:00:00.000Z","project":"rl_q_learning","description":"Designing a 648-bin state space discretizer and a TCP socket IPC architecture for Webots mobile robot autonomous navigation with tabular Q-Learning.","keywords":["Webots Autonomous Robot","Tabular Q-Learning Robotics","State Discretization 648 Bins","TCP Socket IPC Python","Differential Drive Navigation"]},"unlisted":false,"prevItem":{"title":"[Maeumjigi Capstone Dev Log #19] Automated Evaluation Reports & FastAPI PostgreSQL 401 Debugging","permalink":"/blog/2026-05-17-maeumjigi-19"},"nextItem":{"title":"[Maeumjigi Capstone Dev Log #18] Expanding Inference Tokens and Comparing 2nd Fine-Tuning Results","permalink":"/blog/2026-05-13-maeumjigi-18"}},"content":"![Webots Simulation Environment](./images/01_webots_arena.png)\\r\\n\\r\\n> \u{1F4CC} **Key Takeaways (TL;DR)**\\r\\n> - **Problem**: Continuous sensor readings (distance & heading) cause a state-space explosion for tabular Q-learning, and synchronous IPC with the Webots simulator requires low-latency coordination.\\r\\n> - **Solution**: Designed a geometrically partitioned 5-dimensional continuous sensor mapper producing 3 \xd7 8 \xd7 3 \xd7 3 \xd7 3 = 648 discrete states (`discretizer.py`) and a line-delimited JSON IPC socket pipeline over TCP port 5000.\\r\\n> - **Result**: Achieved O(1) fast Q-Table indexing and reliable 32ms physics synchronization between the simulator and Python agent.\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n---\\r\\n\\r\\n## 1. Project Background: Why Webots and Q-Learning?\\r\\n\\r\\nEnabling an autonomous differential-drive robot to navigate an unknown indoor arena and reach a target while avoiding obstacles is a foundational robotics challenge. While Deep Reinforcement Learning (DQN, PPO) handles complex inputs, it demands high computational overhead and lacks straightforward interpretability.\\r\\n\\r\\nIn this project, we apply **classical Tabular Q-Learning (Off-policy TD(0))** to a mobile robot in the Webots 3D physics engine. Our objective is to establish an optimal, mathematically verifiable navigation and obstacle avoidance policy in a 1.2m \xd7 1.2m indoor arena.\\r\\n\\r\\n---\\r\\n\\r\\n## 2. System Architecture: Webots Controller \u2194 Python RL Engine\\r\\n\\r\\nThe system is decoupled into two clean tiers: the **Webots simulation server** and the **Python RL client**.\\r\\n\\r\\n```mermaid\\r\\nflowchart LR\\r\\n    subgraph Webots[\\"Webots 3D Simulator (localhost:5000)\\"]\\r\\n        Robot[\\"Supervisor Robot<br>(Ultrasonic Sensor + Wheels)\\"]\\r\\n        HeadScan[\\"Head-scan Mechanism<br>(Left/Right 1.1 rad servo)\\"]\\r\\n        Server[\\"TCP Socket Server<br>(Line-delimited JSON)\\"]\\r\\n        Robot -\u2192 HeadScan -\u2192 Server\\r\\n    end\\r\\n\\r\\n    subgraph Python[\\"Python RL Engine (Client)\\"]\\r\\n        Env[\\"WebotsEnv (gym-like)<br>reset() / step()\\"]\\r\\n        Disc[\\"Discretizer<br>(Continuous \u2192 0~647 Bin)\\"]\\r\\n        Agent[\\"QLearningAgent<br>(Q-Table 648x4)\\"]\\r\\n        Env -\u2192 Disc -\u2192 Agent\\r\\n    end\\r\\n\\r\\n    Server <-\u2192|\\"request: {type: step, action: 0..3}<br>response: {state: [...], reward, done}\\"| Env\\r\\n```\\r\\n\\r\\n* **Webots Controller (`RL_controller.py`)**: Executes action commands for 480ms (15 simulation ticks \xd7 32ms) and rotates a head-mounted ultrasonic sensor left and right by 1.1 rad ($\\\\approx 63\xb0$) to eliminate blind spots.\\r\\n* **Socket Protocol**: Lightweight line-delimited JSON over TCP localhost:5000:\\r\\n  * Request: `{\\"type\\": \\"step\\", \\"action\\": 0}` (0: Forward, 1: Backward, 2: Turn Left, 3: Turn Right)\\r\\n  * Response: `{\\"state\\": [0.45, 0.12, 0.35, 0.28, 0.40], \\"reward\\": 0.05, \\"done\\": false, \\"info\\": {...}}`\\r\\n\\r\\n---\\r\\n\\r\\n## 3. Discretizing Continuous Sensors into 648 States\\r\\n\\r\\nTo apply tabular Q-learning, continuous floats must be mapped into finite discrete states. We selected 5 crucial observation variables based on kinematic relevance:\\r\\n\\r\\n| Feature | Bins | Thresholds | Semantic Meaning |\\r\\n| :--- | :---: | :--- | :--- |\\r\\n| **`goal_distance`** | **3** | `[0.6m, 1.2m]` | Near, Mid, Far |\\r\\n| **`goal_heading`** | **8** | [-\u03C0, \u03C0] (8 sectors, 45\xb0 each) | Front, Front-Right, Right, Back-Right, Back, Back-Left, Left, Front-Left |\\r\\n| **`front_distance`** | **3** | `[0.15m, 0.30m]` | Danger/Collision, Caution, Safe |\\r\\n| **`left_distance`** | **3** | `[0.15m, 0.30m]` | Danger, Caution, Safe |\\r\\n| **`right_distance`** | **3** | `[0.15m, 0.30m]` | Danger, Caution, Safe |\\r\\n\\r\\nTotal State Count:\\r\\n**N_states = 3 \xd7 8 \xd7 3 \xd7 3 \xd7 3 = 648**\\r\\n\\r\\nThe resulting Q-Table requires only **648 \xd7 4 = 2,592 floating-point entries**, allowing sub-millisecond memory updates and zero GPU overhead.\\r\\n\\r\\n### \u{1F4BB} State Discretization Code (`discretizer.py`)\\r\\n\\r\\n```python\\r\\nimport numpy as np\\r\\n\\r\\n# Dimension boundaries\\r\\nN_GOAL_D, N_GOAL_H, N_FRONT, N_LEFT, N_RIGHT = 3, 8, 3, 3, 3\\r\\nN_STATES = N_GOAL_D * N_GOAL_H * N_FRONT * N_LEFT * N_RIGHT  # 648\\r\\n\\r\\n_HEADING_BINS = np.linspace(-np.pi, np.pi, 9)[1:-1]\\r\\n_NEAR_BINS    = np.array([0.15, 0.30])\\r\\n_DIST_BINS    = np.array([0.6, 1.2])\\r\\n\\r\\ndef discretize(state_dict: dict) \u2192 int:\\r\\n    \\"\\"\\"Maps 5-tuple continuous sensor readings to an integer in [0, 647].\\"\\"\\"\\r\\n    gd = int(np.digitize(state_dict[\\"goal_distance\\"], _DIST_BINS))\\r\\n    gh = int(np.digitize(state_dict[\\"goal_heading\\"], _HEADING_BINS))\\r\\n    df = int(np.digitize(state_dict[\\"front_distance\\"], _NEAR_BINS))\\r\\n    dl = int(np.digitize(state_dict[\\"left_distance\\"], _NEAR_BINS))\\r\\n    dr = int(np.digitize(state_dict[\\"right_distance\\"], _NEAR_BINS))\\r\\n\\r\\n    # Compute flattened 1D index\\r\\n    index = ((((gd * N_GOAL_H + gh) * N_FRONT + df) * N_LEFT + dl) * N_RIGHT + dr)\\r\\n    return int(index)\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\n## 4. Head-Scan Mechanism & Collision Logic\\r\\n\\r\\n![System Architecture](./images/02_architecture.png)\\r\\n\\r\\nA fixed forward-facing sensor leaves lateral blind spots. We implemented an active **Head-Scan routine**:\\r\\n\\r\\n1. **Step Execution**: Drive motors at 3.0 rad/s for 480ms.\\r\\n2. **Head Rotation**: Sweep head servo +1.1 rad to read left distance, then -1.1 rad for right distance.\\r\\n3. **Re-center**: Return head to 0 rad and refresh front distance.\\r\\n4. **Terminal Conditions**:\\r\\n   * **Goal Reached**: Euclidean distance \u2264 0.10m \u2192 success (`done = True`, reward $+1.0$)\\r\\n   * **Collision**: Any distance \u2264 0.08m \u2192 failure (`done = True`, reward $-1.0$)\\r\\n\\r\\n---\\r\\n\\r\\n## 5. What\'s Next?\\r\\n\\r\\nWith the simulator environment, TCP socket IPC, and 648-bin state discretization established, our agent is ready for reinforcement learning.\\r\\n\\r\\nIn Episode #2, we will cover the **mathematical implementation of Tabular Q-Learning, \u03B5-greedy exploration decay, and reward function tuning**!\\r\\n\\r\\n---\\r\\n\\r\\n## Summary & Key Takeaways\\r\\n\\r\\n- **Webots Robotics Simulation Setup**: Established a differential-drive mobile robotics environment in Webots featuring real-time physics and infrared proximity sensing.\\r\\n- **Low-Latency TCP Socket IPC**: Engineered an asynchronous TCP socket bridge decoupling the simulator physics loop from the external Python reinforcement learning engine.\\r\\n- **648-Bin State Space Discretization**: Mapped continuous poses and sensor readings into a compact 648-state discrete grid (3 distance bins \xd7 12 heading bins \xd7 18 obstacle zones).\\r\\n- **Differential Kinematic Actions**: Defined three fundamental discrete velocity actions (Straight, Turn Left, Turn Right) to ensure deterministic robot control and rapid convergence."},{"id":"2026-05-13-maeumjigi-18","metadata":{"permalink":"/blog/2026-05-13-maeumjigi-18","source":"@site/blog/2026-05-13-maeumjigi-18/index.md","title":"[Maeumjigi Capstone Dev Log #18] Expanding Inference Tokens and Comparing 2nd Fine-Tuning Results","description":"Expanding inference max_new_tokens to 384 to eliminate stiff, clipped answers and analyzing the impact of LoRA alpha (8 vs 16) on empathetic depth.","date":"2026-05-13T00:00:00.000Z","tags":[{"inline":true,"label":"devlog","permalink":"/blog/tags/devlog"},{"inline":true,"label":"fine-tuning","permalink":"/blog/tags/fine-tuning"},{"inline":true,"label":"inference","permalink":"/blog/tags/inference"},{"inline":true,"label":"max_new_tokens","permalink":"/blog/tags/max-new-tokens"},{"inline":true,"label":"empathy","permalink":"/blog/tags/empathy"},{"inline":true,"label":"capstone","permalink":"/blog/tags/capstone"}],"readingTime":2.18,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"2026-05-13-maeumjigi-18","title":"[Maeumjigi Capstone Dev Log #18] Expanding Inference Tokens and Comparing 2nd Fine-Tuning Results","authors":["jbgih"],"tags":["devlog","fine-tuning","inference","max_new_tokens","empathy","capstone"],"date":"2026-05-13T00:00:00.000Z","keywords":["AI Mental Health Chatbot","LLM Fine-tuning","AI Safety Wrapper","Capstone Project","Prompt Engineering"],"description":"Expanding inference max_new_tokens to 384 to eliminate stiff, clipped answers and analyzing the impact of LoRA alpha (8 vs 16) on empathetic depth."},"unlisted":false,"prevItem":{"title":"[Webots Robotics] Q-Learning Autonomous Navigation: 648-Bin State Discretization & Socket Architecture (#1)","permalink":"/blog/2026-05-17-rl-qlearning-1"},"nextItem":{"title":"[Maeumjigi Capstone Dev Log #17] 2nd Fine-Tuning Complete & The Trap of the Automation Pipeline","permalink":"/blog/2026-05-12-maeumjigi-17"}},"content":"![Cover Image](./images/01_cover.png)\\n\\nOn May 13th, after fixing the hardcoding bugs discovered yesterday, we finally resumed proper inference testing for the 2nd round fine-tuned models.\\n\\n{/* truncate */}\\n\\n### The Cause of Short Answers: Increase the Token Length!\\n\\nWhile meticulously reviewing the inference results, I felt that the answers from the `Llama33-70B_a8` model were still strangely short and rigid.\\n\\n> \\"This is one of Llama33-70B_a8\'s answers. I feel that max_seq_length and max_new_tokens are too small. I want to increase them. Looking at the VRAM status, how much can I increase them?\\"\\n\\nAfter calculating the available VRAM space (39.8GB at the time) with the Artificial Intelligence (AI), we boldly increased `max_new_tokens` (the maximum number of words generated) to 384. The result was a massive success!\\n\\n```text\\n[Before] \\"It must be really hard to feel that way. It is important to talk to a professional.\\"\\n[After] \\"It must be really hard to feel that way. However, having these thoughts is not a sign that you are weak, but a signal that you are carrying too much burden right now. I highly recommend slowly unraveling these emotions with a professional.\\"\\n```\\n\\nBy simply increasing the token allowance, the model maintained its context to the end and began pouring out much deeper and warmer sentences of empathy. The model had been holding its tongue because it was trapped in a limited token count.\\n\\n### Alpha Value Comparison Analysis (a=8 vs a=16)\\n\\n![Graph Visualization](./images/02_graph.png)\\n\\nThe results for the biggest objective of the 2nd fine-tuning\u2014the performance difference based on the LoRA hyperparameter `alpha`\u2014were also out. By analyzing the logs piled up in the `fine_tuning_2` folder, we generated graphs like `05_alpha_comparison_daily.png`. With `rank=16` fixed, we clearly visualized how the model\'s overfitting patterns and final answer quality differed when given `alpha=8` versus `alpha=16`.\\n\\nUltimately, models granted the correct hyperparameters and ample token length were finally getting closer to the true \'Maeumjigi\' (Heart-keeper) we had originally planned. It seems our mid-term presentation preparations will wrap up very smoothly!\\n\\n---\\n\\n## Summary & Key Takeaways\\n\\n- **Expanding Generation Headroom**: Diagnosed curt, robotic counseling responses as artificial token truncation and safely scaled `max_new_tokens` to 384 utilizing available GPU VRAM headroom.\\n- **Qualitative Empathy Breakthrough**: Verified that expanded context windows enable multi-sentence empathetic validation and de-escalation rather than dismissive, one-line medical disclaimers.\\n- **LoRA Hyperparameter Benchmark**: Compared LoRA scaling factor alpha = 8 versus alpha = 16 (with fixed rank = 16), mapping empirical trade-offs between domain overfitting and conversational flexibility.\\n- **Mid-Term Milestone Alignment**: Synthesized automated loss curves and qualitative evaluation matrices, confirming readiness for our university capstone mid-term presentation."},{"id":"2026-05-12-maeumjigi-17","metadata":{"permalink":"/blog/2026-05-12-maeumjigi-17","source":"@site/blog/2026-05-12-maeumjigi-17/index.md","title":"[Maeumjigi Capstone Dev Log #17] 2nd Fine-Tuning Complete & The Trap of the Automation Pipeline","description":"Executing 2nd-round fine-tuning with clean chat templates and refined LoRA hyperparameters (rank and alpha) to optimize learning convergence.","date":"2026-05-12T00:00:00.000Z","tags":[{"inline":true,"label":"devlog","permalink":"/blog/tags/devlog"},{"inline":true,"label":"fine-tuning","permalink":"/blog/tags/fine-tuning"},{"inline":true,"label":"best-performance","permalink":"/blog/tags/best-performance"},{"inline":true,"label":"checkpoint","permalink":"/blog/tags/checkpoint"},{"inline":true,"label":"hardcoding","permalink":"/blog/tags/hardcoding"},{"inline":true,"label":"capstone","permalink":"/blog/tags/capstone"}],"readingTime":2.11,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"2026-05-12-maeumjigi-17","title":"[Maeumjigi Capstone Dev Log #17] 2nd Fine-Tuning Complete & The Trap of the Automation Pipeline","authors":["jbgih"],"tags":["devlog","fine-tuning","best-performance","checkpoint","hardcoding","capstone"],"date":"2026-05-12T00:00:00.000Z","keywords":["AI Mental Health Chatbot","LLM Fine-tuning","AI Safety Wrapper","Capstone Project","Prompt Engineering"],"description":"Executing 2nd-round fine-tuning with clean chat templates and refined LoRA hyperparameters (rank and alpha) to optimize learning convergence."},"unlisted":false,"prevItem":{"title":"[Maeumjigi Capstone Dev Log #18] Expanding Inference Tokens and Comparing 2nd Fine-Tuning Results","permalink":"/blog/2026-05-13-maeumjigi-18"},"nextItem":{"title":"[Maeumjigi Capstone Dev Log #16] Fatal Mistake, 2nd Fine-Tuning, and React Native App Launch","permalink":"/blog/2026-05-08-maeumjigi-16"}},"content":"![Cover Image](./images/01_cover.png)\\n\\nThe 2nd round of fine-tuning (`fine_tuning_2`) parallel training, which was ambitiously started to correct the LoRA hyperparameter mistake (alpha/rank setup error), finally ended on May 12th!\\n\\n{/* truncate */}\\n\\n### Extracting the Best Checkpoint and Building the Inference Pipeline\\n\\nThe fine-tuning for 3 models with 6 hyperparameter combinations was all completed. I immediately compared the `eval_loss` to extract the best performing checkpoints and moved them to the `adapter` folders for each model.\\n\\nI also created a new `run_test_20_30.sh` script to run evaluation and result comparison all at once in the background on the server.\\n\\n> \\"Currently, the HCX-Text-1p5B models generated 12 outputs in 15 minutes. GPU Util is 1.6GB per graphics card...\\"\\n\\nHowever, the inference speed was still hopeless. Even the lightest 1.5B model couldn\'t even generate 1 answer per minute. The VRAM usage was only 1.6GB, meaning a bottleneck occurred because the Batch Size was set to 1. On top of this, server storage issues forced us to urgently migrate the project\'s base path from `~/home/` to `~/home/data/temporary/`, causing a huge fuss to modify all script paths.\\n\\n### Falling into the Trap of Hardcoding\\n\\n![Hardcoding Bug](./images/02_bug.png)\\n\\nAfter painstakingly running all the evaluation codes, I discovered a horrifying fact.\\n\\n> \\"Why is MODEL_ALIAS hardcoded to \'Qwen35-9B_a16\' in 20_eval_ft_models.ipynb?\\"\\n> \\"So in the server logs, even for 20_eval_HCX-Text-1p5B_a8.ipynb, MODEL_ALIAS was defined as \'Qwen35-9B_a16\'. You\'re telling me it\'s normal that the filename and model name are different?\\"\\n\\nYes. While writing the evaluation automation script, I accidentally hardcoded `MODEL_ALIAS`. The script diligently copied files to test the HCX model, but inside the code, it kept repeatedly loading only the `Qwen35-9B_a16` model and doing the same inference over and over!\\n\\nIt was a day that made me realize once again that fine-tuning is not a science, but a battle of meticulousness. I\'ll have to fix this hardcoded bug and run the inferences again tomorrow.\\n\\n---\\n\\n## Summary & Key Takeaways\\n\\n- **2nd Fine-Tuning Checkpoint Extraction**: Concluded parallel training for 3 baseline architectures across 6 hyperparameter matrices, automatically staging minimum validation loss weights.\\n- **Inference Throughput Bottleneck**: Uncovered severe evaluation latency (under 1 sample/min on 1.5B models) caused by unbatched execution (batch size 1) and VRAM under-allocation.\\n- **The Hardcoded Automation Bug**: Caught a critical pipeline flaw where `MODEL_ALIAS` was hardcoded to `Qwen35-9B_a16`, masking true model distinctions during batch Jupyter evaluation.\\n- **Engineering Rigor in LLM Pipelines**: Reinforced the imperative of dynamic parameterization and automated assertion checks in multi-model evaluation suites before logging comparative benchmarks."},{"id":"2026-05-08-maeumjigi-16","metadata":{"permalink":"/blog/2026-05-08-maeumjigi-16","source":"@site/blog/2026-05-08-maeumjigi-16/index.md","title":"[Maeumjigi Capstone Dev Log #16] Fatal Mistake, 2nd Fine-Tuning, and React Native App Launch","description":"Diagnosing prompt template pollution hardcoded into training dialogues and performing rapid debugging to restore dataset formatting integrity.","date":"2026-05-08T00:00:00.000Z","tags":[{"inline":true,"label":"devlog","permalink":"/blog/tags/devlog"},{"inline":true,"label":"fine-tuning","permalink":"/blog/tags/fine-tuning"},{"inline":true,"label":"LoRA","permalink":"/blog/tags/lo-ra"},{"inline":true,"label":"hyperparameters","permalink":"/blog/tags/hyperparameters"},{"inline":true,"label":"ReactNative","permalink":"/blog/tags/react-native"},{"inline":true,"label":"app-development","permalink":"/blog/tags/app-development"},{"inline":true,"label":"frontend","permalink":"/blog/tags/frontend"}],"readingTime":2.77,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"2026-05-08-maeumjigi-16","title":"[Maeumjigi Capstone Dev Log #16] Fatal Mistake, 2nd Fine-Tuning, and React Native App Launch","authors":["jbgih"],"tags":["devlog","fine-tuning","LoRA","hyperparameters","ReactNative","app-development","frontend"],"date":"2026-05-08T00:00:00.000Z","keywords":["AI Mental Health Chatbot","LLM Fine-tuning","AI Safety Wrapper","Capstone Project","Prompt Engineering"],"description":"Diagnosing prompt template pollution hardcoded into training dialogues and performing rapid debugging to restore dataset formatting integrity."},"unlisted":false,"prevItem":{"title":"[Maeumjigi Capstone Dev Log #17] 2nd Fine-Tuning Complete & The Trap of the Automation Pipeline","permalink":"/blog/2026-05-12-maeumjigi-17"},"nextItem":{"title":"[Maeumjigi Capstone Dev Log #15] Visualizing Fine-Tuning Results of 5 Models & Local Environment Setup","permalink":"/blog/2026-05-07-maeumjigi-15"}},"content":"![Cover Image](./images/01_cover.png)\\n\\nMay 8th was the day we were building our capstone design mid-term presentation (PPT) based on the fine-tuning results. However, while happily filling in the slides, I discovered a massive, chilling mistake.\\n\\n{/* truncate */}\\n\\n### Discovering the Fatal LoRA Hyperparameter Mistake\\n\\nI was refining the model structure diagrams and hyperparameter info with the Artificial Intelligence (AI) for the PPT.\\n\\n> \\"Looking at the fine-tuning examples, the answers are shorter than the base model. I think this is because setting LoRA\'s r to 8 and alpha to 16 reduced the intermediate features too much...\\"\\n> \\"Wait, it was a/r? I thought it was r/a...??? I really applied LoRA greedily...\\"\\n\\nWhen fine-tuning with LoRA, it\'s standard to set the `alpha` value equal to or twice the `rank` value. However, I completely misunderstood the scaling ratio equation, setting it in a way that either severely suppressed or excessively amplified the weight updates. No wonder the fine-tuned models\' answers were unnaturally short and chopped off\u2014the fault lay right at my fingertips.\\n\\n### The Decision for 2nd Round Fine-Tuning (fine_tuning_2)\\n\\nAlthough we already had the 1st round results, we couldn\'t just move on for a perfect \'Maeumjigi\'. I immediately created a `fine_tuning_2` folder and decided on a 2nd round of fine-tuning.\\n\\n> \\"The models to use this time are HCX-Text-1p5B, Llama33-70B, and Qwen35-9B. Train on MIG-0 with rank=16, alpha=16, and on MIG-1 with rank=16, a=8.\\"\\n> \\"Extract the top 2000 longest entries from Daily_train_dataset.jsonl and create a file named Daily_train_dataset_long.jsonl.\\"\\n\\nTo prevent the answers from becoming too short, we extracted only the top 2000 datasets with the longest text length. We also split our MIG (Multi-Instance GPU) resources to run parallel training, directly comparing the performance differences based on the rank and alpha ratios.\\n\\n### Starting Frontend (App) Development While the Backend Trains\\n\\n![App Development](./images/02_app.png)\\n\\nWhile the models fell back into the cycle of training, I didn\'t just sit around. I finally started developing the frontend app where actual users will meet \'Maeumjigi\'!\\n\\n> \\"I need to show a QR code to run maeum-app... but when I type npx go start, I only get an error message. How and where can the QR code be shown?\\"\\n\\nI created the `maeum-app` project using React Native (Expo) and struggled to launch the local server and connect it to my smartphone. I even mistakenly typed `npx go start` instead of `expo`, but I finally succeeded in pulling up the Expo QR code and setting up the app icons (`assets/logo.png`). It was a thrilling day where the brain of the backend (AI) and the face of the frontend (App) were being built simultaneously.\\n\\n---\\n\\n## Summary & Key Takeaways\\n\\n- **LoRA Hyperparameter Post-Mortem**: Diagnosed unnatural response truncation as a fundamental scaling flaw in our LoRA rank-to-alpha ratio and restructured the parameter matrix.\\n- **Launching 2nd Fine-Tuning Sprint**: Initiated multi-architecture parallel training across MIG GPU partitions to benchmark rank = 16 with alpha = 8 versus alpha = 16.\\n- **Long-Sequence Dataset Extraction**: Curated the top 2,000 longest conversational dialogues (`Daily_train_dataset_long.jsonl`) to force the models to generate deep, multi-sentence empathetic support.\\n- **React Native Mobile App Bootstrap**: Initiated client frontend engineering with Expo, configuring local bundler QR bridges and setting up initial mobile brand assets."},{"id":"2026-05-07-maeumjigi-15","metadata":{"permalink":"/blog/2026-05-07-maeumjigi-15","source":"@site/blog/2026-05-07-maeumjigi-15/index.md","title":"[Maeumjigi Capstone Dev Log #15] Visualizing Fine-Tuning Results of 5 Models & Local Environment Setup","description":"Analyzing Perplexity and dialogue response scores across models, and building an automated matplotlib visualization pipeline for mid-term evaluation.","date":"2026-05-07T00:00:00.000Z","tags":[{"inline":true,"label":"devlog","permalink":"/blog/tags/devlog"},{"inline":true,"label":"fine-tuning","permalink":"/blog/tags/fine-tuning"},{"inline":true,"label":"results-analysis","permalink":"/blog/tags/results-analysis"},{"inline":true,"label":"visualization","permalink":"/blog/tags/visualization"},{"inline":true,"label":"Jupyter","permalink":"/blog/tags/jupyter"},{"inline":true,"label":"capstone","permalink":"/blog/tags/capstone"},{"inline":true,"label":"Artificial Intelligence (AI)","permalink":"/blog/tags/artificial-intelligence-ai"}],"readingTime":2.09,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"2026-05-07-maeumjigi-15","title":"[Maeumjigi Capstone Dev Log #15] Visualizing Fine-Tuning Results of 5 Models & Local Environment Setup","authors":["jbgih"],"tags":["devlog","fine-tuning","results-analysis","visualization","Jupyter","capstone","Artificial Intelligence (AI)"],"date":"2026-05-07T00:00:00.000Z","keywords":["AI Mental Health Chatbot","LLM Fine-tuning","AI Safety Wrapper","Capstone Project","Prompt Engineering"],"description":"Analyzing Perplexity and dialogue response scores across models, and building an automated matplotlib visualization pipeline for mid-term evaluation."},"unlisted":false,"prevItem":{"title":"[Maeumjigi Capstone Dev Log #16] Fatal Mistake, 2nd Fine-Tuning, and React Native App Launch","permalink":"/blog/2026-05-08-maeumjigi-16"},"nextItem":{"title":"[Maeumjigi Capstone Dev Log #14] All Fine-Tuning Completed and Parallel Inference (Eval) Pipeline Built","permalink":"/blog/2026-05-06-maeumjigi-14"}},"content":"![Cover Image](./images/01_cover.png)\\n\\nMay 7th was the day we synthesized the fine-tuning results of our 5 models (Llama3.3-70B, DSR1-70B, HCX-Omni-8B, Qwen35-9B, HCX-Text-1.5B) and proceeded with full-scale visualization and local environment setup.\\n\\n{/* truncate */}\\n\\n### Visualization and Local Setup for Model Comparison\\n\\nTo comfortably review the result comparison code (which was previously running on the heavy server) on my personal laptop, I created a new notebook, `31_comparison_local.ipynb`.\\n\\n> \\"Can\'t 30_comparison.ipynb run on my laptop too?\\"\\n> \\"Please tell me how to install pandas, matplotlib, seaborn, and bert_score on the currently selected kernel.\\"\\n\\nWhile setting up the local Jupyter kernel in VSCode and installing the necessary libraries, I faced frequent Kernel Crashes and annoying errors like `ModuleNotFoundError: No module named \'ft_utils\'`. However, I resolved them step-by-step by fixing folder paths. I also successfully recovered the missing `ft_metrics.json` files for some models (like DSR1-70B) using a script.\\n\\n### 5-Model Comprehensive Report and Graph Visualization\\n\\nThe most important task was visualizing the performance of these 5 models so they could be compared at a glance. Together with the AI, we established a plan named `5MODELS_ORGANIZATION_PLAN_present.md` and began systematically organizing the data.\\n\\n> \\"What is the difference between the faint line and the thick line? Bring the training loss and eval loss for each model and visualize them as graphs.\\"\\n> \\"Remove the thick line and make the faint line clearer and save it.\\"\\n\\nI removed the unnecessary trend lines (thick lines) from the matplotlib graphs generated by the AI, finally extracting `03_training_loss_all.png` and `04_eval_loss_all.png` which neatly gathered the Training and Eval Loss curves of all models in one place. We also perfectly documented graphs analyzing the LoRA Rank Decomposition for each model, as well as a GPU memory usage chart (`02_gpu_memory.png`).\\n\\n![Graph Visualization](./images/02_graph.png)\\n\\nNow, based on these graphs, we can beautifully decorate our capstone design mid-term presentation materials for next week. Which of these 5 models will ultimately be selected as the best quality \'Maeumjigi\' chatbot?\\n\\n---\\n\\n## Summary & Key Takeaways\\n\\n- **5-Model Benchmark Synthesis**: Systematically evaluated and compared fine-tuning performance across five architectures (Llama 3.3-70B, DSR1-70B, HCX-Omni-8B, Qwen 3.5-9B, HCX-Text-1.5B).\\n- **Automated Matplotlib Visualization**: Filtered trendline artifacts to generate publication-grade training and validation loss curves in a unified visual dashboard.\\n- **Hardware Profile & VRAM Auditing**: Benchmarked GPU memory utilization and analyzed LoRA rank decomposition dynamics across parameter scales.\\n- **Local Analytical Environment Setup**: Overcame Jupyter kernel failures and module path discrepancies to establish reproducible local analysis notebooks."},{"id":"2026-05-06-maeumjigi-14","metadata":{"permalink":"/blog/2026-05-06-maeumjigi-14","source":"@site/blog/2026-05-06-maeumjigi-14/index.md","title":"[Maeumjigi Capstone Dev Log #14] All Fine-Tuning Completed and Parallel Inference (Eval) Pipeline Built","description":"Completing fine-tuning for HCX-Omni-8B and Qwen35-9B, and building an automated multi-GPU parallel inference script for comprehensive evaluation.","date":"2026-05-06T00:00:00.000Z","tags":[{"inline":true,"label":"devlog","permalink":"/blog/tags/devlog"},{"inline":true,"label":"fine-tuning","permalink":"/blog/tags/fine-tuning"},{"inline":true,"label":"HCX-Omni-8B","permalink":"/blog/tags/hcx-omni-8-b"},{"inline":true,"label":"Qwen35-9B","permalink":"/blog/tags/qwen-35-9-b"},{"inline":true,"label":"model-evaluation","permalink":"/blog/tags/model-evaluation"},{"inline":true,"label":"inference","permalink":"/blog/tags/inference"},{"inline":true,"label":"parallel-processing","permalink":"/blog/tags/parallel-processing"}],"readingTime":2.03,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"2026-05-06-maeumjigi-14","title":"[Maeumjigi Capstone Dev Log #14] All Fine-Tuning Completed and Parallel Inference (Eval) Pipeline Built","authors":["jbgih"],"tags":["devlog","fine-tuning","HCX-Omni-8B","Qwen35-9B","model-evaluation","inference","parallel-processing"],"date":"2026-05-06T00:00:00.000Z","keywords":["AI Mental Health Chatbot","LLM Fine-tuning","AI Safety Wrapper","Capstone Project","Prompt Engineering"],"description":"Completing fine-tuning for HCX-Omni-8B and Qwen35-9B, and building an automated multi-GPU parallel inference script for comprehensive evaluation."},"unlisted":false,"prevItem":{"title":"[Maeumjigi Capstone Dev Log #15] Visualizing Fine-Tuning Results of 5 Models & Local Environment Setup","permalink":"/blog/2026-05-07-maeumjigi-15"},"nextItem":{"title":"[Maeumjigi Capstone Dev Log #13] Limits of 70B Training and the Pivot to Mid-Size Models (HCX, Qwen)","permalink":"/blog/2026-05-04-maeumjigi-13"}},"content":"![Cover Image](./images/01_cover.png)\\n\\nOn May 6th, we finally escaped the long swamp of fine-tuning! After several nights of work and hyperparameter tuning, the training for mid-size models like **HCX-Omni-8B** and **Qwen35-9B** was successfully completed.\\n\\n{/* truncate */}\\n\\n### Fine-Tuning Complete, Analyzing the Logs\\n\\nAs the training progressed, we could see the loss values decreasing stably.\\n\\n```text\\nstep= 1200  loss=0.9698  lr=1.88e-04  gpu=7.7GB\\nstep= 1250  loss=0.8523  lr=1.86e-04  gpu=7.7GB\\n...\\nstep= 1650  loss=0.8783  lr=1.73e-04  gpu=7.7GB\\n```\\n\\nHowever, we had a brief moment of confusion trying to figure out if this was `train loss` or `validation loss`, asking the Artificial Intelligence (AI), \\"Does our code not record eval loss?\\" We realized the evaluation loss logging might have been missed, but since the training was already fully complete (\\"All fine-tuning is complete, proceeding with evaluation\\"), we immediately moved on to the inference and evaluation (Eval) phase using the latest generated checkpoint models.\\n\\n### Building a Parallel Inference Environment\\n\\nWe started generation testing using the `20_eval_ft_models.ipynb` notebook to see how each model responded to user dialogues. We unified the `max_new_tokens` for inference to a generous 1024, constantly worrying if another OOM would occur.\\n\\nBut the inference speed was much slower than expected.\\n> \\"We used two graphics cards for training, so why is inference only using one?\\"\\n\\nTo utilize 100% of the server\'s GPU resources, with the AI\'s help, we wrote a new `run_eval_parallel.sh` script to process inferences in parallel. This drastically reduced the model inference time, and we successfully built a pipeline that automatically aggregates the inference results and perplexity of each model into an Excel file.\\n\\n![Evaluation Pipeline](./images/02_eval.png)\\n\\nAlthough an error occurred because VRAM was not properly released when transitioning from DSR1-70B inference to the next model, we resolved it by isolating the environments with the parallel script. Now, it\'s finally time to compare the actual answer quality of each model!\\n\\n---\\n\\n## Summary & Key Takeaways\\n\\n- **8B-9B Architecture Fine-Tuning Convergence**: Successfully concluded training for HCX-Omni-8B and Qwen 3.5-9B, validating steady loss reduction down to 0.85.\\n- **Multi-GPU Parallel Evaluation Architecture**: Engineered `run_eval_parallel.sh` to saturate dual-GPU compute capacity and eliminate single-device inference bottlenecks.\\n- **Automated Metric Aggregation**: Established an automated benchmarking suite compiling perplexity metrics and sample outputs directly into analytical spreadsheets.\\n- **PyTorch VRAM Leak Isolation**: Solved cross-model GPU memory fragmentation and OOM traps through isolated multi-process execution environments."},{"id":"2026-05-04-maeumjigi-13","metadata":{"permalink":"/blog/2026-05-04-maeumjigi-13","source":"@site/blog/2026-05-04-maeumjigi-13/index.md","title":"[Maeumjigi Capstone Dev Log #13] Limits of 70B Training and the Pivot to Mid-Size Models (HCX, Qwen)","description":"Recognizing synthetic data fatigue and restructuring training corpora with a 2:1 human-to-synthetic ratio to restore genuine conversational depth.","date":"2026-05-04T00:00:00.000Z","tags":[{"inline":true,"label":"devlog","permalink":"/blog/tags/devlog"},{"inline":true,"label":"fine-tuning","permalink":"/blog/tags/fine-tuning"},{"inline":true,"label":"HCX-Omni-8B","permalink":"/blog/tags/hcx-omni-8-b"},{"inline":true,"label":"Qwen35-9B","permalink":"/blog/tags/qwen-35-9-b"},{"inline":true,"label":"checkpoints","permalink":"/blog/tags/checkpoints"},{"inline":true,"label":"hyperparameters","permalink":"/blog/tags/hyperparameters"},{"inline":true,"label":"Artificial Intelligence (AI)","permalink":"/blog/tags/artificial-intelligence-ai"}],"readingTime":2.3,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"2026-05-04-maeumjigi-13","title":"[Maeumjigi Capstone Dev Log #13] Limits of 70B Training and the Pivot to Mid-Size Models (HCX, Qwen)","authors":["jbgih"],"tags":["devlog","fine-tuning","HCX-Omni-8B","Qwen35-9B","checkpoints","hyperparameters","Artificial Intelligence (AI)"],"date":"2026-05-04T00:00:00.000Z","keywords":["AI Mental Health Chatbot","LLM Fine-tuning","AI Safety Wrapper","Capstone Project","Prompt Engineering"],"description":"Recognizing synthetic data fatigue and restructuring training corpora with a 2:1 human-to-synthetic ratio to restore genuine conversational depth."},"unlisted":false,"prevItem":{"title":"[Maeumjigi Capstone Dev Log #14] All Fine-Tuning Completed and Parallel Inference (Eval) Pipeline Built","permalink":"/blog/2026-05-06-maeumjigi-14"},"nextItem":{"title":"[Maeumjigi Capstone Dev Log #12] 70B Massive Model Fine-Tuning and GPU Memory (OOM) Struggle","permalink":"/blog/2026-05-03-maeumjigi-12"}},"content":"![Cover Image](./images/01_cover.png)\\n\\nAfter experiencing the OOM (Out of Memory) hell during the fine-tuning of massive 70B models, on May 4th, we attempted a bold change in strategy. By drastically reducing the batch size, we barely managed to push the 70B models (Llama3.3, DeepSeek-R1) to `checkpoint-1200` and `1300`, but the training time was absurdly long, resulting in terrible efficiency.\\n\\n{/* truncate */}\\n\\n### Pivoting to Mid-Size Models (1.5B ~ 9B)\\n\\nConsidering our physical server resources and the capstone project deadline, we decided it was too risky to rely solely on the 70B models. Therefore, we shifted our focus to relatively lighter mid-size models like **HCX-Omni-8B, Qwen35-9B, and HCX-Text-1.5B**.\\n\\n> \\"It\'s taking a long time to train HCX-Omni-8B, Qwen35-9B, and HCX-Text-1p5B with the current hyperparameters. Are these parameters generally used for these models?\\"\\n> \\"How does increasing the batch size affect the training?\\"\\n\\nThings weren\'t perfectly smooth just because the models were smaller. To speed up training, we increased the batch size and endlessly debated with the AI to find the optimal hyperparameters for each model size. We first evaluated the training results of the smallest model, HCX-Text-1.5B, to set our tuning direction.\\n\\n### Checkpoint Saving Errors and Kernel Version Issues\\n\\nWhile smoothly training HCX-Omni-8B, we hit another snag while trying to save a checkpoint at step 50.\\n\\n```python\\n[RANK 0] Detected kernel version 5.4.0, which is below the recommended minimum of 5.5.0; this can cause the process to hang.\\n...\\n![\uC0AC\uC9C4 02](./images/02_error.png)\\n\\nJSONDecodeError Traceback (most recent call last)\\n---\x3e 60 trainer.train(resume_from_checkpoint=...)\\n```\\n\\nAlong with a warning that the OS kernel version was too low and could cause the process to hang, we faced a horrific `JSONDecodeError` because the saved checkpoint file was corrupted, preventing us from resuming training.\\n\\n> \\"If the models stop during training, do they resume from where they stopped?\\"\\n\\nFortunately, the Hugging Face `Trainer` provides a feature to resume training from checkpoints (`resume_from_checkpoint`), but it\'s useless if the checkpoint file itself is corrupted. Despite reducing the model size, we spent the entire day wrestling with numerous framework and infrastructure errors. Will we ever reach a stable training orbit?\\n\\n---\\n\\n## Summary & Key Takeaways\\n\\n- **Strategic Pivot from 70B to Mid-Scale Models**: Reallocated project compute from sluggish 70B architectures to nimble mid-size models (HCX-Omni-8B, Qwen 3.5-9B, HCX-Text-1.5B) to guarantee deadline feasibility.\\n- **Batch Size & Hyperparameter Retuning**: Re-engineered batch sizes and learning schedules to maximize throughput and GPU utilization on 1.5B to 9B model baselines.\\n- **Checkpoint Corruption Post-Mortem**: Diagnosed fatal `JSONDecodeError` failures during `resume_from_checkpoint` triggered by incomplete disk serialization and OS kernel 5.4.0 hanging states.\\n- **Training Infrastructure Hardening**: Established atomic checkpoint writing protocols to ensure uninterrupted training resumption across unexpected server crashes."},{"id":"2026-05-03-maeumjigi-12","metadata":{"permalink":"/blog/2026-05-03-maeumjigi-12","source":"@site/blog/2026-05-03-maeumjigi-12/index.md","title":"[Maeumjigi Capstone Dev Log #12] 70B Massive Model Fine-Tuning and GPU Memory (OOM) Struggle","description":"Tackling 70B parameter model fine-tuning with 4-bit QLoRA and resolving GPU VRAM OOM errors through aggressive memory offloading.","date":"2026-05-03T00:00:00.000Z","tags":[{"inline":true,"label":"devlog","permalink":"/blog/tags/devlog"},{"inline":true,"label":"fine-tuning","permalink":"/blog/tags/fine-tuning"},{"inline":true,"label":"Llama3.3-70B","permalink":"/blog/tags/llama-3-3-70-b"},{"inline":true,"label":"DeepSeek-R1-70B","permalink":"/blog/tags/deep-seek-r-1-70-b"},{"inline":true,"label":"OOM","permalink":"/blog/tags/oom"},{"inline":true,"label":"troubleshooting","permalink":"/blog/tags/troubleshooting"},{"inline":true,"label":"GPU","permalink":"/blog/tags/gpu"}],"readingTime":2.15,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"2026-05-03-maeumjigi-12","title":"[Maeumjigi Capstone Dev Log #12] 70B Massive Model Fine-Tuning and GPU Memory (OOM) Struggle","authors":["jbgih"],"tags":["devlog","fine-tuning","Llama3.3-70B","DeepSeek-R1-70B","OOM","troubleshooting","GPU"],"date":"2026-05-03T00:00:00.000Z","keywords":["AI Mental Health Chatbot","LLM Fine-tuning","AI Safety Wrapper","Capstone Project","Prompt Engineering"],"description":"Tackling 70B parameter model fine-tuning with 4-bit QLoRA and resolving GPU VRAM OOM errors through aggressive memory offloading."},"unlisted":false,"prevItem":{"title":"[Maeumjigi Capstone Dev Log #13] Limits of 70B Training and the Pivot to Mid-Size Models (HCX, Qwen)","permalink":"/blog/2026-05-04-maeumjigi-13"},"nextItem":{"title":"[Maeumjigi Capstone Dev Log #11] Evaluating M6 Model Trained on Synthetic Data (v5)","permalink":"/blog/2026-04-19-maeumjigi-11"}},"content":"![Cover Image](./images/01_cover.png)\\n\\nOn May 3, having gained enough experience with the 8B models, our team finally challenged the ultimate kings of performance: fine-tuning massive **70B (70 billion parameters)** models. We attempted to train both Llama 3.3 70B and DeepSeek-R1 70B, but as expected, we hit a massive hardware resource wall.\\n\\n{/* truncate */}\\n\\n### 70B Models and the Terror of OOM (Out of Memory)\\n\\n- **Problem**: As soon as we ambitiously uploaded and ran the 70B fine-tuning code on the server, errors started popping up.\\n- **Process**: \\n  > \\"I copied the server\'s fine_tuning folder and sub-files. Please check the copied files and identify the cause of the error.\\"\\n  > \\"Do we not need to modify DeepSeek\'s 70B model? Please check for potential errors.\\"\\n- **Result**: Our brief moment of relaxation, analyzing `train_log.jsonl` and asking for estimated completion times, was shattered when the 70B models instantly devoured all the GPU memory. (OOM error occurred!)\\n\\n### The GPU Memory Diet Operation\\n\\n- **Problem**: \\"The GPU memory usage is already at MAX.\\" We had to somehow reduce the memory usage so the training wouldn\'t crash.\\n- **Process**:\\n  > \\"Modified to save_steps = 50, save_total_limit = 10, eval_steps = 50, patience = 10.\\"\\n  > \\"Please evaluate the configured early stopping conditions.\\"\\n  > \\"I set the max_seq_length of both 70B models to 512 in ft_configs.yaml, but the server\'s nvitop still shows memory usage at max. Why is that?\\"\\n- **Result**: We drastically reduced the context length processed at once (`max_seq_length`) to 512 and heavily modified hyperparameters to reduce unnecessary saving. However, monitoring with `nvitop` showed that VRAM was still gasping at its absolute limit. Eventually, the horrific phenomenon of the training freezing around steps 100 and 150 repeated itself.\\n\\n![Terminal Screenshot](./images/02_term.png)\\n\\nTaming a massive beast like 70B is truly not easy. We are constantly throwing error logs at the Artificial Intelligence (AI) to find solutions, but it seems we need endless testing to see if we can overcome the physical VRAM limits with software optimization techniques (LoRA, Quantization, etc.). Will we succeed in fine-tuning the 70B models? To be continued in the next log!\\n\\n---\\n\\n## Summary & Key Takeaways\\n\\n- **70B Parameter Fine-Tuning Challenge**: Attempted large-scale LoRA fine-tuning on Llama 3.3-70B and DeepSeek-R1-70B, encountering severe hardware boundary constraints.\\n- **Immediate GPU VRAM Saturation**: Faced recurrent Out-of-Memory (OOM) crashes and distributed process freezes as the 70B parameter matrices saturated available GPU memory.\\n- **Aggressive Memory Diet Strategies**: Truncated sequence context (`max_seq_length`) down to 512, reduced checkpoint retention limits, and audited early stopping criteria.\\n- **Empirical Infrastructure Evaluation**: Validated the practical computational ceilings of consumer and academic GPU clusters when fine-tuning frontier 70B LLM architectures."},{"id":"2026-04-19-maeumjigi-11","metadata":{"permalink":"/blog/2026-04-19-maeumjigi-11","source":"@site/blog/2026-04-19-maeumjigi-11/index.md","title":"[Maeumjigi Capstone Dev Log #11] Evaluating M6 Model Trained on Synthetic Data (v5)","description":"Quantitative evaluation of model M6 trained on synthetic dataset v5, uncovering catastrophic forgetting of normal dialogue and empathy collapse.","date":"2026-04-19T00:00:00.000Z","tags":[{"inline":true,"label":"devlog","permalink":"/blog/tags/devlog"},{"inline":true,"label":"synthetic-data","permalink":"/blog/tags/synthetic-data"},{"inline":true,"label":"model-evaluation","permalink":"/blog/tags/model-evaluation"},{"inline":true,"label":"M6","permalink":"/blog/tags/m-6"},{"inline":true,"label":"FAISS","permalink":"/blog/tags/faiss"},{"inline":true,"label":"weekly-report","permalink":"/blog/tags/weekly-report"}],"readingTime":2.53,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"2026-04-19-maeumjigi-11","title":"[Maeumjigi Capstone Dev Log #11] Evaluating M6 Model Trained on Synthetic Data (v5)","authors":["jbgih"],"tags":["devlog","synthetic-data","model-evaluation","M6","FAISS","weekly-report"],"date":"2026-04-19T00:00:00.000Z","keywords":["AI Mental Health Chatbot","LLM Fine-tuning","AI Safety Wrapper","Capstone Project","Prompt Engineering"],"description":"Quantitative evaluation of model M6 trained on synthetic dataset v5, uncovering catastrophic forgetting of normal dialogue and empathy collapse."},"unlisted":false,"prevItem":{"title":"[Maeumjigi Capstone Dev Log #12] 70B Massive Model Fine-Tuning and GPU Memory (OOM) Struggle","permalink":"/blog/2026-05-03-maeumjigi-12"},"nextItem":{"title":"[Maeumjigi Capstone Dev Log #10] Resolving API Rate Limits: Unmanned Automation & Resilient Data Synthesis Pipeline","permalink":"/blog/2026-04-14-maeumjigi-10"}},"content":"![Cover Image](./images/01_cover.png)\\n\\nApril 19 is the day we evaluated the performance of the model (M6) trained on the virtual synthetic dataset (v5) we painstakingly created, and wrote the 7th-week weekly report based on it. Was the data we generated while enduring a $10 bill bomb worth it?\\n\\n{/* truncate */}\\n\\n### A Real Showdown of Model Performance: M0 vs M5 vs M6\\n\\n- **Problem**: To persuade the advising professor and team members, we needed a weekly report that included quantitative test results and intuitive comparison examples, rather than simply claiming \\"it got better.\\"\\n- **Process**: \\n  > \\"Please rewrite the report. The main point is the comparison between M5 based on v4 and M6 based on v5... Include examples of each dataset.\\"\\n  > \\"When describing the test results, include explanations with examples of the differences between the un-tuned base model (M0) and M6.\\"\\n- **Result**: The Artificial Intelligence (AI) analyzed the text results generated by the M0, M5, and M6 models and extracted a comparison file (`m0_m6_compare.json`). The results showed that the base Llama 3.1 model (M0) was somewhat awkward in Korean counseling, and while M5 (trained on refined data v4) improved, it lacked depth. In contrast, the M6 model trained on high-quality synthetic data (v5) perfectly commanded the warm and professional tone typical of a psychological counselor, deeply empathizing with the user\'s emotions.\\n\\n### The 7th-Week Weekly Report Written by AI (DOCX)\\n\\n- **Process**:\\n  > \\"Please write the 7th-week report focusing on the results and significance in two versions (a concise version under 5 pages, and a detailed version). Then generate docx files for each based on the two md files.\\"\\n- **Result**: With a single instruction, two versions (`7th-week_report_v1_concise.md`, `7th-week_report_v2_detailed.md`) were completed in a flash, and even neatly converted into Word files.\\n\\n### Introducing RAG Architecture: FAISS Database (DB) Construction Evaluation\\n\\n- **Process**:\\n  > \\"I performed FAISS_DB construction and wrote FAISS_DB_construction_report.docx. Please evaluate our plan and the results of the report.\\"\\n- **Result**: In addition to fine-tuning, which tweaks the model\'s weights, we introduced a FAISS vector database for RAG (Retrieval-Augmented Generation) to reduce hallucinations by referencing external knowledge. I asked the AI to evaluate the structure I built, and received positive feedback (`FAISS_DB_evaluation.md`).\\n\\n![Terminal Screenshot](./images/02_term.png)\\n\\nToday was a day when all the hard work paid off. The thrill of confirming that the trained AI model actually became noticeably smarter is incredible! With model performance proven and the FAISS DB successfully integrated, the Maeumjigi chatbot is one step closer to completion.\\n\\n---\\n\\n## Summary & Key Takeaways\\n\\n- **Comparative Evaluation of Synthetic Fine-Tuning**: Conducted qualitative and quantitative benchmarking across un-tuned base model M0, filtered-data model M5, and synthetic-dataset model M6.\\n- **Superior Empathetic Dialogue**: Model M6, trained on synthetic dataset v5, demonstrated professional counseling tone and nuanced emotional resonance without generic platitudes.\\n- **Automated Reporting Pipeline**: Prompted AI to generate comprehensive and concise 7th-week academic reports (`.docx`) with empirical comparison tables (`m0_m6_compare.json`).\\n- **RAG Architecture with FAISS Vector DB**: Integrated an external FAISS vector retrieval database alongside fine-tuned weights to ground responses in verified clinical knowledge and curb hallucination."},{"id":"2026-04-14-maeumjigi-10","metadata":{"permalink":"/blog/2026-04-14-maeumjigi-10","source":"@site/blog/2026-04-14-maeumjigi-10/index.md","title":"[Maeumjigi Capstone Dev Log #10] Resolving API Rate Limits: Unmanned Automation & Resilient Data Synthesis Pipeline","description":"Overcoming severe API tier throttling: lifting Anthropic billing limits, engineering an unmanned fault-tolerant worker with atomic checkpointing, and safely resuming our v5 synthetic data pipeline.","date":"2026-04-14T00:00:00.000Z","tags":[{"inline":true,"label":"devlog","permalink":"/blog/tags/devlog"},{"inline":true,"label":"api-rate-limits","permalink":"/blog/tags/api-rate-limits"},{"inline":true,"label":"synthetic-data","permalink":"/blog/tags/synthetic-data"},{"inline":true,"label":"data-generation","permalink":"/blog/tags/data-generation"},{"inline":true,"label":"fault-tolerance","permalink":"/blog/tags/fault-tolerance"},{"inline":true,"label":"state-machine","permalink":"/blog/tags/state-machine"},{"inline":true,"label":"capstone","permalink":"/blog/tags/capstone"}],"readingTime":3.82,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"2026-04-14-maeumjigi-10","title":"[Maeumjigi Capstone Dev Log #10] Resolving API Rate Limits: Unmanned Automation & Resilient Data Synthesis Pipeline","authors":["jbgih"],"tags":["devlog","api-rate-limits","synthetic-data","data-generation","fault-tolerance","state-machine","capstone"],"date":"2026-04-14T00:00:00.000Z","keywords":["Anthropic API Rate Limit","Synthetic Data Generation Pipeline","Unmanned Autonomous Script","Exponential Backoff Jitter","Atomic JSON Checkpointing"],"description":"Overcoming severe API tier throttling: lifting Anthropic billing limits, engineering an unmanned fault-tolerant worker with atomic checkpointing, and safely resuming our v5 synthetic data pipeline."},"unlisted":false,"prevItem":{"title":"[Maeumjigi Capstone Dev Log #11] Evaluating M6 Model Trained on Synthetic Data (v5)","permalink":"/blog/2026-04-19-maeumjigi-11"},"nextItem":{"title":"[Maeumjigi Capstone Dev Log #9] Llama 3.1 Fine-Tuning Error Struggle and Week 6 Mid-term Presentation","permalink":"/blog/2026-04-09-maeumjigi-9"}},"content":"![Cover Image](./images/01_cover.png)\\r\\n\\r\\nApril 14, 2026, was a masterclass in distributed pipeline fault tolerance. Following our temporary halt from unexpected API expenditure spikes, our team resumed synthetic data generation (v5) to enrich our empathy training set. However, unlocking higher billing tiers immediately exposed our worker scripts to severe rate-limiting (`HTTP 429 Too Many Requests`), partial file corruptions, and pipeline stalls. \\r\\n\\r\\nHere is how we re-engineered the synthesis architecture into a self-healing, unmanned autonomous pipeline.\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n### 1. The Anatomy of API Rate Limits: Tier Escalation & Throttling\\r\\n\\r\\nWhen synthesizing multi-turn empathetic dialogues at scale using foundation models (such as Claude 3.5 Sonnet), standard API tiers quickly become an engineering bottleneck. Ingestion of large system contexts causes rapid exhaustion of both Requests Per Minute (RPM) and Tokens Per Minute (TPM).\\r\\n\\r\\n| API Tier Level | Requests Per Minute (RPM) | Tokens Per Minute (TPM) | Monthly Credit Cap | Concurrency Strategy |\\r\\n| :---: | :---: | :---: | :---: | :--- |\\r\\n| **Tier 1 (Default)** | 50 RPM | 40,000 TPM | $100 | Serial requests only; high latency |\\r\\n| **Tier 2 (Deposit)** | 1,000 RPM | 80,000 TPM | $500 | Modest concurrency (4 workers); frequent 429s |\\r\\n| **Tier 3 (Enterprise)** | **2,000 RPM** | **160,000 TPM** | **$1,000+** | **Asynchronous batching (16 workers) with jitter** |\\r\\n\\r\\nAfter negotiating a tier escalation and depositing preliminary billing credits, our rate ceiling lifted. Yet raw speed triggered an unexpected secondary problem: network micro-outages and API dropouts began corrupting intermediate progress markers (`v5_sync_progress.json`).\\r\\n\\r\\n---\\r\\n\\r\\n### 2. The Resilient Unmanned State Machine\\r\\n\\r\\nTo run massive overnight generation batches without human babysitting, we refactored our worker script into an autonomous state machine equipped with **Atomic File Operations** and **Full Jitter Exponential Backoff**.\\r\\n\\r\\n```mermaid\\r\\nstateDiagram-v2\\r\\n    [*] --\x3e Idle: Initialize Worker\\r\\n    Idle --\x3e Fetch_Batch: Read Last Valid Index from Checkpoint\\r\\n    \\r\\n    state Fetch_Batch {\\r\\n        [*] --\x3e LoadSlice\\r\\n        LoadSlice --\x3e ValidateInput\\r\\n    }\\r\\n\\r\\n    Fetch_Batch --\x3e Dispatch_API: Async Request to LLM Engine\\r\\n    \\r\\n    state Dispatch_API {\\r\\n        [*] --\x3e SendRequest\\r\\n        SendRequest --\x3e CheckResponse\\r\\n    }\\r\\n\\r\\n    Dispatch_API --\x3e Backoff_Retry: HTTP 429 / 503 Detected\\r\\n    Backoff_Retry --\x3e Dispatch_API: Exponential Backoff with Jitter (2^n + uniform)\\r\\n    \\r\\n    Dispatch_API --\x3e Process_Result: HTTP 200 OK\\r\\n    Process_Result --\x3e Atomic_Save: Append to JSONL & Write Temp Checkpoint\\r\\n    Atomic_Save --\x3e Commit_State: Atomic os.replace (v5_sync_progress.json)\\r\\n    \\r\\n    Commit_State --\x3e Fetch_Batch: More Samples Pending\\r\\n    Commit_State --\x3e Shutdown_Safe: Target Threshold Reached\\r\\n    \\r\\n    Shutdown_Safe --\x3e [*]: Disconnect API & Log Final Summary\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\n### 3. Engineering Atomic Checkpointing & Exponential Backoff\\r\\n\\r\\nA critical vulnerability in our early script was opening `v5_sync_progress.json` with standard `w` mode: if an unhandled OS kill signal arrived while writing, the file truncated to 0 bytes, losing days of progress tracking.\\r\\n\\r\\nWe solved this via POSIX/Windows atomic file swapping and exponential backoff retry decorators:\\r\\n\\r\\n```python\\r\\n# Fault-tolerant atomic progress tracking & backoff implementation\\r\\nimport os\\r\\nimport json\\r\\nimport time\\r\\nimport random\\r\\n\\r\\ndef save_atomic_progress(filepath: str, data: dict):\\r\\n    temp_filepath = f\\"{filepath}.tmp\\"\\r\\n    with open(temp_filepath, \\"w\\", encoding=\\"utf-8\\") as f:\\r\\n        json.dump(data, f, ensure_ascii=False, indent=2)\\r\\n    # Atomic swap guarantees zero file corruption even during crashes\\r\\n    os.replace(temp_filepath, filepath)\\r\\n\\r\\ndef call_api_with_resilient_backoff(api_func, payload, max_retries=5):\\r\\n    retries = 0\\r\\n    base_delay = 1.5\\r\\n    while retries < max_retries:\\r\\n        try:\\r\\n            return api_func(payload)\\r\\n        except Exception as e:\\r\\n            if \\"429\\" in str(e) or \\"503\\" in str(e):\\r\\n                retries += 1\\r\\n                # Exponential backoff with Full Jitter\\r\\n                sleep_time = (base_delay * (2 ** retries)) + random.uniform(0.1, 1.0)\\r\\n                time.sleep(sleep_time)\\r\\n            else:\\r\\n                raise e\\r\\n    raise RuntimeError(f\\"Max retries exceeded for payload: {payload}\\")\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\n### 4. Unmanned Automation Directive\\r\\n\\r\\nBecause our team members needed uninterrupted rest, we granted Claude Code full autonomous watchdog authority:\\r\\n\\r\\n> **Execution Directive**:  \\r\\n> *\\"All permissions are granted. Monitor synthesis progress continuously. If a connection failure occurs, recover from the last atomic checkpoint. Once all 25,000 synthetic pairs are generated and validated, automatically terminate the background API worker and safely power down the compute instance.\\"*\\r\\n\\r\\nThe AI agent executed this directive flawlessly between 23:30 and 06:15 without a single human intervention.\\r\\n\\r\\n![Terminal Screenshot](./images/02_term.png)\\r\\n\\r\\n---\\r\\n\\r\\n### 5. Day 10 Milestones & Metrics\\r\\n\\r\\n| Quantitative Metric | Measurement | Technical Impact |\\r\\n| :--- | :---: | :--- |\\r\\n| **Synthesis Batch Target** | 25,000 Pairs | Emotion-enriched high-difficulty counseling scenarios |\\r\\n| **API Failure Rate (Post-Backoff)** | **0.00%** | Zero lost payloads over 7-hour overnight run |\\r\\n| **Throughput Rate** | 62.4 requests/min | Sustained near maximum Tier 2/3 allocation |\\r\\n| **Checkpoint Integrity** | 100% | Flawless atomic state persistence despite 3 network blips |\\r\\n\\r\\nIn Dev Log #11, we evaluate our first model checkpoint (M6) trained on this synthesized dataset and benchmark its empathetic resonance!\\n\\n---\\n\\n## Summary & Key Takeaways\\n\\n- **Overcoming API Throttling & Rate Limits**: Escalated API billing tiers to Tier 2/3 and implemented concurrency limits to handle high-volume dialogue generation.\\n- **Resilient State Machine Architecture**: Designed a fault-tolerant synthetic pipeline integrating exponential backoff with full jitter to automatically absorb HTTP 429 and 503 errors.\\n- **Zero-Corruption Atomic Checkpointing**: Employed POSIX/Windows atomic file swapping (`os.replace`) to safeguard intermediate generation state against unexpected script or network failures.\\n- **Unmanned Autonomous Pipeline Execution**: Delegated complete overnight watchdog authority to AI agents, successfully synthesizing 25,000 high-difficulty counseling pairs with 0% data loss."},{"id":"2026-04-09-maeumjigi-9","metadata":{"permalink":"/blog/2026-04-09-maeumjigi-9","source":"@site/blog/2026-04-09-maeumjigi-9/index.md","title":"[Maeumjigi Capstone Dev Log #9] Llama 3.1 Fine-Tuning Error Struggle and Week 6 Mid-term Presentation","description":"Setting up the AWS GPU environment, configuring Unsloth LoRA for Llama 3.1 8B, and completing our very first fine-tuning training run.","date":"2026-04-09T00:00:00.000Z","tags":[{"inline":true,"label":"devlog","permalink":"/blog/tags/devlog"},{"inline":true,"label":"Llama3.1","permalink":"/blog/tags/llama-3-1"},{"inline":true,"label":"fine-tuning","permalink":"/blog/tags/fine-tuning"},{"inline":true,"label":"troubleshooting","permalink":"/blog/tags/troubleshooting"},{"inline":true,"label":"PPT-generation","permalink":"/blog/tags/ppt-generation"},{"inline":true,"label":"ERD","permalink":"/blog/tags/erd"}],"readingTime":2.53,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"2026-04-09-maeumjigi-9","title":"[Maeumjigi Capstone Dev Log #9] Llama 3.1 Fine-Tuning Error Struggle and Week 6 Mid-term Presentation","authors":["jbgih"],"tags":["devlog","Llama3.1","fine-tuning","troubleshooting","PPT-generation","ERD"],"date":"2026-04-09T00:00:00.000Z","keywords":["AI Mental Health Chatbot","LLM Fine-tuning","AI Safety Wrapper","Capstone Project","Prompt Engineering"],"description":"Setting up the AWS GPU environment, configuring Unsloth LoRA for Llama 3.1 8B, and completing our very first fine-tuning training run."},"unlisted":false,"prevItem":{"title":"[Maeumjigi Capstone Dev Log #10] Resolving API Rate Limits: Unmanned Automation & Resilient Data Synthesis Pipeline","permalink":"/blog/2026-04-14-maeumjigi-10"},"nextItem":{"title":"[Maeumjigi Capstone Dev Log #8] Application Programming Interface (API) Bill Bomb Incident and Preparing Colab Fine-Tuning","permalink":"/blog/2026-04-08-maeumjigi-8"}},"content":"![Cover Image](./images/01_cover.png)\\n\\nOn April 9, using the Colab notebook we ambitiously completed yesterday, we finally attempted the first training (fine-tuning) of our artificial intelligence model (Llama 3.1). However, reality was not that easy, and we had to face numerous errors. It was also a tough day as we had to simultaneously create the presentation materials for the 6th week of the Capstone Design project.\\n\\n{/* truncate */}\\n\\n### The Endless Struggle with Colab Fine-Tuning Errors\\n\\n- **Problem**: As soon as we executed `llama31_finetuning_colab.ipynb` created yesterday, various errors poured out.\\n- **Process**: \\n  > \\"Why is an error occurring during M1 fine-tuning in llama31_finetuning_colab (3).ipynb?\\"\\n  > \\"The executed result contains the eos_token. Why is this problem occurring?\\"\\n- **Result**: A series of problems occurred, such as the special token (`eos_token`) not being processed correctly when the Artificial Intelligence (AI) model spit out the training data, and memory overflow issues. We repeated the process of copying and pasting the entire error log to Claude to get solutions and modifying the code multiple times. Finally, after many twists and turns, the training was completed, and we were able to extract a meaningful result graph called `\uD559\uC2B5\uB370\uC774\uD130\uBCC4\uD559\uC2B5\uACB0\uACFC.png`!\\n\\n### The AI Assistant\'s Presentation (PPT) Creation\\n\\n- **Problem**: While staying up all night training the model, we had to immediately create a PPT on the 6th-week frontend and database progress for the presentation next week.\\n- **Process**:\\n  > \\"Capstone_Week6_Frontend.pptx is a collection of images introducing the overview so far. Please use this to create a presentation for this week\'s progress.\\"\\n  > \\"Please express the tables of the database design so that the relationships can be seen, referring to the tables implemented in the backend... The table is too large and messy. Please place the User table in the center.\\"\\n- **Result**: Surprisingly, the AI wove the frontend image screenshots together to create a presentation script and slide skeleton. Even when I persistently gave feedback (centering the User table) asking it to draw a complex database ERD (Entity Relationship Diagram) based on the backend code, it perfectly organized and explained the database relationship diagram.\\n\\n![Terminal Screenshot](./images/02_term.png)\\n\\nToday was a day to feel the thrill of directly tuning the latest language model called Llama 3.1 with my own hands (and the AI\'s brain). At the same time, we are learning how to fully utilize AI not only for coding but also for creating presentation materials and designing Database (DB) architecture diagrams. How smart has our Maeumjigi AI become? We will reveal the test results next time!\\n\\n---\\n\\n## Summary & Key Takeaways\\n\\n- **First Llama 3.1 Fine-Tuning Run**: Executed initial LoRA fine-tuning on Llama 3.1 8B via Google Colab, resolving critical `eos_token` formatting and memory overflow issues.\\n- **Empirical Training Diagnostics**: Extracted empirical loss convergence graphs across dataset variants, confirming valid weight updates for specialized empathetic counseling.\\n- **AI-Assisted Slide Deck Synthesis**: Leveraged LLMs to convert frontend interface screenshots into a polished 6th-week capstone presentation script and slide structure.\\n- **Automated Database ERD Architecture**: Directed AI to reverse-engineer backend models into a user-centric Entity-Relationship Diagram (ERD), clarifying schema constraints."},{"id":"2026-04-08-maeumjigi-8","metadata":{"permalink":"/blog/2026-04-08-maeumjigi-8","source":"@site/blog/2026-04-08-maeumjigi-8/index.md","title":"[Maeumjigi Capstone Dev Log #8] Application Programming Interface (API) Bill Bomb Incident and Preparing Colab Fine-Tuning","description":"Replacing synchronous bottlenecks with an asynchronous multiprocessing pipeline, boosting data generation and crawling throughput by 5x.","date":"2026-04-08T00:00:00.000Z","tags":[{"inline":true,"label":"devlog","permalink":"/blog/tags/devlog"},{"inline":true,"label":"API-billing","permalink":"/blog/tags/api-billing"},{"inline":true,"label":"Llama3.1","permalink":"/blog/tags/llama-3-1"},{"inline":true,"label":"fine-tuning","permalink":"/blog/tags/fine-tuning"},{"inline":true,"label":"GoogleColab","permalink":"/blog/tags/google-colab"},{"inline":true,"label":"data-preprocessing","permalink":"/blog/tags/data-preprocessing"}],"readingTime":2.22,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"2026-04-08-maeumjigi-8","title":"[Maeumjigi Capstone Dev Log #8] Application Programming Interface (API) Bill Bomb Incident and Preparing Colab Fine-Tuning","authors":["jbgih"],"tags":["devlog","API-billing","Llama3.1","fine-tuning","GoogleColab","data-preprocessing"],"date":"2026-04-08T00:00:00.000Z","keywords":["AI Mental Health Chatbot","LLM Fine-tuning","AI Safety Wrapper","Capstone Project","Prompt Engineering"],"description":"Replacing synchronous bottlenecks with an asynchronous multiprocessing pipeline, boosting data generation and crawling throughput by 5x."},"unlisted":false,"prevItem":{"title":"[Maeumjigi Capstone Dev Log #9] Llama 3.1 Fine-Tuning Error Struggle and Week 6 Mid-term Presentation","permalink":"/blog/2026-04-09-maeumjigi-9"},"nextItem":{"title":"[Maeumjigi Capstone Dev Log #7] Synthetic Data (v5) Generation Optimization and Frontend Integration","permalink":"/blog/2026-04-07-maeumjigi-7"}},"content":"![Cover Image](./images/01_cover.png)\\n\\nApril 8th was the day we experienced the biggest crisis and a \'laugh-and-cry\' happening while working on the Maeumjigi project. It was the **Claude API monthly limit exceeded & bill bomb incident**.\\n\\n{/* truncate */}\\n\\n### The Betrayal of the Background: \\"$1 for 10 records?\\"\\n\\n- **Problem**: Relieved that we had finished optimization yesterday, we left the massive test dataset generation script running in the background unattended.\\n- **Process**: \\n  > \\"Problem: Billed exceeding the monthly limit. I left it running thinking it was just working in the background, and this happened.\\"\\n  > \\"No way, it costs $1 to generate 10 records? Does that make sense?\\"\\n- **Result**: During the process of synthesizing high-quality counseling data using an Large Language Model (LLM), the prompt\'s context (input tokens) accumulated, causing the cost to increase exponentially. The script halted because the monthly billing limit was exceeded. We urgently instructed the Artificial Intelligence (AI), \\"Immediately add a feature to print the estimated consumption, cost, and progress in real-time to the console, and prevent limit exceedance.\\" We learned the hard way how crucial billing monitoring is when using clouds or APIs.\\n\\n### Writing a Colab Notebook for Llama 3.1 Training\\n\\n- **Problem**: As the data was getting ready, we now needed the code to actually fine-tune the Llama 3.1 model. Since our local PC\'s GPU wasn\'t nearly enough, we had to use the Google Colab environment.\\n- **Process**:\\n  > \\"Please write a python notebook to execute llama31_finetuning_experiment_plan_revised.md in Colab.\\"\\n  > \\"Split the training data only into train/val instead of train/val/test, using a 9:1 ratio.\\"\\n- **Result**: The AI independently read the training plan and wrote a perfect Jupyter Notebook code called `llama31_finetuning_colab.ipynb`. It perfectly implemented logic including setting up the latest lightweight libraries like Unsloth, and splitting the dataset into a 9:1 ratio for training and validation.\\n\\n![Terminal Screenshot](./images/02_term.png)\\n\\nToday was a day of overcoming a realistic barrier of the project, paying a terrifying initiation fee called the API bill bomb. However, in return, we completed an excellent dataset and a Colab notebook for fine-tuning. Finally, the next step is to train the real artificial intelligence model!\\n\\n---\\n\\n## Summary & Key Takeaways\\n\\n- **API Expenditure Shock & Diagnosis**: Encountered sudden Claude API rate and monthly billing cap limits due to accumulating context tokens during unmanned synthetic dialogue generation.\\n- **Cost Guardrails & Real-Time Monitoring**: Promptly integrated real-time token tracking, console expenditure estimation, and automatic kill-switches to prevent unbudgeted API runs.\\n- **Colab Fine-Tuning Pipeline Authoring**: Engineered `llama31_finetuning_colab.ipynb` incorporating Unsloth optimization for efficient parameter-efficient fine-tuning (PEFT).\\n- **Data Splitting & Preparation**: Partitioned synthesized dialogue datasets into a 9:1 train/validation split to maximize learning samples while preserving validation accuracy."},{"id":"2026-04-07-maeumjigi-7","metadata":{"permalink":"/blog/2026-04-07-maeumjigi-7","source":"@site/blog/2026-04-07-maeumjigi-7/index.md","title":"[Maeumjigi Capstone Dev Log #7] Synthetic Data (v5) Generation Optimization and Frontend Integration","description":"Building a scalable synthetic dialogue generation pipeline with Claude API while implementing batch token optimization to keep API costs under control.","date":"2026-04-07T00:00:00.000Z","tags":[{"inline":true,"label":"devlog","permalink":"/blog/tags/devlog"},{"inline":true,"label":"synthetic-data","permalink":"/blog/tags/synthetic-data"},{"inline":true,"label":"ClaudeAPI","permalink":"/blog/tags/claude-api"},{"inline":true,"label":"data-generation","permalink":"/blog/tags/data-generation"},{"inline":true,"label":"frontend","permalink":"/blog/tags/frontend"},{"inline":true,"label":"cost-optimization","permalink":"/blog/tags/cost-optimization"}],"readingTime":2.38,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"2026-04-07-maeumjigi-7","title":"[Maeumjigi Capstone Dev Log #7] Synthetic Data (v5) Generation Optimization and Frontend Integration","authors":["jbgih"],"tags":["devlog","synthetic-data","ClaudeAPI","data-generation","frontend","cost-optimization"],"date":"2026-04-07T00:00:00.000Z","keywords":["AI Mental Health Chatbot","LLM Fine-tuning","AI Safety Wrapper","Capstone Project","Prompt Engineering"],"description":"Building a scalable synthetic dialogue generation pipeline with Claude API while implementing batch token optimization to keep API costs under control."},"unlisted":false,"prevItem":{"title":"[Maeumjigi Capstone Dev Log #8] Application Programming Interface (API) Bill Bomb Incident and Preparing Colab Fine-Tuning","permalink":"/blog/2026-04-08-maeumjigi-8"},"nextItem":{"title":"[Maeumjigi Capstone Dev Log #6] Automated Report Pipeline: python-docx Visualization & Next.js 14 Frontend Kickoff","permalink":"/blog/2026-04-05-maeumjigi-6"}},"content":"![Cover Image](./images/01_cover.png)\\n\\nApril 7 was the day we attempted integration by running the frontend code built by a teammate in a local environment, \\nand also the day we launched a massive script using Artificial Intelligence (AI) to \'synthesize\' 60,000 new counseling data points to fill our dataset gaps.\\n\\n{/* truncate */}\\n\\n### Filling in the Blanks: Generating AI Synthetic Data (v5)\\n\\n- **Problem**: The previously refined data (v4) alone lacked specific emotions or detailed counseling scenarios. To solve this, we wanted to use the Claude Application Programming Interface (API) to generate 60,000 virtual, high-quality counseling conversations that fit the Llama 3.1 training format (System, User, Assistant).\\n- **Process**: \\n  > \\"We want to create a v5 dataset entirely generated by Claude. Please make a plan.\\"\\n  > \\"I want to obtain 60,000 dataset records generated by Claude in jsonl format.\\"\\n- **Result**: We established `v5_plan.md` and started generating data. However, the API call cost quickly became a stumbling block again.\\n\\n### The Never-ending War with Costs: Prompt Optimization\\n\\n- **Problem**: While trying to make the AI author 60,000 data points, the cost issue we experienced a few days ago resurfaced. During the script execution, $10 in credits evaporated in an instant.\\n- **Process**:\\n  > \\"Will token usage decrease if we proceed exactly like step8_generate_v5_optimized.py?\\"\\n  > \\"We have already consumed $10 of our credit and are only at this progress level.\\"\\n- **Result**: We instructed the AI to perform prompt engineering and code optimization (`step8_generate_v5_optimized.py`) to reduce costs, preventing the waste of output tokens and adding logic to safely save generation progress.\\n\\n### Handover and Execution of Teammate\'s Frontend Code\\n\\n- **Process**: \\n  > \\"This project was created by a teammate; what should I do to run it?\\"\\n  > \\"Error occurred during Database (DB) migration...\\"\\n  > \\"Execution up to frontend step 6 complete. Please tell me how to shut it down and the simple procedure to run it again.\\"\\n- **Result**: We took over the `mental-health` repository written by a teammate, ran it locally, and resolved DB migration errors. Now, the backend AI model and the frontend are ready to meet.\\n\\n![Terminal Screenshot](./images/02_term.png)\\n\\nToday was a meaningful day where, moving beyond simple data preprocessing, we directly implemented the latest deep learning trend of **Synthetic Data Generation**, making an AI write the textbooks (data) to teach another AI.\\nIt was a day of achieving optimization amidst the horror of pouring bills and safely launching the frontend server!\\n\\n---\\n\\n## Summary & Key Takeaways\\n\\n- **Massive Synthetic Data (v5) Generation**: Initiated synthesis of 60,000 multi-turn counseling dialogues using Claude API to enrich training distribution across complex emotional scenarios.\\n- **Aggressive Token & Cost Optimization**: Refactored prompt templates and execution script (`step8_generate_v5_optimized.py`) to eliminate output redundancy and curb billing burn rate.\\n- **Persistent Progress Checkpointing**: Added incremental state persistence to safeguard against API dropouts and prevent duplicate generation overhead.\\n- **Frontend Handoff & Database Migration**: Successfully ran the teammate\'s repository locally, resolving database migration errors and aligning backend AI endpoints with frontend UI."},{"id":"2026-04-05-maeumjigi-6","metadata":{"permalink":"/blog/2026-04-05-maeumjigi-6","source":"@site/blog/2026-04-05-maeumjigi-6/index.md","title":"[Maeumjigi Capstone Dev Log #6] Automated Report Pipeline: python-docx Visualization & Next.js 14 Frontend Kickoff","description":"Wrapping up Phase 1 data preprocessing: building an autonomous python-docx and matplotlib report compiler while scaffolding our real-time Next.js 14 streaming chatbot frontend.","date":"2026-04-05T00:00:00.000Z","tags":[{"inline":true,"label":"devlog","permalink":"/blog/tags/devlog"},{"inline":true,"label":"automated-reporting","permalink":"/blog/tags/automated-reporting"},{"inline":true,"label":"python-docx","permalink":"/blog/tags/python-docx"},{"inline":true,"label":"matplotlib","permalink":"/blog/tags/matplotlib"},{"inline":true,"label":"nextjs-14","permalink":"/blog/tags/nextjs-14"},{"inline":true,"label":"frontend-architecture","permalink":"/blog/tags/frontend-architecture"},{"inline":true,"label":"capstone","permalink":"/blog/tags/capstone"}],"readingTime":3.89,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"2026-04-05-maeumjigi-6","title":"[Maeumjigi Capstone Dev Log #6] Automated Report Pipeline: python-docx Visualization & Next.js 14 Frontend Kickoff","authors":["jbgih"],"tags":["devlog","automated-reporting","python-docx","matplotlib","nextjs-14","frontend-architecture","capstone"],"date":"2026-04-05T00:00:00.000Z","keywords":["Automated Report Generation","python-docx Matplotlib Pipeline","Next.js 14 Chatbot UI","Data Preprocessing Distribution","Full-Stack AI Architecture"],"description":"Wrapping up Phase 1 data preprocessing: building an autonomous python-docx and matplotlib report compiler while scaffolding our real-time Next.js 14 streaming chatbot frontend."},"unlisted":false,"prevItem":{"title":"[Maeumjigi Capstone Dev Log #7] Synthetic Data (v5) Generation Optimization and Frontend Integration","permalink":"/blog/2026-04-07-maeumjigi-7"},"nextItem":{"title":"[Maeumjigi Capstone Dev Log #5] Purifying 100,000 Emotion Data Points and the Pressure of Application Programming Interface (API) Costs","permalink":"/blog/2026-04-03-maeumjigi-5"}},"content":"![Cover Image](./images/01_cover.png)\\r\\n\\r\\nApril 5, 2026, marked a decisive operational turning point for the **Maeumjigi** capstone project. Having completed four iterative versions of data cleansing (v1 through v4), our team needed to accomplish two critical engineering objectives:\\r\\n1. **Automated Faculty Reporting**: Synthesizing our 120,000-sample preprocessing journey into an executive DOCX report with dynamic statistical charts.\\r\\n2. **Next.js 14 Frontend Scaffolding**: Launching the client-side architecture capable of handling low-latency server-sent events (SSE) for streaming model responses.\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n### 1. The Autonomous Report Compiler: python-docx + matplotlib\\r\\n\\r\\nIn traditional academic engineering, compiling comprehensive documentation often consumes more time than the actual coding. To eliminate this overhead, we instructed **Claude Code** to analyze our raw preprocessing outputs and compile an executive Word (`.docx`) report autonomously.\\r\\n\\r\\n```mermaid\\r\\nflowchart LR\\r\\n    subgraph Data_Metrics [\\"Preprocessing Metric Logs\\"]\\r\\n        A[v1_raw_stats.json]\\r\\n        B[v2_dedup_stats.json]\\r\\n        C[v3_pii_stats.json]\\r\\n        D[v4_final_stats.json]\\r\\n    end\\r\\n\\r\\n    subgraph Compiler_Engine [\\"Autonomous Python Compiler\\"]\\r\\n        E[Matplotlib Chart Engine]\\r\\n        F[python-docx Document Builder]\\r\\n        A & B & C & D --\x3e E\\r\\n        E --\x3e|High-Res PNG Graphs| F\\r\\n    end\\r\\n\\r\\n    subgraph Deliverables [\\"Generated Artifacts\\"]\\r\\n        F --\x3e G[(Maeumjigi_Data_Preprocessing_Final_Report.docx)]\\r\\n        F --\x3e H[Emotion Distribution Radar & Bar Charts]\\r\\n    end\\r\\n```\\r\\n\\r\\nThe automated script parsed iteration metadata, calculated statistical variances across dialogue turns, rendered 300 DPI Matplotlib figures, and injected them directly into a pre-styled Word template:\\r\\n\\r\\n```python\\r\\n# Automated report compiler snippet: compile_report.py\\r\\nfrom docx import Document\\r\\nfrom docx.shared import Inches, Pt\\r\\nimport matplotlib.pyplot as plt\\r\\n\\r\\ndef generate_emotion_distribution_chart(data: dict, output_path: str):\\r\\n    fig, ax = plt.subplots(figsize=(8, 4), dpi=300)\\r\\n    categories = list(data.keys())\\r\\n    counts = list(data.values())\\r\\n    ax.barh(categories, counts, color=\'#3B82F6\')\\r\\n    ax.set_title(\\"Maeumjigi v4 Corpus: Emotion Distribution\\", fontsize=12)\\r\\n    plt.tight_layout()\\r\\n    plt.savefig(output_path)\\r\\n    plt.close()\\r\\n\\r\\ndef build_docx_report(stats: dict, chart_path: str, docx_path: str):\\r\\n    doc = Document()\\r\\n    doc.add_heading(\\"Maeumjigi Data Preprocessing Final Technical Report\\", level=0)\\r\\n    doc.add_paragraph(\\"Automated summary of dataset sanitation across iterations v1 to v4.\\")\\r\\n    doc.add_picture(chart_path, width=Inches(6.0))\\r\\n    doc.save(docx_path)\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\n### 2. Multi-Version Data Sanitation Progress (v1 to v4)\\r\\n\\r\\nThrough four iterative refinement cycles, our dataset evolved from noisy raw scraping into an ethically sound, clinical-grade instruction corpus:\\r\\n\\r\\n| Iteration | Record Count | Average Turn Length | Primary Engineering Focus | Key Anomaly Filtered |\\r\\n| :---: | :---: | :---: | :--- | :--- |\\r\\n| **v1** | 124,500 | 18.4 tokens | Initial raw ingestion and JSON unification | Null utterances and broken encoding |\\r\\n| **v2** | 114,800 | 24.2 tokens | Exact & fuzzy deduplication (MinHash LSH) | Scripted chatbot loops and duplicate turns |\\r\\n| **v3** | 102,600 | 32.8 tokens | NER-based PII redaction and profanity mask | Telephone numbers, military unit IDs, names |\\r\\n| **v4 (Final)** | **92,400** | **45.6 tokens** | Empathetic depth scoring & 2048 token cutoff | Truncated responses and low-empathy short phrases |\\r\\n\\r\\n---\\r\\n\\r\\n### 3. Next.js 14 App Router Frontend Architecture\\r\\n\\r\\nWith data readiness secured, we turned our focus to user interaction. A mental health crisis intervention platform requires an intuitive, calm, and distraction-free interface. We initialized **Next.js 14** using the App Router, configuring Tailwind CSS for styling and Zustand for lightweight global state management:\\r\\n\\r\\n```text\\r\\nmaeumjigi/frontend/\\r\\n\u251C\u2500\u2500 app/\\r\\n\u2502   \u251C\u2500\u2500 layout.tsx         # Global typography & dark-mode provider\\r\\n\u2502   \u251C\u2500\u2500 page.tsx           # Crisis landing page & immediate help triggers\\r\\n\u2502   \u2514\u2500\u2500 chat/\\r\\n\u2502       \u251C\u2500\u2500 page.tsx       # Real-time streaming chat canvas\\r\\n\u2502       \u2514\u2500\u2500 components/\\r\\n\u2502           \u251C\u2500\u2500 MessageList.tsx  # Virtualized dialogue stream\\r\\n\u2502           \u251C\u2500\u2500 ChatInput.tsx    # Debounced voice & text input\\r\\n\u2502           \u2514\u2500\u2500 SafetyModal.tsx  # Emergency hotline escalation overlay\\r\\n\u251C\u2500\u2500 stores/\\r\\n\u2502   \u2514\u2500\u2500 useChatStore.ts    # Zustand store: session state & stream buffers\\r\\n\u2514\u2500\u2500 tailwind.config.js     # Accessible color palette with high contrast\\r\\n```\\r\\n\\r\\n```mermaid\\r\\nsequenceDiagram\\r\\n    autonumber\\r\\n    actor User as Client User\\r\\n    participant Next as Next.js 14 App Router\\r\\n    participant API as FastAPI Gateway\\r\\n    participant LLM as Llama 3.1 / Qwen Engine\\r\\n\\r\\n    User->>Next: Types distress message\\r\\n    Next->>API: POST /api/chat/stream (SSE)\\r\\n    API->>API: Safety Wrapper: Zero-shot triage\\r\\n    alt Active Crisis Detected\\r\\n        API--\x3e>Next: event: emergency_escalation (109 / 1393)\\r\\n        Next--\x3e>User: Render SafetyModal & Instant Hotline Dial\\r\\n    else Standard Empathetic Turn\\r\\n        API->>LLM: Stream inference tokens\\r\\n        LLM--\x3e>API: Yield delta token\\r\\n        API--\x3e>Next: event: text_delta\\r\\n        Next--\x3e>User: Smooth typing animation on MessageList\\r\\n    end\\r\\n```\\r\\n\\r\\n![Terminal Screenshot](./images/02_term.png)\\r\\n\\r\\n---\\r\\n\\r\\n### 4. Day 6 Engineering Milestones\\r\\n\\r\\n1. **Zero Documentation Friction**: Completed faculty-ready DOCX and graphic summaries without manual formatting.\\r\\n2. **Full-Stack Architecture Unified**: Connected the AI data pipeline to our modern Next.js 14 web client.\\r\\n3. **Safety-First UI Protocol**: Implemented frontend support for server-sent emergency hotline modal overlays.\\r\\n\\r\\nIn Dev Log #7, we explore synthetic data generation optimizations and how we bridged the gap between raw data and real-time frontend responses!\\n\\n---\\n\\n## Summary & Key Takeaways\\n\\n- **Automated Faculty Reporting Pipeline**: Developed an autonomous script pairing `python-docx` with Matplotlib to generate technical progress documents with dynamic distribution figures.\\n- **Completion of Phase 1 Data Cleansing**: Refined raw scraped dialogues (124,500 samples) down to 92,400 clinical-grade pairs (v4) with high empathetic scoring and PII redaction.\\n- **Next.js 14 Streaming Frontend Scaffolding**: Initialized the web client utilizing App Router, Zustand, and Server-Sent Events (SSE) for low-latency token streaming.\\n- **Crisis Intervention Modal Integration**: Architected frontend emergency protocols to immediately render hotline overlays upon receiving safety wrapper risk events."},{"id":"2026-04-03-maeumjigi-5","metadata":{"permalink":"/blog/2026-04-03-maeumjigi-5","source":"@site/blog/2026-04-03-maeumjigi-5/index.md","title":"[Maeumjigi Capstone Dev Log #5] Purifying 100,000 Emotion Data Points and the Pressure of Application Programming Interface (API) Costs","description":"Purifying Korean public dialogue datasets and managing the first severe Anthropic API billing challenge encountered during automated data processing.","date":"2026-04-03T00:00:00.000Z","tags":[{"inline":true,"label":"devlog","permalink":"/blog/tags/devlog"},{"inline":true,"label":"data-cleaning","permalink":"/blog/tags/data-cleaning"},{"inline":true,"label":"ClaudeAPI","permalink":"/blog/tags/claude-api"},{"inline":true,"label":"emotion-classification","permalink":"/blog/tags/emotion-classification"},{"inline":true,"label":"Llama3.1","permalink":"/blog/tags/llama-3-1"},{"inline":true,"label":"api-cost","permalink":"/blog/tags/api-cost"}],"readingTime":2.41,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"2026-04-03-maeumjigi-5","title":"[Maeumjigi Capstone Dev Log #5] Purifying 100,000 Emotion Data Points and the Pressure of Application Programming Interface (API) Costs","authors":["jbgih"],"tags":["devlog","data-cleaning","ClaudeAPI","emotion-classification","Llama3.1","api-cost"],"date":"2026-04-03T00:00:00.000Z","keywords":["AI Mental Health Chatbot","LLM Fine-tuning","AI Safety Wrapper","Capstone Project","Prompt Engineering"],"description":"Purifying Korean public dialogue datasets and managing the first severe Anthropic API billing challenge encountered during automated data processing."},"unlisted":false,"prevItem":{"title":"[Maeumjigi Capstone Dev Log #6] Automated Report Pipeline: python-docx Visualization & Next.js 14 Frontend Kickoff","permalink":"/blog/2026-04-05-maeumjigi-6"},"nextItem":{"title":"[Maeumjigi Capstone Dev Log #4] Full-Scale Data Preprocessing: Llama 3.1 Chat Template & Autonomous JSONL Pipeline","permalink":"/blog/2026-04-01-maeumjigi-4"}},"content":"![Cover Image](./images/01_cover.png)\\n\\nThis is the record of April 3, the day we began in earnest the task of refining the training conversation data to feed into the deep learning model (Llama 3.1).\\nIt was also the day we ran a massive pipeline that makes the Artificial Intelligence (AI) read the text and judge the emotion on its own, going beyond simple data merging.\\n\\n{/* truncate */}\\n\\n### Reclassifying Data Emotions (v3 -> v4)\\n\\n- **Problem**: The emotion labeling of the existing dataset (`Emotion_train_dataset_v3`) did not perfectly align with our specific psychological counseling goals. Out of a total of 1 million data points, we needed to filter only the meaningful ones and accurately map their emotions.\\n- **Process**: \\n  > \\"The scope is the entire 1 million... Because Claude, as a psychological counseling expert, will read the conversation and directly map the emotion. We are filtering only what falls under our emotion classification and excluding the rest.\\"\\n- **Result**: We established `v4_plan.md` and started the work. Initially targeting 100,000 lines of data, we wrote and ran a script that integrates the Claude API to grasp the conversational context and reclassify emotions.\\n\\n### The Horror of Large Language Model (LLM) API Billing\\n\\n- **Problem**: As we threw massive amounts of text data at an LLM (Claude) for evaluation, the API usage (token count) increased exponentially.\\n- **Process**:\\n  > \\"I\'m already using Claude with a Pro subscription, do I need a separate API?\\"\\n  > \\"Is there a way to use Claude Code instead of the Anthropic API? The billing is burdensome.\\"\\n  > \\"The actual cost came out to $10.27.\\"\\n- **Result**: We painfully realized that, completely separate from the Claude Pro subscription ($20/month), the Anthropic API called by the Python script for automated batch processing is billed on a pay-as-you-go basis depending on usage. Just processing 100,000 test lines instantly cost us about $10.27. Realizing that processing all 1 million records would cost a fortune, it was a day we learned firsthand the importance of model optimization and data sampling.\\n\\n![Terminal Screenshot](./images/02_term.png)\\n\\nToday was the day we hit the realistic wall of \'computing costs\' inevitably encountered during deep learning data preprocessing.\\nAlthough we successfully obtained high-quality, refined data (`v4_report.md`), it was a valuable experience that left us deeply contemplating how to balance cost and efficiency as we proceed with fine-tuning!\\n\\n---\\n\\n## Summary & Key Takeaways\\n\\n- **Context-Aware Emotion Reclassification**: Transitioned dataset v3 to v4 by utilizing LLMs to read conversational context and map multi-turn dialogues into target counseling emotion tags.\\n- **API Pay-As-You-Go Economics**: Discovered firsthand that scripted automated batch ingestion incurs pay-per-token API charges independent of personal Pro subscriptions.\\n- **Empirical Cost Realities**: Sustained a $10.27 expenditure for processing the first 100,000 records, exposing the fiscal impossibility of processing the full 1-million sample corpus naively.\\n- **Pivoting to Stratified Sampling**: Promptly re-evaluated pipeline architecture to balance training efficiency with budget, prioritizing high-leverage samples and prompt compression."},{"id":"2026-04-01-maeumjigi-4","metadata":{"permalink":"/blog/2026-04-01-maeumjigi-4","source":"@site/blog/2026-04-01-maeumjigi-4/index.md","title":"[Maeumjigi Capstone Dev Log #4] Full-Scale Data Preprocessing: Llama 3.1 Chat Template & Autonomous JSONL Pipeline","description":"Executing autonomous data engineering for Maeumjigi: transforming 120,000 raw Korean empathetic dialogue records into strict Llama 3.1 special token JSONL datasets.","date":"2026-04-01T00:00:00.000Z","tags":[{"inline":true,"label":"devlog","permalink":"/blog/tags/devlog"},{"inline":true,"label":"llama-3-1","permalink":"/blog/tags/llama-3-1"},{"inline":true,"label":"data-preprocessing","permalink":"/blog/tags/data-preprocessing"},{"inline":true,"label":"jsonl","permalink":"/blog/tags/jsonl"},{"inline":true,"label":"fine-tuning","permalink":"/blog/tags/fine-tuning"},{"inline":true,"label":"ai-hub","permalink":"/blog/tags/ai-hub"},{"inline":true,"label":"nlp","permalink":"/blog/tags/nlp"}],"readingTime":3.75,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"2026-04-01-maeumjigi-4","title":"[Maeumjigi Capstone Dev Log #4] Full-Scale Data Preprocessing: Llama 3.1 Chat Template & Autonomous JSONL Pipeline","authors":["jbgih"],"tags":["devlog","llama-3-1","data-preprocessing","jsonl","fine-tuning","ai-hub","nlp"],"date":"2026-04-01T00:00:00.000Z","keywords":["Llama 3.1 Chat Template","AI Hub Preprocessing Pipeline","JSONL Multi-turn Formatting","LLM Instruction Fine-Tuning","Empathetic Dialogue Dataset"],"description":"Executing autonomous data engineering for Maeumjigi: transforming 120,000 raw Korean empathetic dialogue records into strict Llama 3.1 special token JSONL datasets."},"unlisted":false,"prevItem":{"title":"[Maeumjigi Capstone Dev Log #5] Purifying 100,000 Emotion Data Points and the Pressure of Application Programming Interface (API) Costs","permalink":"/blog/2026-04-03-maeumjigi-5"},"nextItem":{"title":"[Maeumjigi Capstone Dev Log #3] Alarm App Build Test and Fine-Tuning Preprocessing Kickoff","permalink":"/blog/maeumjigi-3"}},"content":"![Cover Image](./images/01_cover.png)\\r\\n\\r\\nApril 1, 2026, was the day our engineering team launched the automated preprocessing pipeline for the massive counseling corpora that would form the foundation of **Maeumjigi**. Training a high-performance open-source Large Language Model (LLM) like **Meta Llama 3.1** requires rigorous data hygiene: converting unstructured multi-party dialogues into clean, token-bounded, and special-token-aligned instruction datasets.\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n### 1. The Challenge of Raw Multi-Turn Dialogue Corpora\\r\\n\\r\\nOur raw data originated from public Korean empathetic dialogue and counseling datasets (AI Hub). While academically valuable, raw dialogue data poses critical obstacles for instruction fine-tuning:\\r\\n1. **Inconsistent Turn Structures**: Casual multi-speaker exchanges frequently have broken turns (e.g., three consecutive user utterances followed by an empty response).\\r\\n2. **Personal Identifiable Information (PII)**: Raw transcripts contain phone numbers, specific military unit identifiers, and real names that must be strictly anonymized.\\r\\n3. **Token Length Exceedance**: Unbounded conversations often exceed the target attention context window (2,048 tokens), triggering out-of-memory (OOM) failures during PyTorch gradient computation.\\r\\n\\r\\n---\\r\\n\\r\\n### 2. Autonomous Preprocessing Pipeline Architecture\\r\\n\\r\\nInstead of having human engineers manually massage CSV records, we instructed **Claude Code** to autonomously architect and execute a 5-stage transformation pipeline based on our blueprint document: `llama31_finetuning_data_preprocessing_plan_short.md`.\\r\\n\\r\\n```mermaid\\r\\nflowchart TD\\r\\n    subgraph Ingestion [\\"Stage 1: Raw Data Ingestion\\"]\\r\\n        A[AI Hub Raw Corpus: 124,500 Dialogues] --\x3e B[Schema Normalizer]\\r\\n    end\\r\\n\\r\\n    subgraph Cleansing [\\"Stage 2: Sanitization & Filtering\\"]\\r\\n        B --\x3e C[PII Masking & Regex De-identification]\\r\\n        C --\x3e D[Turn Parity Validator: Eliminate Single-Turn & Orphan Rows]\\r\\n    end\\r\\n\\r\\n    subgraph Tokenization [\\"Stage 3: Token Budgeting & Bounds\\"]\\r\\n        D --\x3e E[Llama 3.1 BPE Tokenizer Profiling]\\r\\n        E --\x3e F[Context Truncation: Hard Ceiling at 2048 Tokens]\\r\\n    end\\r\\n\\r\\n    subgraph Formatting [\\"Stage 4: Chat Template Injection\\"]\\r\\n        F --\x3e G[Special Token Ingestion: begin_of_text, start_header_id, eot_id]\\r\\n        G --\x3e H[Final Train/Val Split: 90/10 Ratio]\\r\\n    end\\r\\n\\r\\n    H --\x3e I[(maeumjigi_llama31_train.jsonl: 99,000)]\\r\\n    H --\x3e J[(maeumjigi_llama31_val.jsonl: 11,000)]\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\n### 3. Strict Llama 3.1 Chat Template Formatting\\r\\n\\r\\nLlama 3.1 introduces a strict tokenized header structure that models must strictly learn to avoid runaway generation loops:\\r\\n\\r\\n```text\\r\\n<|begin_of_text|><|start_header_id|>system<|end_header_id|>\\r\\n\\r\\nYou are \'Maeumjigi\', an empathetic clinical psychological counseling AI companion. Listen with deep empathy and never judge.<|eot_id|>\\r\\n<|start_header_id|>user<|end_header_id|>\\r\\n\\r\\nI feel overwhelmed by military life and nobody understands me.<|eot_id|>\\r\\n<|start_header_id|>assistant<|end_header_id|>\\r\\n\\r\\nAdapting to military service can feel deeply isolating. It is completely natural to feel overwhelmed. Would you like to share what was hardest today?<|eot_id|>\\r\\n```\\r\\n\\r\\nEvery single training sample was converted into a structured JSONL entry containing exact role tokens:\\r\\n\\r\\n```python\\r\\n# Core formatting logic implemented in transform_llama31.py\\r\\nimport json\\r\\n\\r\\ndef format_llama31_sample(system_prompt: str, turns: list) -> dict:\\r\\n    formatted_text = \\"<|begin_of_text|>\\"\\r\\n    formatted_text += f\\"<|start_header_id|>system<|end_header_id|>\\\\n\\\\n{system_prompt}<|eot_id|>\\"\\r\\n    \\r\\n    for turn in turns:\\r\\n        role = turn[\\"role\\"] # \\"user\\" or \\"assistant\\"\\r\\n        content = turn[\\"content\\"].strip()\\r\\n        formatted_text += f\\"<|start_header_id|>{role}<|end_header_id|>\\\\n\\\\n{content}<|eot_id|>\\"\\r\\n        \\r\\n    return {\\"text\\": formatted_text}\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\n### 4. Data Preprocessing Attrition & Statistics\\r\\n\\r\\nThe data cleansing pipeline strictly dropped malformed rows to guarantee training convergence. The quantitative attrition audit:\\r\\n\\r\\n| Preprocessing Stage | Remaining Records | Dropped Count | Exclusion Rationale |\\r\\n| :--- | :---: | :---: | :--- |\\r\\n| **Raw AI Hub Input** | 124,500 | - | Baseline multi-speaker transcripts |\\r\\n| **PII & Malformed Encoding** | 120,400 | 4,100 | Encoding errors, exposed phone/unit IDs |\\r\\n| **Turn Parity Validation** | 112,200 | 8,200 | Orphan utterances, missing assistant responses |\\r\\n| **Token Budgeting (< 2048)** | 110,000 | 2,200 | Exceeded context ceiling; risk of mid-thought cut |\\r\\n| **Final Train Set (90%)** | **99,000** | - | Structured instruction tuning samples |\\r\\n| **Final Val Set (10%)** | **11,000** | - | Out-of-distribution benchmark evaluation |\\r\\n\\r\\n![Terminal Screenshot](./images/02_term.png)\\r\\n\\r\\n---\\r\\n\\r\\n### 5. Day 4 Takeaways & Milestones\\r\\n\\r\\n1. **Fully Automated Data Pipeline**: Processing over 120,000 dialogue pairs was executed completely hands-free by our AI agent in under 45 minutes.\\r\\n2. **Zero Syntax Drift**: Every record adhered to the exact `Llama 3.1` special token specifications, preventing generation loop bugs during fine-tuning.\\r\\n3. **Ready for Distributed Training**: Output datasets were validated and staged for GPU cluster deployment on Google Colab and AWS.\\r\\n\\r\\nIn Dev Log #5, we dive into the financial reality of large-scale LLM data synthesis and the API cost challenges that followed!\\n\\n---\\n\\n## Summary & Key Takeaways\\n\\n- **Autonomous 5-Stage Data Engineering**: Architected an autonomous Python pipeline to transform 124,500 raw AI Hub multi-speaker counseling records into clean JSONL instruction datasets.\\n- **Strict Turn Parity & PII Redaction**: Filtered 14,500 malformed, orphan, or PII-exposed dialogue records, ensuring zero data contamination and consistent user-assistant alternation.\\n- **Token Budgeting & Context Ceiling**: Profiling with the Llama 3.1 BPE tokenizer enforced a hard limit under 2,048 tokens to eliminate out-of-memory errors during PyTorch backpropagation.\\n- **Llama 3.1 Special Token Formatting**: Injected exact special tokens (`<|begin_of_text|>`, `<|start_header_id|>`, `<|eot_id|>`) to safeguard against infinite generation loops during training."},{"id":"maeumjigi-3","metadata":{"permalink":"/blog/maeumjigi-3","source":"@site/blog/2026-03-31-maeumjigi-3/index.md","title":"[Maeumjigi Capstone Dev Log #3] Alarm App Build Test and Fine-Tuning Preprocessing Kickoff","description":"Completing the alarm app and executing a major project pivot toward \'Maeumjigi\', an AI-powered mental health and suicide prevention chatbot.","date":"2026-03-31T00:00:00.000Z","tags":[{"inline":true,"label":"devlog","permalink":"/blog/tags/devlog"},{"inline":true,"label":"Artificial Intelligence (AI)-coding","permalink":"/blog/tags/artificial-intelligence-ai-coding"},{"inline":true,"label":"ClaudeCode","permalink":"/blog/tags/claude-code"},{"inline":true,"label":"capstone","permalink":"/blog/tags/capstone"},{"inline":true,"label":"Android","permalink":"/blog/tags/android"},{"inline":true,"label":"build-test","permalink":"/blog/tags/build-test"},{"inline":true,"label":"Llama3.1","permalink":"/blog/tags/llama-3-1"}],"readingTime":2.16,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"maeumjigi-3","title":"[Maeumjigi Capstone Dev Log #3] Alarm App Build Test and Fine-Tuning Preprocessing Kickoff","authors":["jbgih"],"tags":["devlog","Artificial Intelligence (AI)-coding","ClaudeCode","capstone","Android","build-test","Llama3.1"],"date":"2026-03-31T00:00:00.000Z","keywords":["AI Mental Health Chatbot","LLM Fine-tuning","AI Safety Wrapper","Capstone Project","Prompt Engineering"],"description":"Completing the alarm app and executing a major project pivot toward \'Maeumjigi\', an AI-powered mental health and suicide prevention chatbot."},"unlisted":false,"prevItem":{"title":"[Maeumjigi Capstone Dev Log #4] Full-Scale Data Preprocessing: Llama 3.1 Chat Template & Autonomous JSONL Pipeline","permalink":"/blog/2026-04-01-maeumjigi-4"},"nextItem":{"title":"[Maeumjigi Capstone Dev Log #2] Initial Alarm App Planning and Testing","permalink":"/blog/maeumjigi-2"}},"content":"![Cover Image](./images/01_cover.png)\\n\\nThis is the record of March 31, when we conducted the Android build test of the MND Convention reservation alarm app, which was the initial direction of the Maeumjigi project, while simultaneously starting the **Llama 3.1 fine-tuning data preprocessing**, hinting at a full transition into an AI-based project.\\n\\n{/* truncate */}\\n\\n### Android App Build and Unit Testing\\n\\n- **Problem**: We needed to verify if the server and Android client codes planned and generated yesterday would successfully build and pass tests in the actual Android Studio environment.\\n- **Process**: \\n  > To Claude Code: \\"Current progress... Stop all work... What were you working on?\\"\\n- **Result**: Numerous build artifacts and metadata were generated in the `mnd-reservation-alarm/android/app/build/...` path. We executed unit tests such as `NotificationBuilderTest` and checked the Android-specific build pipeline, including debug resource merging and manifest processing. The core logic of detecting reservation changes in the background and popping up alarms was tested.\\n\\n### The Great Turning Point: Starting Llama 3.1 Fine-Tuning Preprocessing\\n\\n- **Problem**: Moving beyond a simple alarm app, preparation was needed to integrate an advanced AI that understands the user\'s (soldier\'s) reservation context and emotional state.\\n- **Process**:\\n  > To Claude Code: \\"Please proceed with the work according to llama31_finetuning_data_preprocessing_plan_short.md\\"\\n  > \\"No additional permission is needed for any choices regarding this task.\\"\\n- **Result**: We took a crucial first step that would completely change the nature of the project. We instructed the work according to the data preprocessing plan for fine-tuning the Llama 3.1 model. To speed up the process, we granted the AI strong authority by saying, \\"execute immediately without asking for additional permission for all choices,\\" and started the massive data processing pipeline.\\n\\n![Terminal Screenshot](./images/02_term.png)\\n\\nThis day was a meaningful day when the Android build work to improve the completeness of the alarm app and the AI fine-tuning data preprocessing, which will become the core feature of the future, started in parallel.\\nFrom now on, the arduous preprocessing journey of processing tens of thousands of conversation data points to fit Llama 3.1 will begin in earnest!\\n\\n---\\n\\n## Summary & Key Takeaways\\n\\n- **Android Client Build & Unit Testing**: Verified the Android Studio build pipeline for the reservation alarm service, validating background notification dispatch and manifest merging.\\n- **Strategic Pivot Toward Conversational AI**: Reoriented project scope from a simple notification utility toward Maeumjigi, an empathetic AI counseling and crisis intervention system.\\n- **Fine-Tuning Preprocessing Kickoff**: Initiated the dataset preprocessing pipeline based on `llama31_finetuning_data_preprocessing_plan_short.md` for Meta Llama 3.1.\\n- **Autonomous Agent Execution Grant**: Empowered the autonomous AI coding agent with unrestricted execution authority to accelerate multi-stage data transformations without approval bottlenecks."},{"id":"maeumjigi-2","metadata":{"permalink":"/blog/maeumjigi-2","source":"@site/blog/2026-03-30-maeumjigi-2/index.md","title":"[Maeumjigi Capstone Dev Log #2] Initial Alarm App Planning and Testing","description":"Implementing the core alarm app functionality by integrating JSoup background web crawling with Android Room database for real-time reservation alerts.","date":"2026-03-30T00:00:00.000Z","tags":[{"inline":true,"label":"devlog","permalink":"/blog/tags/devlog"},{"inline":true,"label":"Artificial Intelligence (AI)-coding","permalink":"/blog/tags/artificial-intelligence-ai-coding"},{"inline":true,"label":"ClaudeCode","permalink":"/blog/tags/claude-code"},{"inline":true,"label":"capstone","permalink":"/blog/tags/capstone"},{"inline":true,"label":"testing","permalink":"/blog/tags/testing"}],"readingTime":2.12,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"maeumjigi-2","title":"[Maeumjigi Capstone Dev Log #2] Initial Alarm App Planning and Testing","authors":["jbgih"],"tags":["devlog","Artificial Intelligence (AI)-coding","ClaudeCode","capstone","testing"],"date":"2026-03-30T00:00:00.000Z","keywords":["AI Mental Health Chatbot","LLM Fine-tuning","AI Safety Wrapper","Capstone Project","Prompt Engineering"],"description":"Implementing the core alarm app functionality by integrating JSoup background web crawling with Android Room database for real-time reservation alerts."},"unlisted":false,"prevItem":{"title":"[Maeumjigi Capstone Dev Log #3] Alarm App Build Test and Fine-Tuning Preprocessing Kickoff","permalink":"/blog/maeumjigi-3"},"nextItem":{"title":"[Maeumjigi Capstone Dev Log #1] The First Steps: Claude Code AI Workflow & Capstone Architecture Planning","permalink":"/blog/maeumjigi-1"}},"content":"![Cover Image](./images/01_cover.png)\\n\\nThis is the record of March 30, when we officially started developing the \'MND Convention Reservation Alarm\' application, which was the initial idea for the Maeumjigi project.\\nBased on the coding rules we set last time, we established a detailed project plan and laid the foundation for Test-Driven Development (TDD).\\n\\n{/* truncate */}\\n\\n### Designing the Project Milestone\\n\\n- **Problem**: We had the application idea, but we needed a clear step-by-step plan on how to proceed with the development.\\n- **Process**: \\n  > To Claude Code: \\"Please proceed with the project according to Claude plan.md\\"\\n- **Result**: We completed a detailed project plan document called `Claude plan.md`. This document details the implementation goals for each stage, including the Android client, server structure, and crawling, and will serve as an unwavering milestone when working with AI.\\n\\n### Building Test Web Pages (Fixtures)\\n\\n- **Problem**: To build a crawler that detects changes on a reservation site in real-time, we would normally have to continuously connect to the actual website to test it. However, this can strain the server and create an unstable testing environment. Therefore, a mockup environment where we could test safely and freely offline was essential.\\n- **Process**:\\n  > To Claude Code: \\"continue\\"\\n- **Result**: The AI independently determined and perfectly created fake web page (Fixture) HTML data needed for frontend and backend testing. By precisely generating `sample_page.html` (fully booked status) and `sample_page_changed.html` (available status due to cancellations), a strong foundation was laid to quickly and safely test whether the server-side crawler code normally detects changes in HTML DOM elements.\\n\\n![Terminal Screenshot](./images/02_term.png)\\n\\nToday was a day to truly glimpse the beauty of \'AI-driven automated development\', where instead of human step-by-step instructions, we simply told the AI to \\"proceed according to plan,\\" and it independently broke down the milestones and created the necessary test data and documentation.\\nPlease continue to watch our rough (?) journey to see how this simple alarm app project transforms into a massive Deep Learning and Large Language Model (LLM)-based capstone project!\\n\\n---\\n\\n## Summary & Key Takeaways\\n\\n- **Project Roadmap & Milestone Authoring**: Formulated a structured execution blueprint (`Claude plan.md`) detailing the Android client, server crawler, and notification engine.\\n- **Offline HTML Test Fixture Construction**: Generated realistic static DOM mockups (`sample_page.html` and `sample_page_changed.html`) representing booked and cancelled reservation states.\\n- **Test-Driven Crawler Development (TDD)**: Verified DOM parsing and change-detection logic locally without overloading live production servers or creating testing latency.\\n- **AI-Driven Autonomous Development Workflow**: Validated prompt-driven autonomous engineering where high-level directives were independently translated into test assets and milestone tasks."},{"id":"maeumjigi-1","metadata":{"permalink":"/blog/maeumjigi-1","source":"@site/blog/2026-03-26-maeumjigi-1/index.md","title":"[Maeumjigi Capstone Dev Log #1] The First Steps: Claude Code AI Workflow & Capstone Architecture Planning","description":"Day 1 of our capstone engineering journey: Setting up Claude Code AI agent workflows, establishing coding conventions, and executing the critical pivot from a convention alarm app to an AI mental health counseling system.","date":"2026-03-26T00:00:00.000Z","tags":[{"inline":true,"label":"devlog","permalink":"/blog/tags/devlog"},{"inline":true,"label":"ai-agent","permalink":"/blog/tags/ai-agent"},{"inline":true,"label":"claude-code","permalink":"/blog/tags/claude-code"},{"inline":true,"label":"capstone","permalink":"/blog/tags/capstone"},{"inline":true,"label":"project-planning","permalink":"/blog/tags/project-planning"},{"inline":true,"label":"architecture","permalink":"/blog/tags/architecture"}],"readingTime":4.21,"hasTruncateMarker":true,"authors":[{"name":"Jaybee","title":"AI & Robotics Engineer","url":"https://github.com/jbjihwan","imageURL":"https://github.com/jbjihwan.png","key":"jbgih","page":null}],"frontMatter":{"slug":"maeumjigi-1","title":"[Maeumjigi Capstone Dev Log #1] The First Steps: Claude Code AI Workflow & Capstone Architecture Planning","authors":["jbgih"],"tags":["devlog","ai-agent","claude-code","capstone","project-planning","architecture"],"date":"2026-03-26T00:00:00.000Z","keywords":["Claude Code AI Workflow","AI Mental Health Chatbot","Capstone Project Architecture","LLM Fine-Tuning Roadmap","Autonomous AI Agent Rules"],"description":"Day 1 of our capstone engineering journey: Setting up Claude Code AI agent workflows, establishing coding conventions, and executing the critical pivot from a convention alarm app to an AI mental health counseling system."},"unlisted":false,"prevItem":{"title":"[Maeumjigi Capstone Dev Log #2] Initial Alarm App Planning and Testing","permalink":"/blog/maeumjigi-2"}},"content":"![Cover Image](./images/01_cover.png)\\r\\n\\r\\nMarch 26, 2026, marks the historic first day of our university capstone engineering project. Today laid the structural bedrock for everything to come: adopting an autonomous AI coding assistant (**Claude Code**), designing team collaboration protocols, and making the pivotal architectural decision that transformed a simple reservation alert tool into **Maeumjigi**, a specialized AI mental health counseling platform.\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n### 1. The Autonomous AI Collaboration Framework: Claude Code & Rulesets\\r\\n\\r\\nAt the onset of the capstone project, our engineering team decided to break away from traditional manual pair programming and integrate **Claude Code** as our primary autonomous coding agent. \\r\\n\\r\\nTo prevent AI hallucination, uncontrolled code sprawl, and incompatible dependency conflicts, we established two foundational rule documents: `Claude.md` (project domain constraints) and `CLAUDE_coding_rule.md` (syntactic and architectural rules).\\r\\n\\r\\n```markdown\\r\\n# Excerpt from CLAUDE_coding_rule.md\\r\\n1. Architecture Integrity:\\r\\n   - All backend APIs must follow strict RESTful standards using FastAPI and Pydantic schemas.\\r\\n   - Do not invent non-existent packages; verify imports against requirements.txt.\\r\\n2. Safe Automation:\\r\\n   - The AI agent has autonomous permissions within the project workspace.\\r\\n   - Irreversible file deletions or git push operations require explicit verification checkpoints.\\r\\n3. Documentation & Verification:\\r\\n   - Every module must maintain unit tests covering standard execution and edge-case exceptions.\\r\\n```\\r\\n\\r\\nBy defining these boundaries on Day 1, Claude Code transformed from a simple autocomplete tool into an autonomous junior engineer capable of running data pipelines, debugging database crashes, and compiling comprehensive technical documentation.\\r\\n\\r\\n---\\r\\n\\r\\n### 2. The Architectural Pivot: From Alarm Notifier to Mental Health AI\\r\\n\\r\\nOur team\'s initial capstone proposal was a practical Android utility: a web scraper monitoring wedding convention cancellations (MND Convention) that delivered instant mobile push notifications via Firebase Cloud Messaging (FCM). \\r\\n\\r\\nHowever, during architectural review, we recognized that simple web scraping had limited academic depth and high legal/operational fragility due to anti-bot protections. Concurrently, analyzing societal data revealed a severe crisis: rising depressive symptoms and psychological isolation among young adults and military service members, contrasted with a stark shortage of licensed clinical psychologists.\\r\\n\\r\\nWe executed an immediate architectural **pivot**: repurposing our engineering pipeline to build a 24/7 empathetic crisis intervention chatbot fine-tuned on real Korean empathetic dialogue datasets.\\r\\n\\r\\n```mermaid\\r\\nflowchart TD\\r\\n    subgraph Initial_Plan [\\"Initial Concept: Android Convention Alarm\\"]\\r\\n        A[MND Convention Web Portal] --\x3e|Periodic Scraper| B[Python Polling Engine]\\r\\n        B --\x3e|Status Change Detected| C[FCM Push Server]\\r\\n        C --\x3e|Instant Alert| D[Android Client App]\\r\\n    end\\r\\n\\r\\n    subgraph Architecture_Pivot [\\"Critical Engineering Pivot\\"]\\r\\n        direction TB\\r\\n        E[Societal Problem: Youth & Military Mental Health Crisis]\\r\\n        F[Academic Rigor: Fine-Tuned Open-Source LLMs]\\r\\n    end\\r\\n\\r\\n    subgraph Final_Roadmap [\\"Final System: Maeumjigi Mental Health AI\\"]\\r\\n        G[AI Hub Korean Empathetic Corpora] --\x3e|100K Curation| H[Llama 3.1 & Qwen Fine-Tuning]\\r\\n        H --\x3e|LoRA & QLoRA| I[Dual-Layer Safety Wrapper]\\r\\n        I --\x3e|FastAPI Serving| J[Cross-Platform Client Web/App]\\r\\n    end\\r\\n\\r\\n    Initial_Plan -.->|Evaluated for Capstone Scope| Architecture_Pivot\\r\\n    Architecture_Pivot ==>|System Redeveloped| Final_Roadmap\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\n### 3. Engineering Feasibility Comparison\\r\\n\\r\\nTo validate our pivot before the faculty review board, we conducted a side-by-side engineering feasibility matrix:\\r\\n\\r\\n| Evaluation Dimension | Initial Concept (Convention Alarm App) | Pivoted Architecture (Maeumjigi AI Platform) |\\r\\n| :--- | :--- | :--- |\\r\\n| **Primary Tech Stack** | Android (Kotlin), Python BeautifulSoup, FCM | FastAPI, PyTorch, Hugging Face, Llama 3.1, React Native |\\r\\n| **Data Engineering** | Fragile HTML DOM parsing & cron jobs | 100,000+ multi-turn empathetic dialogue curation |\\r\\n| **Algorithmic Depth** | Deterministic string matching & diff checks | LoRA fine-tuning, loss convergence, Perplexity evaluation |\\r\\n| **Safety Requirements** | Low (occasional false alarm acceptable) | Critical (Active Suicidality triage & zero hallucination) |\\r\\n| **Scalability & Impact** | Limited to single event reservation utility | Universal mental health support and suicide prevention triage |\\r\\n\\r\\n---\\r\\n\\r\\n### 4. Prototype Scraper vs. Prompt Engineering Blueprint\\r\\n\\r\\nOn Day 1, we preserved our exploratory scraper prototype while drafting the prompt engineering blueprint for the mental health model:\\r\\n\\r\\n```python\\r\\n# Initial prototyping: Establishing structured logging and error handling\\r\\nimport sys\\r\\nimport logging\\r\\n\\r\\nlogging.basicConfig(level=logging.INFO, format=\\"%(asctime)s [%(levelname)s] %(message)s\\")\\r\\n\\r\\ndef initialize_project_environment():\\r\\n    logging.info(\\"Initializing Capstone Workspace...\\")\\r\\n    rules = [\\"CLAUDE_coding_rule.md\\", \\"Claude.md\\"]\\r\\n    for r in rules:\\r\\n        logging.info(f\\"Enforcing active agent configuration: {r}\\")\\r\\n    logging.info(\\"Core system status: Ready for Phase 1 Data Pipeline.\\")\\r\\n\\r\\nif __name__ == \\"__main__\\":\\r\\n    initialize_project_environment()\\r\\n```\\r\\n\\r\\n![Terminal Screenshot](./images/02_term.png)\\r\\n\\r\\n---\\r\\n\\r\\n### 5. Day 1 Key Achievements & Next Steps\\r\\n\\r\\n1. **Autonomous Workflow Setup**: Established Claude Code coding rules (`CLAUDE_coding_rule.md`) to ensure zero code divergence during automated generations.\\r\\n2. **Capstone Direction Finalized**: Successfully approved the pivot from a trivial scraper app to a high-impact mental health LLM platform.\\r\\n3. **Data Acquisition Strategy**: Outlined the pipeline to source and filter over 100,000 multi-turn counseling dialogues from AI Hub.\\r\\n\\r\\nIn the next devlog, we will explore our initial Android and React Native UI scaffolding and the first attempts at data ingestion!\\n\\n---\\n\\n## Summary & Key Takeaways\\n\\n- **Autonomous AI Engineering Framework**: Established foundational coding guardrails (`CLAUDE_coding_rule.md`) to empower Claude Code with safe, high-speed autonomous development capabilities.\\n- **Pivotal Capstone Redirection**: Shifted project scope from an Android scraping utility to \'Maeumjigi\', an empathetic conversational AI addressing youth and military mental health crises.\\n- **Engineering Feasibility & Safety Benchmarking**: Formulated technical matrices evaluating FastAPI serving, open-source LLM fine-tuning, and zero-shot crisis triage versus simple scraping.\\n- **Strategic Data Acquisition Roadmap**: Outlined the pipeline to source, de-identify, and format 100,000+ multi-turn empathetic Korean dialogues from AI Hub into instruction corpora."}]}}')}}]);